#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/*
 * Raspberry Pi 4 Model B – MCP3008 Soil Moisture Sensor
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> DFRobot Soil Moisture Sensor v2.0 analog out
 *
 * The DFRobot sensor is an analog resistive sensor; the ADC value
 * corresponds to the resistance of the soil. A higher voltage
 * (lower resistance) indicates drier soil.
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_BAUD       1000000    /* 1 MHz – well within MCP3008 spec */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended CH0 */
#define SAMPLE_PERIOD  1.0        /* seconds between readings */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
 *   tx[0] = 0x01                       Start bit
 *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1 (single-ended) + ch
 *   tx[2] = 0x00                       Don't-care (clocks out low bits)
 *
 * Result:
 *   rx[1] bits 1..0  -> upper 2 data bits
 *   rx[2]           -> lower 8 data bits
 *   10-bit value    -> ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;  /* 0..1023 */
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d): %s\n",
                g_spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Reader\n");
    printf("SPI channel %d, ADC channel %d, %d Hz sampling\n",
           SPI_CHANNEL, ADC_CHANNEL, (int)(SPI_BAUD / 1000));
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = mcp3008_read(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error – continuing\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL &&
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                printf("[%s] ADC CH%d: %4d  |  moisture level (0=dry, 1023=wet)\n",
                       ts, ADC_CHANNEL, adc);
            } else {
                printf("ADC CH%d: %4d\n", ADC_CHANNEL, adc);
            }
            fflush(stdout);
        }

        /* Sleep SAMPLE_PERIOD, but wake early on signal */
        if (g_running) {
            time_sleep(SAMPLE_PERIOD);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

