#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADS1115 I2C address (ADDR pin tied to GND) */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config register bit layout (16-bit, big-endian on the wire):
 *   [15]    OS: Operational status / single-shot start
 *   [14:12] MUX: AIN0 single-ended (100)
 *   [11:9]  PGA: PGA range ±4.096 V (001)
 *   [8]     MODE: Single-shot (1)
 *   [7:5]   DR: 128 SPS (100)
 *   [4]     COMP_MODE: Traditional (0)
 *   [3]     COMP_POL: Active low (0)
 *   [2]     COMP_LAT: Non-latching (0)
 *   [1:0]   COMP_QUE: Disable comparator (11)
 *
 * Binary: 1100 0001 1000 0011
 * => 0xC183
 */
#define ADS1115_CONFIG_BASE 0xC183

/* MLX91219 parameters */
#define MLX91219_SENSITIVITY 0.040  /* V/A */
#define MLX91219_ZERO_OFFSET 2.5   /* V (mid-supply) */

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a 16-bit value to an ADS1115 register.
 * pigpio's i2cWriteI2CBlockData sends [reg, data_hi, data_lo] on the wire.
 */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, buf + 1, 2) < 0) {
        fprintf(stderr, "Error: i2cWriteI2CBlockData to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from an ADS1115 register.
 * pigpio's i2cReadI2CBlockData returns [reg, data_hi, data_lo].
 */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *value)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData from reg 0x%02X failed\n", reg);
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Trigger a single-shot conversion and read the raw ADC code.
 * Returns 0 on success, -1 on error.
 */
static int ads1115_read_raw(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CONFIG_BASE;

    /* Write config to start a single-shot conversion */
    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Poll OS bit (bit 15) until it reads 1 (conversion ready) */
    for (int i = 0; i < 20; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & 0x8000) {
            uint16_t conv;
            if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) < 0)
                return -1;
            *raw_out = (int16_t)conv;
            return 0;
        }
        gpioDelay(2000);
    }

    fprintf(stderr, "Error: ADS1115 conversion timeout\n");
    return -1;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address 0x48 */
    g_i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Check wiring and ADS1115 presence.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 current monitor via ADS1115 (I2C addr 0x48, bus 1).\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;

        if (ads1115_read_raw(g_i2c_handle, &raw) < 0) {
            fprintf(stderr, "Warning: ADC read failed, retrying next cycle.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /*
         * Convert raw ADC code to voltage.
         * PGA ±4.096 V => 1 bit = 125 µV.
         * AIN0 single-ended => no gain setting bit applies.
         */
        double voltage = (raw * 0.000125);

        /* Convert voltage to current using MLX91219 transfer function */
        double current = (voltage - MLX91219_ZERO_OFFSET) / MLX91219_SENSITIVITY;

        printf("Current: %.4f A\n", current);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

