#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY_US 50000
#define POLL_INTERVAL_US 100000
#define BUZZER_DURATION_US 2000000
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_flame_event_tick = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        uint32_t elapsed = tick - last_flame_event_tick;
        if (elapsed >= DEBOUNCE_DELAY_US) {
            last_flame_event_tick = tick;
            printf("Flame detected!\n");
        }
    }
}

static int read_temperature(double *temperature) {
    if (temperature == NULL) return -1;
    *temperature = -1.0;

    /*
     * Write single-shot config for AIN0, gain ±4.096V, 128 SPS.
     * Bit layout: OS=1, MUX=100 (AIN0), PGA=010 (±4.096V), MODE=1 (single),
     * DR=100 (128 SPS), COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11 (disable).
     */
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_AIN0 |
                      ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS | 0x0003;

    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, cfg, 3) != 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config register.\n");
        return -1;
    }

    /* Wait for conversion to complete (~8.5ms at 128 SPS) */
    gpioDelay(10000);

    /* Point to conversion register and read 2 bytes */
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion data.\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    /* PGA ±4.096V -> 1 bit = 125 µV */
    double voltage = (raw * 4.096) / 32768.0;
    *temperature = (voltage / 0.01) - 273.15;
    return 0;
}

static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, ADS1115_ADDR);
        fclose(log_file);
        log_file = NULL;
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR for flame sensor.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler.\n");
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_detected = (gpioRead(FLAME_SENSOR_PIN) == 0);

        double temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Warning: Temperature read failed, skipping this cycle.\n");
        } else {
            if (temperature > TEMPERATURE_THRESHOLD) {
                if (flame_detected) {
                    log_event("Flame detected! Temperature exceeded threshold.");
                    gpioWrite(BUZZER_PIN, 1);
                    gpioDelay(BUZZER_DURATION_US);
                    gpioWrite(BUZZER_PIN, 0);
                } else {
                    char msg[128];
                    snprintf(msg, sizeof(msg), "Temperature exceeded threshold: %.2f°C", temperature);
                    log_event(msg);
                }
            } else if (flame_detected) {
                log_event("Flame detected!");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

