        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0.0f) {
                    fprintf(stderr, "Invalid sensitivity value: %s\n", optarg);
                    return EXIT_FAILURE;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Invalid threshold value: %s\n", optarg);
                    return EXIT_FAILURE;
                }
