#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SLEEP_INTERVAL 5
#define MAX_RETRIES 3

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: Start single conversion, AIN0, PGA 4.096V, 128 SPS, Single-shot
#define ADS1115_CONFIG_BASE 0x8000 | (0x4000) | (0x0200) | (0x0100) | (0x0080) | (0x0040) | (0x0003)

// Calibration parameters (example values, replace with actual calibration)
#define CO_SCALE_FACTOR 0.1
#define CO_OFFSET 0.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_co_resistance();
float calculate_co_ppm(int resistance);
int log_co_ppm(float ppm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Reads the raw resistance value from the sensor via ADS1115
int read_co_resistance() {
    char config[3];
    char conversion[2];
    int raw_value;
    int retries = 0;

    // Write config to start single conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_BASE >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_BASE & 0xFF;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, config, 3) == 0) {
            break;
        } else {
            fprintf(stderr, "Error writing config to ADS1115 (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(100000); // 100ms delay before retry
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to write config to ADS1115 after %d attempts\n", MAX_RETRIES);
        return -1;
    }

    // Wait for conversion to complete (approx 8ms for 128 SPS)
    gpioDelay(10000);

    // Read conversion register
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error setting conversion register pointer\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, conversion, 2) != 2) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    raw_value = (conversion[0] << 8) | conversion[1];
    return raw_value;
}

// Calculates the CO concentration in PPM using a logarithmic curve
float calculate_co_ppm(int resistance) {
    float ppm = CO_SCALE_FACTOR * log10f(resistance + 1) + CO_OFFSET;
    return ppm;
}

// Logs the CO concentration to a file
int log_co_ppm(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int raw_resistance = read_co_resistance();
        if (raw_resistance >= 0) {
            float ppm = calculate_co_ppm(raw_resistance);
            if (log_co_ppm(ppm) != 0) {
                fprintf(stderr, "Error logging CO concentration\n");
            }
        } else {
            fprintf(stderr, "Error reading CO resistance, skipping logging\n");
        }

        sleep(SLEEP_INTERVAL);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

