#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 /* 1 MHz */
#define SPI_FLAGS 0
#define LOG_FILE "flame_data.csv"
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

/* Global variables */
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int initialize_gpio(void);
static int read_flame_sensor(void);
static int read_mcp3008(int channel);
static float convert_adc_to_temperature(int adc_value);
static int log_data(int flame_detected, float temperature);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialize GPIO pins */
static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read the digital flame sensor (KY-026 D0) */
static int read_flame_sensor(void) {
    return gpioRead(FLAME_SENSOR_GPIO);
}

/* Read a single-ended channel from the MCP3008 ADC */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: Start bit (0x01)
     * Byte 1: Single-ended mode (0x80) | channel << 4
     * Byte 2: Dummy (0x00)
     */
    char spi_tx_buf[3] = {0x01, (char)(0x80 | (channel << 4)), 0x00};
    char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    /* Extract 10-bit ADC value: bits 9-2 from rx_buf[1], bits 1-0 from rx_buf[2] */
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | (spi_rx_buf[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value to approximate temperature (10.0-40.0 C) */
static float convert_adc_to_temperature(int adc_value) {
    return 10.0f + ((float)adc_value / 1023.0f) * 30.0f;
}

/* Log data to CSV file */
static int log_data(int flame_detected, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        fclose(fp);
        return -1;
