#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x58
#define CO_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *ox_reading, int *red_reading);
float calculate_co_ppm(int ox_reading, int red_reading);
void log_co_level(float co_ppm);
void log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from the MICS-4514
int read_sensor_data(int *ox_reading, int *red_reading) {
    char buf[4];
    int result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // MICS-4514 returns 16-bit ADC values (OX then RED)
    *ox_reading = (buf[0] << 8) | buf[1];
    *red_reading = (buf[2] << 8) | buf[3];

    return 0;
}

// Calculate CO level in PPM
float calculate_co_ppm(int ox_reading, int red_reading) {
    // Placeholder calibration formula (adjust based on sensor specifications)
    return (float)ox_reading * 0.1f + (float)red_reading * 0.05f;
}

// Log CO level to file
void log_co_level(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
}

// Log alert to file
void log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold! CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int ox_reading, red_reading;
    float co_ppm;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&ox_reading, &red_reading) == 0) {
            co_ppm = calculate_co_ppm(ox_reading, red_reading);
            log_co_level(co_ppm);

            if (co_ppm > CO_THRESHOLD) {
                log_alert(co_ppm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", READ_INTERVAL_SEC);
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    cleanup();
    return 0;
}

