#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define I2C_BUS 1
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "audio_log.txt"

/* IMP23ABSU: -38 dBV/Pa sensitivity, 20e-6 Pa reference pressure */
#define SENSITIVITY_DBV_PER_PA -38.0
#define REFERENCE_PRESSURE_PA 20.0e-6

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double read_microphone(int handle, int addr) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(handle, 0x00, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading I2C block from 0x%02X (got %d bytes)\n", addr, bytes);
        return -999.0;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    double voltage = (double)raw * (3.3 / 65536.0);
    double pressure_pa = voltage * 100000.0; /* dBV -> Pa */
    double db = 20.0 * log10(pressure_pa / REFERENCE_PRESSURE_PA);
    return db;
}

static void log_data(double avg_db) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f dB\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_db);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for mic1: %d\n", i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for mic2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        double db1 = read_microphone(i2c_handle1, MIC1_ADDR);
        double db2 = read_microphone(i2c_handle2, MIC2_ADDR);
        double avg_db = (db1 + db2) / 2.0;
        log_data(avg_db);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return EXIT_SUCCESS;
}

