#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define LED_GPIO 27
#define THRESHOLD 0.7
#define NUM_SAMPLES 100
#define SAMPLE_INTERVAL_US 1000  // 1 ms
#define LED_ON_DURATION_US 500000 // 500 ms
#define NORMALIZATION_SCALE 100.0

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double calculate_rms(int *samples, int num_samples);
void trigger_led();
void log_event(double mic1_rms, double mic2_rms);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended mode + channel selection)
    // Byte 2: 0x00 (Don't care, clocking out data)
    char spi_tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + (spi_rx_buf[2] & 0xFF);
    return adc_value;
}

// Calculate RMS value
double calculate_rms(int *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Trigger LED
void trigger_led() {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_DURATION_US);
    gpioWrite(LED_GPIO, 0);
}

// Log event to CSV file
void log_event(double mic1_rms, double mic2_rms) {
    FILE *fp = fopen("audio_events.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening audio_events.csv for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int mic1_samples[NUM_SAMPLES];
        int mic2_samples[NUM_SAMPLES];

        // Sample microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            mic1_samples[i] = read_mcp3008(0); // Channel 0 for Mic1
            mic2_samples[i] = read_mcp3008(1); // Channel 1 for Mic2
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        // Calculate RMS values
        double mic1_rms = calculate_rms(mic1_samples, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_samples, NUM_SAMPLES);

        // Normalize RMS values
        mic1_rms /= NORMALIZATION_SCALE;
        mic2_rms /= NORMALIZATION_SCALE;

        // Check if threshold is exceeded
        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            trigger_led();
            log_event(mic1_rms, mic2_rms);
        }
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Audio monitoring stopped.\n");
    return 0;
}

