#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_GPIO 17
#define CURRENT_THRESHOLD 50.0 // Amperes
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000 // 100ms

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: A0 single-ended, +/-4.096V, 128 SPS, continuous
#define ADS1115_CONFIG_BASE 0x4000
#define ADS1115_CONFIG_MUX_A0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_CONTINUOUS 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

// MLX91204 Conversion: 5V supply, 0.5V to 4.5V for 0-100A
#define V_SUPPLY 5.0
#define V_MIN 0.5
#define V_MAX 4.5
#define CURRENT_MAX 100.0

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer = {{0.0}, 0, 0};

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float get_average_current();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication with ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }

    // Configure ADS1115: single-ended A0, +/-4.096V, 128 SPS, continuous
    uint16_t config = ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V |
                      ADS1115_CONFIG_MODE_CONTINUOUS | ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read raw 16-bit value from ADS1115 conversion register
int read_ads1115(int16_t *raw_value) {
    char reg = ADS1115_REG_CONVERSION;
    char data[2];

    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error writing conversion register address\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Error reading conversion data\n");
        return -1;
    }

    *raw_value = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

// Convert raw ADC value to current (Amperes)
float convert_to_current(int16_t raw_value) {
    // ADS1115 is 16-bit signed, +/-4.096V range
    // Convert to voltage: raw * 4.096 / 32768.0
    float voltage = (float)raw_value * 4.096 / 32768.0;
    // Clamp to valid sensor range
    if (voltage < V_MIN) voltage = V_MIN;
    if (voltage > V_MAX) voltage = V_MAX;
    // Current = (voltage - V_MIN) / (V_MAX - V_MIN) * CURRENT_MAX
    return (voltage - V_MIN) / (V_MAX - V_MIN) * CURRENT_MAX;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer.buffer[current_buffer.head] = current;
    current_buffer.head = (current_buffer.head + 1) % BUFFER_SIZE;
    if (current_buffer.count < BUFFER_SIZE) {
        current_buffer.count++;
    }
}

// Calculate average current from circular buffer
float get_average_current() {
    if (current_buffer.count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < current_buffer.count; i++) {
        sum += current_buffer.buffer[i];
    }
    return sum / current_buffer.count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Check sensor wiring and ADS1115 address.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(current);
            float average_current = get_average_current();
            control_led(average_current);
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

