#define TCS34725_RDATAL  0x16
#define TCS34725_RDATAH  0x17
#define TCS34725_GDATAL  0x18
#define TCS34725_GDATAH  0x19
#define TCS34725_BDATAL  0x1A
#define TCS34725_BDATAH  0x1B

/* Expected chip ID: lower 4 bits of byte 0x12 should be 0x44 */
#define TCS34725_ID_VALUE 0x44

/* Globals for signal-safe cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; defer heavy work to main loop      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register; return 0 on success, -1 err  */
/* ------------------------------------------------------------------ */
static int tcs34725_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register; return 0 on success, -1 err */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                           */
/* ------------------------------------------------------------------ */
static int tcs34725_read_word(int handle, uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (tcs34725_read_reg(handle, reg_low, &lo) < 0)
        return -1;
    if (tcs34725_read_reg(handle, reg_low + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure the TCS34725: power on, set integration time, gain, enable */
/* ------------------------------------------------------------------ */
static int tcs34725_configure(int handle)
{
    /* Power on */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, 0x01) < 0)
        return -1;

    /* Integration time: 2.4 ms (0xFF) */
    if (tcs34725_write_reg(handle, TCS34725_ATIME, 0xFF) < 0)
        return -1;

    /* Gain: 4x (0x01) */
    if (tcs34725_write_reg(handle, TCS34725_CONTROL, 0x01) < 0)
        return -1;

    /* Enable RGBC ADC: power on + RGBC enable */
    if (tcs34725_write_reg(handle, TCS34725_ENABLE, 0x01 | 0x02) < 0)
        return -1;

    /* Wait for first integration cycle to complete (2.4 ms + margin) */
    gpioDelay(3000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channels; return 0 on success, -1 on transient error  */
/* ------------------------------------------------------------------ */
static int tcs34725_read_channels(int handle,
                                  uint16_t *clear,
                                  uint16_t *red,
                                  uint16_t *green,
                                  uint16_t *blue)
{
    if (tcs34725_read_word(handle, TCS34725_CDATAL, clear) < 0)
        return -1;
    if (tcs34725_read_word(handle, TCS34725_RDATAL, red)   < 0)
        return -1;
    if (tcs34725_read_word(handle, TCS34725_GDATAL, green) < 0)
        return -1;
    if (tcs34725_read_word(handle, TCS34725_BDATAL, blue)  < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row; write header if file is empty                   */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp,
                    uint16_t clear,
                    uint16_t red,
                    uint16_t green,
                    uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n",
