    uint8_t id = 0;
    if (tcs34725_read_reg(g_i2c_handle, TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Cannot read TCS34725 ID register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if ((id & 0x0F) != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- configure sensor --- */
    if (tcs34725_configure(g_i2c_handle) < 0) {
        fprintf(stderr, "TCS34725 configuration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open CSV (append mode) --- */
    g_log_file = fopen("color_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Cannot open color_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

