            consecutive_failures = 0;
            if (log_data(g_log_file, clear, red, green, blue) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "I2C read failure #%d\n", consecutive_failures);
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Too many consecutive failures; aborting.\n");
                break;
            }
        }

        /* Sleep 1 s using gpioDelay (non-blocking signal-safe) */
        gpioDelay(1000000);
    }

    /* --- graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

