#define MAX_RETRIES 3

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    unsigned char mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    unsigned char bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return -1;
    }
    motor_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!motor_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(motor_line, "motor_shutdown", 1) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        motor_line = NULL;
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
