    if (motor_line) {
        gpiod_line_set_value(motor_line, 0);
        printf("Motor shutdown triggered!\n");
    }
}

static void reenable_motor(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        printf("Motor re-enabled!\n");
    }
}

static void cleanup(void) {
    if (motor_line) {
        gpiod_line_set_value(motor_line, 1);
        gpiod_line_release(motor_line);
        motor_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

