    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }
    if (init_spi() < 0) {
        return 1;
    }
    if (init_gpio() < 0) {
        close(spi_fd);
        return 1;
    }
    printf("Current monitoring started. Press Ctrl+C to exit.\n");
    while (program_running) {
        int adc_value = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) break;
            fprintf(stderr, "SPI read failed, retrying (%d/%d)...\n", attempt + 1, MAX_RETRIES);
            usleep(100000);
        }
        if (adc_value < 0) {
