#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0
#define MAX_READ_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: pigpio error %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int init_log_file(void)
{
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }
    return 0;
}

static int read_pressure_raw(uint16_t *raw_out)
{
    int rc = i2cReadWordData(g_i2c_handle, PRESSURE_REG);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X: pigpio error %d\n",
                PRESSURE_REG, rc);
        return -1;
    }
    *raw_out = (uint16_t)(rc & 0xFFFF);
    return 0;
}

static double convert_to_kPa(uint16_t raw)
{
    return ((double)raw / 65535.0) * 500.0;
}

static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static int log_data(const char *timestamp, double pressure)
{
    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_log_file() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_errors = 0;

    while (g_running) {
        uint16_t raw;
        if (read_pressure_raw(&raw) == 0) {
            consecutive_errors = 0;
            double pressure = convert_to_kPa(raw);
            char timestamp[32];
            get_iso8601_timestamp(timestamp, sizeof(timestamp));
            if (log_data(timestamp, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error #%d\n", consecutive_errors);
            if (consecutive_errors >= MAX_READ_ERRORS) {
                fprintf(stderr, "Too many consecutive read errors; aborting\n");
                break;
            }
        }
        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

