#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_SINGLE (1 << 15)
#define ADS1115_CONFIG_MUX_AIN0_GND (0x04 << 12)
#define ADS1115_CONFIG_MUX_AIN1_GND (0x05 << 12)
#define ADS1115_CONFIG_PGA_2_048V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (1 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x04 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

#define WARNING_LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f

#define VREF 4.096f
#define PRESSURE_MAX 400.0f
#define TEMP_MAX 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_channel(int handle, uint8_t mux) {
    uint16_t config = ADS1115_CONFIG_OS_SINGLE | mux |
                      ADS1115_CONFIG_PGA_2_048V |
                      ADS1115_CONFIG_MODE_SINGLE |
                      ADS1115_CONFIG_DR_128SPS |
                      ADS1115_CONFIG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config\n");
        return -1;
    }

    gpioDelay(10000);

    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion register\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion\n");
        return -1;
    }

    return (int16_t)((read_buf[0] << 8) | read_buf[1]);
}

static float convert_to_pressure(int16_t raw) {
    float voltage = (float)raw * VREF / 32768.0f;
    return (voltage / 5.0f) * PRESSURE_MAX;
}

static float convert_to_temperature(int16_t raw) {
    float voltage = (float)raw * VREF / 32768.0f;
    return (voltage - 1.0f) * TEMP_MAX / 1.0f;
}

static void control_led(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", WARNING_LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    control_led(WARNING_LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Monitor\n");
    printf("Press Ctrl+C to exit\n");

    while (running) {
        int16_t raw_pressure = -1, raw_temp = -1;
        int retries = 3;

        while (retries > 0 && raw_pressure < 0) {
            raw_pressure = read_ads1115_channel(i2c_handle, ADS1115_CONFIG_MUX_AIN0_GND);
            if (raw_pressure < 0) {
                fprintf(stderr, "Pressure read failed, retrying...\n");
                retries--;
                gpioDelay(100000);
            }
        }

        retries = 3;
        while (retries > 0 && raw_temp < 0) {
            raw_temp = read_ads1115_channel(i2c_handle, ADS1115_CONFIG_MUX_AIN1_GND);
            if (raw_temp < 0) {
                fprintf(stderr, "Temperature read failed, retrying...\n");
                retries--;
                gpioDelay(100000);
            }
        }

        if (raw_pressure < 0 || raw_temp < 0) {
            fprintf(stderr, "Sensor read failed after retries. Skipping cycle.\n");
            gpioDelay(1000000);
            continue;
        }

        float pressure = convert_to_pressure(raw_pressure);
        float temperature = convert_to_temperature(raw_temp);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            control_led(WARNING_LED_GPIO, 1);
        } else {
            control_led(WARNING_LED_GPIO, 0);
        }

        gpioDelay(1000000);
    }

    control_led(WARNING_LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return 0;
}

