#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* Configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3        /* Reference voltage */
#define SENSOR_ZERO_CURRENT_V  (VREF / 2.0)
#define SENSOR_SENSITIVITY_V_PER_A 0.066  /* 66 mV/A */
#define OVERCURRENT_THRESHOLD_A 10.0
#define SHUTDOWN_GPIO   27         /* GPIO27 */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int read_adc(int channel);
static double adc_to_voltage(int adc_value);
static double voltage_to_current(double voltage);
static void log_current(double current);
static void shutdown_motor(void);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel, upper nibble)
     *   Byte 2: 0x00  (clock out remaining bits)
     * Response: bits 9-8 in rx[1] (lower 2 bits), bits 7-0 in rx[2].
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Convert ADC count to voltage. */
static double adc_to_voltage(int adc_value) {
    return ((double)adc_value / (double)ADC_MAX_VALUE) * VREF;
}

/* Convert sensor voltage to current (A). */
static double voltage_to_current(double voltage) {
    return (voltage - SENSOR_ZERO_CURRENT_V) / SENSOR_SENSITIVITY_V_PER_A;
}

/* Log current reading with timestamp. */
static void log_current(double current) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Current: %.4f A\n", timestamp, current);
    fflush(log_file);
}

/* Shutdown motor and log event. */
static void shutdown_motor(void) {
    fprintf(stderr, "OVERCURRENT DETECTED! Shutting down motor.\n");
    if (log_file != NULL) {
        fprintf(log_file, "OVERCURRENT DETECTED! Shutting down motor.\n");
        fflush(log_file);
    }
    gpioWrite(SHUTDOWN_GPIO, 1);
    gpioDelay(1000000);  /* 1 s */
    gpioWrite(SHUTDOWN_GPIO, 0);
    program_running = 0;
}

/* Signal handler for graceful shutdown. */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources. */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(SHUTDOWN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure shutdown GPIO */
    if (gpioSetMode(SHUTDOWN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SHUTDOWN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(SHUTDOWN_GPIO, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring motor current (MLX91209 via MCP3008 ch0)...\n");
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double current = voltage_to_current(voltage);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD_A) {
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

