#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000  /* 1 MHz */
#define SPI_FLAGS      0        /* Mode 0, active-low CE */
#define ADC_CHANNEL    0        /* MCP3008 single-ended channel 0 */
#define LOG_FILE       "methane_log.txt"
#define LEAK_THRESHOLD 1000.0f  /* PPM */
#define ADC_MAX        1023     /* 10-bit ADC full-scale */
#define PPM_MAX        5000.0f  /* PPM at full-scale */
#define SAMPLE_PERIOD  1.0     /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (value stored in *out), -1 on SPI error.
 */
static int read_mcp3008(int handle, int channel, int *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (dummy, clocks out low 2 bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0, 0, 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *out = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static float adc_to_ppm(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX) adc_value = ADC_MAX;
    return (float)adc_value * PPM_MAX / (float)ADC_MAX;
}

static void log_reading(FILE *fp, float ppm)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fflush(fp);
}

static void check_leak(float ppm)
{
    if (ppm > LEAK_THRESHOLD) {
        fprintf(stderr, "*** LEAK ALARM *** Methane concentration: %.2f PPM\n", ppm);
    }
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus 0, channel 0, 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed\n");
        fclose(fp);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Methane monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;

        if (read_mcp3008(g_spi_handle, ADC_CHANNEL, &adc_value) != 0) {
            /* SPI error: log and continue rather than crash */
            fprintf(stderr, "ADC read error; continuing\n");
        } else {
            float ppm = adc_to_ppm(adc_value);
            log_reading(fp, ppm);
            check_leak(ppm);
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    fclose(fp);
    spiClose(g_spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

