#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_PGA_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128SPS 0x0080
#define ADS1115_OS_BEGIN 0x8000
#define ADS1115_CHANNEL_AIN0 0x4000
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// MLX90830 Transfer Function (Linear)
#define SENSOR_OFFSET 0.5 // Volts at 0 kPa
#define SENSOR_SENSITIVITY 0.1 // V/kPa
#define MIN_PRESSURE 0.0 // kPa
#define MAX_PRESSURE 100.0 // kPa

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_pressure(int16_t raw_value);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

// Initialize I2C communication with ADS1115
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

// Read raw 16-bit value from ADS1115 channel AIN0
int read_ads1115(int16_t *raw_value) {
    uint16_t config = ADS1115_OS_BEGIN | ADS1115_CHANNEL_AIN0 | ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE | ADS1115_DR_128SPS;
    char config_buf[3];
    config_buf[0] = ADS1115_CONFIG_REG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion register
    char reg_buf[1] = {ADS1115_CONVERSION_REG};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error setting conversion register pointer: %s\n", strerror(errno));
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
