#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define HUMIDITY_CHANNEL 0
#define THERMISTOR_CHANNEL 1
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

float calculate_humidity(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) return -1.0;
    float vout = (float)adc_value / 4095.0 * 5.0;
    return 100.0 * (0.824 + 0.0315 * vout);
}

float calculate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 4095) return -1.0;
    float vout = (float)adc_value / 4095.0 * 5.0;
    float beta = 3950.0;
    float r0 = 10000.0;
    float r = r0 * (5.0 - vout) / vout;
    float t = 1.0 / (1.0 / 298.15 + 1.0 / beta * log(r / r0));
    return t - 273.15;
}

int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return -1;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, humidity, temperature);
    fclose(fp);
    return 0;
}

int send_email_alert(float humidity, float temperature) {
    char cmd[512];
    snprintf(cmd, sizeof(cmd),
             "echo \"Subject: Humidity Alert\\n\\nHumidity: %.2f%%, Temperature: %.2fC\" | ssmtp %s",
             humidity, temperature, EMAIL_RECIPIENT);
    return system(cmd);
}

int main() {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        int hum_raw = read_mcp3208(HUMIDITY_CHANNEL);
        int therm_raw = read_mcp3208(THERMISTOR_CHANNEL);

        if (hum_raw < 0 || therm_raw < 0) {
            fprintf(stderr, "SPI transfer error\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float humidity = calculate_humidity(hum_raw);
        float temperature = calculate_temperature(therm_raw);

        if (humidity < 0 || temperature < 0) {
            fprintf(stderr, "Invalid sensor data\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Log write failed\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            if (send_email_alert(humidity, temperature) != 0) {
                fprintf(stderr, "Email send failed\n");
            }
        }

        sleep(SAMPLE_INTERVAL);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

