#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNELS   3          /* X, Y, Z */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3        /* ADC reference voltage */
#define ADC_ZERO_G     1.65       /* ADC value at 0g */
#define SENSITIVITY    0.3        /* 300 mV/g */
#define IMPACT_THRESHOLD 2.0      /* g */
#define SAMPLE_RATE_HZ 100
#define LOG_FILE       "impact_log.txt"

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int read_adc(int channel);
static double adc_to_g(int adc_value);
static void log_data(int x, int y, int z, double xg, double yg, double zg);
static void signal_handler(int sig);
static void cleanup(void);

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0..1023 on success, -1 on SPI error, -2 on out-of-range.
 */
static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    /* Assert CS (active low) */
    gpioWrite(8, 0);

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d)\n", channel, ret);
        gpioWrite(8, 1);
        return -1;
    }

    /* De-assert CS */
    gpioWrite(8, 1);

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    int value = ((rx[1] & 0x03) << 8) | rx[2];

    if (value < 0 || value > ADC_MAX_VALUE) {
        fprintf(stderr, "ADC value out of range on channel %d: %d\n", channel, value);
        return -2;
    }
    return value;
}

/* Convert ADC count to acceleration in g (3.3V supply, 300 mV/g) */
static double adc_to_g(int adc_value) {
    return (adc_value - ADC_ZERO_G) * SENSITIVITY;
}

/* Append one timestamped data row to the log file */
static void log_data(int x, int y, int z, double xg, double yg, double zg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d,%.3f,%.3f,%.3f\n",
            ts, x, y, z, xg, yg, zg);
    fflush(log_file);

    if (fabs(xg) > IMPACT_THRESHOLD ||
        fabs(yg) > IMPACT_THRESHOLD ||
        fabs(zg) > IMPACT_THRESHOLD) {
        fprintf(log_file, "%s,IMPACT DETECTED\n", ts);
        fflush(log_file);
    }
}

/* Signal handler for graceful shutdown (SIGINT / SIGTERM) */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Release all resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure CS pin as output, de-asserted (active low) */
    gpioSetMode(8, PI_OUTPUT);
    gpioWrite(8, 1);

    /* Open SPI0 CE0 at 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_adc,y_adc,z_adc,x_g,y_g,z_g\n");
        fflush(log_file);
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 + MCP3008 logging started. Sampling at %d Hz. Press Ctrl+C to stop.\n",
           SAMPLE_RATE_HZ);

    /* Main sampling loop */
    while (!terminate) {
        int x = read_adc(0);
        int y = read_adc(1);
        int z = read_adc(2);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error (x=%d y=%d z=%d); skipping sample\n", x, y, z);
            gpioDelay(1000000 / SAMPLE_RATE_HZ);
            continue;
        }

        double xg = adc_to_g(x);
        double yg = adc_to_g(y);
        double zg = adc_to_g(z);

        log_data(x, y, z, xg, yg, zg);

        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

