#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/*
 * Raspberry Pi Zero W - Si1172-A30-GMR Optical Heart Rate Sensor
 *
 * NOTE: The Si1172 is a proprietary sensor with a closed algorithm.
 * This program reads raw PPG samples (IR + RED) and logs them as
 * proxy HR and SpO2 values. A proper implementation requires the
 * Si1172 SDK or a proprietary algorithm from Silicon Labs.
 *
 * Wiring:
 *   Si1172 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   Si1172 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   Si1172 VDD -> 3.3V
 *   Si1172 GND -> GND
 */

#define I2C_BUS        1
#define SI1172_ADDR    0x49

/* Si1172 register addresses (command-based protocol) */
#define SI1172_REG_COMMAND  0xC0
#define SI1172_REG_FIFO_DATA 0xC1
#define SI1172_REG_FIFO_COUNT 0xC2

/* Command codes */
#define SI1172_CMD_RESET      0x01
#define SI1172_CMD_START      0x02
#define SI1172_CMD_STOP       0x03
#define SI1172_CMD_ALS_FORCE  0x06

#define LOG_FILE_NAME "biometric_log.csv"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a Si1172 register                            */
/* ------------------------------------------------------------------ */
static int si1172_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (reg=0x%02X, val=0x%02X)\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a Si1172 register                           */
/* ------------------------------------------------------------------ */
static int si1172_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    char reg_buf[1];
    char data_buf[1];

    reg_buf[0] = (char)reg;

    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed (reg=0x%02X)\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
