            fprintf(stderr, "Error: Failed to convert ADC to flow rate\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (flow_rate < 0.0f || flow_rate > FLOW_RANGE) {
            fprintf(stderr, "Warning: Flow rate out of plausible range: %.2f L/min\n", flow_rate);
        }

        log_flow_rate(flow_rate);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

