#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define SAMPLE_RATE 44100
#define NUM_SAMPLES 1024
#define GAIN_DEFAULT 1.0f

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

int main(int argc, char *argv[]) {
    float gain = GAIN_DEFAULT;

    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0.0f) {
            fprintf(stderr, "Invalid gain value. Using default gain: %f\n", GAIN_DEFAULT);
            gain = GAIN_DEFAULT;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Audio Noise Cancellation (MP23ABS1 via MCP3008)\n");
    printf("Sample Rate: %d Hz, Gain: %f\n", SAMPLE_RATE, gain);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int audio_left = 0;
        int audio_right = 0;
        int error = 0;

        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val = read_mcp3008(0);
            if (val < 0) { error = 1; break; }
            audio_left += val;

            val = read_mcp3008(1);
            if (val < 0) { error = 1; break; }
            audio_right += val;
        }

        if (error) {
            fprintf(stderr, "Error reading audio data. Exiting.\n");
            break;
        }

        int16_t left_sample = (int16_t)(audio_left / NUM_SAMPLES);
        int16_t right_sample = (int16_t)(audio_right / NUM_SAMPLES);

        int16_t canceled_sample = (int16_t)((left_sample - right_sample) * gain);

        printf("%d,%d\n", left_sample, canceled_sample);
        fflush(stdout);

        gpioDelay(1000000 / SAMPLE_RATE);
    }

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

