#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

static int log_data(const char *timestamp, int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    fprintf(fp, "%s,%d\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("VH400 soil moisture logger started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);

    while (running) {
        time_t now = time(NULL);
        if (now == (time_t)-1) {
            perror("Error getting time");
            break;
        }
        struct tm *utc = gmtime(&now);
        if (!utc) {
            perror("Error converting time to UTC");
            break;
        }
        char timestamp[32];
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc) == 0) {
            fprintf(stderr, "Error: Failed to format timestamp\n");
            break;
        }

        int moisture = read_mcp3008(MCP3008_CHANNEL);
        if (moisture < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            break;
        }

        if (log_data(timestamp, moisture) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
            break;
        }

        printf("%s, Moisture: %d\n", timestamp, moisture);

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

