#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define BUZZER_GPIO 18
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3
#define VREF 3.3
#define ADC_MAX 1023.0

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    char buf[256];
    if (!fgets(buf, sizeof(buf), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    char *nl = strchr(buf, '\n');
    if (nl) *nl = '\0';
    char *cr = strchr(buf, '\r');
    if (cr) *cr = '\0';
    char *endptr;
    float t = strtof(buf, &endptr);
    if (endptr == buf || *endptr != '\0') {
        fprintf(stderr, "Invalid temperature value: %s\n", buf);
        return -1;
    }
    *temp = t;
    return 0;
}

static int read_mcp3008(int fd, int channel, int *value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(FILE *fp, int adc, float voltage, float comp_voltage, float temp, int flame) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%d,%.3f,%.3f,%.2f,%d\n", ts, adc, voltage, comp_voltage, temp, flame);
    fflush(fp);
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        fclose(log_fp);
        return 1;
    }
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_GPIO);
    if (!buzzer_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n", BUZZER_GPIO, strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(buzzer_line, "flame_buzzer", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return 1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return 1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        cleanup();
        return 1;
    }

    float ambient_temp = 25.0f;
    if (read_temperature(&ambient_temp) < 0) {
        fprintf(stderr, "Using default ambient temperature: %.2f\n", ambient_temp);
    } else {
        printf("Ambient temperature: %.2f\n", ambient_temp);
    }

    while (running) {
        int adc_value = -1;
        int retries = 0;
        while (retries < MAX_RETRIES && running) {
            if (read_mcp3008(spi_fd, 0, &adc_value) == 0) break;
            retries++;
            usleep(10000);
        }
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            log_data(log_fp, -1, -1.0f, -1.0f, ambient_temp, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "ADC value out of range: %d\n", adc_value);
            log_data(log_fp, adc_value, -1.0f, -1.0f, ambient_temp, 0);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        float voltage = (float)adc_value * VREF / ADC_MAX;
        float comp_voltage = voltage + (ambient_temp - 25.0f) * 0.001f;
        int flame = (comp_voltage > 1.0f) ? 1 : 0;

        if (gpiod_line_set_value(buzzer_line, flame) < 0) {
            fprintf(stderr, "Failed to set buzzer: %s\n", strerror(errno));
        }

        log_data(log_fp, adc_value, voltage, comp_voltage, ambient_temp, flame);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    close(spi_fd);
    printf("\nExiting gracefully.\n");
    return 0;
}

