#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_GPIO    17
#define WATER_HIGH  75.0
#define WATER_LOW   70.0
#define JSON_FILE   "water_levels.json"
#define SAMPLE_US   5000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_percent(int adc_value) {
    return (double)adc_value / 1023.0 * 100.0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

static int log_to_json(double water_level) {
    char ts[40];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(json_fp, "  { \"timestamp\": \"%s\", \"water_level\": %.2f },\n", ts, water_level) < 0) {
        perror("fprintf to JSON failed");
        return -1;
    }
    fflush(json_fp);
    return 0;
}

static void control_led(double water_level) {
    if (water_level > WATER_HIGH) {
        gpioWrite(LED_GPIO, 1);
    } else if (water_level < WATER_LOW) {
        gpioWrite(LED_GPIO, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    json_fp = fopen(JSON_FILE, "w");
    if (!json_fp) {
        perror("Failed to open JSON file");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(json_fp, "[\n");
    fflush(json_fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            gpioDelay(100000);
            continue;
        }
        double level = adc_to_percent(adc);
        if (log_to_json(level) != 0) {
            fprintf(stderr, "JSON logging failed; continuing\n");
        }
        control_led(level);
        gpioDelay(SAMPLE_US);
    }

    fprintf(json_fp, "]\n");
    fclose(json_fp);
    json_fp = NULL;

    gpioWrite(LED_GPIO, 0);
    spiClose(spi_handle);
    spi_handle = -1;
    gpioTerminate();

    return EXIT_SUCCESS;
}

