#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_RAW 300
#define DEFAULT_MAX_RAW 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60
#define DEFAULT_RECIPIENT_EMAIL "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG_FILE "/path/to/msmtprc"
#define LOG_FILE "plant_data.txt"
#define SPI_SPEED 500000
#define SPI_FLAGS 0
#define ADC_MAX 1023

static int spi_channel = DEFAULT_SPI_CHANNEL;
static int adc_channel = DEFAULT_ADC_CHANNEL;
static int min_raw = DEFAULT_MIN_RAW;
static int max_raw = DEFAULT_MAX_RAW;
static int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
static int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
static char *recipient_email = DEFAULT_RECIPIENT_EMAIL;
static char *msmtp_config_file = DEFAULT_MSMTP_CONFIG_FILE;
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | channel) << 4;
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, (char *)tx_buf, (char *)rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

static float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Error: Invalid calibration values (min_raw=%d, max_raw=%d)\n", min_raw, max_raw);
        return -1.0f;
    }

    float percentage = 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw)) * 100.0f;
    if (percentage < 0.0f) percentage = 0.0f;
    if (percentage > 100.0f) percentage = 100.0f;
    return percentage;
}

static int log_data(float moisture_percentage) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file\n");
        return -1;
    }

    return 0;
}

static int send_email_alert(float moisture_percentage) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "msmtp -a %s -t <<EOF\n"
        "To: %s\n"
        "Subject: Plant Moisture Alert\n"
        "\n"
        "Plant moisture is low! Current moisture level: %.2f%%\n"
        "EOF",
        msmtp_config_file, recipient_email, moisture_percentage);

    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: Command buffer too small\n");
        return -1;
    }

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp via popen\n");
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed\n");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    if (WIFSIGNALED(status)) {
        fprintf(stderr, "Error: msmtp killed by signal %d\n", WTERMSIG(status));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:f:r:e:h")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_raw = atoi(optarg); break;
            case 'M': max_raw = atoi(optarg); break;
            case 't': moisture_threshold = atoi(optarg); break;
            case 'f': logging_frequency = atoi(optarg); break;
            case 'r': recipient_email = optarg; break;
            case 'e': msmtp_config_file = optarg; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw] [-M max_raw] [-t threshold] [-f frequency] [-r recipient_email] [-e msmtp_config_file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Plant moisture monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_value = read_adc(adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", logging_frequency);
            sleep(logging_frequency);
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(raw_value, min_raw, max_raw);
        if (moisture_percentage < 0.0f) {
            fprintf(stderr, "Error: Failed to calculate moisture percentage\n");
            sleep(logging_frequency);
            continue;
        }

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }

        printf("Raw ADC: %d, Moisture: %.2f%%\n", raw_value, moisture_percentage);

        if (moisture_percentage < moisture_threshold) {
            if (send_email_alert(moisture_percentage) != 0) {
                fprintf(stderr, "Warning: Failed to send email alert\n");
            }
        }

        sleep(logging_frequency);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

