#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 5

#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int fd, int channel, uint16_t *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    *adc_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static float adc_to_moisture(uint16_t adc_value) {
    if (adc_value <= MIN_ADC_VALUE) return 0.0f;
    if (adc_value >= MAX_ADC_VALUE) return 100.0f;
    return ((float)(adc_value - MIN_ADC_VALUE) /
            (float)(MAX_ADC_VALUE - MIN_ADC_VALUE)) * 100.0f;
}

static void log_reading(float moisture_pct) {
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    printf("[%s] Moisture: %.2f%% (ADC: %u)\n", ts, moisture_pct,
           (unsigned int)(moisture_pct * 100.0f));
    fflush(stdout);
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("MCP3008 Soil Moisture Sensor Reader\n");
    printf("SPI device: %s | Mode: %d | Speed: %d Hz | Channel: %d\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, MCP3008_CHANNEL);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(fd, MCP3008_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "SPI read error — continuing after delay.\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        /* Sensor-absent / bus-fault heuristics */
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Warning: ADC value at rail (%u) — possible wiring fault.\n",
                    (unsigned)adc_value);
        }

        float moisture = adc_to_moisture(adc_value);
        log_reading(moisture);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

