#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL_MS 5000
#define LOG_BUFFER_SIZE 20

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

static LogEntry log_buffer[LOG_BUFFER_SIZE];
static int log_index = 0;
static int log_count = 0;
static int pump_state = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void control_pump(int moisture_level) {
    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_state = 1;
            printf("Pump ON (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to set pump GPIO high\n");
        }
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_state = 0;
            printf("Pump OFF (moisture=%d)\n", moisture_level);
        } else {
            fprintf(stderr, "Failed to set pump GPIO low\n");
        }
    }
}

static void log_data(int moisture_level) {
    time_t now = time(NULL);
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pump_state;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
    if (log_count < LOG_BUFFER_SIZE) log_count++;
}

static void print_log_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", log_count);
    for (int i = 0; i < log_count; i++) {
        int idx = (log_index - log_count + i + LOG_BUFFER_SIZE) % LOG_BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Moisture=%d Pump=%s\n",
               ts, log_buffer[idx].moisture_level,
               log_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("------------------------------\n");
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int moisture = read_mcp3008(0);
    if (moisture < 0) {
        fprintf(stderr, "Skipping sample due to SPI error\n");
        return;
    }
    control_pump(moisture);
    log_data(moisture);
    print_log_buffer();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set pigpio timer\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Monitoring System started.\n");
    printf("SPI: channel %d, speed %d Hz, mode 0 | Pump: GPIO%d | Thresholds: ON<%d, OFF>%d\n",
           SPI_CHANNEL, SPI_SPEED, PUMP_GPIO, MOISTURE_LOW_THRESHOLD, MOISTURE_HIGH_THRESHOLD);

    while (running) {
        sleep(1);
    }

    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, NULL, NULL);
    gpioWrite(PUMP_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

