#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15

#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define MAX_SAMPLES 100

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = {(char)reg, (char)value};
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, pigpio_error(i2cWriteDevice(handle, buf, 2)));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed (reg 0x%02X): %s\n", reg, pigpio_error(i2cWriteDevice(handle, reg_buf, 1)));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, pigpio_error(i2cReadDevice(handle, data_buf, 1)));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_burst(int handle, uint8_t reg, uint8_t *buf, int len) {
    char reg_buf[1] = {(char)reg};
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C burst write (reg select) failed (reg 0x%02X): %s\n", reg, pigpio_error(i2cWriteDevice(handle, reg_buf, 1)));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C burst read failed (reg 0x%02X, len %d): %s\n", reg, len, pigpio_error(i2cReadDevice(handle, (char *)buf, len)));
        return -1;
    }
    return 0;
}

static int max30102_init(int handle) {
    uint8_t part_id;
    if (i2c_read_reg(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID - sensor may be absent\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x40) != 0) return -1;
    gpioDelay(10000);

    if (i2c_write_reg(handle, REG_INTR_ENABLE_1, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_INTR_ENABLE_2, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_RD_PTR, 0x00) != 0) return -1;
    if (i2c_write_reg(handle, REG_FIFO_CONFIG, 0x4F) != 0) return -1;
    if (i2c_write_reg(handle, REG_MODE_CONFIG, 0x03) != 0) return -1;
    if (i2c_write_reg(handle, REG_SPO2_CONFIG, 0x27) != 0) return -1;
    if (i2c_write_reg(handle, REG_LED1_PA, 0x24) != 0) return -1;
    if (i2c_write_reg(handle, REG_LED2_PA, 0x24) != 0) return -1;

    return 0;
}

static int read_fifo_sample(int handle, uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(handle, REG_FIFO_DATA, buf, 6) != 0) return -1;
    *red = ((uint32_t)(buf[0] & 0x03) << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir = ((uint32_t)(buf[3] & 0x03) << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static void log_health_data(float spo2, float heart_rate) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening health_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, SpO2: %.2f%%, Heart Rate: %.2f BPM\n", timestamp, spo2, heart_rate);
    fclose(fp);
}

static void log_error(const char *msg) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening health_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, ERROR: %s\n", timestamp, msg);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device (bus %d, addr 0x%02X): %s\n", I2C_BUS, MAX30102_ADDR, pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (max30102_init(i2c_handle) != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MAX30102 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t red_buf[MAX_SAMPLES], ir_buf[MAX_SAMPLES];
        int sample_count = 0;

        while (sample_count < MAX_SAMPLES && running) {
            uint32_t red, ir;
            if (read_fifo_sample(i2c_handle, &red, &ir) != 0) {
                fprintf(stderr, "FIFO read error, retrying...\n");
                gpioDelay(10000);
                continue;
            }
            red_buf[sample_count] = red;
            ir_buf[sample_count] = ir;
            sample_count++;
            gpioDelay(SAMPLE_PERIOD_US);
        }

        if (!running) break;

        if (sample_count == 0) {
            fprintf(stderr, "No samples captured, skipping analysis\n");
            continue;
        }

        float ir_data[MAX_SAMPLES];
        for (int i = 0; i < sample_count; i++) ir_data[i] = (float)ir_buf[i];

        int peak_index = 0;
        float peak_val = ir_data[0];
        for (int i = 1; i < sample_count; i++) {
            if (ir_data[i] > peak_val) {
                peak_val = ir_data[i];
                peak_index = i;
            }
        }

        int start_index = (peak_index > 1) ? peak_index - 2 : 0;
        int end_index = (peak_index + 2 < sample_count) ? peak_index + 3 : sample_count;

        float sum = 0.0f;
        for (int i = start_index; i < end_index; i++) sum += ir_data[i];
        float avg_ir = sum / (end_index - start_index);

        float heart_rate = 0.0f;
        if (avg_ir > 0.0f) {
            float diff = ir_data[peak_index] - avg_ir;
            if (diff > 0.0f) heart_rate = (60.0f / (diff * 0.000001f));
        }

        float spo2 = 95.0f;
        if (heart_rate > 0.0f) {
            spo2 = 95.0f - (heart_rate - 60.0f) * 0.1f;
            if (spo2 < 80.0f) spo2 = 80.0f;
            if (spo2 > 100.0f) spo2 = 100.0f;
        }

        if (spo2 < 95.0f) {
            log_health_data(spo2, heart_rate);
            printf("SpO2: %.2f%%, Heart Rate: %.2f BPM (logged)\n", spo2, heart_rate);
        } else {
            printf("SpO2: %.2f%%, Heart Rate: %.2f BPM\n", spo2, heart_rate);
        }
    }

    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

