#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01
#define ADS1115_REG_LO_THRESH  0x02
#define ADS1115_REG_HI_THRESH  0x03

#define RELAY_GPIO     17
#define REED_GPIO      27
#define NUM_BASELINE   10
#define POLL_MS        200
#define RELAY_HOLD_MS  3000
#define LOG_FILE       "/var/log/door_events.log"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t cfg = 0x8483;
    cfg |= (1 << 15);
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg) < 0) return -1;
    usleep(10000);
    return 0;
}

static int ads1115_read_raw(int fd, int16_t *raw) {
    uint16_t val;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &val) < 0) return -1;
    *raw = (int16_t)val;
    return 0;
}

static int read_distance(int16_t *raw) {
    if (ads1115_read_raw(i2c_fd, raw) < 0) return -1;
    if (*raw < -32768) return -1;
    return 0;
}

static int calibrate_threshold(int *threshold) {
    long sum = 0;
    int16_t r;
    for (int i = 0; i < NUM_BASELINE; i++) {
        if (read_distance(&r) < 0) return -1;
        sum += r;
        usleep(50000);
    }
    *threshold = (int)(sum / NUM_BASELINE * 0.8);
    return 0;
}

static void cleanup(void) {
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (relay_line) gpiod_line_release(relay_line);
    if (reed_line) gpiod_line_release(reed_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }
    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    reed_line = gpiod_chip_get_line(chip, REED_GPIO);
    if (!relay_line || !reed_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(relay_line, "door_relay", 0) < 0) {
        perror("relay request_output");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("reed request_input");
        cleanup();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c");
        cleanup();
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }
    if (ads1115_init(i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 init failed\n");
        cleanup();
        return 1;
    }

    int threshold = 0;
    if (calibrate_threshold(&threshold) < 0) {
        log_event("Error: calibration failed (sensor absent?)");
        cleanup();
        return 1;
    }
    printf("Calibrated threshold: %d\n", threshold);

    while (running) {
        int16_t raw;
        if (read_distance(&raw) < 0) {
            log_event("Error: I2C read failure");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (raw < threshold) {
            log_event("Distance below threshold, releasing lock");
            gpiod_line_set_value(relay_line, 1);
            usleep(RELAY_HOLD_MS * 1000);
            gpiod_line_set_value(relay_line, 0);
            int reed = gpiod_line_get_value(reed_line);
            if (reed < 0) {
                log_event("Error: reed read failure");
            } else if (reed == 0) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }
        usleep(POLL_MS * 1000);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

