#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define LOG_FILE "irrigation.log"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Invalid MCP3008 channel");
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "SPI transfer failed (attempt %d/%d), ret=%d", attempt + 1, MAX_RETRIES, ret);
        log_message(msg);
        gpioDelay(100000);
    }
    log_message("SPI transfer failed after all retries");
    return -1;
}

static float adc_to_moisture(int adc_value, int dry_adc, int wet_adc) {
    if (dry_adc <= wet_adc) {
        log_message("Invalid calibration bounds (dry <= wet)");
        return 0.0f;
    }
    float pct = 100.0f - ((float)(adc_value - wet_adc) / (float)(dry_adc - wet_adc)) * 100.0f;
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", state ? "activated" : "deactivated");
    log_message(msg);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': threshold = atoi(optarg); break;
            case 'd': duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (threshold < 0 || threshold > 100) {
        fprintf(stderr, "Threshold must be 0-100\n");
        return EXIT_FAILURE;
    }
    if (duration <= 0) {
        fprintf(stderr, "Duration must be positive\n");
        return EXIT_FAILURE;
    }
    if (sleep_interval <= 0) {
        fprintf(stderr, "Sleep interval must be positive\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            log_message("Skipping irrigation cycle due to SPI read error");
            gpioDelay(sleep_interval * 1000000);
            continue;
        }
        float moisture = adc_to_moisture(adc, 200, 800);
        char msg[128];
        snprintf(msg, sizeof(msg), "Moisture: %.2f%% (ADC: %d)", moisture, adc);
        log_message(msg);

        if (moisture < threshold) {
            log_message("Moisture below threshold, activating pump");
            control_pump(1);
            gpioDelay(duration * 1000000);
            control_pump(0);
            log_message("Pump deactivated");
        }
        gpioDelay(sleep_interval * 1000000);
    }

    log_message("Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

