#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_OS_SINGLE 0x8000
#define ADS1115_MUX_AIN0_GND 0x4000
#define ADS1115_PGA_4_096V 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128_SPS 0x0080
#define ADS1115_CQUE_NONE 0x0003
#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL_US 1000000
#define VREF 3.3
#define ZERO_FIELD_V 2.5
#define SENSITIVITY 0.0014
#define THRESHOLD_GAUSS 500.0

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_ads1115(void) {
    uint16_t config = ADS1115_OS_SINGLE | ADS1115_MUX_AIN0_GND |
                      ADS1115_PGA_4_096V | ADS1115_MODE_SINGLE |
                      ADS1115_DR_128_SPS | ADS1115_CQUE_NONE;
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config");
        return -1;
    }
    return 0;
}

static int read_ads1115(int16_t *raw) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "Failed to set conversion register pointer");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion");
        return -1;
    }
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static float voltage_to_gauss(float v) {
    return (v - ZERO_FIELD_V) / SENSITIVITY;
}

static void buffer_add(CircularBuffer *cb, float g) {
    cb->buffer[cb->head] = g;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float buffer_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("hall_sensor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "I2C open failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_ads1115() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    CircularBuffer cb = {0};
    cb.head = 0;
    cb.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Hall sensor monitoring started");

    while (!terminate) {
        int16_t raw;
        if (read_ads1115(&raw) < 0) {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float voltage = (raw / 32767.0f) * VREF;
        if (voltage < 0.0f || voltage > VREF) {
            syslog(LOG_ERR, "Invalid voltage: %.3f V", voltage);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float gauss = voltage_to_gauss(voltage);
        buffer_add(&cb, gauss);
        float avg = buffer_average(&cb);

        syslog(LOG_INFO, "Voltage: %.3f V, Gauss: %.2f, Avg: %.2f",
               voltage, gauss, avg);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss", avg);
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

