#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define PWM_PIN     18
#define PWM_FREQ    1000
#define PWM_RANGE   1023
#define ADC_CHANNEL 0
#define SAMPLE_US  100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a single-ended channel from the MCP3008 via SPI.
 * Returns 0-1023 on success, -1 on error. */
static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then 10 data bits.
     * tx[0] = 0x01 (start)
     * tx[1] = (0x08 | channel) << 4  ->  SGL/DIFF=1, channel in upper nibble
     * tx[2] = 0x00 (don't care)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with PWM off */
    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 PWM control started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error; skipping PWM update\n");
        } else {
            if (gpioPWM(PWM_PIN, adc_value) != 0) {
                fprintf(stderr, "gpioPWM failed for duty %d\n", adc_value);
            }
            printf("ADC: %4d  PWM: %4d\n", adc_value, adc_value);
        }
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

