                fprintf(stderr, "gpioPWM failed for duty %d\n", adc_value);
            }
            printf("ADC: %4d  PWM: %4d\n", adc_value, adc_value);
        }
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioPWM(PWM_PIN, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

