#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000
#define BLINK_DURATION_US 1000000
#define BLINK_HALF_US 50000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115(int handle) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC0; /* AIN0 single-ended, PGA=4.096V, single-shot, 128 SPS */
    config[2] = 0x83; /* MUX=AIN0, PGA=4.096V, single-shot, 128 SPS */

    if (i2cWriteDevice(handle, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config.\n");
        return -1;
    }

    gpioDelay(8000); /* 8 ms > 1/128 SPS */

    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion.\n");
        return -1;
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

static double adc_to_gauss(int16_t raw) {
    /* ADS1115 PGA=4.096V, 16-bit signed => LSB = 4.096V / 32768 = 0.000125 V */
    double voltage = (raw * 4.096) / 32768.0;
    /* SS49E: 1.65V at 0 Gauss, sensitivity 0.001 V/Gauss => 1000 Gauss/V */
    return (voltage - 1.65) / 0.001;
}

static void blink_led(int gpio, int duration_us) {
    gpioWrite(gpio, 1);
    gpioDelay(BLINK_HALF_US);
    gpioWrite(gpio, 0);
    gpioDelay(BLINK_HALF_US);
}

int main(int argc, char *argv[]) {
    double threshold = 100.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Error: Threshold must be positive.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring magnetic field (threshold: %.2f Gauss)...\n", threshold);

    while (running) {
        int16_t raw = read_ads1115(i2c_handle);
        if (raw < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double field = adc_to_gauss(raw);
        printf("Magnetic Field: %.2f Gauss\n", field);

        if (field > threshold) {
            printf("Threshold exceeded! Blinking LED.\n");
            for (int i = 0; i < 5 && running; i++) {
                blink_led(LED_GPIO, BLINK_DURATION_US);
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

