#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define RELAY_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC_PUMP "pump_control"
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define SAMPLE_INTERVAL_SEC 60
#define ADC_MAX 1023
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_soil_moisture(void) {
    int raw = read_mcp3008(ADC_CHANNEL);
    if (raw < 0) return -1;
    return (int)(((float)raw / (float)ADC_MAX) * 100.0f);
}

static void control_pump(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write relay GPIO %d", RELAY_GPIO);
    } else {
        syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    }
}

static void pump_control_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        if (strncmp((const char *)message->payload, "on", 2) == 0) {
            control_pump(1);
        } else if (strncmp((const char *)message->payload, "off", 3) == 0) {
            control_pump(0);
        } else {
            syslog(LOG_WARNING, "Invalid pump command: %s", (const char *)message->payload);
        }
    }
}

static void publish_moisture(int moisture) {
    if (mosq) {
        char payload[16];
        snprintf(payload, sizeof(payload), "%d", moisture);
        int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC_MOISTURE, (int)strlen(payload), payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        }
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay GPIO %d as output", RELAY_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        cleanup();
        return EXIT_FAILURE;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_PUMP, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed: %s", mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_message_callback_set(mosq, pump_control_callback);

    while (running) {
        int moisture = read_soil_moisture();
        if (moisture < 0) {
            syslog(LOG_ERR, "Sensor read error");
        } else if (moisture < 0 || moisture > 100) {
            syslog(LOG_WARNING, "Sensor value out of range: %d", moisture);
        } else {
            publish_moisture(moisture);
            if (moisture < MOISTURE_THRESHOLD_LOW) {
                control_pump(1);
            } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
                control_pump(0);
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

