            fprintf(stderr, "ADC read error, skipping iteration\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        if (adc_value > THRESHOLD) {
            int duty_cycle = (int)(((float)adc_value / 1023.0f) * PWM_RANGE);
            set_motor_pwm(MOTOR1_GPIO, duty_cycle);
            set_motor_pwm(MOTOR2_GPIO, duty_cycle);
            log_event(adc_value);
        } else {
            set_motor_pwm(MOTOR1_GPIO, 0);
            set_motor_pwm(MOTOR2_GPIO, 0);
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_motor_pwm(MOTOR1_GPIO, 0);
    set_motor_pwm(MOTOR2_GPIO, 0);

    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

