#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONT_HRES2 0x11
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {0};
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_bh1750(int fd) {
    unsigned char cmd = BH1750_CONT_HRES2;
    if (write(fd, &cmd, 1) != 1) return -1;
    usleep(180000);
    unsigned char buf[2] = {0};
    if (read(fd, buf, 2) != 2) return -1;
    return (buf[0] << 8) | buf[1];
}

static void log_data(FILE *fp, int sound_level, int light_level, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[24];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, sound_level, light_level, error_code);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open SPI"); return 1; }
    unsigned int speed = SPI_SPEED;
    unsigned char bits = 8;
    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI config"); close(spi_fd); return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) { perror("open I2C"); close(spi_fd); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("I2C slave"); close(i2c_fd); close(spi_fd); return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("open log"); close(i2c_fd); close(spi_fd); return 1; }

    while (running) {
        int sound_level = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        int light_level = read_bh1750(i2c_fd);
        int error_code = 0;
        if (sound_level < 0) error_code |= 0x01;
        if (light_level < 0) error_code |= 0x02;
        log_data(log_fp, sound_level, light_level, error_code);
        sleep(SAMPLE_INTERVAL);
    }

    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

