#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define MCP3008_CHANNEL 0
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL 60

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d), ret=%d\n", attempt + 1, MAX_RETRIES, ret);
        gpioDelay(100000);
    }
    return -1;
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1.0f;
    float voltage = (adc_value / 1023.0f) * 3.3f;
    float moisture = (voltage / 3.0f) * 100.0f;
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    return moisture;
}

static void control_pump(float moisture) {
    if (moisture < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1);
        printf("Pump ON (Moisture: %.2f%%)\n", moisture);
    } else {
        gpioWrite(PUMP_GPIO, 0);
        printf("Pump OFF (Moisture: %.2f%%)\n", moisture);
    }
}

static void log_data(float moisture) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        float moisture = adc_to_moisture(adc_value);
        if (moisture < 0.0f) {
            fprintf(stderr, "Invalid moisture reading\n");
            gpioDelay(SAMPLE_INTERVAL * 1000000);
            continue;
        }

        control_pump(moisture);
        log_data(moisture);

        gpioDelay(SAMPLE_INTERVAL * 1000000);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

