#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define PWM_DEVICE "/sys/class/pwm/pwmchip0/pwm0"
#define CONFIG_FILE "theremin_config.txt"

#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define MIN_DUTY 0
#define MAX_DUTY 1000000

#define TIMEOUT_US 30000
#define ECHO_SETTLE_US 1000
#define LOOP_DELAY_US 100000

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

typedef struct {
    float min_distance;
    float max_distance;
    float min_frequency;
    float max_frequency;
    float min_duty;
    float max_duty;
} calibration_data_t;

calibration_data_t calibration = {
    .min_distance = 2.0,
    .max_distance = 400.0,
    .min_frequency = 220.0,
    .max_frequency = 880.0,
    .min_duty = 0.0,
    .max_duty = 100.0
};

int spi_fd = -1;
struct gpiod_chip *chip = NULL;
struct gpiod_line *trig_line = NULL;
struct gpiod_line *echo_line = NULL;

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }
    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

int init_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) {
        perror("Failed to request trig line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(echo_line, "theremin") < 0) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trig_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

int init_pwm() {
    FILE *f = fopen(PWM_DEVICE "export", "w");
    if (!f) {
        perror("Failed to export PWM");
        return -1;
    }
    fclose(f);
    usleep(100000);
    f = fopen(PWM_DEVICE "period", "w");
    if (!f) {
        perror("Failed to set PWM period");
        return -1;
    }
    fprintf(f, "%d", 1000000);
    fclose(f);
    f = fopen(PWM_DEVICE "duty_cycle", "w");
    if (!f) {
        perror("Failed to set PWM duty cycle");
        return -1;
    }
    fprintf(f, "%d", 0);
    fclose(f);
    f = fopen(PWM_DEVICE "enable", "w");
    if (!f) {
        perror("Failed to enable PWM");
        return -1;
    }
    fprintf(f, "1");
    fclose(f);
    return 0;
}

void set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > MAX_DUTY) duty = MAX_DUTY;
    FILE *f = fopen(PWM_DEVICE "duty_cycle", "w");
    if (f) {
        fprintf(f, "%d", duty);
        fclose(f);
    }
}

float read_distance() {
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;
    usleep(2);
    if (gpiod_line_set_value(trig_line, 1) < 0) return -1.0;
    usleep(10);
    if (gpiod_line_set_value(trig_line, 0) < 0) return -1.0;

    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed > TIMEOUT_US) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed > TIMEOUT_US) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &now);
    long pulse_width = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;
    return (float)pulse_width / 58.0;
}

float map_distance_to_frequency(float distance) {
    if (distance < calibration.min_distance) distance = calibration.min_distance;
    if (distance > calibration.max_distance) distance = calibration.max_distance;
    return calibration.min_frequency + (distance - calibration.min_distance) * (calibration.max_frequency - calibration.min_frequency) / (calibration.max_distance - calibration.min_distance);
}

float map_photoresistor_to_duty(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return calibration.min_duty + (float)adc_value / 1023.0 * (calibration.max_duty - calibration.min_duty);
}

void save_calibration(const char *filename) {
    FILE *f = fopen(filename, "w");
    if (!f) {
        perror("Failed to open config file for writing");
        return;
    }
    fprintf(f, "%f,%f,%f,%f,%f,%f\n",
            calibration.min_distance, calibration.max_distance,
            calibration.min_frequency, calibration.max_frequency,
            calibration.min_duty, calibration.max_duty);
    fclose(f);
}

void load_calibration(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) return;
    if (fscanf(f, "%f,%f,%f,%f,%f,%f",
               &calibration.min_distance, &calibration.max_distance,
               &calibration.min_frequency, &calibration.max_frequency,
               &calibration.min_duty, &calibration.max_duty) == 6) {
        printf("Calibration loaded: min_dist=%.2f, max_dist=%.2f, min_freq=%.2f, max_freq=%.2f, min_duty=%.2f, max_duty=%.2f\n",
               calibration.min_distance, calibration.max_distance,
               calibration.min_frequency, calibration.max_frequency,
               calibration.min_duty, calibration.max_duty);
    } else {
        fprintf(stderr, "Failed to parse calibration file\n");
    }
    fclose(f);
}

void cleanup() {
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    FILE *f = fopen(PWM_DEVICE "enable", "w");
    if (f) {
        fprintf(f, "0");
        fclose(f);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_spi() < 0) {
        fprintf(stderr, "SPI init failed\n");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO init failed\n");
        cleanup();
        return 1;
    }
    if (init_pwm() < 0) {
        fprintf(stderr, "PWM init failed\n");
        cleanup();
        return 1;
    }

    load_calibration(CONFIG_FILE);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        float frequency = map_distance_to_frequency(distance);
        int pwm_freq = (int)frequency;
        if (pwm_freq < MIN_FREQUENCY) pwm_freq = MIN_FREQUENCY;
        if (pwm_freq > MAX_FREQUENCY) pwm_freq = MAX_FREQUENCY;
        FILE *f = fopen(PWM_DEVICE "period", "w");
        if (f) {
            fprintf(f, "%d", 1000000 / pwm_freq);
            fclose(f);
        }
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        float duty = map_photoresistor_to_duty(adc_value);
        int duty_int = (int)duty;
        if (duty_int < MIN_DUTY) duty_int = MIN_DUTY;
        if (duty_int > MAX_DUTY) duty_int = MAX_DUTY;
        set_pwm_duty(duty_int);
        usleep(LOOP_DELAY_US);
    }

    cleanup();
    printf("Theremin stopped.\n");
    return 0;
}

