        long elapsed = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;
        if (elapsed > TIMEOUT_US) return -1.0;
    }
    clock_gettime(CLOCK_MONOTONIC, &now);
    long pulse_width = (now.tv_sec - start.tv_sec) * 1000000 + (now.tv_nsec - start.tv_nsec) / 1000;
    return (float)pulse_width / 58.0;
}

float map_distance_to_frequency(float distance) {
    if (distance < calibration.min_distance) distance = calibration.min_distance;
    if (distance > calibration.max_distance) distance = calibration.max_distance;
    return calibration.min_frequency + (distance - calibration.min_distance) * (calibration.max_frequency - calibration.min_frequency) / (calibration.max_distance - calibration.min_distance);
}

float map_photoresistor_to_duty(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return calibration.min_duty + (float)adc_value / 1023.0 * (calibration.max_duty - calibration.min_duty);
}

void save_calibration(const char *filename) {
    FILE *f = fopen(filename, "w");
    if (!f) {
        perror("Failed to open config file for writing");
        return;
    }
    fprintf(f, "%f,%f,%f,%f,%f,%f\n",
            calibration.min_distance, calibration.max_distance,
            calibration.min_frequency, calibration.max_frequency,
            calibration.min_duty, calibration.max_duty);
    fclose(f);
}

void load_calibration(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (!f) return;
    if (fscanf(f, "%f,%f,%f,%f,%f,%f",
               &calibration.min_distance, &calibration.max_distance,
               &calibration.min_frequency, &calibration.max_frequency,
               &calibration.min_duty, &calibration.max_duty) == 6) {
        printf("Calibration loaded: min_dist=%.2f, max_dist=%.2f, min_freq=%.2f, max_freq=%.2f, min_duty=%.2f, max_duty=%.2f\n",
               calibration.min_distance, calibration.max_distance,
               calibration.min_frequency, calibration.max_frequency,
               calibration.min_duty, calibration.max_duty);
    } else {
        fprintf(stderr, "Failed to parse calibration file\n");
    }
    fclose(f);
}

void cleanup() {
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    FILE *f = fopen(PWM_DEVICE "enable", "w");
    if (f) {
        fprintf(f, "0");
        fclose(f);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_spi() < 0) {
        fprintf(stderr, "SPI init failed\n");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO init failed\n");
        cleanup();
        return 1;
    }
    if (init_pwm() < 0) {
        fprintf(stderr, "PWM init failed\n");
        cleanup();
        return 1;
    }

    load_calibration(CONFIG_FILE);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor read error\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        float frequency = map_distance_to_frequency(distance);
        int pwm_freq = (int)frequency;
        if (pwm_freq < MIN_FREQUENCY) pwm_freq = MIN_FREQUENCY;
        if (pwm_freq > MAX_FREQUENCY) pwm_freq = MAX_FREQUENCY;
        FILE *f = fopen(PWM_DEVICE "period", "w");
        if (f) {
            fprintf(f, "%d", 1000000 / pwm_freq);
            fclose(f);
        }
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            usleep(LOOP_DELAY_US);
            continue;
        }
        float duty = map_photoresistor_to_duty(adc_value);
        int duty_int = (int)duty;
        if (duty_int < MIN_DUTY) duty_int = MIN_DUTY;
        if (duty_int > MAX_DUTY) duty_int = MAX_DUTY;
        set_pwm_duty(duty_int);
        usleep(LOOP_DELAY_US);
    }

    cleanup();
    printf("Theremin stopped.\n");
    return 0;
}

