#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define MQ135_CHANNEL 0
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define SAMPLE_INTERVAL_US 5000000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)(0x08 | (channel << 4)), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int calculate_aqi(int adc_value) {
    if (adc_value < 0) return -1;
    return (int)(((float)adc_value / 1023.0f) * 500.0f);
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("Fan ON (AQI: %d)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("Fan OFF (AQI: %d)\n", aqi);
    }
}

