    gpioWrite(FAN_GPIO, 0);

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(MQ135_CHANNEL);
            if (adc_value >= 0) break;
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read failed, retry %d/%d\n", retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_US);
                if (init_spi() != 0) {
                    fprintf(stderr, "SPI re-init failed, exiting\n");
                    terminate = 1;
                    break;
                }
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries, exiting\n", MAX_RETRIES);
            terminate = 1;
            break;
        }

        int aqi = calculate_aqi(adc_value);
        if (aqi < 0) {
            fprintf(stderr, "AQI calculation failed\n");
            continue;
        }

        control_fan(aqi);
        log_data(aqi);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(FAN_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();

    printf("Air quality monitoring stopped.\n");
    return 0;
}

