#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Motor 1 GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIO pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Motor speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables for cleanup
int spi_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float map_logarithmic(int value, int in_min, int in_max, float out_min, float out_max);
void motor_forward(int motor_num);
void motor_backward(int motor_num);
void motor_stop(int motor_num);
void set_motor_speed(int motor_num, int speed);
void cleanup();
void signal_handler(int signal);

// Function to read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message for MCP3008 single-ended mode
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Logarithmic mapping function
float map_logarithmic(int value, int in_min, int in_max, float out_min, float out_max) {
    if (in_max == in_min) return out_min;
    float log_val = log10f((float)value / (float)in_max);
    float log_min = log10f((float)in_min / (float)in_max);
    float log_max = log10f((float)in_max / (float)in_max);
    return out_min + (out_max - out_min) * (log_val - log_min) / (log_max - log_min);
}

// Motor control functions
void motor_forward(int motor_num) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_DIRECTION, 1);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_DIRECTION, 1);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
    }
}

void motor_backward(int motor_num) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_DIRECTION, 0);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_DIRECTION, 0);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
    }
}

void motor_stop(int motor_num) {
    if (motor_num == 1) {
        gpioPWM(MOTOR1_ENABLE, 0);
    } else if (motor_num == 2) {
        gpioPWM(MOTOR2_ENABLE, 0);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
    }
}

void set_motor_speed(int motor_num, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (motor_num == 1) {
        gpioPWM(MOTOR1_ENABLE, speed);
    } else if (motor_num == 2) {
        gpioPWM(MOTOR2_ENABLE, speed);
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up and exiting...\n");
    // Stop motors
    motor_stop(1);
    motor_stop(2);
    // Release PWM and SPI
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break;
        }

        // Map potentiometer values to speed factors
        float speed_factor1 = map_logarithmic(pot1_value, 0, 1023, 0.0, 1.0);
        float speed_factor2 = map_logarithmic(pot2_value, 0, 1023, 0.0, 1.0);

        // Calculate motor speeds
        int motor1_speed = (int)(MIN_SPEED + speed_factor1 * (MAX_SPEED - MIN_SPEED));
        int motor2_speed = (int)(MIN_SPEED + speed_factor2 * (MAX_SPEED - MIN_SPEED));

        // Move motors forward
        motor_forward(1);
        motor_backward(2);
        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);
        printf("Motor 1 speed: %d, Motor 2 speed: %d\n", motor1_speed, motor2_speed);

        // Hold for 2 seconds
        time_sleep(2.0);

        // Decelerate back to minimum speed
        for (int i = 0; i < 10; i++) {
            motor1_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (10 - i) / 10.0);
            motor2_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (10 - i) / 10.0);
            set_motor_speed(1, motor1_speed);
            set_motor_speed(2, motor2_speed);
            time_sleep(0.1);
        }
        motor_stop(1);
        motor_stop(2);

        // Pause for 5 seconds
        time_sleep(5.0);

        // Reverse directions
        motor_backward(1);
        motor_forward(2);
        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);
        printf("Motor 1 speed: %d, Motor 2 speed: %d\n", motor1_speed, motor2_speed);

        // Hold for 2 seconds
        time_sleep(2.0);

        // Decelerate back to minimum speed
        for (int i = 0; i < 10; i++) {
            motor1_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (10 - i) / 10.0);
            motor2_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (10 - i) / 10.0);
            set_motor_speed(1, motor1_speed);
            set_motor_speed(2, motor2_speed);
            time_sleep(0.1);
        }
        motor_stop(1);
        motor_stop(2);

        // Pause for 5 seconds
        time_sleep(5.0);
    }

    cleanup();
    return 0;
}

