    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            break;
        }

        // Map potentiometer values to speed factors
        float speed_factor1 = map_logarithmic(pot1_value, 0, 1023, 0.0, 1.0);
        float speed_factor2 = map_logarithmic(pot2_value, 0, 1023, 0.0, 1.0);

        // Calculate motor speeds
        int motor1_speed = (int)(MIN_SPEED + speed_factor1 * (MAX_SPEED - MIN_SPEED));
        int motor2_speed = (int)(MIN_SPEED + speed_factor2 * (MAX_SPEED - MIN_SPEED));

        // Move motors forward
        motor_forward(1);
        motor_backward(2);
        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);
        printf("Motor 1 speed: %d, Motor 2 speed: %d\n", motor1_speed, motor2_speed);

        // Hold for 2 seconds
        time_sleep(2.0);

        // Decelerate back to minimum speed
        for (int i = 0; i < 10; i++) {
            motor1_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (10 - i) / 10.0);
            motor2_speed = MIN_SPEED + (int)((MAX_SPEED - MIN_SPEED) * (10 - i) / 10.0);
            set_motor_speed(1, motor1_speed);
            set_motor_speed(2, motor2_speed);
            time_sleep(0.1);
        }
        motor_stop(1);
        motor_stop(2);

        // Pause for 5 seconds
        time_sleep(5.0);

        // Reverse directions
        motor_backward(1);
        motor_forward(2);
        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);
        printf("Motor 1 speed: %d, Motor 2 speed: %d\n", motor1_speed, motor2_speed);

        // Hold for 2 seconds
        time_sleep(2.0);

        // Decelerate back to minimum speed
        for (int i = 0; i < 10; i++) {
