            set_motor_speed(1, motor1_speed);
            set_motor_speed(2, motor2_speed);
            time_sleep(0.1);
        }
        motor_stop(1);
        motor_stop(2);

        // Pause for 5 seconds
        time_sleep(5.0);
    }

    cleanup();
    return 0;
}

