#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_US 10000
#define CALIBRATION_DURATION_S 5
#define DEBOUNCE_DELAY_US 10000
#define NOISE_THRESHOLD_PERCENT 10.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_average_level(int num_samples) {
    double sum = 0.0;
    int valid = 0;

    for (int i = 0; i < num_samples; i++) {
        int val = read_mcp3008(0);
        if (val < 0) {
            fprintf(stderr, "Error reading ADC during calibration\n");
            continue;
        }
        sum += val;
        valid++;
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (valid == 0) {
        fprintf(stderr, "No valid samples during calibration\n");
        return -1.0;
    }

    return sum / valid;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    double ambient_level = calculate_average_level(CALIBRATION_DURATION_S * 1000 / SAMPLE_INTERVAL_US);
    if (ambient_level < 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    double noise_threshold = ambient_level * (1.0 + (NOISE_THRESHOLD_PERCENT / 100.0));
    printf("Ambient level: %.2f, Noise threshold: %.2f\n", ambient_level, noise_threshold);

    int led_state = 0;
    uint32_t last_trigger_time = 0;

    while (running) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading ADC\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();
        if (sound_level > noise_threshold && (now - last_trigger_time) > DEBOUNCE_DELAY_US) {
            led_state = 1;
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
            }
            last_trigger_time = now;
        } else if (sound_level <= noise_threshold && led_state) {
            led_state = 0;
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

