#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel connected to AWM720P
#define VOLTAGE_MIN 0.5   // Voltage at 0 SLPM
#define VOLTAGE_MAX 4.5   // Voltage at 200 SLPM
#define AIRFLOW_MAX 200.0 // Maximum airflow in SLPM
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
void log_airflow(float airflow);
void timer_callback(void *user_data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC via SPI
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode + channel
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert voltage to airflow (SLPM)
float voltage_to_airflow(float voltage) {
    if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
        fprintf(stderr, "Error: Voltage out of range: %.3f V\n", voltage);
        return -1.0;
    }
    return ((voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN)) * AIRFLOW_MAX;
}

// Function to log airflow with timestamp
void log_airflow(float airflow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (airflow >= 0) {
        fprintf(log_file, "%s, %.2f SLPM\n", timestamp, airflow);
    } else {
        fprintf(log_file, "%s, ERROR: ADC read failed\n", timestamp);
    }
    fflush(log_file);
}

// Timer callback function (called every SAMPLE_INTERVAL_MS milliseconds)
void timer_callback(void *user_data) {
    (void)user_data; // Suppress unused parameter warning

    int adc_value = read_adc(ADC_CHANNEL);
    if (adc_value < 0) {
        log_airflow(-1.0);
        return;
    }

    float voltage = (float)adc_value / 1023.0 * 3.3; // Convert ADC value to voltage
    float airflow = voltage_to_airflow(voltage);

    log_airflow(airflow);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    terminate = 1;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    // Set up timer interrupt (pigpio timer 0, every SAMPLE_INTERVAL_MS milliseconds)
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up timer\n");
        cleanup();
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop: wait for termination signal
    while (!terminate) {
        gpioDelay(100000); // Sleep 100 ms to reduce CPU usage
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

