#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0       // CE0
#define SPI_SPEED 1000000   // 1 MHz
#define MCP3008_CHANNEL 0   // ADC channel 0
#define VREF 3.3            // Reference voltage
#define LOG_FILE "gas_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_ppm(int adc_value);
void log_data(float voltage, float ppm);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message for MCP3008 (single-ended mode)
    spi_tx_buf[0] = 0x01;                       // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;      // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                       // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to PPM (placeholder linear relationship)
float voltage_to_ppm(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    return voltage * 1000.0; // Placeholder: PPM = voltage * 1000
}

// Function to log data to file
void log_data(float voltage, float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Voltage: %.3f V, PPM: %.2f\n", s, voltage, ppm);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Propane leak detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying...\n");
            gpioDelay(100000); // 100 ms delay
            continue;
        }

        // Convert to voltage and PPM
        float voltage = (float)adc_value / 1023.0 * VREF;
        float ppm = voltage_to_ppm(adc_value);

        // Log data
        log_data(voltage, ppm);

        // Print to console
        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

