#define SPI_FLAGS 0        // Mode 0, active low CS

// MCP3008 channel assignments
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// ADXL335 parameters
#define SENSITIVITY 0.3 // 300 mV/g
#define ZERO_G_BIAS 1.5 // 1.5V
#define VREF 3.3        // Reference voltage

// Kalman filter parameters
#define Q_PROCESS 0.01
#define Q_MEASURE 0.03
#define R_MEASURE 0.1

// Global variables
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

// Kalman filter state
typedef struct {
    double x;
    double P;
} KalmanState;

static KalmanState kalman_x = {0.0, 0.0};
static KalmanState kalman_y = {0.0, 0.0};
static KalmanState kalman_z = {0.0, 0.0};

// Function prototypes
int initialize_spi(void);
int read_mcp3008(int channel);
double convert_to_g(int adc_value);
double kalman_filter(double measurement, KalmanState *state, double q_process, double q_measure, double r_measure);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Initialize SPI communication
int initialize_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command format for single-ended mode:
    // Byte 0: 0x01 (Start bit)
    // Byte 1: (0x08 | channel) << 4 (Single-ended + channel selection)
    // Byte 2: 0x00 (Don't care, clocking out data)
    char spi_tx_buf[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char spi_rx_buf[3] = {0};

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) | (spi_rx_buf[2] & 0xFF);
    return adc_value;
}

// Convert ADC value to acceleration in g
double convert_to_g(int adc_value) {
    double voltage = (double)adc_value * VREF / 1023.0;
    double acceleration = (voltage - ZERO_G_BIAS) / SENSITIVITY;
    return acceleration;
}

// Kalman filter implementation
double kalman_filter(double measurement, KalmanState *state, double q_process, double q_measure, double r_measure) {
    double P_pred = state->P + q_process;
    double K = P_pred / (P_pred + r_measure);
    double x_est = state->x + K * (measurement - state->x);
    double P_est = (1.0 - K) * P_pred;

    state->x = x_est;
    state->P = P_est;

    return x_est;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 Kalman Filter Reader (pigpio)\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying...\n");
            gpioDelay(100000); // 100ms delay before retry
            continue;
        }

        // Convert ADC values to acceleration in g
        double x_g = convert_to_g(x_adc);
        double y_g = convert_to_g(y_adc);
        double z_g = convert_to_g(z_adc);

        // Apply Kalman filter to each axis
        double x_filtered = kalman_filter(x_g, &kalman_x, Q_PROCESS, Q_MEASURE, R_MEASURE);
        double y_filtered = kalman_filter(y_g, &kalman_y, Q_PROCESS, Q_MEASURE, R_MEASURE);
        double z_filtered = kalman_filter(z_g, &kalman_z, Q_PROCESS, Q_MEASURE, R_MEASURE);

        // Print acceleration values in g
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_filtered, y_filtered, z_filtered);

        gpioDelay(100000); // 100ms delay (10 Hz sampling rate)
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

