#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define VCC 3.3f
#define V_QUIESCENT (VCC / 2.0f)
#define SENSITIVITY 0.025f
#define MIN_MT -100.0f
#define MAX_MT 100.0f
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static float read_sensor(struct gpiod_line *line) {
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1.0f;
    }
    return (val == 1) ? (VCC - V_QUIESCENT) / SENSITIVITY : 0.0f;
}

static void log_data(float s1, float s2, float s3) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%.2f,%.2f,%.2f\n", s1, s2, s3);
    fflush(fp);
    fclose(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    int ret = EXIT_FAILURE;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_reader") < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("DRV5055VA Hall-Effect Sensor Reader started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float s1 = read_sensor(lines[0]);
        float s2 = read_sensor(lines[1]);
        float s3 = read_sensor(lines[2]);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Error reading sensor data, skipping log.\n");
        } else if (s1 < MIN_MT || s1 > MAX_MT ||
                   s2 < MIN_MT || s2 > MAX_MT ||
                   s3 < MIN_MT || s3 > MAX_MT) {
            fprintf(stderr, "Warning: Sensor reading out of range (S1=%.2f, S2=%.2f, S3=%.2f)\n", s1, s2, s3);
        }

        log_data(s1, s2, s3);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

