#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define NUM_CHANNELS 3
#define LOG_INTERVAL_SEC 1
#define CSV_FILENAME "sensor_data.csv"

static volatile sig_atomic_t keep_running = 1;
static int spi_fd = -1;
static FILE *csv_file = NULL;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)(0x80 | (channel << 4)),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %d: %s\n", channel, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int log_data(int ch0, int ch1, int ch2) {
    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILENAME, "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILENAME, strerror(errno));
            return -1;
        }
    }

    if (fprintf(csv_file, "%d,%d,%d\n", ch0, ch1, ch2) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(csv_file) != 0) {
        fprintf(stderr, "Error flushing CSV file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

void cleanup(void) {
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

