    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int ch0 = read_mcp3008(0);
        int ch1 = read_mcp3008(1);
        int ch2 = read_mcp3008(2);

        if (ch0 < 0 || ch1 < 0 || ch2 < 0) {
            fprintf(stderr, "Error reading ADC values, exiting.\n");
            break;
        }

        if (log_data(ch0, ch1, ch2) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        printf("Channel 0: %d, Channel 1: %d, Channel 2: %d\n", ch0, ch1, ch2);

        sleep(LOG_INTERVAL_SEC);
    }

    cleanup();
    printf("Exiting gracefully.\n");
    return 0;
}

