static int initialize_bmp280(void) {
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIP_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error: Failed to read chip ID (I2C bus error)\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present?\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    gpioDelay(10000);
    if (read_calibration_data() != 0) return -1;
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register\n");
        return -1;
    }
    return 0;
}

static int read_raw_data(int32_t *raw_pressure, int32_t *raw_temperature) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }
    *raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    if (initialize_bmp280() != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    printf("BMP280 initialized. Logging to %s every 5 seconds. Press Ctrl+C to exit.\n", LOG_FILE);
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;
        if (read_raw_data(&raw_pressure, &raw_temperature) == 0) {
            int32_t temp_comp = compensate_temperature(raw_temperature);
            uint32_t press_comp = compensate_pressure(raw_pressure);
            double altitude = calculate_altitude((double)press_comp);
            if (log_data(altitude) != 0) {
                fprintf(stderr, "Warning: Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, retrying...\n");
        }
        gpioDelay(5000000);
    }
    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

