#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define VREF 3.3f
#define LM35_MV_PER_C 10.0f
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define SAMPLE_INTERVAL_SEC 5

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0f) * VREF;
    return voltage * 1000.0f / LM35_MV_PER_C;
}

static void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

static void write_buffer_to_file(void) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    size_t elements_to_write = BUFFER_SIZE;
    size_t elements_written = fwrite(temperature_buffer, sizeof(float), elements_to_write, fp);
    if (elements_written != elements_to_write) {
        fprintf(stderr, "Error writing to log file: wrote %zu of %zu elements\n", elements_written, elements_to_write);
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping this sample\n");
        } else {
            float temperature = convert_to_celsius(adc_value);
            log_temperature(temperature);

            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            if (buffer_index == 0) {
                write_buffer_to_file();
            }
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

