#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* MCP3008 SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define SPI_FLAGS   0  /* mode 0, active-low CE */

/* MCP4725 I2C configuration */
#define I2C_BUS     1
#define I2C_ADDR    0x62

/* TMP36 parameters */
#define TMP36_OFFSET 0.0
#define TMP36_SCALE  100.0

/* DAC output range */
#define DAC_VREF     3.3
#define DAC_MAX_CODE 4095

/* Sampling interval */
#define SAMPLE_INTERVAL_US 500000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Globals for cleanup */
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                             */
/* Returns 0-1023 on success, -1 on failure                            */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit + SGL/DIFF=1 + D2 D1 D0 */
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Convert TMP36 ADC value to Celsius                                  */
/* ------------------------------------------------------------------ */
static float adc_to_celsius(int adc_value)
{
    return (float)adc_value * TMP36_SCALE / 1024.0 + TMP36_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Set MCP4725 DAC output voltage (0-Vref)                             */
/* Returns 0 on success, -1 on failure                                 */
/* ------------------------------------------------------------------ */
static int set_dac_voltage(float voltage)
{
    if (voltage < 0.0f || voltage > DAC_VREF) {
        fprintf(stderr, "DAC voltage out of range: %.3f V\n", voltage);
        return -1;
    }

    /* MCP4725: 12-bit data, left-justified in 16-bit word */
    uint16_t code = (uint16_t)((voltage / DAC_VREF) * DAC_MAX_CODE);
    uint8_t buf[2] = {
        (uint8_t)((code >> 4) & 0xFF),
        (uint8_t)((code << 4) & 0xF0)
    };

    int ret = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (ret != 0) {
        fprintf(stderr, "I2C write failed (returned %d)\n", ret);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one reading                                                     */
/* ------------------------------------------------------------------ */
static void log_reading(int adc_value, float temp_c, float dac_v)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n",
            ts, adc_value, temp_c, dac_v);
    fflush(log_file);

    printf("%s, ADC=%d, Temp=%.2f C, DAC=%.3f V\n",
           ts, adc_value, temp_c, dac_v);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (handle %d)\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        perror("fopen temperature_log.txt");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retries = 0;

        /* Read ADC with retries */
        while (retries < MAX_RETRIES && !terminate) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0)
                break;
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US);
        }

        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed after %d retries; skipping cycle\n",
                    MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float temp_c = adc_to_celsius(adc_value);

        /* Map 0C -> 0V, 50C -> Vref */
        float dac_v = (temp_c / 50.0f) * DAC_VREF;
        if (dac_v < 0.0f) dac_v = 0.0f;
        if (dac_v > DAC_VREF) dac_v = DAC_VREF;

        /* Set DAC with retry */
        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (set_dac_voltage(dac_v) == 0)
                break;
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US);
        }

        if (retries >= MAX_RETRIES)
            fprintf(stderr, "DAC set failed after %d retries\n", MAX_RETRIES);

        log_reading(adc_value, temp_c, dac_v);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

