#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define CONSUMER "light_sequencer"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};
static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void deactivate_all_relays(void) {
    for (int i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            deactivate_all_relays();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(relay_lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request output on GPIO %d\n", relay_pins[i]);
            deactivate_all_relays();
            return EXIT_FAILURE;
        }
    }

    while (keep_running) {
        for (int i = 0; i < 4 && keep_running; i++) {
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                perror("gpiod_line_set_value (activate)");
                deactivate_all_relays();
                return EXIT_FAILURE;
            }
            sleep(1);
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                perror("gpiod_line_set_value (deactivate)");
                deactivate_all_relays();
                return EXIT_FAILURE;
            }
            sleep(1);
        }
    }

    deactivate_all_relays();
    return EXIT_SUCCESS;
}

