#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* GPIO pin definitions */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Rain sensor threshold (0-10 scale) */
#define RAIN_THRESHOLD 5

/* Motor PWM parameters */
#define PWM_RANGE 255
#define PWM_SPEED 150

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; no I/O here                         */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7) via SPI                     */
/* Returns 0-1023 on success, -1 on error                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value (0-1023) to rain level (0-10)                     */
/* Lower ADC value = higher voltage = heavier rain                     */
/* ------------------------------------------------------------------ */
static int adc_to_rain_level(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* Map 0..1023 to 10..0 (dry = 0, wet = 10) */
    return 10 - (int)(((float)adc_value / 1023.0f) * 10.0f);
}

/* ------------------------------------------------------------------ */
/* Drive motor for given duration (seconds) in given direction         */
/* ------------------------------------------------------------------ */
static void motor_drive(int direction, int duration_sec)
{
    if (direction == 1) {
        /* Close window: IN1=1, IN2=0 */
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else if (direction == -1) {
        /* Open window: IN1=0, IN2=1 */
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    } else {
        fprintf(stderr, "Invalid motor direction %d\n", direction);
        return;
    }

    /* Set PWM speed */
    gpioPWM(MOTOR_ENA, PWM_SPEED);

    /* Wait, checking for shutdown signal every 100 ms */
    for (int i = 0; i < duration_sec * 10 && g_running; i++) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Stop motor */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
}

/* ------------------------------------------------------------------ */
/* Log rain reading with timestamp                                     */
/* ------------------------------------------------------------------ */
static void log_rain_reading(int rain_level)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush on log file failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motor */
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
