#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>

#define MIC_GPIO 26
#define LED_GPIO 16
#define THRESHOLD_RAW 700
#define DEBOUNCE_US 50000
#define LED_ON_US 500000
#define SAMPLE_INTERVAL_US 1000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_mic_raw(void) {
    int sum = 0;
    for (int i = 0; i < 10; i++) {
        int v = gpioRead(MIC_GPIO);
        if (v < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n", MIC_GPIO);
            return -1;
        }
        sum += v;
        gpioDelay(100);
    }
    return sum;
}

static void trigger_led(void) {
    if (gpioWrite(LED_GPIO, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn LED on.\n");
        return;
    }
    gpioDelay(LED_ON_US);
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn LED off.\n");
    }
}

static void log_detection(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Warning: time() failed.\n");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Warning: strftime failed.\n");
        return;
    }
    printf("[%s] Clap detected!\n", ts);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    bool last_clap = false;

    while (running) {
        int raw = read_mic_raw();
        if (raw < 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        bool clap = (raw > THRESHOLD_RAW);

        if (clap && !last_clap) {
            trigger_led();
            log_detection();
            last_clap = true;
        } else if (!clap) {
            last_clap = false;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

