#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define CONSUMER_ID "sharp_gp2y0a21yk0f"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_export(int pin) {
    char buf[64];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to export GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[64];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Failed to unexport GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "Failed to set direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_read_value(int pin) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", path, strerror(errno));
        return -1;
    }
    char buf[4];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n <= 0) {
        fprintf(stderr, "Failed to read GPIO %d value: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    buf[n] = '\0';
    close(fd);
    return (buf[0] == '1') ? 1 : 0;
}

static float voltage_to_distance(int value) {
    const float A = 26.0f;
    const float B = -6.0f;
    float voltage = (value == 1) ? 3.3f : 0.0f;
    return A / voltage + B;
}

static void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Distance: %.2f mm\n", ts, distance);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Sharp GP2Y0A21YK0F distance sensor monitoring started on GPIO %d.\n", GPIO_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int val = gpio_read_value(GPIO_PIN);
        if (val < 0) {
            fprintf(stderr, "Read error, retrying in 1 second...\n");
            sleep(1);
            continue;
        }

        float distance = voltage_to_distance(val);
        log_distance(distance);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated (Distance: %.2f mm)\n", distance);
        } else {
            printf("Feeder Idle (Distance: %.2f mm)\n", distance);
        }

        sleep(1);
    }

    gpio_unexport(GPIO_PIN);
    printf("\nExiting cleanly.\n");
    return 0;
}

