        }

        double magnetic_field = calculate_magnetic_field(adc_value);

        if (log_data(log_fp, magnetic_field) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp)  fclose(log_fp);
    if (spi_fd >= 0) close(spi_fd);
    if (cs_line)  gpiod_line_release(cs_line);
    if (chip)    gpiod_chip_close(chip);
    return ret;
}

