    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.3f\n", timestamp, current) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0);
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        return 1;
    }
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }
    printf("Starting current monitoring. Press Ctrl+C to stop.\n");
    while (running) {
        gpiod_line_set_value(gpio_line, 1);
        usleep(1000);
        int adc_value = read_adc(ADC_CHANNEL);
        gpiod_line_set_value(gpio_line, 0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        float current = adc_to_current(adc_value);
        if (log_data(current) < 0) {
            fprintf(stderr, "Logging error, continuing\n");
        }
        sleep(SAMPLE_INTERVAL);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

