#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/*
 * Raspberry Pi Zero W – MLX91211 current sensor via MCP3008 SPI ADC
 *
 * Wiring:
 *   MCP3008 VDD/VREF -> Pi 5V (pin 2 or 4)
 *   MCP3008 AGND/DGND -> Pi GND (pin 6)
 *   MCP3008 CLK  -> Pi GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> Pi GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> Pi GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> Pi GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * MLX91211 ratiometric: 2.5 V at 0 A, 5.0 V at +50 A.
 * MCP3008 single-ended channel 0, 10-bit, 0–1023.
 */

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_BAUD       1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX        1023       /* 10-bit */
#define ADC_VREF       5.0        /* V */
#define ADC_VZERO      2.5        /* V at 0 A */
#define ADC_VMIN       0.0        /* V at 0 A */
#define ADC_VMAX       5.0        /* V at +50 A */
#define CURRENT_MAX    50.0       /* A */
#define SAMPLE_US      100000     /* 100 ms */
#define LOG_FILE       "current_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one sample from the MCP3008 (single-ended, channel 0–7).
 * Returns 0 on success and stores the 10-bit code in *code;
 * returns -1 on SPI transfer failure.
 */
static int read_mcp3008(int channel, int *code)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (3 bytes):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = 0x80 | (channel << 4)      SGL/DIFF=1 (single) + channel
     *   tx[2] = 0x00                       padding for clocking data out
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01,
                            (unsigned char)(0x80 | (channel << 4)),
                            0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *code = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float adc_to_voltage(int code)
{
    return ((float)code / (float)ADC_MAX) * ADC_VREF;
}

static float voltage_to_current(float v)
{
    if (v <= ADC_VMIN) return 0.0f;
    if (v >= ADC_VMAX) return CURRENT_MAX;
    return (v - ADC_VZERO) * (CURRENT_MAX / (ADC_VMAX - ADC_VZERO));
}

static void log_current(float current)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log, "%s %.2f A\n", ts, current);
    fflush(g_log);
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current logger started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        int code = 0;
        if (read_mcp3008(ADC_CHANNEL, &code) != 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = adc_to_voltage(code);
        if (voltage < 0.0f || voltage > ADC_VREF) {
            fprintf(stderr, "Warning: voltage %.3f V out of range [0, %.1f]\n",
                    voltage, ADC_VREF);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = voltage_to_current(voltage);
        log_current(current);

        gpioDelay(SAMPLE_US);
    }

    /* --- cleanup --- */
    printf("\nShutting down...\n");
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

