        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        fclose(g_log);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX91211 current logger started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        int code = 0;
        if (read_mcp3008(ADC_CHANNEL, &code) != 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = adc_to_voltage(code);
        if (voltage < 0.0f || voltage > ADC_VREF) {
            fprintf(stderr, "Warning: voltage %.3f V out of range [0, %.1f]\n",
                    voltage, ADC_VREF);
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = voltage_to_current(voltage);
        log_current(current);

        gpioDelay(SAMPLE_US);
    }

    /* --- cleanup --- */
    printf("\nShutting down...\n");
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

