#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(sensor1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(sensor2)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-sensor1") < 0) {
        perror("gpiod_line_request_input(sensor1)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-sensor2") < 0) {
        perror("gpiod_line_request_input(sensor2)");
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO4 and GPIO17...\n");

    while (running) {
        int s1_val = 1, s2_val = 1;
        int s1_count = 0, s2_count = 0;

        for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
            int v = gpiod_line_get_value(line1);
            if (v < 0) {
                perror("gpiod_line_get_value(sensor1)");
                goto cleanup;
            }
            if (v == 0) s1_count++;
            usleep(DEBOUNCE_DELAY_US);
        }
        s1_val = (s1_count > DEBOUNCE_SAMPLES / 2) ? 0 : 1;

        for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
            int v = gpiod_line_get_value(line2);
            if (v < 0) {
                perror("gpiod_line_get_value(sensor2)");
                goto cleanup;
            }
            if (v == 0) s2_count++;
            usleep(DEBOUNCE_DELAY_US);
        }
        s2_val = (s2_count > DEBOUNCE_SAMPLES / 2) ? 0 : 1;

        printf("Sensor 1 (GPIO4): %s\n", s1_val == 0 ? "OBJECT PRESENT" : "NO OBJECT");
        printf("Sensor 2 (GPIO17): %s\n", s2_val == 0 ? "OBJECT PRESENT" : "NO OBJECT");

        if (s1_val == 0 && s2_val == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

