#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    int read_delay;
    int min_adc;
    int max_adc;
    const char *log_file;
} spi_config_t;

static volatile sig_atomic_t terminate = 0;
static int spi_handle = -1;

int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80 | (channel << 4);
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) moisture_level = 0.0;
    if (moisture_level > 100.0) moisture_level = 100.0;
    return moisture_level;
}

int log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s for appending.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

int spi_setup(spi_config_t config) {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed on channel %d at %d baud.\n", config.spi_channel, config.spi_baud);
        return -1;
    }
    return 0;
}

int main() {
    spi_config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_baud = SPI_BAUD,
        .mcp3008_channel = MCP3008_CHANNEL,
        .read_delay = READ_DELAY,
        .min_adc = MIN_ADC,
        .max_adc = MAX_ADC,
        .log_file = LOG_FILE
    };

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (spi_setup(config) != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d seconds.\n", config.read_delay);
            sleep(config.read_delay);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        printf("Moisture Level: %.2f%%\n", moisture_level);

        sleep(config.read_delay);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

