#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 200
#define POLL_INTERVAL_US 50000
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        syslog(LOG_ERR, "Capture path '%s' exists but is not a directory", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        syslog(LOG_ERR, "Failed to create capture directory '%s': %s", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_image(void) {
    time_t rawtime;
    struct tm timeinfo;
    char filename[256];
    char command[512];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        syslog(LOG_ERR, "localtime_r failed: %s", strerror(errno));
        return -1;
    }

    if (strftime(filename, sizeof(filename), CAPTURE_DIR "%Y%m%dT%H%M%S.jpg", &timeinfo) == 0) {
        syslog(LOG_ERR, "strftime failed to format filename");
        return -1;
    }

    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width %d --height %d --nopreview",
             filename, CAPTURE_WIDTH, CAPTURE_HEIGHT);

    syslog(LOG_INFO, "Capturing image: %s", command);

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        execlp("libcamera-still", "libcamera-still", "-o", filename,
               "--width", "1280", "--height", "720", "--nopreview", (char *)NULL);
        syslog(LOG_ERR, "execlp libcamera-still failed: %s", strerror(errno));
        _exit(127);
    }

    int status = 0;
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR) continue;
        syslog(LOG_ERR, "waitpid failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured successfully: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
    return -1;
}

int main(void) {
    openlog("security_camera", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_capture_dir() != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    syslog(LOG_INFO, "Security camera started on GPIO%d", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead failed on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead failed on GPIO%d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_MS * 1000);
            int confirmed = gpioRead(PIR_GPIO);
            if (confirmed < 0) {
                syslog(LOG_ERR, "gpioRead (debounce) failed on GPIO%d", PIR_GPIO);
                break;
            }
            if (confirmed == current_state) {
                last_state = current_state;
                if (current_state == 1) {
                    syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);
                    if (capture_image() != 0) {
                        syslog(LOG_ERR, "Image capture failed");
                    }
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Security camera shutting down");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

