#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define DEFAULT_WIDTH 640
#define DEFAULT_HEIGHT 480
#define MAX_FILENAME_LENGTH 64
#define MAX_BUFFERS 1

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(int argc, char *argv[]) {
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;
    int width = DEFAULT_WIDTH;
    int height = DEFAULT_HEIGHT;
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct v4l2_capability cap;
    char *buffer = NULL;
    char filename[MAX_FILENAME_LENGTH];
    unsigned int i;
    int frame_count = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(device, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device);
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device);
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Error: Device does not support grayscale format\n");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = MAX_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        close(fd);
        return EXIT_FAILURE;
    }

    buffer = mmap(NULL, fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer %u: %s\n", i, strerror(errno));
            munmap(buffer, fmt.fmt.pix.sizeimage);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMON, &buf.type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer, fmt.fmt.pix.sizeimage);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing grayscale images from %s... Press Ctrl+C to stop.\n", device);

    while (!stop_flag) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            break;
        } else if (r == 0) {
            fprintf(stderr, "Error: Timeout waiting for frame\n");
            break;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            break;
        }

        snprintf(filename, sizeof(filename), "image_%04d.pgm", ++frame_count);

        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        } else {
            fprintf(fp, "P5\n%d %d\n255\n", width, height);
            if (fwrite(buffer, 1, fmt.fmt.pix.sizeimage, fp) != fmt.fmt.pix.sizeimage) {
                fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
            }
            fclose(fp);
            printf("Saved %s (%dx%d)\n", filename, width, height);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &buf.type) == -1) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
    }

    munmap(buffer, fmt.fmt.pix.sizeimage);
    close(fd);

    printf("Captured %d frames.\n", frame_count);
    return EXIT_SUCCESS;
}

