        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            munmap(buffer, buf.length);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("socket");
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", server_ip);
        close(sockfd);
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned int frame_index = 0;
    unsigned int total_fragments = 0;
    unsigned int payload_size = 0;
    unsigned char *payload_ptr = NULL;
    unsigned int fragment_index = 0;

    while (running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        struct timeval tv;
        tv.tv_sec = 2;
        tv.tv_usec = 0;
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            continue;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) continue;
            perror("VIDIOC_DQBUF");
            break;
        }

        if (buf.bytesused == 0) {
            fprintf(stderr, "Empty frame\n");
            if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
                perror("VIDIOC_QBUF");
                break;
            }
            continue;
        }

        total_fragments = (buf.bytesused + MAX_FRAGMENT_SIZE - 1) / MAX_FRAGMENT_SIZE;
        payload_size = buf.bytesused;
        payload_ptr = (unsigned char *)buffer;
        fragment_index = 0;

        while (fragment_index < total_fragments && running) {
            unsigned int frag_size = (fragment_index == total_fragments - 1) ? (payload_size % MAX_FRAGMENT_SIZE) : MAX_FRAGMENT_SIZE;
            if (frag_size == 0) frag_size = MAX_FRAGMENT_SIZE;

            FrameHeader header;
            header.frame_index = frame_index;
            header.fragment_index = fragment_index;
            header.total_fragments = total_fragments;
            header.payload_size = frag_size;

            unsigned char *packet = malloc(FRAME_HEADER_SIZE + frag_size);
            if (!packet) {
                perror("malloc");
                break;
            }
            memcpy(packet, &header, FRAME_HEADER_SIZE);
            memcpy(packet + FRAME_HEADER_SIZE, payload_ptr, frag_size);

            ssize_t sent = sendto(sockfd, packet, FRAME_HEADER_SIZE + frag_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr));
            free(packet);

            if (sent == -1) {
                perror("sendto");
                break;
            }

            payload_ptr += frag_size;
            fragment_index++;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            break;
        }

        frame_index++;
    }

    xioctl(fd, VIDIOC_STREAMOFF, &type);
    munmap(buffer, buf.length);
    close(sockfd);
    close(fd);

    fprintf(stderr, "Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

