#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH  1920
#define IMAGE_HEIGHT 1080
#define NUM_BUFFERS  4
#define OUTPUT_FILE  "image.jpg"

typedef struct {
    void  *start;
    size_t length;
} buffer_t;

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR, 0);
    if (fd < 0) {
        perror("open device");
        return -1;
    }
    return fd;
}

static int query_capabilities(int fd) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        return -1;
    }
    return 0;
}

static int set_format(int fd, enum v4l2_buf_type type) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = type;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device did not accept MJPEG format\n");
        return -1;
    }
    return 0;
}

static int request_buffers(int fd, int n_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }
    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on device\n");
        return -1;
    }
    return (int)req.count;
}

static int query_buffer(int fd, int index, buffer_t *buf) {
    struct v4l2_buffer vbuf;
    memset(&vbuf, 0, sizeof(vbuf));
    vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vbuf.memory = V4L2_MEMORY_MMAP;
    vbuf.index = index;
    if (xioctl(fd, VIDIOC_QUERYBUF, &vbuf) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }
    buf->length = vbuf.length;
    buf->start = mmap(NULL, vbuf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, vbuf.m.offset);
    if (buf->start == MAP_FAILED) {
        perror("mmap");
        buf->start = NULL;
        return -1;
    }
    return 0;
}

static int enqueue_buffer(int fd, int index) {
    struct v4l2_buffer vbuf;
    memset(&vbuf, 0, sizeof(vbuf));
    vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vbuf.memory = V4L2_MEMORY_MMAP;
    vbuf.index = index;
    if (xioctl(fd, VIDIOC_QBUF, &vbuf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int dequeue_buffer(int fd, buffer_t *buf) {
    struct v4l2_buffer vbuf;
    memset(&vbuf, 0, sizeof(vbuf));
    vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vbuf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &vbuf) == -1) {
        if (errno == EAGAIN) {
            return 1;
        }
        perror("VIDIOC_DQBUF");
        return -1;
    }
    buf->length = vbuf.bytesused;
    buf->start = NULL;
    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

static int save_image(const buffer_t *buf, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen output");
        return -1;
    }
    size_t written = fwrite(buf->start, 1, buf->length, fp);
    if (written != buf->length) {
        fprintf(stderr, "Short write: %zu of %zu bytes\n", written, buf->length);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) == EOF) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static void release_buffers(buffer_t *buffers, int n_buffers) {
    if (buffers) {
        for (int i = 0; i < n_buffers; i++) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
                buffers[i].start = NULL;
            }
        }
        free(buffers);
    }
}

int main(void) {
    int fd = -1;
    buffer_t *buffers = NULL;
    int n_buffers = 0;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1) {
        goto done;
    }

    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        goto done;
    }

    if (query_capabilities(fd) == -1) {
        goto cleanup_fd;
    }

    if (set_format(fd, V4L2_BUF_TYPE_VIDEO_CAPTURE) == -1) {
        goto cleanup_fd;
    }

    n_buffers = request_buffers(fd, NUM_BUFFERS);
    if (n_buffers == -1) {
        goto cleanup_fd;
    }

    buffers = calloc((size_t)n_buffers, sizeof(buffer_t));
    if (!buffers) {
        perror("calloc");
        goto cleanup_fd;
    }

    for (int i = 0; i < n_buffers; i++) {
        if (query_buffer(fd, i, &buffers[i]) == -1) {
            fprintf(stderr, "Failed to query buffer %d\n", i);
            goto cleanup_all;
        }
        if (enqueue_buffer(fd, i) == -1) {
            fprintf(stderr, "Failed to enqueue buffer %d\n", i);
            goto cleanup_all;
        }
    }

    if (start_streaming(fd) == -1) {
        goto cleanup_all;
    }

    buffer_t frame;
    memset(&frame, 0, sizeof(frame));
    int got_frame = 0;

    while (!g_stop) {
        int r = dequeue_buffer(fd, &frame);
        if (r == 1) {
            continue;
        }
        if (r == -1) {
            goto cleanup_stream;
        }
        got_frame = 1;
        break;
    }

    if (!got_frame) {
        fprintf(stderr, "No frame captured before signal\n");
        goto cleanup_stream;
    }

    if (save_image(&frame, OUTPUT_FILE) == -1) {
        fprintf(stderr, "Failed to save image\n");
        goto cleanup_stream;
    }

    printf("Saved %zu bytes to %s\n", frame.length, OUTPUT_FILE);
    ret = EXIT_SUCCESS;

cleanup_stream:
    stop_streaming(fd);

cleanup_all:
    for (int i = 0; i < n_buffers; i++) {
        if (buffers && buffers[i].start && buffers[i].start != MAP_FAILED) {
            munmap(buffers[i].start, buffers[i].length);
        }
    }
    free(buffers);

cleanup_fd:
    close(fd);

done:
    return ret;
}

