#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define TILT_UP_BUTTON   6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON  8
#define PAN_RIGHT_BUTTON 9

#define PWM_PERIOD_US    20000   /* 50 Hz */
#define PWM_RANGE        1000
#define PWM_MID          75
#define PWM_MIN          25
#define PWM_MAX          125
#define PWM_STEP          5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int set_servo_pulse(struct gpiod_line *line, int position)
{
    if (position < PWM_MIN) position = PWM_MIN;
    if (position > PWM_MAX) position = PWM_MAX;

    int duty = (position * PWM_RANGE) / 100;
    int on_us  = (PWM_PERIOD_US * duty) / PWM_RANGE;
    int off_us = PWM_PERIOD_US - on_us;

    if (on_us < 1000) on_us = 1000;
    if (off_us < 1000) off_us = 1000;

    if (gpiod_line_set_value(line, 1) < 0) return -1;
    usleep(on_us);
    if (gpiod_line_set_value(line, 0) < 0) return -1;
    usleep(off_us);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pan_line = NULL;
    struct gpiod_line *tilt_line = NULL;
    struct gpiod_line *tilt_up = NULL;
    struct gpiod_line *tilt_down = NULL;
    struct gpiod_line *pan_left = NULL;
    struct gpiod_line *pan_right = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_SERVO_PIN);
    tilt_line = gpiod_chip_get_line(chip, TILT_SERVO_PIN);
    tilt_up = gpiod_chip_get_line(chip, TILT_UP_BUTTON);
    tilt_down = gpiod_chip_get_line(chip, TILT_DOWN_BUTTON);
    pan_left = gpiod_chip_get_line(chip, PAN_LEFT_BUTTON);
    pan_right = gpiod_chip_get_line(chip, PAN_RIGHT_BUTTON);

    if (!pan_line || !tilt_line || !tilt_up || !tilt_down ||
        !pan_left || !pan_right) {
        fprintf(stderr, "Failed to get one or more GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(pan_line, "camera-pan", 0) < 0) {
        perror("request pan_line");
        goto cleanup;
    }
    if (gpiod_line_request_output(tilt_line, "camera-tilt", 0) < 0) {
        perror("request tilt_line");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(tilt_up, "tilt-up",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request tilt_up");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(tilt_down, "tilt-down",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("request tilt_down");
        goto cleanup;
    }
