#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define CAMERA_DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAME_SIZE (WIDTH * HEIGHT)
#define BLUR_RADIUS 2
#define NUM_BUFFERS 4
#define JPEG_QUALITY 75

static volatile sig_atomic_t stop_flag = 0;

static void sigint_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int yuyv_to_rgb(const unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int i = 0, j = 0; i < width * height * 2; i += 4, j += 6) {
        unsigned char y0 = yuyv[i];
        unsigned char u = yuyv[i + 1];
        unsigned char y1 = yuyv[i + 2];
        unsigned char v = yuyv[i + 3];
        rgb[j] = y0;
        rgb[j + 1] = (unsigned char)((y0 * 7630 + u * -10985 + v * 12296 + 32768) >> 16);
        rgb[j + 2] = (unsigned char)((y0 * 7630 + u * 13844 + v * -11684 + 32768) >> 16);
        rgb[j + 3] = y1;
        rgb[j + 4] = (unsigned char)((y1 * 7630 + u * -10985 + v * 12296 + 32768) >> 16);
        rgb[j + 5] = (unsigned char)((y1 * 7630 + u * 13844 + v * -11684 + 32768) >> 16);
    }
    return 0;
}

static int blur_image(unsigned char *image, int width, int height) {
    unsigned char *temp = malloc((size_t)width * height * 3);
    if (!temp) {
        fprintf(stderr, "Failed to allocate blur temp buffer: %s\n", strerror(errno));
        return -1;
    }
    memcpy(temp, image, (size_t)width * height * 3);
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            long r_sum = 0, g_sum = 0, b_sum = 0;
            int count = 0;
            for (int j = -BLUR_RADIUS; j <= BLUR_RADIUS; j++) {
                for (int i = -BLUR_RADIUS; i <= BLUR_RADIUS; i++) {
                    int nx = x + i;
                    int ny = y + j;
                    if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
                        int idx = (nx + ny * width) * 3;
                        r_sum += temp[idx];
                        g_sum += temp[idx + 1];
                        b_sum += temp[idx + 2];
                        count++;
                    }
                }
            }
            if (count > 0) {
                int idx = (x + y * width) * 3;
                image[idx] = (unsigned char)(r_sum / count);
                image[idx + 1] = (unsigned char)(g_sum / count);
                image[idx + 2] = (unsigned char)(b_sum / count);
            }
        }
    }
    free(temp);
    return 0;
}

static int save_jpeg(const unsigned char *image, int width, int height, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile = NULL;
    JSAMPROW row_pointer[1];
    int rc = -1;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if (!(outfile = fopen(filename, "wb"))) {
        fprintf(stderr, "Failed to open JPEG file %s: %s\n", filename, strerror(errno));
        goto cleanup;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;
    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)(image + (cinfo.next_scanline * width * 3));
        if (jpeg_write_scanlines(&cinfo, row_pointer, 1) != 1) {
            fprintf(stderr, "JPEG write failed\n");
            goto cleanup;
        }
    }

    jpeg_finish_compress(&cinfo);
    rc = 0;

cleanup:
    if (outfile) fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return rc;
}

int main(void) {
    int fd = -1;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    struct timeval tv;
    fd_set fds;
    unsigned char *rgb_frame = NULL;
    unsigned char *yuyv_frame = NULL;
    int rc = EXIT_FAILURE;

    signal(SIGINT, sigint_handler);

    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", CAMERA_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    rgb_frame = malloc((size_t)WIDTH * HEIGHT * 3);
    yuyv_frame = malloc((size_t)WIDTH * HEIGHT * 2);
    if (!rgb_frame || !yuyv_frame) {
        fprintf(stderr, "Failed to allocate frame buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }
        buf.length = WIDTH * HEIGHT * 2;
        buf.m.offset = buf.m.offset;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            goto cleanup;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        unsigned char *frame_data = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (frame_data == MAP_FAILED) {
            fprintf(stderr, "mmap() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        memcpy(yuyv_frame, frame_data, (size_t)WIDTH * HEIGHT * 2);
        munmap(frame_data, buf.length);

        yuyv_to_rgb(yuyv_frame, rgb_frame, WIDTH, HEIGHT);
        blur_image(rgb_frame, WIDTH, HEIGHT);

        time_t rawtime;
        struct tm *timeinfo;
        char filename[64];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

        if (save_jpeg(rgb_frame, WIDTH, HEIGHT, filename) < 0) {
            fprintf(stderr, "Failed to save JPEG\n");
        } else {
            printf("Saved %s\n", filename);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        break;
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < req.count; i++) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;
            xioctl(fd, VIDIOC_QUERYBUF, &buf);
            if (buf.length > 0 && buf.m.offset > 0) {
                munmap((void *)buf.m.offset, buf.length);
            }
        }
        close(fd);
    }
    free(rgb_frame);
    free(yuyv_frame);
    return rc;
}

