    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    rgb_frame = malloc((size_t)WIDTH * HEIGHT * 3);
    yuyv_frame = malloc((size_t)WIDTH * HEIGHT * 2);
    if (!rgb_frame || !yuyv_frame) {
        fprintf(stderr, "Failed to allocate frame buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }
        buf.length = WIDTH * HEIGHT * 2;
        buf.m.offset = buf.m.offset;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    while (!stop_flag) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            goto cleanup;
        }

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        unsigned char *frame_data = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (frame_data == MAP_FAILED) {
            fprintf(stderr, "mmap() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        memcpy(yuyv_frame, frame_data, (size_t)WIDTH * HEIGHT * 2);
        munmap(frame_data, buf.length);

        yuyv_to_rgb(yuyv_frame, rgb_frame, WIDTH, HEIGHT);
        blur_image(rgb_frame, WIDTH, HEIGHT);

        time_t rawtime;
        struct tm *timeinfo;
        char filename[64];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

        if (save_jpeg(rgb_frame, WIDTH, HEIGHT, filename) < 0) {
            fprintf(stderr, "Failed to save JPEG\n");
        } else {
            printf("Saved %s\n", filename);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            goto cleanup;
        }

        break;
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < req.count; i++) {
            memset(&buf, 0, sizeof(buf));
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;
            buf.index = i;
            xioctl(fd, VIDIOC_QUERYBUF, &buf);
            if (buf.length > 0 && buf.m.offset > 0) {
                munmap((void *)buf.m.offset, buf.length);
            }
        }
        close(fd);
    }
    free(rgb_frame);
    free(yuyv_frame);
    return rc;
}

