#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void print_capability(const struct v4l2_capability *cap) {
    printf("Capabilities:\n");
    printf("  Driver: %s\n", cap->driver);
    printf("  Card: %s\n", cap->card);
    printf("  Bus: %s\n", cap->bus_info);
    printf("  Version: %u.%u.%u\n",
           (cap->version >> 16) & 0xFF,
           (cap->version >> 8) & 0xFF,
           cap->version & 0xFF);
    printf("  Capabilities: 0x%08x\n", cap->capabilities);
}

static void print_frame_size(const struct v4l2_frmsizeenum *fse) {
    printf("  Width: %u, Height: %u\n", fse->discrete.width, fse->discrete.height);
}

static void print_frame_interval(const struct v4l2_frmivalenum *fie) {
    printf("    Width: %u, Height: %u, Interval: %u/%u s\n",
           fse->discrete.width, fse->discrete.height,
           fie->discrete.numerator, fie->discrete.denominator);
}

static void print_supported_resolutions(int fd) {
    struct v4l2_frmsizeenum fse;
    memset(&fse, 0, sizeof(fse));
    fse.index = 0;

    printf("Supported Resolutions:\n");
    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) == 0) {
        if (fse.pixel_format != V4L2_PIX_FMT_YUYV) {
            fse.index++;
            continue;
        }
        printf("  Resolution %u:\n", fse.index);
        print_frame_size(&fse);
        fse.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
    }
}

static void print_supported_framerates(int fd, unsigned int width, unsigned int height) {
    struct v4l2_frmivalenum fie;
    memset(&fie, 0, sizeof(fie));
    fie.index = 0;
    fie.width = width;
    fie.height = height;
    fie.pixel_format = V4L2_PIX_FMT_YUYV;

    printf("  Supported Frame Rates for %ux%u:\n", width, height);
    while (xioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fie) == 0) {
        print_frame_interval(&fie);
        fie.index++;
    }
    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
    }
}

static void print_autofocus_support(int fd) {
    struct v4l2_queryctrl qc;
    memset(&qc, 0, sizeof(qc));
    qc.id = V4L2_CID_FOCUS_AUTO;

    if (xioctl(fd, VIDIOC_QUERYCTRL, &qc) == 0) {
        printf("Autofocus Supported: YES\n");
    } else {
        printf("Autofocus Supported: NO\n");
    }
}

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    print_capability(&cap);
    print_supported_resolutions(fd);

    unsigned int width, height;
    struct v4l2_frmsizeenum fse;
    memset(&fse, 0, sizeof(fse));
    fse.index = 0;

    while (xioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fse) == 0) {
        if (fse.pixel_format != V4L2_PIX_FMT_YUYV) {
            fse.index++;
            continue;
        }
        width = fse.discrete.width;
        height = fse.discrete.height;
        print_supported_framerates(fd, width, height);
        fse.index++;
    }

    if (errno != EINVAL) {
        fprintf(stderr, "Error enumerating frame sizes: %s\n", strerror(errno));
    }

    print_autofocus_support(fd);

    close(fd);
    return EXIT_SUCCESS;
}

