#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN    4
#define TILT_SERVO_PIN   5
#define UP_BUTTON_PIN    6
#define DOWN_BUTTON_PIN  7
#define LEFT_BUTTON_PIN  8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_US     1000
#define SERVO_MAX_US     2000
#define SERVO_CENTER_US  1500
#define SERVO_STEP_US    10
#define LOOP_DELAY_US    50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp_servo(int us)
{
    if (us < SERVO_MIN_US) return SERVO_MIN_US;
    if (us > SERVO_MAX_US) return SERVO_MAX_US;
    return us;
}

static void cleanup(void)
{
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    int pan_pos  = SERVO_CENTER_US;
    int tilt_pos = SERVO_CENTER_US;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups (active-low) */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    /* Configure servo pins for PWM output */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Center servos at startup */
    if (gpioServo(PAN_SERVO_PIN, SERVO_CENTER_US) != 0 ||
        gpioServo(TILT_SERVO_PIN, SERVO_CENTER_US) != 0) {
        fprintf(stderr, "Error: failed to start servo PWM.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers.\n");
    }

    printf("Camera pan-tilt control started.\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  Up button : GPIO%d (active-low)\n", UP_BUTTON_PIN);
    printf("  Down button: GPIO%d (active-low)\n", DOWN_BUTTON_PIN);
    printf("  Left button: GPIO%d (active-low)\n", LEFT_BUTTON_PIN);
    printf("  Right button: GPIO%d (active-low)\n", RIGHT_BUTTON_PIN);
    printf("  Center position: %d us\n", SERVO_CENTER_US);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int up_pressed   = (gpioRead(UP_BUTTON_PIN) == 0);
        int down_pressed = (gpioRead(DOWN_BUTTON_PIN) == 0);
        int left_pressed = (gpioRead(LEFT_BUTTON_PIN) == 0);
        int right_pressed = (gpioRead(RIGHT_BUTTON_PIN) == 0);

        if (up_pressed)   pan_pos = clamp_servo(pan_pos + SERVO_STEP_US);
        if (down_pressed) pan_pos = clamp_servo(pan_pos - SERVO_STEP_US);
        if (left_pressed) tilt_pos = clamp_servo(tilt_pos - SERVO_STEP_US);
        if (right_pressed) tilt_pos = clamp_servo(tilt_pos + SERVO_STEP_US);

        if (gpioServo(PAN_SERVO_PIN, pan_pos) != 0 ||
            gpioServo(TILT_SERVO_PIN, tilt_pos) != 0) {
            fprintf(stderr, "Warning: gpioServo failed in main loop.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

