#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o '%s' --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
             filename);
    int result = system(command);
    if (result == -1) {
        log_event("Error: system() failed to execute libcamera-still.");
        return -1;
    }
    if (!WIFEXITED(result) || WEXITSTATUS(result) != 0) {
        char errmsg[256];
        snprintf(errmsg, sizeof(errmsg),
                 "Error: libcamera-still exited with status %d.",
                 WIFEXITED(result) ? WEXITSTATUS(result) : -1);
        log_event(errmsg);
        return -1;
    }
    return 0;
}

static void generate_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    snprintf(buf, len, "%04d%02d%02d_%02d%02d%02d_%03d",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec,
             tm.tm_mday);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        log_event("Error: Failed to open gpiochip0.");
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", PIR_PIN, strerror(errno));
        log_event("Error: Failed to get GPIO line 17.");
        goto cleanup_chip;
    }

    if (gpiod_line_request_falling_edge_events(pir_line, "motion_capture") < 0) {
        fprintf(stderr, "Error requesting falling edge events on GPIO %d: %s\n",
                PIR_PIN, strerror(errno));
        log_event("Error: Failed to request falling edge events on GPIO 17.");
        goto cleanup_chip;
    }

    log_event("Motion capture service started.");

    while (running) {
        struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
        int event = gpiod_line_event_wait(pir_line, &ts);

        if (event < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            log_event("Error: gpiod_line_event_wait failed.");
            break;
        }

        if (event == 0) {
            continue;
        }

        struct gpiod_line_event ev;
        if (gpiod_line_event_read(pir_line, &ev) < 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            log_event("Error: gpiod_line_event_read failed.");
            continue;
        }

        if (ev.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) {
            continue;
        }

        char timestamp[32];
        generate_timestamp(timestamp, sizeof(timestamp));

        char filename[256];
        snprintf(filename, sizeof(filename), "%s/%s.jpg", IMAGE_DIR, timestamp);

        if (capture_image(filename) == 0) {
            char msg[300];
            snprintf(msg, sizeof(msg), "Motion detected. Image saved: %s", filename);
            log_event(msg);
        } else {
            char msg[256];
            snprintf(msg, sizeof(msg), "Motion detected, but image capture failed for: %s", filename);
            log_event(msg);
        }

        struct timespec remaining = {0, DEBOUNCE_MS * 1000000L};
        while (nanosleep(&remaining, &remaining) == -1 && errno == EINTR && running) {
            /* Retry nanosleep after signal interruption */
        }
    }

    log_event("Motion capture service stopped.");
    ret = 0;

cleanup_chip:
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

