#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define OUTPUT_FILE "cropped.yuv"

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    void *buffer_start = NULL;
    size_t buffer_length = 0;
    FILE *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open(" DEVICE_NAME ")");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer_length = buf.length;
    buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        perror("mmap");
        buffer_start = NULL;
        buffer_length = 0;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int rv = select(fd + 1, &fds, NULL, NULL, &tv);
    if (rv == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "select() interrupted by signal\n");
            goto cleanup;
        }
        perror("select");
        goto cleanup;
    }
    if (rv == 0) {
        fprintf(stderr, "select() timeout: no frame received\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        goto cleanup;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Captured frame is empty (bytesused=0)\n");
        goto cleanup;
    }

    if (buf.index != 0) {
        fprintf(stderr, "Unexpected buffer index %u\n", buf.index);
        goto cleanup;
    }

    if (buf.width != WIDTH || buf.height != HEIGHT || buf.format.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Captured frame dimensions or format mismatch: w=%u h=%u fmt=%u\n",
                buf.width, buf.height, buf.format.pixelformat);
        goto cleanup;
    }

    unsigned char *src = (unsigned char *)buffer_start;
    unsigned char *dst = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!dst) {
        perror("malloc");
        goto cleanup;
    }

    int src_y = CROP_Y * WIDTH * 2;
    int src_x = CROP_X * 2;
    int dst_y = 0;
    int dst_x = 0;

    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int src_idx = src_y + src_x + (y * WIDTH + x) * 2;
            int dst_idx = dst_y + dst_x + y * CROP_WIDTH * 2 + x * 2;
            dst[dst_idx] = src[src_idx];
            dst[dst_idx + 1] = src[src_idx + 1];
        }
    }

    out = fopen(OUTPUT_FILE, "wb");
    if (!out) {
        perror("fopen(" OUTPUT_FILE ")");
        free(dst);
        goto cleanup;
    }

    size_t to_write = CROP_WIDTH * CROP_HEIGHT * 2;
    size_t written = fwrite(dst, 1, to_write, out);
    if (written != to_write) {
        perror("fwrite");
        free(dst);
        goto cleanup;
    }

    printf("Cropped frame saved as %s (%dx%d YUYV)\n", OUTPUT_FILE, CROP_WIDTH, CROP_HEIGHT);
    ret = EXIT_SUCCESS;

cleanup:
    if (out) fclose(out);
    if (buffer_start && buffer_start != MAP_FAILED) munmap(buffer_start, buffer_length);
    if (fd >= 0) {
        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
}

