#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define STEP_SIZE 5
#define NEUTRAL_ANGLE 90
#define PWM_FREQ 50
#define PWM_RANGE 2000000  // 20 ms period for 50 Hz
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulsewidth(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    // SG90: 0 deg = 500 us, 180 deg = 2500 us
    return 500 + (angle * (2500 - 500) / MAX_ANGLE);
}

int set_servo_angle(int gpio, int angle) {
    int pw = angle_to_pulsewidth(angle);
    if (pw < 0) return -1;
    if (gpioPWM(gpio, pw) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", gpio, pw);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQ);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQ);
    gpioSetPWMrange(PAN_GPIO, PWM_RANGE);
    gpioSetPWMrange(TILT_GPIO, PWM_RANGE);

    // Center servos
    if (set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE) != 0 ||
        set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Error: Failed to center servos\n");
        gpioTerminate();
        return 1;
    }

    printf("Pan-Tilt Camera Mount ready. Press arrow keys or 'q' to quit.\n");

    while (keep_running) {
        int c = getchar();
        if (c == EOF) break;

        switch (c) {
            case 'q':
            case 'Q':
                keep_running = 0;
                break;
            case '\033':  // Escape
                c = getchar();
                if (c == '[') {
                    c = getchar();
                    switch (c) {
                        case 'A':  // Up
                            if (set_servo_angle(TILT_GPIO, tilt_angle + STEP_SIZE) != 0)
                                fprintf(stderr, "Error: Failed to adjust tilt\n");
                            break;
                        case 'B':  // Down
                            if (set_servo_angle(TILT_GPIO, tilt_angle - STEP_SIZE) != 0)
                                fprintf(stderr, "Error: Failed to adjust tilt\n");
                            break;
                        case 'C':  // Right
                            if (set_servo_angle(PAN_GPIO, pan_angle + STEP_SIZE) != 0)
                                fprintf(stderr, "Error: Failed to adjust pan\n");
                            break;
                        case 'D':  // Left
                            if (set_servo_angle(PAN_GPIO, pan_angle - STEP_SIZE) != 0)
                                fprintf(stderr, "Error: Failed to adjust pan\n");
                            break;
                    }
                }
                break;
        }

        gpioDelay(DELAY_MS * 1000);
    }

    // Cleanup: center servos
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

