#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define PULSES_PER_LITER 450.0
#define UPDATE_INTERVAL_SEC 1
#define LCD_UPDATE_INTERVAL_SEC 10

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static volatile double total_volume = 0.0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)level; (void)tick;
    pulse_count++;
}

static int init_lcd(void) {
    i2c_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                LCD_I2C_BUS, LCD_I2C_ADDR, i2c_handle);
        return -1;
    }

    /* HD44780 initialization sequence (4-bit mode) */
    char init_cmds[] = {
        0x33, 0x32, 0x28, 0x0C, 0x06, 0x01
    };
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (i2cWriteByte(i2c_handle, init_cmds[i]) < 0) {
            fprintf(stderr, "LCD init write failed at index %zu\n", i);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            return -1;
        }
        gpioDelay(5000); /* 5 ms */
    }
    return 0;
}

static void update_lcd(double flow_rate, double total) {
    if (i2c_handle < 0) return;

    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Total: %.2f L", total);

    /* HD44780 4-bit interface: shift out 4 bits, then send lower nibble */
    char buf[4];
    buf[0] = 0x01; /* LCD line 1 */
    buf[1] = (line1[0] << 4) | (line1[1] >> 4);
    buf[2] = ((line1[1] & 0x0F) << 4) | (line1[2] >> 4);
    buf[3] = ((line1[2] & 0x0F) << 4) | (line1[3] >> 4);
