#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define LCD_ADDR          0x27
#define LCD_WIDTH         16
#define LCD_CHR           1
#define LCD_CMD           0
#define LCD_BACKLIGHT     0x08
#define LCD_ENABLE        0x04
#define LCD_RS            0x01

#define ANEMOMETER_GPIO   17
#define SPI_CHANNEL       0
#define SPI_SPEED         1000000
#define SPI_FLAGS         0
#define ADC_CHANNEL       0
#define ADC_MAX           1023
#define WIND_DIR_MAX      359
#define SAMPLE_MS         500

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void lcd_pulse_enable(int handle, int bits) {
    if (i2cWriteByteData(handle, 0, bits | LCD_ENABLE | LCD_BACKLIGHT) < 0)
        return;
    gpioDelay(1);
    i2cWriteByteData(handle, 0, bits | LCD_BACKLIGHT);
    gpioDelay(50);
}

static void lcd_send_nibble(int handle, int nibble, int mode) {
    int bits = (nibble & 0xF0) | LCD_RS;
    if (mode) bits |= LCD_BACKLIGHT;
    lcd_pulse_enable(handle, bits);
}

static void lcd_send_byte(int handle, int bits, int mode) {
    lcd_send_nibble(handle, bits >> 4, mode);
    lcd_send_nibble(handle, bits & 0x0F, mode);
}

static void lcd_string(int handle, const char *s) {
    while (*s) {
        lcd_send_byte(handle, (uint8_t)*s++, LCD_CHR);
    }
}

static void lcd_clear(int handle) {
    lcd_send_byte(handle, 0x01, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_home(int handle) {
    lcd_send_byte(handle, 0x02, LCD_CMD);
    gpioDelay(2000);
}

static void lcd_set_cursor(int handle, int col, int row) {
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_send_byte(handle, addr, LCD_CMD);
}

static int lcd_init(int handle) {
    gpioDelay(50000);
    lcd_send_nibble(handle, 0x30, LCD_CMD);
    gpioDelay(5000);
    lcd_send_nibble(handle, 0x30, LCD_CMD);
    gpioDelay(150);
    lcd_send_nibble(handle, 0x30, LCD_CMD);
    gpioDelay(150);
    lcd_send_nibble(handle, 0x20, LCD_CMD);
    gpioDelay(150);
    lcd_send_byte(handle, 0x28, LCD_CMD);
    lcd_send_byte(handle, 0x0C, LCD_CMD);
    lcd_send_byte(handle, 0x06, LCD_CMD);
    lcd_send_byte(handle, 0x01, LCD_CMD);
    lcd_clear(handle);
    return 0;
}

static int read_adc(int handle, int channel) {
    if (channel < 0 || channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};
    if (spiXfer(handle, (char *)tx, (char *)rx, 3) < 0)
        return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_wind_direction(int handle) {
    int adc = read_adc(handle, ADC_CHANNEL);
    if (adc < 0) return -1;
    if (adc == 0 || adc == ADC_MAX) {
        fprintf(stderr, "Warning: ADC stuck at %d (sensor absent or wiring fault)\n", adc);
        return -1;
    }
    return (int)(((float)adc / (float)ADC_MAX) * (float)WIND_DIR_MAX + 0.5f);
}

static void display_wind_speed(int handle, float speed) {
    char buf[17];
    snprintf(buf, sizeof(buf), "Speed: %.1f m/s", speed);
    lcd_clear(handle);
    lcd_set_cursor(handle, 0, 0);
    lcd_string(handle, buf);
}

static void display_wind_direction(int handle, int direction) {
    char buf[17];
    snprintf(buf, sizeof(buf), "Dir: %d deg", direction);
    lcd_set_cursor(handle, 0, 1);
    lcd_string(handle, buf);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, LCD_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", SPI_CHANNEL, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return 1;
    }

    if (lcd_init(g_i2c_handle) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(ANEMOMETER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP);

    volatile int pulse_count = 0;
    int last_pulse_count = 0;
    uint32_t last_tick = gpioTick();

    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", ANEMOMETER_GPIO);
        cleanup();
        return 1;
    }

    while (g_running) {
        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_tick;
        if (elapsed >= SAMPLE_MS * 1000) {
            int current_pulse_count = pulse_count;
            float speed = (float)(current_pulse_count - last_pulse_count) * 0.5f;
            int direction = read_wind_direction(g_spi_handle);

            display_wind_speed(g_i2c_handle, speed);
            if (direction >= 0) {
                display_wind_direction(g_i2c_handle, direction);
            } else {
                lcd_clear(g_i2c_handle);
                lcd_set_cursor(g_i2c_handle, 0, 0);
                lcd_string(g_i2c_handle, "Dir: N/A");
            }

            last_pulse_count = current_pulse_count;
            last_tick = now;
        }
        gpioDelay(10000);
    }

    lcd_clear(g_i2c_handle);
    lcd_string(g_i2c_handle, "Shutting down");
    gpioDelay(1000000);
    cleanup();
    return 0;
}

