#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define CALIBRATION_FACTOR 7.5
#define SAMPLE_INTERVAL_SEC 1
#define MAX_CONSECUTIVE_ZERO_PULSES 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void lcd_send_byte(int handle, unsigned char val, int is_data) {
    unsigned char high = (val & 0xF0) | (is_data ? 0x0D : 0x0C);
    unsigned char low = ((val << 4) & 0xF0) | (is_data ? 0x0D : 0x0C);
    if (i2cWriteByte(handle, high) < 0) {
        fprintf(stderr, "Error: I2C write failed (high nibble).\n");
    }
    if (i2cWriteByte(handle, low) < 0) {
        fprintf(stderr, "Error: I2C write failed (low nibble).\n");
    }
    gpioDelay(1000);
}

static void lcd_send_command(int handle, unsigned char cmd) {
    lcd_send_byte(handle, cmd, 0);
}

static void lcd_send_data(int handle, unsigned char data) {
    lcd_send_byte(handle, data, 1);
}

static void lcd_init(int handle) {
    gpioDelay(50000);
    lcd_send_command(handle, 0x33);
    lcd_send_command(handle, 0x32);
    lcd_send_command(handle, 0x28);
    lcd_send_command(handle, 0x0C);
    lcd_send_command(handle, 0x06);
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_clear(int handle) {
    lcd_send_command(handle, 0x01);
    gpioDelay(2000);
}

static void lcd_set_cursor(int handle, int row, int col) {
    unsigned char addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_send_command(handle, addr);
}

static void lcd_write_string(int handle, const char *str) {
    while (*str) {
        lcd_send_data(handle, (unsigned char)*str++);
    }
}

static void display_flow_rate(int handle, float flow_rate) {
    char buffer[17];
    lcd_clear(handle);
    lcd_set_cursor(handle, 0, 0);
    lcd_write_string(handle, "Flow Rate:");
    lcd_set_cursor(handle, 1, 0);
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_write_string(handle, buffer);
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick;
    int *pulse_count = (int *)userdata;
    if (level == 1) {
        (*pulse_count)++;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Warning: Failed to set pull-up on GPIO%d.\n", FLOW_SENSOR_GPIO);
    }

    i2c_handle = i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", LCD_I2C_BUS, LCD_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init(i2c_handle);
    lcd_clear(i2c_handle);
    lcd_write_string(i2c_handle, "Initializing...");
    gpioDelay(1000000);

    int pulse_count = 0;
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, &pulse_count) != 0) {
        fprintf(stderr, "Error: Failed to set alert function on GPIO%d.\n", FLOW_SENSOR_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);

        int pulses = pulse_count;
        pulse_count = 0;

        if (pulses == 0) {
            static int zero_count = 0;
            zero_count++;
            if (zero_count >= MAX_CONSECUTIVE_ZERO_PULSES) {
                fprintf(stderr, "Warning: No pulses detected for %d seconds. Sensor may be disconnected.\n", zero_count);
                lcd_clear(i2c_handle);
                lcd_write_string(i2c_handle, "Sensor absent");
            }
            continue;
        }

        zero_count = 0;
        float flow_rate = (float)pulses / CALIBRATION_FACTOR * 60.0f;
        display_flow_rate(i2c_handle, flow_rate);
    }

    printf("\nShutting down...\n");
    lcd_clear(i2c_handle);
    lcd_write_string(i2c_handle, "Shutting down");
    gpioDelay(1000000);

    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

