#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static volatile sig_atomic_t running = 1;

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];

static void cleanup_and_exit(int signum) {
    (void)signum;
    running = 0;
}

static void release_lines(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            return -1;
        }
    }
    return 0;
}

static void all_off(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_set_value(row_lines[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_set_value(col_lines[i], 1);
    }
}

static void display_frame(const int frame[NUM_ROWS]) {
    all_off();
    for (int row = 0; row < NUM_ROWS; row++) {
        if (gpiod_line_set_value(row_lines[row], 1) < 0) {
            fprintf(stderr, "Failed to set row %d HIGH\n", row);
            return;
        }
        for (int col = 0; col < NUM_COLS; col++) {
            int val = (frame[row] >> col) & 1;
            if (gpiod_line_set_value(col_lines[col], val) < 0) {
                fprintf(stderr, "Failed to set col %d %s\n", col, val ? "HIGH" : "LOW");
                return;
            }
        }
        usleep(SCAN_DELAY_US);
    }
    all_off();
}

static void shift_left_to_right(int frame[NUM_ROWS]) {
    for (int i = 0; i < NUM_ROWS; i++) {
        frame[i] = (frame[i] << 1) | (frame[i + 1] & 0x80);
    }
}

static void shift_right_to_left(int frame[NUM_ROWS]) {
    for (int i = NUM_ROWS - 1; i > 0; i--) {
        frame[i] = (frame[i] >> 1) | ((frame[i - 1] & 1) << 7);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (setup_gpio() < 0) {
        release_lines();
        return 1;
    }

    int frame[NUM_ROWS] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80};

    while (running) {
        display_frame(frame);
        shift_left_to_right(frame);
        usleep(100000);
    }

    release_lines();
    return 0;
}

