#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define DELAY_MS 150

// GPIO lines for row anodes (active low) and column cathodes (active high)
const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile int keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
            row_lines[i] = NULL;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
            col_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    // Open GPIO chip 0 (Raspberry Pi GPIO controller)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open /dev/gpiochip0");
        return EXIT_FAILURE;
    }

    // Request row anode lines as outputs, initially HIGH (inactive for common anode)
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    // Request column cathode lines as outputs, initially LOW (off)
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            release_resources();
            return EXIT_FAILURE;
        }
    }

    // Set up signal handlers for clean exit
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    // Main animation loop
    while (keep_running) {
        // Clear matrix: set all column cathodes HIGH (off) and all row anodes LOW (off)
        for (int i = 0; i < NUM_COLS; i++) {
            gpiod_line_set_value(col_lines[i], 1);
        }
        for (int i = 0; i < NUM_ROWS; i++) {
            gpiod_line_set_value(row_lines[i], 0);
        }
        usleep(1000); // small delay to ensure all lines settle

        // Scan columns from left to right
        for (int col = 0; col < NUM_COLS && keep_running; col++) {
            // Set column cathode LOW to light this column
            if (gpiod_line_set_value(col_lines[col], 0) < 0) {
                fprintf(stderr, "Failed to set column %d LOW\n", col);
                cleanup_and_exit(0);
            }
            // Set all row anodes HIGH to light this column
            for (int row = 0; row < NUM_ROWS; row++) {
                if (gpiod_line_set_value(row_lines[row], 1) < 0) {
                    fprintf(stderr, "Failed to set row %d HIGH\n", row);
                    cleanup_and_exit(0);
                }
            }
            usleep(DELAY_MS * 1000);

            // Clear column: set column cathode HIGH (off) and row anodes LOW (off)
            if (gpiod_line_set_value(col_lines[col], 1) < 0) {
                fprintf(stderr, "Failed to set column %d HIGH\n", col);
                cleanup_and_exit(0);
            }
            for (int row = 0; row < NUM_ROWS; row++) {
                if (gpiod_line_set_value(row_lines[row], 0) < 0) {
                    fprintf(stderr, "Failed to set row %d LOW\n", row);
                    cleanup_and_exit(0);
                }
            }
            usleep(DELAY_MS * 1000);
        }
    }

    // Clean exit
    release_resources();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

