/*
 * VL53L3CX Time-of-Flight Multi-Target Sensor Reader
 * Board: Raspberry Pi 3 Model B+
 * Bus: I2C bus 1 (GPIO2=SDA, GPIO3=SCL), Address: 0x29
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download (ULD)
 * sequence. The code below stubs the initialization flow; replace the
 * register writes with the actual ULD commands from ST's datasheet.
 *
 * Build: gcc -Wall -o vl53l3cx vl53l3cx.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L3CX_ADDR  0x29

/* VL53L3CX Register Map (Standard ULD API) */
#define REG_SOFT_RESET              0x0003
#define REG_MODEL_ID                0x010F
#define REG_SYSTEM_START            0x0187
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_NUM_TARGETS      0x008A
#define REG_RESULT_TARGET_DISTANCE  0x0096

#define EXPECTED_MODEL_ID           0xEA
#define MAX_TARGETS                 4
#define POLL_DELAY_US               100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address and 16-bit value to the sensor */
static int write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register from the sensor */
static int read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* Read a 32-bit register from the sensor */
static int read_reg32(int handle, uint16_t reg, uint32_t *value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 4) != 4) {
        return -1;
    }
    *value = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
             ((uint32_t)buf[2] << 8)  | (uint32_t)buf[3];
    return 0;
}

/* Initialize the VL53L3CX sensor */
static int init_sensor(int handle) {
    uint16_t model_id = 0;

    /* 1. Software Reset */
    if (write_reg16(handle, REG_SOFT_RESET, 0x0001) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* 2. Verify Model ID */
    if (read_reg16(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Unexpected model ID 0x%04X (expected 0x%04X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L3CX detected (Model ID: 0x%04X).\n", model_id);

    /* 3. Start ranging (Standard ULD flow) */
    /*
     * Replace the following stub with the actual ULD commands from ST's
     * datasheet. The ULD flow configures the sensor for ranging and
     * enables the system.
     */
    if (write_reg16(handle, REG_SYSTEM_START, 0x0001) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */

    return 0;
}

/* Read distance data for all detected targets */
static int read_distance_data(int handle, int *num_targets, uint16_t *distances) {
    uint16_t status = 0;
    uint32_t num_targets_u32 = 0;

    /* Check if new data is ready */
    if (read_reg16(handle, REG_RESULT_RANGE_STATUS, &status) < 0) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* No new data yet */
    }

    /* Read number of targets */
    if (read_reg16(handle, REG_RESULT_NUM_TARGETS, &num_targets_u32) < 0) {
        fprintf(stderr, "Error: Failed to read number of targets.\n");
        return -1;
    }
    *num_targets = (int)num_targets_u32;

    /* Read distances for each target */
    for (int i = 0; i < *num_targets; i++) {
        uint16_t reg = REG_RESULT_TARGET_DISTANCE + (uint16_t)(i * 2);
        if (read_reg16(handle, reg, &distances[i]) < 0) {
            fprintf(stderr, "Error: Failed to read distance for target %d.\n", i);
            return -1;
        }
    }

    /* Clear interrupt to allow next measurement */
    if (write_reg16(handle, REG_RESULT_RANGE_STATUS, 0x0001) < 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
    }

    return 0;
}

/* Log distance data to the console with timestamp */
static void log_data(int num_targets, const uint16_t *distances) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Targets: %d", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf("  Target %d: %u mm", i + 1, distances[i]);
    }
    printf("\n");
    fflush(stdout);
}

int main(void) {
    int num_targets = 0;
    uint16_t distances[MAX_TARGETS];

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (handle: %d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L3CX reader started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int ret = read_distance_data(i2c_handle, &num_targets, distances);
        if (ret == 0) {
            log_data(num_targets, distances);
        } else if (ret < 0) {
            fprintf(stderr, "Error: Failed to read distance data.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

