#define SI1145_ADDR 0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_IRQ_ENABLE 0x0F
#define SI1145_REG_IRQ_STATUS 0x12
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0 0x24
#define SI1145_REG_ALS_IR_DATA1 0x25
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_PS_AUTO 0x0D
#define SI1145_CMD_ALS_AUTO 0x0B
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X val=0x%02X rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X rc=%d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_lo, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(reg_lo, &lo) < 0) return -1;
    if (read_reg(reg_lo + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    gpioDelay(10000);

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;

    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;

    if (write_reg(SI1145_REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_IRQ_STATUS, 0xFF) < 0) return -1;

    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_AUTO) < 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_AUTO) < 0) return -1;

    gpioDelay(10000);
    return 0;
}

static void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, msg);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Logging Si1145 data to biometric_log.txt (Ctrl+C to stop)\n");

    while (running) {
        uint16_t proximity, ambient_light;

        if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) {
            log_error("Failed to trigger ALS force");
            gpioDelay(500000);
            continue;
        }
        gpioDelay(10000);

        if (read_word(SI1145_REG_ALS_VIS_DATA0, &ambient_light) < 0) {
            log_error("Failed to read ambient light");
            gpioDelay(500000);
            continue;
        }

        if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) {
            log_error("Failed to trigger PS force");
            gpioDelay(500000);
            continue;
        }
        gpioDelay(10000);

        if (read_word(SI1145_REG_ALS_IR_DATA0, &proximity) < 0) {
            log_error("Failed to read proximity");
            gpioDelay(500000);
            continue;
        }

        log_data(proximity, ambient_light);
        gpioDelay(500000);
    }

    printf("\nShutting down cleanly...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

