#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define DISTANCE_THRESHOLD 15.0
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 60
#define TIMEOUT_US 30000
#define TRIGGER_PULSE_US 10
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

static void log_reading(float distance, const char *status) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: Distance=%.2f cm, Status=%s\n", ts, distance, status);
    fflush(log_file);
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **trig, struct gpiod_line **echo) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    *trig = gpiod_chip_get_line(*chip, TRIGGER_PIN);
    if (!*trig) {
        perror("gpiod_chip_get_line(trigger)");
        gpiod_chip_close(*chip);
        return -1;
    }
    *echo = gpiod_chip_get_line(*chip, ECHO_PIN);
    if (!*echo) {
        perror("gpiod_chip_get_line(echo)");
        gpiod_chip_close(*chip);
        return -1;
    }
    if (gpiod_line_request_output(*trig, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        gpiod_chip_close(*chip);
        return -1;
    }
    if (gpiod_line_request_input(*echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        gpiod_line_release(*trig);
        gpiod_chip_close(*chip);
        return -1;
    }
    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *trig, struct gpiod_line *echo) {
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
}

static long long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL + (end->tv_nsec - start->tv_nsec) / 1000LL;
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo, float *distance) {
    struct timespec start, end;
    struct timespec timeout = {0, TIMEOUT_US * 1000};
    int ret;

    memset(&start, 0, sizeof(start));
    memset(&end, 0, sizeof(end));

    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    ret = clock_gettime(CLOCK_MONOTONIC, &start);
    if (ret < 0) return -1;

    while (gpiod_line_get_value(echo) == 0) {
        if (elapsed_us(&start, &(struct timespec){0}) > TIMEOUT_US) return 1;
    }
    ret = clock_gettime(CLOCK_MONOTONIC, &end);
    if (ret < 0) return -1;

    while (gpiod_line_get_value(echo) == 1) {
        if (elapsed_us(&end, &(struct timespec){0}) > TIMEOUT_US) return 1;
    }
    ret = clock_gettime(CLOCK_MONOTONIC, &end);
    if (ret < 0) return -1;

    long long pulse_us = elapsed_us(&start, &end);
    *distance = (float)pulse_us * 34300.0f / 2.0f / 1000000.0f;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    float distance;
    int rc;

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    if (init_gpio(&chip, &trig, &echo) < 0) {
        log_message("GPIO initialization failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup_gpio(chip, trig, echo);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_message("Program started");

    while (program_running) {
        rc = measure_distance(trig, echo, &distance);
        if (rc == 0) {
            if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
                log_reading(distance, "OK");
                if (distance < DISTANCE_THRESHOLD) {
                    log_message("Time to water the plant!");
                }
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Out of range: %.2f cm", distance);
                log_reading(distance, msg);
            }
        } else if (rc == 1) {
            log_reading(0.0f, "Timeout");
        } else {
            log_reading(0.0f, "GPIO error");
        }
        sleep(POLL_INTERVAL_SEC);
    }

    log_message("Program exiting");
    cleanup_gpio(chip, trig, echo);
    fclose(log_file);
    return EXIT_SUCCESS;
}

