/* APDS-9960 I2C address (ADDR pin tied to GND) */
#define APDS9960_ADDR 0x39

/* APDS-9960 register addresses */
#define APDS9960_ENABLE   0x80
#define APDS9960_ATIME    0x81
#define APDS9960_WTIME    0x83
#define APDS9960_PPULSE   0x8E
#define APDS9960_CONTROL  0xF1
#define APDS9960_CONFIG2  0x90
#define APDS9960_ID       0x92
#define APDS9960_STATUS   0x93
#define APDS9960_CDATAL   0x96
#define APDS9960_CDATAH   0x97
#define APDS9960_RDATAL   0x98
#define APDS9960_RDATAH   0x99
#define APDS9960_GDATAL   0x9A
#define APDS9960_GDATAH   0x9B
#define APDS9960_PDATA    0x9C

/* Expected device ID */
#define APDS9960_ID_VALUE 0xAB

/* Proximity threshold */
#define PROXIMITY_THRESHOLD 200

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an APDS-9960 register                               */
/* ------------------------------------------------------------------ */
static int apds9960_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a byte from an APDS-9960 register                              */
/* ------------------------------------------------------------------ */
static int apds9960_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Initialize the APDS-9960 sensor                                     */
/* ------------------------------------------------------------------ */
static int apds9960_init(int handle)
{
    int rc;

    /* Verify device ID */
    rc = apds9960_read_reg(handle, APDS9960_ID);
    if (rc < 0) {
        return -1;
    }
    if (rc != APDS9960_ID_VALUE) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                rc, APDS9960_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (apds9960_write_reg(handle, APDS9960_ENABLE, 0x03) < 0) return -1;

    /* ALS integration time: 256 - 0xDB = 211 cycles */
    if (apds9960_write_reg(handle, APDS9960_ATIME, 0xDB) < 0) return -1;

    /* Wait time: 0xF6 * 2.78 ms = 811.4 ms */
    if (apds9960_write_reg(handle, APDS9960_WTIME, 0xF6) < 0) return -1;

    /* Proximity pulse length: 0x87 * 2.78 ms = 229.1 ms */
    if (apds9960_write_reg(handle, APDS9960_PPULSE, 0x87) < 0) return -1;

    /* Control register: PGAIN=4x, AGAIN=4x, PDRIVE=100mA */
    if (apds9960_write_reg(handle, APDS9960_CONTROL, 0x03) < 0) return -1;

    /* Config2: 100 ms ADC integration time */
    if (apds9960_write_reg(handle, APDS9960_CONFIG2, 0x01) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read RGB and proximity values from the APDS-9960                    */
/* ------------------------------------------------------------------ */
static int apds9960_read_data(int handle, uint16_t *red, uint16_t *green,
                              uint16_t *blue, uint8_t *proximity)
{
    int rc;

    rc = apds9960_read_reg(handle, APDS9960_CDATAL);
    if (rc < 0) return -1;
    *red   = (uint16_t)rc;

    rc = apds9960_read_reg(handle, APDS9960_CDATAH);
    if (rc < 0) return -1;
    *red   |= ((uint16_t)rc << 8);

    rc = apds9960_read_reg(handle, APDS9960_RDATAL);
    if (rc < 0) return -1;
    *green = (uint16_t)rc;

    rc = apds9960_read_reg(handle, APDS9960_RDATAH);
    if (rc < 0) return -1;
    *green |= ((uint16_t)rc << 8);

    rc = apds9960_read_reg(handle, APDS9960_GDATAL);
    if (rc < 0) return -1;
    *blue  = (uint16_t)rc;

    rc = apds9960_read_reg(handle, APDS9960_GDATAH);
    if (rc < 0) return -1;
    *blue  |= ((uint16_t)rc << 8);

    rc = apds9960_read_reg(handle, APDS9960_PDATA);
    if (rc < 0) return -1;
    *proximity = (uint8_t)rc;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log data to the CSV file                                            */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t green,
                     uint16_t blue, uint8_t proximity)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        return;
    }

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(fp);
}

