        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the CSV log file in append mode */
    g_log_file = fopen("color_proximity_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open color_proximity_log.csv for writing\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,red,green,blue,proximity\n");
        fflush(g_log_file);
    }

