    }

    printf("APDS-9960 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        rc = apds9960_read_data(g_i2c_handle, &red, &green, &blue, &proximity);

        if (rc == 0) {
            if (proximity > PROXIMITY_THRESHOLD) {
                log_data(g_log_file, red, green, blue, proximity);
            }
        } else {
            fprintf(stderr, "[WARN] I2C read error — re-initializing sensor...\n");

            /* Close and re-open the I2C bus */
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;

            g_i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[ERROR] i2cOpen failed after close: %d\n",
