            if (apds9960_init(g_i2c_handle) < 0) {
                fprintf(stderr, "[ERROR] Sensor re-initialization failed\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

