#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI1182_ADDR    0x5A

#define REG_PART_ID     0x00
#define REG_MEAS_RATE0  0x08
#define REG_PS_DATA0    0x24
#define REG_PS_DATA1    0x25
#define REG_COMMAND     0x47

#define CMD_RESET       0x01
#define CMD_START       0x08

#define EXPECTED_PART_ID 0x82

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    union i2c_smbus_data data;
    data.byte = val;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_WRITE,
        .command = reg,
        .size = I2C_SMBUS_BYTE_DATA,
        .data = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_write_byte: ioctl failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out) {
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_READ,
        .command = reg,
        .size = I2C_SMBUS_BYTE_DATA,
        .data = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_read_byte: ioctl failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = data.byte;
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out) {
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args = {
        .read_write = I2C_SMBUS_READ,
        .command = reg,
        .size = I2C_SMBUS_WORD_DATA,
        .data = &data
    };
    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_read_word: ioctl failed for reg 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)data.word;
    return 0;
}

static int si1182_init(int fd) {
    uint8_t part_id;
    if (i2c_read_byte(fd, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    if (i2c_write_byte(fd, REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Failed to configure MEAS_RATE0.\n");
        return -1;
    }

    if (i2c_write_byte(fd, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Failed to reset Si1182.\n");
        return -1;
    }
    usleep(10000);

    if (i2c_write_byte(fd, REG_COMMAND, CMD_START) < 0) {
        fprintf(stderr, "Failed to start Si1182.\n");
        return -1;
    }
    usleep(10000);

    return 0;
}

static int read_proximity(int fd, uint16_t *prox) {
    return i2c_read_word(fd, REG_PS_DATA0, prox);
}

static int calculate_bpm(uint16_t prox) {
    return (int)(1000000.0 / (double)prox);
}

static void log_data(FILE *fp, int bpm) {
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d\n", ts, bpm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SI1182_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (si1182_init(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        close(fd);
        return 1;
    }

    FILE *fp = fopen("heartrate.csv", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open heartrate.csv: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Starting heart rate measurement. Press Ctrl+C to stop.\n");

    while (running) {
        uint16_t prox;
        if (read_proximity(fd, &prox) < 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample.\n");
            usleep(100000);
            continue;
        }

        int bpm = calculate_bpm(prox);
        log_data(fp, bpm);
        usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    fclose(fp);
    close(fd);
    return 0;
}

