#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

/* VL53L0X register addresses */
#define REG_SYSRANGE_START          0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS     0x14
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0B

#define MEASUREMENT_TIMEOUT_MS 100
#define POLL_DELAY_US          1000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C read block failed (reg 0x%02X, len %u): %d\n", reg, len, rc);
    }
    return rc;
}

static int vl53l0x_init(int handle) {
    /* Probe: try a dummy read to confirm the device is present */
    uint8_t dummy;
    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, &dummy, 1) < 0) {
        fprintf(stderr, "VL53L0X not detected at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    /* Start a single measurement */
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0) {
        return -1;
    }

    /* Poll interrupt status until data ready or timeout */
    uint8_t status = 0xFF;
    int elapsed = 0;
    while (status != 0x00 && elapsed < MEASUREMENT_TIMEOUT_MS) {
        if (i2c_read_block(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) < 0) {
            return -1;
        }
        if (status != 0x00) {
            gpioDelay(POLL_DELAY_US);
            elapsed += POLL_DELAY_US / 1000;
        }
    }

    if (status != 0x00) {
        fprintf(stderr, "VL53L0X measurement timeout after %d ms\n", MEASUREMENT_TIMEOUT_MS);
        return -1;
    }

    /* Read 14-byte result block starting at RESULT_RANGE_STATUS (0x14) */
    uint8_t data[14];
    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) < 0) {
        return -1;
    }

    /* Clear the interrupt so the next measurement can be triggered */
    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        return -1;
    }

    /* Distance is bytes 10-11 of the 14-byte block (big-endian) */
    *distance_mm = ((uint16_t)data[10] << 8) | data[11];
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, distance_mm);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, VL53L0X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l0x_init(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO pin as input with pull-up */
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X distance measurement started. Press Ctrl+C to exit.\n");

    /* Main loop: trigger on falling edge */
    while (running) {
        if (gpioRead(GPIO_PIN) == 0) {
            uint16_t distance;
            if (vl53l0x_read_distance(i2c_handle, &distance) == 0) {
                log_distance(log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Failed to read distance\n");
            }
            /* Wait for GPIO to go high again to avoid immediate re-trigger */
            while (gpioRead(GPIO_PIN) == 0 && running) {
                gpioDelay(1000);
            }
        }
        gpioDelay(1000);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

