#define LED_GPIO 17
#define DISTANCE_THRESHOLD_CM 20.0f
#define LOG_FILE "distance_log.txt"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_distance_cm(float *distance_cm) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *distance_cm = (float)raw / 100.0f;
    return 0;
}

static void log_distance(float distance_cm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance_cm);
    fclose(fp);
}

static void control_led(float distance_cm) {
    int level = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", LED_GPIO);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Starting distance monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float distance_cm;
        if (read_distance_cm(&distance_cm) == 0) {
            log_distance(distance_cm);
            control_led(distance_cm);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

