#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define WHO_AM_I_REG 0x01
#define WHO_AM_I_VAL 0x01
#define DISTANCE_REG 0x02
#define LED_GPIO 17
#define LOG_FILE "tof_log.txt"
#define POLL_DELAY_US 50000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed for reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed for reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    uint8_t lo, hi;
    if (read_register(handle, DISTANCE_REG, &lo) < 0) return -1;
    if (read_register(handle, DISTANCE_REG + 1, &hi) < 0) return -1;
    *distance = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void log_distance(uint16_t distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %u mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    }
    fclose(fp);
}

static void control_led(int gpio, int on) {
    gpioWrite(gpio, on ? 1 : 0);
}

int main(int argc, char *argv[]) {
    int threshold = (argc > 1) ? atoi(argv[1]) : 100;
    if (threshold <= 0) {
        fprintf(stderr, "Invalid threshold, using default 100 mm\n");
        threshold = 100;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who;
    if (read_register(i2c_handle, WHO_AM_I_REG, &who) < 0) {
        fprintf(stderr, "Sensor not responding or WHO_AM_I read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 initialized. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    while (running) {
        uint16_t dist;
        if (read_distance(i2c_handle, &dist) == 0) {
            log_distance(dist);
            control_led(LED_GPIO, dist < threshold);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

