#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define INTRUSION_THRESHOLD_MM 1000
#define NUM_SAMPLES 10
#define MEASUREMENT_DELAY_MS 10
#define SAMPLE_DELAY_MS 100
#define LOG_FILE "intrusion_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_bytes(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int read_distance(int fd, int *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_bytes(fd, cmd, sizeof(cmd)) != 0) {
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, resp, sizeof(resp)) != 0) {
        return -1;
    }

    if (resp[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X (expected 0x50)\n", resp[0]);
        return -1;
    }

    *distance_mm = ((int)resp[11] << 8) | resp[12];
    return 0;
}

static void log_intrusion(int distance_mm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Intrusion detected! Distance: %d mm\n", ts, distance_mm);
    } else {
        fprintf(fp, "[timestamp error] - Intrusion detected! Distance: %d mm\n", distance_mm);
    }

    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SENSOR_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    printf("Omron B5L-LD50-07050 intrusion detection started.\n");
    printf("Threshold: %d mm. Press Ctrl+C to exit.\n", INTRUSION_THRESHOLD_MM);

    while (running) {
        int sum = 0;
        int valid = 0;

        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            int dist;
            if (read_distance(i2c_fd, &dist) == 0) {
                sum += dist;
                valid++;
            } else {
                fprintf(stderr, "Sensor read failed (sample %d/%d).\n", i + 1, NUM_SAMPLES);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid > 0) {
            int avg = sum / valid;
            printf("Average distance: %d mm\n", avg);
            if (avg < INTRUSION_THRESHOLD_MM) {
                log_intrusion(avg);
            }
        } else {
            fprintf(stderr, "No valid samples this cycle.\n");
        }

        if (running) {
            usleep(SAMPLE_DELAY_MS * 1000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

