        for (int i = 0; i < NUM_SAMPLES && running; i++) {
            int dist;
            if (read_distance(i2c_fd, &dist) == 0) {
                sum += dist;
                valid++;
            } else {
                fprintf(stderr, "Sensor read failed (sample %d/%d).\n", i + 1, NUM_SAMPLES);
            }
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (valid > 0) {
            int avg = sum / valid;
            printf("Average distance: %d mm\n", avg);
            if (avg < INTRUSION_THRESHOLD_MM) {
                log_intrusion(avg);
            }
        } else {
            fprintf(stderr, "No valid samples this cycle.\n");
        }

        if (running) {
            usleep(SAMPLE_DELAY_MS * 1000);
        }
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 0;
}

