#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* VL53L0X I2C default address */
#define VL53L0X_ADDR 0x29

/* VL53L0X register addresses */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0xC0
#define VL53L0X_REG_SYSRANGE_START           0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS  0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS      0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR   0x0B

#define VL53L0X_MODEL_ID_EXPECTED 0xEE

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Polling timeout for ranging completion (microseconds) */
#define RANGING_TIMEOUT_US 100000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write one byte to a VL53L0X register; returns 0 on success, -1 on error. */
static int vl53l0x_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a VL53L0X register; returns 0 on success, -1 on error. */
static int vl53l0x_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* Read a 16-bit little-endian value from two consecutive registers. */
static int vl53l0x_read_word(int handle, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (vl53l0x_read_byte(handle, reg, &lo) < 0)
        return -1;
    if (vl53l0x_read_byte(handle, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* Initialize the VL53L0X sensor. Returns 0 on success, -1 on error. */
static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    if (vl53l0x_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X).\n",
                model_id, VL53L0X_MODEL_ID_EXPECTED);
        return -1;
    }

    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);
    return 0;
}

/* Perform a single-shot ranging measurement. Returns distance in mm on success,
   -1 on error, -2 on timeout. */
static int vl53l0x_read_distance(int handle)
{
    /* Start a single-shot measurement */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS until bit 0 is set (data ready) */
    uint8_t status = 0;
    int elapsed = 0;
    const int poll_step = 5000; /* 5 ms */

    while (elapsed < RANGING_TIMEOUT_US) {
        if (vl53l0x_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(poll_step);
        elapsed += poll_step;
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Ranging timeout after %d us.\n", RANGING_TIMEOUT_US);
        return -2;
    }

    /* Read 16-bit distance (little-endian) */
    uint16_t distance = 0;
    if (vl53l0x_read_word(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &distance) < 0)
        return -1;

    /* Clear the interrupt so the next measurement can signal again */
    if (vl53l0x_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return (int)distance;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C device at VL53L0X_ADDR on bus 1 */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting VL53L0X distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        int distance = vl53l0x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Distance: %d mm\n", timestamp, distance);
            fflush(stdout);
        } else if (distance == -2) {
            fprintf(stderr, "Ranging timeout.\n");
        } else {
            fprintf(stderr, "I2C read error during ranging.\n");
        }

        gpioDelay(500000); /* 500 ms between readings */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

