#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1182_ADDR 0x39
#define REG_IRQ_STATUS 0x25
#define REG_PROX_LSB 0x2A
#define REG_PROX_MSB 0x2B
#define REG_CONFIG 0x18
#define CONFIG_PROX_MODE 0x01

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_proximity(int handle, uint16_t *prox) {
    uint8_t lsb, msb;
    if (read_reg(handle, REG_PROX_LSB, &lsb) < 0) return -1;
    if (read_reg(handle, REG_PROX_MSB, &msb) < 0) return -1;
    *prox = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, SI1182_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SI1182_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id = 0;
    if (read_reg(handle, 0x00, &part_id) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X (NACK)\n", SI1182_ADDR);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Si1182 detected (PART_ID=0x%02X)\n", part_id);

    if (write_reg(handle, REG_CONFIG, CONFIG_PROX_MODE) < 0) {
        fprintf(stderr, "Failed to configure Si1182 for proximity mode\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t irq = 0;
        if (read_reg(handle, REG_IRQ_STATUS, &irq) < 0) {
            fprintf(stderr, "Error reading IRQ status\n");
            break;
        }
        if (irq & 0x01) {
            uint16_t prox = 0;
            if (read_proximity(handle, &prox) == 0) {
                printf("Proximity: %u\n", prox);
                fflush(stdout);
            } else {
                fprintf(stderr, "Error reading proximity data\n");
            }
        }
        gpioDelay(500000);
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

