/*
 * MLX75030 Time-of-Flight distance sensor reader for Raspberry Pi 4.
 * Uses the Linux I2C userland API (i2c-dev) — no wiringPi.
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD -> 3.3 V
 *   MLX75030 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c
 * Run:    ./mlx75030   (user must be in the 'i2c' group or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS          "/dev/i2c-1"
#define MLX75030_ADDR    0x4C
#define DISTANCE_REG     0x00
#define DISTANCE_FACTOR  0.125f   /* mm per count */
#define POLL_MS          500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Sleep for `ms` milliseconds.
 * Uses nanosleep for sub-second resolution; falls back to usleep for
 * older libc builds where nanosleep is not available.
 */
static void sleep_ms(unsigned int ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000U,
