#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define OPT3101_I2C_ADDR 0x44
#define I2C_BUS 1

// OPT3101 Register Addresses
#define REG_DISTANCE_0 0x00
#define REG_AMBIENT_0  0x02
#define REG_ERROR_FLAGS 0x04

// Global variables for graceful shutdown
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Function to read a 16-bit register from the OPT3101
int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        return -1; // Indicate error
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to read a 16-bit register from the OPT3101 with error checking
int read_register16_checked(int handle, uint8_t reg, uint16_t *value) {
    if (read_register16(handle, reg, value) != 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read distance from channel 0
int read_distance(int handle, uint16_t *distance) {
    return read_register16_checked(handle, REG_DISTANCE_0, distance);
}

// Function to read ambient light from channel 0
int read_ambient_light(int handle, uint16_t *ambient_light) {
    return read_register16_checked(handle, REG_AMBIENT_0, ambient_light);
}

// Function to read error flags
int read_error_flags(int handle, uint16_t *error_flags) {
    return read_register16_checked(handle, REG_ERROR_FLAGS, error_flags);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("OPT3101 Distance Sensor Reader\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        uint16_t distance = 0;
        uint16_t ambient_light = 0;
        uint16_t error_flags = 0;

        // Read sensor data
        if (read_distance(i2c_handle, &distance) == 0 &&
            read_ambient_light(i2c_handle, &ambient_light) == 0 &&
            read_error_flags(i2c_handle, &error_flags) == 0) {

            // Print data to console
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s - Distance: %u mm, Ambient Light: %u, Error Flags: 0x%04X\n",
                   timestamp, distance, ambient_light, error_flags);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500000 microseconds = 500 milliseconds
    }

    // Clean up resources
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return 0;
}

