#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define MAX_PULSE_US     38000    /* HC-SR04 max range ~3.3 m */
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm. Returns >= 0 on success, -1 on timeout,
 * -2 on invalid pulse width, -3 on pigpio error.
 */
static int measure_distance(void)
{
    uint32_t start_tick, end_tick;
    uint32_t deadline;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -3;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -3;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -3;
    }

    /* Wait for echo rising edge (timeout 200 ms) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 200 ms) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;

    /* HC-SR04: distance = (pulse_us * 0.0343) / 2  (cm) */
    float distance = (pulse_us * 0.0343f) / 2.0f;

    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse duration %u us (out of range)\n",
                pulse_us);
        return -2;
    }

    return (int)distance;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    printf("HC-SR04 distance sensor started. Trigger=GPIO%d, Echo=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Note: HC-SR04 operates at 5V, GPIO is 3.3V tolerant. "
           "Use a 1kOhm series resistor on the echo line.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", (double)distance);
        } else {
            fprintf(stderr, "Sensor read failed (code %d)\n", distance);
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    /* Cleanup */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

