#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define RANGE_RESOLUTION 0.0486f
#define NUM_RANGE_BINS 64
#define DATA_LENGTH (NUM_RANGE_BINS * 2)
#define MAGIC_WORD_LENGTH 8
#define LOG_FILE "intrusion_log.csv"

static const uint8_t MAGIC_WORD[MAGIC_WORD_LENGTH] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t terminate = 0;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag = CS8 | CLOCAL | CREAD;
    tty.c_iflag = IGNPAR;
    tty.c_oflag = 0;
    tty.c_lflag = 0;
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            perror("Error reading from UART");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "UART read returned 0 (sensor absent or disconnected)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int process_frame(const uint8_t *data, float *distance) {
    for (int i = 0; i < NUM_RANGE_BINS; i++) {
        uint16_t range = (uint16_t)data[i * 2] | ((uint16_t)data[i * 2 + 1] << 8);
        if (range > 0) {
            *distance = (float)range * RANGE_RESOLUTION;
            return 0;
        }
    }
    return -1;
}

static void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f\n", timestamp, distance);
    fflush(log_file);
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    printf("Intrusion detection started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint8_t header[MAGIC_WORD_LENGTH];
        if (read_exact(uart_fd, header, MAGIC_WORD_LENGTH) != 0) {
            if (!terminate) {
                fprintf(stderr, "Failed to read magic word, retrying...\n");
            }
            continue;
        }

        for (int i = 0; i < MAGIC_WORD_LENGTH; i++) {
            if (header[i] != MAGIC_WORD[i]) {
                fprintf(stderr, "Invalid magic word, resyncing...\n");
                tcflush(uart_fd, TCIFLUSH);
                continue;
            }
        }

        uint8_t data[DATA_LENGTH];
        if (read_exact(uart_fd, data, DATA_LENGTH) != 0) {
            if (!terminate) {
                fprintf(stderr, "Failed to read data frame, retrying...\n");
            }
            continue;
        }

        float distance;
        if (process_frame(data, &distance) == 0) {
            if (distance <= DISTANCE_THRESHOLD) {
                printf("Intrusion detected! Distance: %.3f m\n", distance);
                log_intrusion(distance);
                gpioWrite(GPIO_LED, 1);
                gpioDelay(2000000);
                gpioWrite(GPIO_LED, 0);
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

