#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define DIST_HIGH_REG  0x31
#define DIST_LOW_REG   0x32
#define ALERT_PIN      17
#define DIST_THRESHOLD 10.0f
#define SAMPLE_US      100000
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_distance(int handle, float *distance_cm)
{
    int high, low;

    high = i2cReadByteData(handle, DIST_HIGH_REG);
    if (high < 0) {
        fprintf(stderr, "I2C read error (high byte): %d\n", high);
        return -1;
    }

    low = i2cReadByteData(handle, DIST_LOW_REG);
    if (low < 0) {
        fprintf(stderr, "I2C read error (low byte): %d\n", low);
        return -1;
    }

    uint16_t raw = ((uint16_t)high << 8) | (uint16_t)low;
    *distance_cm = (float)raw / 10.0f;
