#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define CH201_ADDR     0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000    /* 10 ms */

/* CH201 register addresses (16-bit, big-endian on the bus) */
#define CH201_REG_DISTANCE_HIGH 0x00
#define CH201_REG_DISTANCE_LOW  0x01
#define CH201_REG_CONFIG        0x02

/* Config: enable continuous measurement mode (0x01) */
#define CH201_CONFIG_CONTINUOUS 0x01

/* Linear mapping: 50 mm -> 10 Hz, 500 mm -> 1 Hz */
#define MIN_DISTANCE_MM 50
#define MAX_DISTANCE_MM 500
#define MIN_BLINK_HZ    10
#define MAX_BLINK_HZ    1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a 16-bit-indexed register. */
static int ch201_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 2);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): rc=%d\n",
                reg, attempt + 1, MAX_RETRIES, rc);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read a 16-bit big-endian value from a 16-bit-indexed register. */
static int ch201_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d/%d)\n",
                    reg, attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2cReadDevice(handle, data, 2) != 2) {
            fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d/%d)\n",
                    reg, attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }
        *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
        return 0;
    }
    return -1;
}

static int ch201_init(int handle)
{
    if (ch201_write_reg(handle, CH201_REG_CONFIG, CH201_CONFIG_CONTINUOUS) != 0) {
        fprintf(stderr, "Failed to configure CH201 continuous mode\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */
    return 0;
}

static int ch201_read_distance(int handle, uint16_t *distance_mm)
{
    return ch201_read_reg16(handle, CH201_REG_DISTANCE_HIGH, distance_mm);
}

static int map_distance_to_blink_hz(uint16_t distance_mm)
{
    if (distance_mm <= MIN_DISTANCE_MM)
        return MAX_BLINK_HZ;
    if (distance_mm >= MAX_DISTANCE_MM)
        return MIN_BLINK_HZ;
    return MAX_BLINK_HZ -
           (int)(((float)(distance_mm - MIN_DISTANCE_MM) /
                  (float)(MAX_DISTANCE_MM - MIN_DISTANCE_MM)) *
                 (MAX_BLINK_HZ - MIN_BLINK_HZ));
}

static void log_data(uint16_t distance_mm, int blink_hz)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("%s - Distance: %u mm, Blink Frequency: %d Hz\n",
           timestamp, distance_mm, blink_hz);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, CH201_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ch201_init(g_i2c_handle) != 0) {
        fprintf(stderr, "CH201 sensor not detected or init failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    int led_state = 0;
    uint32_t last_tick = gpioTick();

    while (g_running) {
        uint16_t distance_mm = 0;
        if (ch201_read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Distance read failed; continuing\n");
        } else {
            int blink_hz = map_distance_to_blink_hz(distance_mm);
            log_data(distance_mm, blink_hz);

            uint32_t now = gpioTick();
            uint32_t period_us = 1000000 / blink_hz;
            uint32_t elapsed = now - last_tick;

            if (elapsed >= period_us) {
                led_state = !led_state;
                gpioWrite(LED_GPIO, led_state);
                last_tick = now;
            }
        }
        gpioDelay(SAMPLE_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

