#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 10000
#define LOG_FILE "proximity_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Sensor %d: %s\n", timestamp, sensor_id, event_type) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int prev1 = -1, prev2 = -1;
    int cur1, cur2;
    uint32_t last_debounce1 = 0, last_debounce2 = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity detection started. Press Ctrl+C to exit.\n");

    while (running) {
        cur1 = gpioRead(SENSOR_1_GPIO);
        cur2 = gpioRead(SENSOR_2_GPIO);

        if (cur1 < 0 || cur2 < 0) {
            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", cur1, cur2);
            break;
        }

        if (cur1 != prev1) {
            uint32_t now = gpioTick();
            if (now - last_debounce1 >= DEBOUNCE_MS * 1000) {
                prev1 = cur1;
                last_debounce1 = now;
                if (log_event(1, cur1 == 0 ? "DETECTED" : "CLEARED") != 0) {
                    fprintf(stderr, "Failed to log event for sensor 1\n");
                }
            }
        }

        if (cur2 != prev2) {
            uint32_t now = gpioTick();
            if (now - last_debounce2 >= DEBOUNCE_MS * 1000) {
                prev2 = cur2;
                last_debounce2 = now;
                if (log_event(2, cur2 == 0 ? "DETECTED" : "CLEARED") != 0) {
                    fprintf(stderr, "Failed to log event for sensor 2\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

