            fprintf(stderr, "gpioRead error (s1=%d, s2=%d)\n", cur1, cur2);
            break;
        }

        if (cur1 != prev1) {
            uint32_t now = gpioTick();
            if (now - last_debounce1 >= DEBOUNCE_MS * 1000) {
                prev1 = cur1;
                last_debounce1 = now;
                if (log_event(1, cur1 == 0 ? "DETECTED" : "CLEARED") != 0) {
                    fprintf(stderr, "Failed to log event for sensor 1\n");
                }
            }
        }

        if (cur2 != prev2) {
            uint32_t now = gpioTick();
            if (now - last_debounce2 >= DEBOUNCE_MS * 1000) {
                prev2 = cur2;
                last_debounce2 = now;
                if (log_event(2, cur2 == 0 ? "DETECTED" : "CLEARED") != 0) {
                    fprintf(stderr, "Failed to log event for sensor 2\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

