/*
 * Smart Parking System - TDK CH-101 ToF Sensor
 * Raspberry Pi 5, I2C bus 1, address 0x49
 * Uses Linux i2c-dev (no wiringPi dependency).
 *
 * Build:  gcc -O2 -Wall -o ch101_parking ch101_parking.c
 * Run:    ./ch101_parking
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS          "/dev/i2c-1"
#define CH101_ADDR       0x49

/* CH-101 register addresses */
#define REG_MEAS_TRIGGER 0x04
#define REG_MEAS_STATUS  0x06
#define REG_DIST_HIGH    0x08
#define REG_DIST_LOW     0x09

#define MEAS_TRIGGER_CMD 0x01
#define MEAS_STATUS_DATA_READY 0x01
#define MEAS_TIMEOUT_MS 50

#define LOG_FILE "distance_log.csv"
#define SAMPLE_PERIOD_MS 500

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on error.
 */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X): write returned %zd (errno %d: %s)\n",
                reg, value, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a register.
 * Returns 0 on success and stores the byte in *out, -1 on error.
 */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): write returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }

    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8(0x%02X): read returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Perform a combined write-then-read transaction: write `cmd` to `reg`,
 * then read `len` bytes from `reg` + 1.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_burst: write reg 0x%02X returned %zd (errno %d: %s)\n",
                reg, n, errno, strerror(errno));
        return -1;
    }

    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst: read %zu bytes returned %zd (errno %d: %s)\n",
                len, n, errno, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                   */
/* ------------------------------------------------------------------ */

/*
 * Trigger a single range measurement and wait for data-ready.
 * Returns 0 on success, -1 on error.
 */
static int ch101_trigger_and_wait(int fd)
{
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, MEAS_TRIGGER_CMD) != 0)
        return -1;

    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 5) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) != 0)
            return -1;
        if (status & MEAS_STATUS_DATA_READY)
            return 0;
        usleep(5000); /* 5 ms */
    }

    fprintf(stderr, "CH-101: measurement timeout after %d ms\n", MEAS_TIMEOUT_MS);
    return -1;
}

/*
 * Read the 16-bit distance (mm) from the sensor.
 * Returns 0 on success and stores distance in *distance_mm, -1 on error.
 */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t buf[2];
    if (i2c_read_burst(fd, REG_DIST_HIGH, buf, sizeof(buf)) != 0)
        return -1;

    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s,%u\n", ts, (unsigned)distance_mm) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    else
        fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                CH101_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_mm\n");
        fflush(g_log_fp);
    }

    printf("CH-101 smart parking system started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm = 0;

        if (ch101_trigger_and_wait(g_i2c_fd) != 0) {
            fprintf(stderr, "Skipping sample due to trigger/status error.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (ch101_read_distance(g_i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Skipping sample due to distance read error.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        log_data(g_log_fp, distance_mm);
        printf("Distance: %u mm\n", (unsigned)distance_mm);

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

