#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x00
#define DATA_REG 0x01
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define LOOP_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_distance(int handle, uint16_t *distance) {
    char cmd = MEASURE_CMD;
    char buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(1000);

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        *distance = ((uint16_t)(buf[0] & 0x0F) << 8) | (uint8_t)buf[1];
        return 0;
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1;
}

static void log_distance(uint16_t distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ms = ts.tv_nsec / 1000000;
    printf("[%ld.%03ld] Distance: %u mm\n", ts.tv_sec, ms, distance);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d.\n", MLX75030_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX75030 ToF sensor reader started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) == 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Sensor read error. Continuing...\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

