#define REG_SOFT_RESET       0x7FFF
#define REG_SYSTEM_START     0x0009
#define REG_GPIO_HV_MUX      0x0030
#define REG_GPIO_TIO_HV      0x0031
#define REG_SYSTEM_THRESH    0x004E
#define REG_SYSTEM_INTERRUPT 0x0046
#define REG_RESULT_DISTANCE  0x0096
#define REG_RESULT_STATUS    0x0089

#define I2C_BUS 1
#define POLL_INTERVAL_US 500000  /* 500 ms */
#define RESET_DELAY_US   10000   /* 10 ms  */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address                        */
/* ------------------------------------------------------------------ */
static int vl53l4cx_write_reg(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error: i2cWriteDevice to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit register address                       */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg(int handle, uint16_t reg, uint8_t *value)
{
    char addr_buf[2];
    char data_buf[1];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cWriteDevice (addr) to reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error: i2cReadDevice from reg 0x%04X failed\n", reg);
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from a 16-bit register address       */
/* ------------------------------------------------------------------ */
static int vl53l4cx_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char addr_buf[2];
    char data_buf[2];

    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cWriteDevice (addr) to reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error: i2cReadDevice from reg 0x%04X failed\n", reg);
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L4CX sensor                                     */
/* ------------------------------------------------------------------ */
static int vl53l4cx_init(int handle)
{
    /* Soft reset: write 0x00 to register 0x7FFF */
    if (vl53l4cx_write_reg(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: VL53L4CX soft reset failed\n");
        return -1;
    }
    gpioDelay(RESET_DELAY_US);

    /* Start ranging: write 0x01 to register 0x0009 */
    if (vl53l4cx_write_reg(handle, REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error: VL53L4CX start ranging failed\n");
        return -1;
