/* ------------------------------------------------------------------ */
static int vl53l4cx_read_distance(int handle, uint16_t *distance)
{
    uint8_t int_status = 0;
    uint16_t dist_hi = 0, dist_lo = 0;

    /* Poll interrupt status register 0x0046 bit 0 */
    if (vl53l4cx_read_reg(handle, REG_SYSTEM_INTERRUPT, &int_status) != 0) {
        return -1;
    }
    if ((int_status & 0x01) == 0) {
        /* No new data yet — not an error, just skip this cycle */
        return 1;
    }

    /* Read 16-bit distance result from registers 0x0096 (high) and 0x0097 (low) */
    if (vl53l4cx_read_reg16(handle, REG_RESULT_DISTANCE, &dist_hi) != 0) {
