        fprintf(stderr, "Error: Failed to stop sensor.\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle, uint16_t *distance) {
    if (write_reg16(handle, REG_SYSTEM__MODE_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000);
    if (read_reg16_16bit(handle, REG_RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, distance) < 0) {
        fprintf(stderr, "Error: Failed to read distance.\n");
        return -1;
    }
    if (write_reg16(handle, REG_SYSTEM__MODE_START, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to stop ranging.\n");
        return -1;
    }
    return 0;
}

static void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int buzzer_active = 0;
    uint16_t distance;

    while (running) {
        if (read_distance(i2c_handle, &distance) == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD && !buzzer_active) {
                control_buzzer(1);
                buzzer_active = 1;
                printf("Buzzer ON\n");
            } else if (distance >= DISTANCE_THRESHOLD && buzzer_active) {
                control_buzzer(0);
                buzzer_active = 0;
                printf("Buzzer OFF\n");
            }
        } else {
            fprintf(stderr, "Error: I2C communication failure. Re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus.\n");
                break;
            }
            if (init_sensor(i2c_handle) != 0) {
                fprintf(stderr, "Error: Sensor re-initialization failed.\n");
                break;
            }
            buzzer_active = 0;
            control_buzzer(0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

