#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mqueue.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define TIMING_BUDGET_MS 50
#define POLL_INTERVAL_US 50000
#define MQ_NAME "/sensor_queue"

/* VL53L1X register addresses */
#define REG_SOFT_RESET 0x0000
#define REG_MODEL_ID 0x010F
#define REG_SYSTEM_START 0x0080
#define REG_RESULT_INT_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

#define EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static mqd_t mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read failed at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n", model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID: 0x%02X)\n", model_id);

    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) != 0) return -1;
