#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0   /* cm/s at ~20 C */
#define MIN_DISTANCE   2.0       /* cm */
#define MAX_DISTANCE   400.0     /* cm */
#define THRESHOLD_CM   30.0      /* cm */
#define TRIGGER_PULSE_US 10      /* HC-SR04 needs >=10 us HIGH */
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define LOOP_DELAY_US    100000  /* 100 ms between readings */

static volatile sig_atomic_t running = 1;

/* Shared state between alert callback and main thread */
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_seen  = 0;
static volatile int      reading_active = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/*
 * pigpio alert callback for the echo pin.
 * Triggered on every edge of the echo pulse.
 */
static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        start_tick = tick;
        echo_seen  = 0;
        reading_active = 1;
    } else if (level == 0 && reading_active) {
        /* Falling edge: end of echo pulse */
        end_tick = tick;
        echo_seen = 1;
        reading_active = 0;
    }
}

/*
 * Compute distance in cm from the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout/no echo, -2.0 on out-of-range.
 */
static double get_distance(void)
{
    start_tick = 0;
    end_tick   = 0;
    echo_seen  = 0;
    reading_active = 0;

    /* Send 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger HIGH\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger LOW\n");
        return -1.0;
    }

    /* Wait for echo with timeout */
    uint32_t waited = 0;
    while (!echo_seen && running) {
        gpioDelay(100);
        waited += 100;
        if (waited >= ECHO_TIMEOUT_US) {
            return -1.0; /* sensor absent or not responding */
        }
    }
    if (!running) {
        return -1.0;
    }

    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t pulse_us = end_tick - start_tick;

    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    double distance = (double)pulse_us * SPEED_OF_SOUND / 2000000.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -2.0; /* out of valid range */
    }
    return distance;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO modes */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register alert callback for echo pin */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on echo pin %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure buzzer is off */
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize buzzer pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("Trigger: GPIO %d | Echo: GPIO %d | Buzzer: GPIO %d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);

    int buzzer_on = 0;

    while (running) {
        double distance = get_distance();

        if (distance < 0.0) {
            if (distance == -1.0) {
                fprintf(stderr, "Warning: echo timeout - sensor absent or not responding\n");
            } else {
                fprintf(stderr, "Warning: invalid distance reading (%.2f cm) - out of range\n", distance);
            }
            /* Turn buzzer off on invalid reading */
            if (buzzer_on) {
                gpioWrite(BUZZER_PIN, 0);
                buzzer_on = 0;
            }
        } else {
            printf("Distance: %.2f cm\n", distance);

            if (distance < THRESHOLD_CM && !buzzer_on) {
                if (gpioWrite(BUZZER_PIN, 1) == 0) {
                    buzzer_on = 1;
                    printf("Buzzer ON (distance < %.1f cm)\n", THRESHOLD_CM);
                } else {
                    fprintf(stderr, "Error: failed to turn buzzer ON\n");
                }
            } else if (distance >= THRESHOLD_CM && buzzer_on) {
                if (gpioWrite(BUZZER_PIN, 0) == 0) {
                    buzzer_on = 0;
                    printf("Buzzer OFF (distance >= %.1f cm)\n", THRESHOLD_CM);
                } else {
                    fprintf(stderr, "Error: failed to turn buzzer OFF\n");
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Parking sensor stopped.\n");

    return EXIT_SUCCESS;
}

