#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEED_OF_SOUND 0.0343  /* cm/us at ~20 C */
#define TRIGGER_PULSE_US 10
#define MEASURE_INTERVAL_US 200000  /* 200 ms -> 5 Hz */
#define ECHO_TIMEOUT_US 60000       /* 60 ms max echo wait */
#define MIN_PULSE_US 100
#define MAX_PULSE_US 30000
#define LOG_FILE "distance_log.txt"

/* Shared state between callback and main thread */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile int      g_echo_seen = 0;
static volatile int      g_running   = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (runs in pigpio thread)                          */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    if (level == 1) {
        g_rise_tick = tick;
        g_echo_seen = 0;
    } else if (level == 0) {
        g_fall_tick = tick;
        g_echo_seen = 1;
    }
    /* level == 2 (timeout) is ignored here; pigpio handles it internally */
}

/* ------------------------------------------------------------------ */
/* Trigger a 10 us pulse on the TRIG pin                               */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute distance from pulse width (microseconds)                    */
/* ------------------------------------------------------------------ */
static float calculate_distance(uint32_t pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND / 2.0f;
}

/* ------------------------------------------------------------------ */
/* Log a reading with an ISO 8601 timestamp                             */
/* ------------------------------------------------------------------ */
static void log_distance(FILE *fp, float distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(fp);
    printf("%s, Distance: %.2f cm\n", timestamp, distance);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n",
                TRIGGER_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n",
                ECHO_PIN);
        goto cleanup_gpio;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN %d.\n",
                ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: failed to register alert on ECHO_PIN %d.\n",
                ECHO_PIN);
        goto cleanup_gpio;
    }

    /* ---- Open log file ---- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto cleanup_gpio;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIGGER: GPIO %d | ECHO: GPIO %d | Log: %s\n",
           TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset shared state */
        g_rise_tick = 0;
        g_fall_tick = 0;
        g_echo_seen = 0;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (waited < ECHO_TIMEOUT_US && g_running) {
            gpioDelay(1000);  /* 1 ms */
            waited += 1000;
            if (g_echo_seen)
                break;
        }

        if (!g_running)
            break;

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout - no object detected.\n");
            log_distance(fp, -1.0f);
            gpioDelay(MEASURE_INTERVAL_US);
            continue;
        }

        /* pigpio ticks are 32-bit microseconds; handle wraparound */
        uint32_t pulse_us = g_fall_tick - g_rise_tick;

        if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
            fprintf(stderr,
                    "Warning: implausible pulse width %u us - noise/out of range.\n",
                    pulse_us);
            log_distance(fp, -1.0f);
        } else {
            float distance = calculate_distance(pulse_us);
            log_distance(fp, distance);
        }

        gpioDelay(MEASURE_INTERVAL_US);
    }

    rc = EXIT_SUCCESS;

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (fp) {
        fclose(fp);
    }
    gpioSetAlertFunc(ECHO_PIN, NULL);  /* unregister callback */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return rc;

cleanup_gpio:
    gpioTerminate();
    return rc;
}

