#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18

#define DISTANCE_THRESHOLD_OPEN 50
#define DISTANCE_THRESHOLD_CLOSE 60

#define LOG_FILE "parking_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0046
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_THRESHOLD_HIGH 0x0091
#define VL53L1X_REG_SYSTEM_THRESHOLD_LOW 0x0090
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x000A
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x006B
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0046
#define VL53L1X_REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0084
#define VL53L1X_REG_GPIO_TIO_HV_STATUS 0x0085
#define VL53L1X_REG_GPIO_TIO_HV_STATUS 0x0085
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0046
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

#define VL53L1X_MODEL_ID 0xEA

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_write_reg16(int handle, uint16_t reg, uint8_t value) {
    return i2c_write_reg16(handle, reg, value);
}

static int vl53l1x_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    return i2c_read_reg16(handle, reg, buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID: 0x%02X (expected 0x%02X).\n", model_id, VL53L1X_MODEL_ID);
        return -1;
    }

    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x04) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESHOLD_HIGH, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESHOLD_LOW, 0x00) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0xFF) < 0) return -1;
    if (vl53l1x_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0) return -1;

    return 0;
}

static int vl53l1x_read_distance(int handle) {
    uint8_t status = 0;
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) return -1;
    if ((status & 0x01) == 0) return -2;

    uint8_t buf[2] = {0};
    if (vl53l1x_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) < 0) return -1;
    return (buf[0] << 8) | buf[1];
}

static void log_event(const char *event, int distance) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s, Distance: %d cm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event, distance);
    fflush(log_file);
}

static void control_gate(int distance) {
    static int gate_open = 0;
    if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
        gpioServo(SERVO_PIN, 1500);
        gpioDelay(500000);
        gate_open = 1;
        log_event("Gate Opened", distance);
    } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
        gpioServo(SERVO_PIN, 1000);
        gpioDelay(500000);
        gate_open = 0;
        log_event("Gate Closed", distance);
    }
}

static void cleanup() {
    if (i2c_handle >= 0) {
        vl53l1x_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioServo(SERVO_PIN, 0);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(SHUTDOWN_PIN, 0);
    gpioDelay(10000);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X.\n", VL53L1X_ADDR);
        cleanup();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            if (distance == -2) {
                gpioDelay(100000);
            } else {
                fprintf(stderr, "Error: I2C read failed.\n");
                gpioDelay(100000);
            }
            continue;
        }
        control_gate(distance);
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

