#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19
#define DISTANCE_THRESHOLD_MM 200
#define POLL_INTERVAL_US 500000

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_RANGE_CONFIG_TIMING_BUDGET 0x001E
#define VL53L1X_REG_RANGE_CONFIG_INTERMEASUREMENT 0x001B

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s: %s\n", ts, event);
    fflush(log_file);
}

static int i2c_write_reg16(uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteI2CBlockData(i2c_handle, (char)(reg >> 8), buf, 3);
}

static int i2c_read_reg16(uint16_t reg, uint8_t *buf, uint32_t len) {
    return i2cReadI2CBlockData(i2c_handle, (char)(reg >> 8), (char *)buf, len);
}

