#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18

#define REG_SOFT_RESET 0x0000
#define REG_SYSTEM_START 0x0000
#define REG_GPIO_HV_MUX_CTRL 0x0030
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0089
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_DISTANCE 0x0096

#define DIST_THRESHOLD_FORWARD 100
#define DIST_THRESHOLD_BACKWARD 300

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    int retries = 3;
    int delay_ms = 10;
    while (retries > 0) {
        int rc = i2cWriteDevice(handle, buf, 3);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write to 0x%04X failed (rc=%d), retrying in %d ms\n", reg, rc, delay_ms);
        gpioDelay(delay_ms * 1000);
        delay_ms *= 2;
        retries--;
    }
    return -1;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    int retries = 3;
    int delay_ms = 10;
    while (retries > 0) {
        if (i2cWriteDevice(handle, reg_buf, 2) != 0) {
            fprintf(stderr, "I2C write reg 0x%04X failed, retrying in %d ms\n", reg, delay_ms);
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            retries--;
            continue;
        }
        if (i2cReadDevice(handle, (char *)buf, len) == (int)len) return 0;
        fprintf(stderr, "I2C read from 0x%04X failed, retrying in %d ms\n", reg, delay_ms);
        gpioDelay(delay_ms * 1000);
        delay_ms *= 2;
        retries--;
    }
    return -1;
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(1000);
    if (i2c_write_reg16(handle, REG_SOFT_RESET, 0x01) != 0) {
        fprintf(stderr, "VL53L1X start measurement failed\n");
        return -1;
    }
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 100;
    while (timeout > 0) {
        if (i2c_read_reg16(handle, REG_RESULT_INTERRUPT_STATUS, &status, 1) != 0) {
            fprintf(stderr, "Failed to read interrupt status\n");
            return -1;
        }
        if (status & 0x01) break;
        gpioDelay(1000);
        timeout--;
    }
    if (timeout == 0) {
        fprintf(stderr, "VL53L1X measurement timeout\n");
        return -1;
    }
    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, buf, 2) != 0) {
        fprintf(stderr, "Failed to read distance registers\n");
        return -1;
    }
    *distance = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void motor_forward(void) {
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    gpioWrite(GPIO_MOTOR_FORWARD, 1);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void) {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    printf("Motor: BACKWARD\n");
}

static void motor_stop(void) {
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    printf("Motor: STOP\n");
}

static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    if (i2c_handle < 0) return;
    uint16_t distance;
    if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        if (distance < DIST_THRESHOLD_FORWARD) {
            motor_forward();
        } else if (distance > DIST_THRESHOLD_BACKWARD) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Failed to read distance, stopping motor\n");
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO_TRIGGER, PI_INPUT);
    gpioSetMode(GPIO_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    if (gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, trigger_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO %d\n", GPIO_TRIGGER);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("System ready. Trigger sensor on GPIO24 (rising edge). Ctrl+C to exit.\n");
    while (running) {
        gpioDelay(100000);
    }
    gpioSetISRFuncEx(GPIO_TRIGGER, RISING_EDGE, 0, NULL, NULL);
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

