#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define NUM_ELECTRODES 12
#define NUM_LEDS 4
#define POLL_INTERVAL_US 50000

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[NUM_LEDS] = {NULL};
static FILE *log_file = NULL;

static const int led_pins[NUM_LEDS] = {17, 18, 27, 22};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    if (i2c_read_reg8(fd, MPR121_SOFTRESET, NULL) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_E0TTH, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0RTH, 0x01) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_USL, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_LSL, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_TL, 0xB4) < 0) return -1;

    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t low, high;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &low) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &high) < 0) return -1;
    *status = ((uint16_t)high << 8) | low;
    return 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void set_led_pattern(int pattern) {
    for (int i = 0; i < NUM_LEDS; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], (pattern >> i) & 1);
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < NUM_LEDS; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("proximity_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        log_event("Failed to open I2C bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        log_event("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        log_event("MPR121 initialization failed");
        cleanup();
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        log_event("Failed to open gpiochip0");
        cleanup();
        return 1;
    }

    for (int i = 0; i < NUM_LEDS; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            log_event("Failed to get GPIO line");
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity_art", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", led_pins[i], strerror(errno));
            log_event("Failed to request GPIO line as output");
            cleanup();
            return 1;
        }
    }

    log_event("Proximity art installation started");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_fd, &touch_status) < 0) {
            log_event("Error reading touch status");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1 << i)) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode >= 0) {
            int pattern = 1 << active_electrode;
            set_led_pattern(pattern);
            char log_msg[64];
            snprintf(log_msg, sizeof(log_msg), "Electrode %d touched, LED pattern 0x%X", active_electrode, pattern);
            log_event(log_msg);
        } else {
            set_led_pattern(0);
            log_event("No electrode touched");
        }

        usleep(POLL_INTERVAL_US);
    }

    log_event("Proximity art installation stopped");
    cleanup();
    return 0;
}

