#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define I2C_BUS 1

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_AUTOCONFIG0 0x7B
#define MPR121_AUTOCONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_NHD_DATA 0x33
#define MPR121_NCL_DATA 0x34
#define MPR121_FDL_DATA 0x35
#define MPR121_E0TTH_FALL 0x36
#define MPR121_E0RTH_FALL 0x37
#define MPR121_DEBOUNCE_FALL 0x38
#define MPR121_AFE_CONFIG1 0x5B
#define MPR121_AFE_CONFIG2 0x5C
#define MPR121_ELECTRODE_CURRENT 0x5D
#define MPR121_FILTER_CONFIG 0x2B
#define MPR121_BASELINE_FILTERING 0x2C
#define MPR121_AUTOCONFIG_USL 0x7D
#define MPR121_AUTOCONFIG_LSL 0x7E
#define MPR121_AUTOCONFIG_TL 0x7F
#define MPR121_USL_MAX 0xC8
#define MPR121_LSL_MAX 0x82
#define MPR121_TL_MAX 0xB4
#define MPR121_DEVICE_ID 0x5C

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_read(uint8_t reg) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

int mpr121_init() {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_AUTOCONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTOCONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_USL, MPR121_USL_MAX) < 0) return -1;
    if (mpr121_write(MPR121_LSL, MPR121_LSL_MAX) < 0) return -1;
    if (mpr121_write(MPR121_TL, MPR121_TL_MAX) < 0) return -1;
    if (mpr121_write(MPR121_E0TTH, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E0RTH, 0x05) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE_FALL, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AFE_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_AFE_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE_CURRENT, 0x0C) < 0) return -1;
    if (mpr121_write(MPR121_FILTER_CONFIG, 0x04) < 0) return -1;
    if (mpr121_write(MPR121_BASELINE_FILTERING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AUTOCONFIG_USL, MPR121_USL_MAX) < 0) return -1;
    if (mpr121_write(MPR121_AUTOCONFIG_LSL, MPR121_LSL_MAX) < 0) return -1;
    if (mpr121_write(MPR121_AUTOCONFIG_TL, MPR121_TL_MAX) < 0) return -1;
    if (mpr121_write(MPR121_ELECTRODE_CONFIG, 0x01) < 0) return -1;

    return 0;
}

int read_touch_status() {
    int low = mpr121_read(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
