#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN  17
#define ECHO_PIN     18
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define LOG_FILE     "distance_log.txt"
#define TIMEOUT_US   30000
#define SETTLE_US    10000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_error(FILE *log_file, const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s ERROR: %s\n", ts, msg);
    fflush(log_file);
}

static int measure_distance(struct gpiod_line *trig, struct gpiod_line *echo,
                            FILE *log_file)
{
    struct timespec t0, t1;
    long elapsed_us;
    int ret;

    /* Ensure trigger starts low */
    ret = gpiod_line_set_value(trig, 0);
    if (ret < 0) {
        log_error(log_file, "Failed to set trigger low");
        return -1;
    }
    usleep(SETTLE_US);

    /* 10 us trigger pulse */
    ret = gpiod_line_set_value(trig, 1);
    if (ret < 0) {
        log_error(log_file, "Failed to set trigger high");
        return -1;
    }
    usleep(10);
    ret = gpiod_line_set_value(trig, 0);
    if (ret < 0) {
        log_error(log_file, "Failed to set trigger low after pulse");
        return -1;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (1) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            log_error(log_file, "Failed to read echo pin");
            return -1;
        }
        if (ret == 1)
            break;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                     (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            log_error(log_file, "Timeout waiting for echo rising edge");
            return -1;
        }
    }

    /* Measure echo pulse width (timeout 30 ms) */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (1) {
        ret = gpiod_line_get_value(echo);
        if (ret < 0) {
            log_error(log_file, "Failed to read echo pin");
            return -1;
        }
        if (ret == 0)
            break;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                     (t1.tv_nsec - t0.tv_nsec) / 1000L;
        if (elapsed_us > TIMEOUT_US) {
            log_error(log_file, "Timeout waiting for echo falling edge");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);

    long pulse_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                    (t1.tv_nsec - t0.tv_nsec) / 1000L;

    /* distance = (pulse_us * 0.0343) / 2 cm */
    double distance = (pulse_us * 0.0343) / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_error(log_file, "Distance out of range");
        return -1;
    }

    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(log_file, "%s Distance: %.2f cm\n", ts, distance);
    fflush(log_file);
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (program_running) {
        if (measure_distance(trig, echo, log_file) < 0) {
            /* Error already logged in helper */
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    if (log_file)
        fclose(log_file);
    return ret;
}

