#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define LOG_FILE    "distance_log.txt"

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_PULSE_US 58
#define MAX_PULSE_US 25000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_seen  = 0;
static volatile int      running    = 1;
static FILE             *log_file   = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        start_tick = tick;
        echo_seen  = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_seen = 1;
    }
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

static float calculate_distance(uint32_t pulse_us) {
    return (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 1000000.0f;
}

static void log_distance(float distance) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file);
}

