#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define TRIGGER_PIN    27

/* VL53L1X register addresses */
#define REG_SYSTEM_MODE_START_RANGE      0x0010
#define REG_SYSTEM_INTERRUPT_CLEAR       0x0015
#define REG_RESULT_INTERRUPT_STATUS      0x0016
#define REG_RESULT_RANGE_STATUS          0x0014
#define REG_SYSTEM_MODE_GPIO1_CTRL       0x0018
#define REG_SYSTEM_MODE_GPIO2_CTRL       0x0019
#define REG_SYSTEM_MODE_START_STOP       0x0020

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    if (i2cReadDevice(handle, (char *)value, 1) != 1)
        return -1;
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *value = (uint16_t)((data[1] << 8) | data[0]);
    return 0;
}

static int init_vl53l1x(int handle)
{
    /* Set continuous mode, no timeout */
    if (i2c_write_reg8(handle, REG_SYSTEM_MODE_GPIO1_CTRL, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write GPIO1_CTRL");
        return -1;
    }
    if (i2c_write_reg8(handle, REG_SYSTEM_MODE_GPIO2_CTRL, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write GPIO2_CTRL");
        return -1;
    }
    /* Start ranging */
    if (i2c_write_reg8(handle, REG_SYSTEM_MODE_START_STOP, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to start ranging");
        return -1;
    }
    return 0;
}

static void log_data(uint16_t distance, uint8_t status)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (status == 0) {
        syslog(LOG_INFO, "%s - Distance: %u mm, Status: 0x%02X",
               timestamp, distance, status);
    } else {
        syslog(LOG_ERR, "%s - Distance: %u mm, Status: 0x%02X",
               timestamp, distance, status);
    }
}

int main(void)
{
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at 0x%02X on bus %d",
               VL53L1X_ADDR, I2C_BUS);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", TRIGGER_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(TRIGGER_PIN, 1);

    if (init_vl53l1x(g_i2c_handle) < 0) {
        syslog(LOG_ERR, "VL53L1X initialisation failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X sensor started on I2C bus %d, address 0x%02X",
           I2C_BUS, VL53L1X_ADDR);

    while (g_running) {
        uint16_t distance = 0;
        uint8_t status = 0;

        if (i2c_read_reg16(g_i2c_handle, REG_RESULT_RANGE_STATUS, &distance) < 0) {
            syslog(LOG_ERR, "Failed to read distance register");
        } else if (i2c_read_reg8(g_i2c_handle, REG_RESULT_INTERRUPT_STATUS, &status) < 0) {
            syslog(LOG_ERR, "Failed to read status register");
        } else {
            log_data(distance, status);
        }

        gpioDelay(100000); /* 100 ms */
    }

    syslog(LOG_INFO, "Shutting down...");
    i2cClose(g_i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

