#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GATE_GPIO      24
#define DIST_THRESHOLD 20.0f   /* cm */
#define POLL_DELAY_US  100000  /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_MODEL_ID                0x010F
#define REG_RANGING_MODE            0x0021
#define REG_SYSTEM_START            0x0015
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE         0x0096

#define EXPECTED_MODEL_ID           0xEA
#define RANGING_MODE_SHORT          0x00
#define SYSTEM_START_RANGING        0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers (16-bit register addressing)                            */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* Sensor init                                                         */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    uint8_t id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &id, 1) != 1) {
        fprintf(stderr, "Error: failed to read model ID\n");
        return -1;
    }
    if (id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X)\n",
                id, EXPECTED_MODEL_ID);
        return -1;
    }

    if (i2c_write_reg16(handle, REG_RANGING_MODE, RANGING_MODE_SHORT) != 0) {
        fprintf(stderr, "Error: failed to set ranging mode\n");
        return -1;
    }

    if (i2c_write_reg16(handle, REG_SYSTEM_START, SYSTEM_START_RANGING) != 0) {
        fprintf(stderr, "Error: failed to start ranging\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance (mm)                                                  */
/* ------------------------------------------------------------------ */
static int read_distance_mm(int handle, int *distance_mm)
{
    uint8_t status = 0;
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_STATUS, &status, 1) != 1)
        return -1;

    if ((status & 0x01) == 0) {
        /* Data not ready yet */
        return 1;
    }

    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_DISTANCE, buf, 2) != 2)
        return -1;

    *distance_mm = (buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gate control                                                        */
/* ------------------------------------------------------------------ */
static void control_gate(int distance_mm)
{
    int dist_cm = distance_mm / 10;
    int new_state = (dist_cm < DIST_THRESHOLD) ? 1 : 0;

    if (gpioWrite(GATE_GPIO, new_state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO %d\n", GATE_GPIO);
        return;
    }

    if (g_log_file) {
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm, Gate: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                distance_mm, new_state ? "OPEN" : "CLOSED");
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: sensor initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on GPIO %d\n", GATE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);  /* gate starts closed */

    g_log_file = fopen("gate_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open gate_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "--- Gate control system started ---\n");
    fflush(g_log_file);

    while (g_running) {
        int dist_mm = 0;
        int rc = read_distance_mm(g_i2c_handle, &dist_mm);

        if (rc == 0) {
            control_gate(dist_mm);
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failed\n");
            if (g_log_file) {
                time_t t = time(NULL);
                struct tm tm;
                localtime_r(&t, &tm);
                fprintf(g_log_file, "%04d-%02d-%02d %02d:%02d:%02d, Error: I2C read failed\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec);
                fflush(g_log_file);
            }
        }
        /* rc == 1: data not ready, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    fprintf(g_log_file, "--- Gate control system stopped ---\n");
    fflush(g_log_file);
    cleanup();
    return EXIT_SUCCESS;
}

