#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define MIN_PULSEWIDTH 500
#define MAX_PULSEWIDTH 2500
#define TRIGGER_US    10
#define ECHO_TIMEOUT_US 30000
#define SAMPLE_COUNT  5
#define LOG_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulse_start = 0;
static volatile uint32_t pulse_end = 0;
static volatile int pulse_ready = 0;
static FILE *log_file = NULL;

static double distance_history[SAMPLE_COUNT];
static int history_index = 0;
static int history_filled = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pulse_start = tick;
    } else if (level == 0) {
        pulse_end = tick;
        pulse_ready = 1;
    }
}

static double calculate_distance(uint32_t pulse_width_us) {
    return (pulse_width_us * SPEED_OF_SOUND) / 2000000.0;
}

static double moving_average(double new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % SAMPLE_COUNT;
    if (history_index == 0) history_filled = 1;

    double sum = 0.0;
    int count = history_filled ? SAMPLE_COUNT : history_index;
    for (int i = 0; i < count; i++) sum += distance_history[i];
    return sum / count;
}

static double map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return (double)MIN_ANGLE +
           (double)MAX_ANGLE *
           (log10(distance / MIN_DISTANCE) / log10(MAX_DISTANCE / MIN_DISTANCE));
}

static int set_servo_angle(double angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulsewidth = (int)((angle / 180.0) * (MAX_PULSEWIDTH - MIN_PULSEWIDTH) + MIN_PULSEWIDTH);
    int rc = gpioServo(SERVO_PIN, pulsewidth);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

static void log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, (int)angle);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set echo pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to register echo callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        pulse_ready = 0;
        pulse_start = 0;
        pulse_end = 0;

        if (gpioWrite(TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high\n");
            break;
        }
        gpioDelay(TRIGGER_US);
        if (gpioWrite(TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low\n");
            break;
        }

        uint32_t start_wait = gpioTick();
        while (!pulse_ready && running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            gpioDelay(100);
        }

        if (!pulse_ready) {
            log_data(-1.0, -1.0);
            set_servo_angle(90.0);
            gpioDelay(LOG_INTERVAL_US);
            continue;
        }

        uint32_t pulse_width = pulse_end - pulse_start;
        double distance = calculate_distance(pulse_width);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            log_data(-1.0, -1.0);
            set_servo_angle(90.0);
        } else {
            double avg_distance = moving_average(distance);
            double angle = map_distance_to_angle(avg_distance);
            set_servo_angle(angle);
            log_data(avg_distance, angle);
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

