#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <stdbool.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define THRESHOLD_MM 200
#define POLL_DELAY_US 50000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET              0x0003
#define REG_SYSTEM_MODE_START       0x0008
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define REG_RESULT_INTERRUPT_STATUS 0x0089
#define REG_RESULT_RANGE_STATUS     0x0089
#define REG_RESULT_DISTANCE         0x0096
#define REG_SYSTEM_THRESH_HIGH      0x009E
#define REG_SYSTEM_THRESH_LOW       0x009F
#define REG_SYSTEM_CONFIG           0x00A0
#define REG_CROSSTALK_COMPENSATION  0x00A4
#define REG_RANGE_CONFIG_A          0x00A6
#define REG_RANGE_CONFIG_B          0x00A7
#define REG_INTERMEASUREMENT_MS     0x00A8
#define REG_SYSTEM_INTERMEASUREMENT 0x00A9

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address followed by a 16-bit value (big-endian). */
static int write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Write a 16-bit register address followed by an 8-bit value. */
static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit value from a 16-bit register address. */
static int read_reg16(int handle, uint16_t reg, uint16_t *out) {
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) < 0) return -1;
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
