#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEAKER_PIN 18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  200.0
#define SENSITIVITY   50.0

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  200000
#define LOOP_DELAY_US    10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set SPEAKER_PIN %d as output.\n", SPEAKER_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on ECHO_PIN.\n");
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize TRIGGER_PIN low.\n");
        return -1;
    }
    if (gpioPWM(SPEAKER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM on SPEAKER_PIN.\n");
        return -1;
    }

    return 0;
}

static double measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high.\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low.\n");
        return -1.0;
    }

    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout.\n");
            return -1.0;
        }
    }

    start_tick = gpioTick();

