        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1.0;
    }

    start_tick = gpioTick();
    timeout_tick = start_tick;

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) > 0) {
            fprintf(stderr, "Error: echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * 0.0343f / 2.0f;
    return distance;
}

static int calculate_frequency(float distance) {
    if (distance < 0.0f) return -1;
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;
    int freq = MIN_FREQUENCY_HZ +
               (int)((MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) *
                     (MAX_DISTANCE_CM - distance) /
                     (MAX_DISTANCE_CM - MIN_DISTANCE_CM));
    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return freq;
}

static void set_buzzer_frequency(int frequency) {
    if (frequency < 0) return;
    if (gpioHardwarePWM(BUZZER_PIN, frequency, 500000) < 0) {
