            fprintf(stderr, "Warning: invalid frequency, using last valid frequency\n");
            frequency = last_valid_frequency;
        } else {
            last_valid_frequency = frequency;
        }

        set_buzzer_frequency(frequency);

        printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    gpioHardwarePWM(BUZZER_PIN, 0, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

