#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8
#define LOG_FILE "distance_log.csv"
#define MIN_DISTANCE_MM 200
#define MAX_DISTANCE_MM 5000
#define SAMPLE_DELAY_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x3F), (char)value };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write error: reg=0x%02X, val=0x%02X\n", reg, value);
        return -1;
    }
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = {0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read error: reg=0x%02X\n", reg);
        return -1;
    }
    *value = (uint8_t)rx[1];
    return 0;
}

static int init_sensor(void) {
    if (spi_write_reg(0x01, 0x01) != 0) return -1;
    if (spi_write_reg(0x02, 0x00) != 0) return -1;
    if (spi_write_reg(0x00, 0x01) != 0) return -1;
    return 0;
}

static int read_distance_mm(int *distance_mm) {
    uint8_t lo, hi;
    if (spi_read_reg(0x0C, &lo) != 0) return -1;
    if (spi_read_reg(0x0D, &hi) != 0) return -1;
    *distance_mm = (hi << 8) | lo;
    return 0;
}

static void log_distance(int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d\n", timestamp, distance_mm);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance measurements...\n");

    while (running) {
        int distance;
        if (read_distance_mm(&distance) == 0) {
            if (distance >= MIN_DISTANCE_MM && distance <= MAX_DISTANCE_MM) {
                log_distance(distance);
                printf("Distance: %d mm\n", distance);
            } else {
                fprintf(stderr, "Out-of-range reading: %d mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

