#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_als_visible(int fd, uint16_t *out) {
    uint8_t low = 0, high = 0;
    if (i2c_read_reg(fd, SI1175_REG_ALS_VIS_DATA0, &low) < 0) return -1;
    if (i2c_read_reg(fd, SI1175_REG_ALS_VIS_DATA1, &high) < 0) return -1;
    *out = ((uint16_t)high << 8) | low;
    return 0;
}

static int log_data(FILE *fp, uint16_t als) {
    time_t t = time(NULL);
    struct tm tm_info;
    char ts[32];
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", ts, als) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long fsize = ftell(g_log_fp);
    if (fsize == 0) {
        if (fprintf(g_log_fp, "timestamp,als_visible\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            fclose(g_log_fp);
            g_log_fp = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return 1;
        }
        fflush(g_log_fp);
    }

    printf("Si1175 proximity logger started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als = 0;
        if (read_als_visible(g_i2c_fd, &als) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            if (log_data(g_log_fp, als) < 0) {
                fprintf(stderr, "Logging error; continuing.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return 0;
}

