#define SI1120_REG_PS1_DATA1 0x19

#define SI1120_PART_ID_VAL 0x41
#define SI1120_CMD_RESET   0x01
#define SI1120_CMD_PS_FORCE 0x05
#define SI1120_CMD_ALS_FORCE 0x06

#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 500000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        int rc = i2cWriteByteData(i2c_handle, reg, val);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X), rc=%d, attempt %d/%d\n",
                reg, val, rc, i + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        int rc = i2cReadByteData(i2c_handle, reg);
        if (rc >= 0) { *val = (uint8_t)rc; return 0; }
        fprintf(stderr, "I2C read failed (reg 0x%02X), rc=%d, attempt %d/%d\n",
                reg, rc, i + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_reg16(uint8_t reg_lo, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(reg_lo, &lo) != 0) return -1;
    if (read_reg(reg_lo + 1, &hi) != 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int wait_response(uint8_t expected) {
    for (int i = 0; i < 10; i++) {
        uint8_t resp;
        if (read_reg(SI1120_REG_RESPONSE, &resp) != 0) return -1;
        if (resp == expected) return 0;
        gpioDelay(10000);
    }
    fprintf(stderr, "Si1120 response timeout (expected 0x%02X)\n", expected);
    return -1;
}

static int init_si1120(void) {
    uint8_t part_id;
    if (read_reg(SI1120_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read Part ID - sensor not present or bus error\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID_VAL) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID_VAL);
        return -1;
    }
    printf("Si1120 detected (Part ID 0x%02X)\n", part_id);

    if (write_reg(SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to send reset command\n");
        return -1;
    }
    gpioDelay(10000);

    if (wait_response(0x00) != 0) {
        fprintf(stderr, "Si1120 reset did not complete\n");
        return -1;
    }

    if (write_reg(SI1120_REG_HW_KEY, 0x17) != 0) return -1;
    if (write_reg(SI1120_REG_MEAS_RATE0, 0x08) != 0) return -1;
    if (write_reg(SI1120_REG_MEAS_RATE1, 0x00) != 0) return -1;
    if (write_reg(SI1120_REG_ALS_RATE, 0x08) != 0) return -1;
    if (write_reg(SI1120_REG_PS_RATE, 0x08) != 0) return -1;
    if (write_reg(SI1120_REG_PS_LED21, 0x0F) != 0) return -1;
    if (write_reg(SI1120_REG_PS_LED3, 0x00) != 0) return -1;

    printf("Si1120 initialised successfully\n");
    return 0;
}

static int read_sensor_data(uint16_t *als, uint16_t *ps) {
    if (write_reg(SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) return -1;
    if (wait_response(0x00) != 0) return -1;
    if (read_reg16(SI1120_REG_ALS_VIS_DATA0, als) != 0) return -1;

    if (write_reg(SI1120_REG_COMMAND, SI1120_CMD_PS_FORCE) != 0) return -1;
    if (wait_response(0x00) != 0) return -1;
    if (read_reg16(SI1120_REG_PS1_DATA0, ps) != 0) return -1;

    return 0;
}

static void log_data(uint16_t als, uint16_t ps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, PS: %u\n", timestamp, als, ps);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (i2c_handle >= 0) { i2cClose(i2c_handle); i2c_handle = -1; }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1120() != 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging Si1120 data to si1120_log.txt (Ctrl+C to stop)\n");

    while (!terminate) {
        uint16_t als = 0, ps = 0;
        if (read_sensor_data(&als, &ps) == 0) {
            log_data(als, ps);
            printf("ALS: %u, PS: %u\n", als, ps);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

