#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS 1

#define REG_HW_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_IRQ_ENABLE 0x1A
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80

#define REG_PS1_DATA0 0x16
#define REG_PS1_DATA1 0x17

#define CMD_PS_FORCE 0x03

#define MAX_RETRIES 3
#define LOG_FILE "proximity_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

static int init_si1145(int handle) {
    if (write_reg(handle, REG_HW_KEY, 0x03) < 0) return -1;
    if (write_reg(handle, REG_MEAS_RATE, 0x02) < 0) return -1;
    if (write_reg(handle, REG_IRQ_ENABLE, 0x00) < 0) return -1;
    if (write_reg(handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x0B) < 0) return -1;
    if (write_reg(handle, REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (write_reg(handle, REG_PS_ADC_COUNTER, 0x49) < 0) return -1;
    if (write_reg(handle, REG_PS_LED21, 0x03) < 0) return -1;
    if (write_reg(handle, REG_PS_LED3, 0x0F) < 0) return -1;
    if (write_reg(handle, REG_PS_ADC_MISC, 0x03) < 0) return -1;
    if (write_reg(handle, REG_PS_ADC_GAIN, 0x07) < 0) return -1;
    if (write_reg(handle, REG_COMMAND, CMD_PS_FORCE) < 0) return -1;
    return 0;
}

static int read_proximity(int handle, uint16_t *prox) {
    int lo = i2cReadByteData(handle, REG_PS1_DATA0);
    if (lo < 0) {
        fprintf(stderr, "Error reading PS1_DATA0 (rc=%d)\n", lo);
        return -1;
    }
    int hi = i2cReadByteData(handle, REG_PS1_DATA1);
    if (hi < 0) {
        fprintf(stderr, "Error reading PS1_DATA1 (rc=%d)\n", hi);
        return -1;
    }
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

