    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X (rc=%d)\n", SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handlers\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1145 proximity logger started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        uint16_t prox;
        if (read_proximity(i2c_handle, &prox) == 0) {
            log_data(log_file, prox);
        } else {
            int retries = 0;
            while (retries < MAX_RETRIES && !terminate) {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", retries + 1, MAX_RETRIES);
                if (read_proximity(i2c_handle, &prox) == 0) {
                    log_data(log_file, prox);
