#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD 20.0
#define SPEED_OF_SOUND 0.0343
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
        echo_received = 0;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static void trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return;
    }
}

static double calculate_distance(uint32_t start, uint32_t end) {
    uint32_t diff = end - start;
    if (diff > ECHO_TIMEOUT_US) {
        return -1.0;
    }
    return (double)diff * SPEED_OF_SOUND / 2.0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER, OUTPUT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(BUZZER, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_sensor();

        uint32_t wait_start = gpioTick();
        while (!echo_received && running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: Echo timeout - sensor may be disconnected\n");
                break;
            }
            gpioDelay(100);
        }

        if (!echo_received) {
            gpioDelay(100000);
            continue;
        }

        double distance = calculate_distance(start_tick, end_tick);

        if (distance < 0) {
            fprintf(stderr, "Warning: Invalid distance reading (timeout or out of range)\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_PIN, 1) < 0) {
                    fprintf(stderr, "Error: gpioWrite(BUZZER, 1) failed\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) < 0) {
                    fprintf(stderr, "Error: gpioWrite(BUZZER, 0) failed\n");
                }
            }
        }

        gpioDelay(1000000);
    }

    printf("\nExiting...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

