#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_CLOSE 200
#define DISTANCE_THRESHOLD_OPEN 250
#define SERVO_CLOSED_US 1000
#define SERVO_OPEN_US 2000
#define SERVO_SPEED 1000
#define POLL_DELAY_US 100000

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0087
#define VL53L1X_REG_RANGE_CONFIG_TIMING_BUDGET 0x008E

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char cmd[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(handle, cmd, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG_TIMING_BUDGET, 0x006B) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x006B) != 0) return -1;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int vl53l1x_read_distance(int handle) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) return -1;
    if (!(status & 0x01)) return -2;

    uint8_t buf[2] = {0};
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) != 2) return -1;
    int distance = (buf[0] << 8) | buf[1];

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    return distance;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, event);
    fflush(log_file);
}

static void set_servo_pulse(int pin, int pulse_width) {
    gpioServo(pin, pulse_width);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int gate_open = 0;
    int last_distance = -1;

    while (running) {
        int distance = vl53l1x_read_distance(i2c_handle);

        if (distance == -1) {
            fprintf(stderr, "Error: I2C read failed\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (distance >= 0 && distance < DISTANCE_THRESHOLD_CLOSE && !gate_open) {
            set_servo_pulse(SERVO_PIN, SERVO_CLOSED_US);
            gate_open = 1;
            log_event("Gate opened");
        } else if (distance >= 0 && distance > DISTANCE_THRESHOLD_OPEN && gate_open) {
            set_servo_pulse(SERVO_PIN, SERVO_OPEN_US);
            gate_open = 0;
            log_event("Gate closed");
        }

        if (distance >= 0 && distance != last_distance) {
            printf("Distance: %d mm\n", distance);
            last_distance = distance;
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

