#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_ANGLE_DEG  0
#define MAX_ANGLE_DEG  180
#define SERVO_MIN_US  500
#define SERVO_MAX_US  2500
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000
#define LOOP_DELAY_US    100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > ECHO_TIMEOUT_US) return -1.0;
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    return (pulse_width * SPEED_OF_SOUND_CM_PER_US) / 2.0;
}

static int calculate_angle(double distance) {
    if (distance < MIN_DISTANCE_CM) return MIN_ANGLE_DEG;
    if (distance > MAX_DISTANCE_CM) return MAX_ANGLE_DEG;
    return (int)(((distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) *
                 (MAX_ANGLE_DEG - MIN_ANGLE_DEG));
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE_DEG) angle = MIN_ANGLE_DEG;
    if (angle > MAX_ANGLE_DEG) angle = MAX_ANGLE_DEG;
    int pulse_width = SERVO_MIN_US +
        (int)(((double)angle / MAX_ANGLE_DEG) *
              (SERVO_MAX_US - SERVO_MIN_US));
    return gpioServo(SERVO_PIN, pulse_width);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioServo(SERVO_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Error: sensor timeout or read failure.\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int angle = calculate_angle(distance);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Error: gpioServo failed for angle %d.\n", angle);
        }

        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

