#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_sensor(void) {
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing CONFIG register\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion delay */
    return 0;
}

static int read_sensor(float *temperature, float *humidity) {
    int raw_temp, raw_humidity;

    if (i2cWriteByte(i2c_handle, TEMP_REG) < 0) {
        fprintf(stderr, "Error writing temperature register address\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion delay */

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    if (i2cWriteByte(i2c_handle, HUMID_REG) < 0) {
        fprintf(stderr, "Error writing humidity register address\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion delay */

    raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    *temperature = (175.72f * (float)raw_temp) / 65536.0f - 46.85f;
    *humidity = (125.0f * (float)raw_humidity) / 65536.0f - 6.0f;

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    float temperature, humidity;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Read failed, attempting recovery...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000); /* 1 s backoff */
            i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Recovery failed, exiting\n");
                break;
            }
            if (init_sensor() < 0) {
                fprintf(stderr, "Recovery init failed, exiting\n");
                break;
            }
        }
        gpioDelay(2000000); /* 2 s */
    }

    cleanup();
    return EXIT_SUCCESS;
}

