#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C default address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 register addresses */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_CONFIG     0x1A
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

/* Expected device ID */
#define MPU6050_WHO_AM_I_RESP 0x68

/* Scaling factors for default ranges */
#define ACCEL_SCALE 16384.0f  /* +/- 2 g  */
#define GYRO_SCALE  131.0f    /* +/- 250 deg/s */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_init(int handle)
{
    int status;

    /* Verify device identity */
    status = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error: I2C read of WHO_AM_I failed (pigpio status %d).\n", status);
        return -1;
    }
    if (status != MPU6050_WHO_AM_I_RESP) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                status, MPU6050_WHO_AM_I_RESP);
        return -1;
    }

    /* Reset the device */
    status = i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x80);
    if (status < 0) {
        fprintf(stderr, "Error: PWR_MGMT_1 write failed (pigpio status %d).\n", status);
        return -1;
    }

    /* Allow time for the reset to take effect */
    gpioDelay(100000); /* 100 ms */

    /* Wake up: clear sleep bit, use internal 8 MHz oscillator */
    status = i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: PWR_MGMT_1 wake-up failed (pigpio status %d).\n", status);
        return -1;
    }

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    status = i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 7);
    if (status < 0) {
        fprintf(stderr, "Error: SMPLRT_DIV write failed (pigpio status %d).\n", status);
        return -1;
    }

    /* DLPF_CFG = 0 (bandwidth 256 Hz, delay 0 ms) */
    status = i2cWriteByteData(handle, MPU6050_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: CONFIG write failed (pigpio status %d).\n", status);
        return -1;
    }

    /* Gyro full-scale range = +/- 250 deg/s */
    status = i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: GYRO_CONFIG write failed (pigpio status %d).\n", status);
        return -1;
    }

    /* Accel full-scale range = +/- 2 g */
    status = i2cWriteByteData(handle, MPU6050_ACCEL_CONFIG, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: ACCEL_CONFIG write failed (pigpio status %d).\n", status);
        return -1;
    }

    return 0;
}

static int read_sensor_data(int handle,
                            float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz)
{
    char buffer[14];
    int16_t raw_ax, raw_ay, raw_az;
    int16_t raw_gx, raw_gy, raw_gz;
    int status;

    status = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buffer, 14);
    if (status != 14) {
        fprintf(stderr, "Error: I2C block read failed (got %d bytes, expected 14).\n", status);
        return -1;
    }

    /* Accelerometer data is big-endian */
    raw_ax = (int16_t)(((uint8_t)buffer[0]  << 8) | (uint8_t)buffer[1]);
    raw_ay = (int16_t)(((uint8_t)buffer[2]  << 8) | (uint8_t)buffer[3]);
    raw_az = (int16_t)(((uint8_t)buffer[4]  << 8) | (uint8_t)buffer[5]);
    /* Temperature bytes at buffer[6..7] are skipped */
    raw_gx = (int16_t)(((uint8_t)buffer[8]  << 8) | (uint8_t)buffer[9]);
    raw_gy = (int16_t)(((uint8_t)buffer[10] << 8) | (uint8_t)buffer[11]);
    raw_gz = (int16_t)(((uint8_t)buffer[12] << 8) | (uint8_t)buffer[13]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *gx = (float)raw_gx / GYRO_SCALE;
    *gy = (float)raw_gy / GYRO_SCALE;
    *gz = (float)raw_gz / GYRO_SCALE;

    return 0;
}

int main(void)
{
    float ax, ay, az, gx, gy, gz;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 default address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio status %d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the MPU-6050 */
    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialised on I2C bus 1 at address 0x%02X.\n", MPU6050_ADDR);
    printf("Logging accelerometer and gyroscope data every 100 ms. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g  |  Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, continuing...\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("Done.\n");

    return EXIT_SUCCESS;
}

