#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDR        0x44
#define I2C_BUS           1
#define MEASURE_CMD       0xFD
#define MEASURE_DELAY_US  10000   /* 10 ms */
#define READ_LEN          6
#define POLL_INTERVAL_S   5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int read_sht40(int handle, float *temp, float *rh)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[READ_LEN];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to send measurement command 0x%02X\n", cmd);
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "Error: failed to read 6 bytes from SHT40\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X got=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X got=0x%02X)\n",
                crc8(buf + 3, 2), buf[5]);
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh   = -6.0f  + 125.0f * (float)h_raw / 65535.0f;

    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (code %d)\n",
                I2C_BUS, SHT40_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, rh;

        if (read_sht40(handle, &temp, &rh) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, rh);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: read failed, re-opening I2C bus...\n");
            i2cClose(handle);
            handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
            if (handle < 0) {
                fprintf(stderr, "Error: i2cOpen re-open failed (code %d)\n", handle);
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++)
            gpioDelay(100000);
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

