#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A
#define TA_REG 0x06
#define TO_REG 0x07
#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *temp) {
    uint8_t buf[3];
    ssize_t n = read(fd, buf, 3);
    if (n != 3) {
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *temp = (float)raw * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(FILE *fp, float ambient, float object) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_DEV);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen " LOG_FILE);
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient, object;
        int ta_ok = i2c_read_reg16(fd, TA_REG, &ambient);
        int to_ok = i2c_read_reg16(fd, TO_REG, &object);

        if (ta_ok != 0 || to_ok != 0) {
            fprintf(stderr, "I2C read error (ta=%d, to=%d): %s\n",
                    ta_ok, to_ok, strerror(errno));
        } else {
            if (log_temperature(fp, ambient, object) != 0) {
                fprintf(stderr, "Log write error: %s\n", strerror(errno));
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

