#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define STS30_ADDR 0x4A
#define I2C_BUS 1
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static FILE *err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!err_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(err_fp, "%s: %s\n", ts, msg);
    fflush(err_fp);
}

static int read_temperature(int handle, float *temp) {
    unsigned char cmd = 0x71;
    unsigned char buf[3];
    int rc;

    rc = i2cWriteDevice(handle, (char *)&cmd, 1);
    if (rc < 0) {
        log_error("I2C write failed (trigger measurement)");
        return -1;
    }

    gpioDelay(20000); // 20ms conversion time

    rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc < 0) {
        log_error("I2C read failed (measurement data)");
        return -1;
    }
    if (rc != 3) {
        log_error("I2C read short read");
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 16) | ((unsigned int)buf[1] << 8) | buf[2];
    raw >>= 2;
    *temp = -45.0f + (175.0f * raw / 65535.0f);
    return 0;
}

static void log_data(float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s,%.2f\n", ts, temp);
    fflush(log_fp);
}

int main(void) {
    int handle;
    float temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", STS30_ADDR);
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        perror("Failed to open error log file");
        fclose(log_fp);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(handle, &temperature) == 0) {
            log_data(temperature);
        } else {
            log_error("Failed to read temperature");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    fclose(log_fp);
    fclose(err_fp);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

