#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP31_ADDR     0x28
#define LOG_FILE       "airflow.log"
#define SAMPLE_US      100000   /* 100 ms */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 100000   /* 100 ms */
#define MEAS_DELAY_US  1000     /* 1 ms  */

static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* CRC-8 polynomial 0x31, init 0xFF — Sensirion convention */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int sdp31_read(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = { 0x21, 0x96 };
    uint8_t buf[6];
    int     retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US * (1 << retries));
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US * (1 << retries));
            continue;
        }

        if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
            retries++;
            if (retries < MAX_RETRIES)
                gpioDelay(RETRY_DELAY_US * (1 << retries));
            continue;
        }

        int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure    = (float)raw_pressure    / 60.0f;
        *temperature = (float)raw_temperature / 200.0f;
        return 0;
    }

    fprintf(stderr, "SDP31 read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(FILE *fp, float pressure, float temperature)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    localtime_r(&t, &tm);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void)
{
    float pressure, temperature;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        if (sdp31_read(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            fprintf(stderr, "Read error — continuing\n");
        }
        gpioDelay(SAMPLE_US);
    }

    fprintf(stderr, "Shutting down cleanly...\n");
    if (log_file)   fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

