#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMIDITY   0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_PERIOD  5.0
#define MEAS_TIMEOUT   20000   /* microseconds (20 ms) */
#define POLL_DELAY     1000    /* microseconds */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit measurement from the Si7015 in No Hold Master mode.
 * Returns 0 on success and stores the raw value in *out_raw;
 * returns -1 on I2C error or timeout.
 */
static int read_measurement(int handle, uint8_t cmd, uint16_t *out_raw)
{
    char buf[2];
    int  rc;

    /* Send the measurement command (No Hold Master: write, no data byte) */
    rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, pigpio_error(rc));
        return -1;
    }

    /*
     * Wait for the sensor to complete the conversion.
     * The Si7015 No Hold Master mode takes ~11 ms max; poll for data
     * readiness every 1 ms up to MEAS_TIMEOUT.
     */
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT; elapsed += POLL_DELAY) {
        gpioDelay(POLL_DELAY);

        /*
         * Read 2 bytes: the first read returns 0xFF if the previous
         * command is still in progress, or the data bytes if ready.
         */
        rc = i2cReadDevice(handle, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X): %s\n",
                    cmd, pigpio_error(rc));
            return -1;
        }
        if (rc == 2) {
            *out_raw = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
            return 0;
        }
        /* rc == 0: no data yet; keep polling */
    }

    fprintf(stderr, "Timeout waiting for measurement (cmd 0x%02X)\n", cmd);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity);
    } else {
        fprintf(fp, "(time error), Temperature: %.2f C, Humidity: %.2f %%\n",
                temperature, humidity);
    }

    fclose(fp);
}

int main(void)
{
    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, SI7015_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t raw_temp = 0, raw_hum = 0;
        int ok = 1;

        if (read_measurement(g_i2c_handle, CMD_TEMP, &raw_temp) != 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
            ok = 0;
        }
        if (ok && read_measurement(g_i2c_handle, CMD_HUMIDITY, &raw_hum) != 0) {
            fprintf(stderr, "Humidity read failed; retrying next cycle.\n");
            ok = 0;
        }

        if (ok) {
            float temperature = convert_temperature(raw_temp);
            float humidity    = convert_humidity(raw_hum);

            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

