#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define MEASURE_CMD    0x362F
#define MEASURE_DELAY_MS 45
#define LOG_INTERVAL_MS 100
#define LOG_FILE       "airflow_data.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) return -1;
        if (n == 0) return -1;
        total += n;
    }
    return 0;
}

static int read_sdp800(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, MEASURE_CMD) < 0) return -1;
    usleep(MEASURE_DELAY_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, 9) < 0) return -1;

    if (crc8(&data[0], 2) != data[2]) return -2;
    if (crc8(&data[3], 2) != data[5]) return -2;
    if (crc8(&data[6], 2) != data[8]) return -2;

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) return -3;

    *pressure    = (float)raw_pressure / (float)scale_factor;
    *temperature = (float)raw_temp / 200.0f - 45.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        close(g_i2c_fd);
        return 1;
    }

    fprintf(g_log_fp, "timestamp,pressure_pa,temperature_c\n");
    fflush(g_log_fp);

    while (g_running) {
        float pressure, temperature;
        int rc = read_sdp800(g_i2c_fd, &pressure, &temperature);
        if (rc == 0) {
            log_data(g_log_fp, pressure, temperature);
        } else if (rc == -2) {
            fprintf(stderr, "CRC mismatch on sensor data\n");
        } else if (rc == -3) {
            fprintf(stderr, "Invalid scale factor (0)\n");
        } else {
            fprintf(stderr, "I2C read error (rc=%d)\n", rc);
        }
        usleep(LOG_INTERVAL_MS * 1000);
    }

    if (g_log_fp) fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

