#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_HIGH      28.0
#define TEMP_LOW       27.0
#define MAX_RETRIES    3
#define MEAS_DELAY_US  15000   /* 15 ms — covers 10 ms max conversion time */
#define SAMPLE_US      2000000 /* 2 s */

/* Si7021 measurement commands (Hold Master mode) */
#define CMD_TEMP_HOLD  0xE3
#define CMD_HUM_HOLD   0xE5

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

static SensorData buffer[BUFFER_SIZE];
static int        buf_head = 0;
static int        buf_count = 0;
static int        i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void)
{
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        return -1;
    }
    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing GPIO %d low\n", FAN_GPIO);
        return -1;
    }
    return 0;
}

/*
 * Trigger a Hold Master measurement and read the 2-byte response.
 * Returns 0 on success, -1 on failure.
 */
static int read_measurement(uint8_t cmd, uint16_t *raw_out)
{
    char cmd_buf[1] = { (char)cmd };
    char data[2];
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd_buf, 1) != 0) {
            fprintf(stderr, "I2C write failed (cmd 0x%02X), retry %d/%d\n",
                    cmd, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000); /* 10 ms backoff */
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        if (i2cReadDevice(i2c_handle, data, 2) != 2) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X), retry %d/%d\n",
                    cmd, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        *raw_out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
        return 0;
    }

    fprintf(stderr, "Failed to read measurement 0x%02X after %d retries\n",
            cmd, MAX_RETRIES);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float h = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (h < 0.0f)   h = 0.0f;
    if (h > 100.0f) h = 100.0f;
    return h;
}

static void add_to_buffer(float temp, float hum)
{
    buffer[buf_head].timestamp   = time(NULL);
    buffer[buf_head].temperature = temp;
    buffer[buf_head].humidity    = hum;
    buf_head = (buf_head + 1) % BUFFER_SIZE;
    if (buf_count < BUFFER_SIZE) buf_count++;
}

static void print_buffer(void)
{
    int start = (buf_count < BUFFER_SIZE) ? 0 : buf_head;
    printf("\n--- Sensor Log (%d entries) ---\n", buf_count);
    for (int i = 0; i < buf_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&buffer[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n",
               ts, buffer[idx].temperature, buffer[idx].humidity);
    }
    printf("-------------------------------\n");
    fflush(stdout);
}

static void control_fan(float temp)
{
    static int fan_on = 0;

    if (temp > TEMP_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (T=%.2f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temp < TEMP_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (T=%.2f C)\n", temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Si7021 fan controller started. Ctrl+C to exit.\n");

    while (running) {
        uint16_t raw_t = 0, raw_h = 0;

        if (read_measurement(CMD_TEMP_HOLD, &raw_t) != 0) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (read_measurement(CMD_HUM_HOLD, &raw_h) != 0) {
            fprintf(stderr, "Sensor read error — skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float temp = convert_temperature(raw_t);
        float hum  = convert_humidity(raw_h);

        add_to_buffer(temp, hum);
        print_buffer();
        control_fan(temp);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

