#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 5000000
#define MEASUREMENT_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write command 0x%04X to I2C device.\n", cmd);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *data, int len) {
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: Failed to read %d bytes from I2C device.\n", len);
        return -1;
    }
    return 0;
}

static int check_data_ready(void) {
    if (send_command(0xE4B8) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[3];
    if (read_data(data, 3) != 0)
        return -1;
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready word.\n");
        return -1;
    }
    uint16_t word = (data[0] << 8) | data[1];
    return (word & 0x07FF) == 0 ? 1 : 0;
}

static int read_measurement(uint16_t *co2, uint16_t *temp, uint16_t *hum) {
    if (send_command(0xEC05) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t data[9];
    if (read_data(data, 9) != 0)
        return -1;
    for (int i = 0; i < 3; i++) {
        if (crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement word %d.\n", i);
            return -1;
        }
    }
    *co2 = (data[0] << 8) | data[1];
    *temp = (data[3] << 8) | data[4];
    *hum = (data[6] << 8) | data[7];
    return 0;
}

static void log_data(uint16_t co2, uint16_t temp, uint16_t hum) {
    float t = -45.0f + 175.0f * (float)temp / 65535.0f;
    float h = 100.0f * (float)hum / 65535.0f;
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, t, h);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, SCD40_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(0x21B1) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(MEASUREMENT_INTERVAL_US);

    while (!terminate) {
        int ready = check_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Error: Data-ready check failed, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        if (ready == 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        uint16_t co2, temp, hum;
        if (read_measurement(&co2, &temp, &hum) != 0) {
            fprintf(stderr, "Error: Measurement read failed, retrying...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }
        log_data(co2, temp, hum);
        gpioDelay(POLL_INTERVAL_US);
    }

    if (send_command(0x3F86) != 0)
        fprintf(stderr, "Warning: Failed to stop periodic measurement.\n");

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

