#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR        0x62
#define SCD40_CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_CMD_READ_MEASUREMENT           0xEC05
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define SCD40_CMD_GET_DATA_READY_STATUS      0xE4B8

#define LED_GPIO                 17
#define CO2_THRESHOLD            1000
#define BUFFER_SIZE              20
#define MEASUREMENT_INTERVAL_S   5
#define POLL_TIMEOUT_MS          1000
#define POLL_INTERVAL_US         20000

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT       0xFF

typedef struct {
    uint16_t co2;
    float    temperature;
    float    humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int scd40_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_data(uint8_t *buf, int len) {
    if (i2cReadDevice(i2c_handle, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(void) {
    return scd40_write_command(SCD40_CMD_START_PERIODIC_MEASUREMENT);
}

static int scd40_stop_periodic_measurement(void) {
    return scd40_write_command(SCD40_CMD_STOP_PERIODIC_MEASUREMENT);
}

static int scd40_get_data_ready_status(uint16_t *status) {
    if (scd40_write_command(SCD40_CMD_GET_DATA_READY_STATUS) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (scd40_read_data(buf, 3) != 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready status\n");
        return -1;
    }
    *status = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh) {
    if (scd40_write_command(SCD40_CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(2000);
    uint8_t buf[9];
    if (scd40_read_data(buf, 9) != 0)
        return -1;
    if (crc8(buf, 2) != buf[2] ||
        crc8(buf + 3, 2) != buf[5] ||
        crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on measurement data\n");
        return -1;
    }
    *co2 = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t h_raw = (uint16_t)((buf[6] << 8) | buf[7]);
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh   = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *b) {
    b->head = 0;
    b->count = 0;
}

static void buffer_add(circular_buffer_t *b, sensor_data_t d) {
    b->data[b->head] = d;
    b->head = (b->head + 1) % BUFFER_SIZE;
    if (b->count < BUFFER_SIZE)
        b->count++;
}

static void control_led(uint16_t co2) {
    gpioWrite(LED_GPIO, co2 > CO2_THRESHOLD ? 1 : 0);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (scd40_start_periodic_measurement() != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    buffer_init(&buffer);
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ready = 0;
        int poll_ok = 0;
        for (int i = 0; i < POLL_TIMEOUT_MS / 2 && running; i++) {
            if (scd40_get_data_ready_status(&ready) == 0) {
                poll_ok = 1;
                break;
            }
            gpioDelay(POLL_INTERVAL_US);
        }
        if (!poll_ok) {
            fprintf(stderr, "Warning: Failed to poll data-ready status\n");
            continue;
        }
        if (!(ready & 0x01)) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint16_t co2_raw;
        float temp, rh;
        if (scd40_read_measurement(&co2_raw, &temp, &rh) != 0) {
            fprintf(stderr, "Warning: Failed to read measurement\n");
            continue;
        }

        sensor_data_t d;
        d.co2 = co2_raw;
        d.temperature = temp;
        d.humidity = rh;
        buffer_add(&buffer, d);
        control_led(co2_raw);

        printf("CO2: %u ppm, Temp: %.2f C, RH: %.2f %%\n", co2_raw, temp, rh);

        for (int s = 0; s < MEASUREMENT_INTERVAL_S * 1000 && running; s += 100)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

