#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define POLL_TIMEOUT_US 50000        /* 50 ms per edge wait */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Busy-wait for a GPIO edge; returns 0 on success, -1 on timeout. */
static int wait_for_edge(int pin, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    int lvl = gpioRead(pin);
    if (lvl < 0) return -1;
    while (lvl == level) {
        if ((gpioTick() - start) >= timeout_us) return -1;
        lvl = gpioRead(pin);
        if (lvl < 0) return -1;
    }
    return 0;
}

/*
 * Measure the high-time (TH) and total-cycle-time (TL) of a TMP05-style
 * PWM-style output on `pin`.  Returns 0 on success, -1 on timeout or read error.
 */
static int measure_pulse(int pin, uint32_t *th, uint32_t *tl) {
    int rc;

    /* Wait for the line to go HIGH (start of a cycle). */
    rc = wait_for_edge(pin, 0, POLL_TIMEOUT_US);
    if (rc < 0) return -1;

    uint32_t t_high_start = gpioTick();

    /* Wait for the line to go LOW (end of the high pulse). */
    rc = wait_for_edge(pin, 1, POLL_TIMEOUT_US);
    if (rc < 0) return -1;

    uint32_t t_high_end = gpioTick();

    /* Wait for the line to go HIGH again (start of the low pulse). */
    rc = wait_for_edge(pin, 0, POLL_TIMEOUT_US);
    if (rc < 0) return -1;

    uint32_t t_low_start = gpioTick();

    /* Wait for the line to go LOW again (end of the cycle). */
    rc = wait_for_edge(pin, 1, POLL_TIMEOUT_US);
    if (rc < 0) return -1;

    uint32_t t_low_end = gpioTick();

    *th = t_high_end - t_high_start;
    *tl = t_low_end - t_low_start;
    return 0;
}

