#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_HIGH_REP 0x24
#define MEASURE_CMD_LOW_REP 0x00
#define MEASUREMENT_DELAY_US 15000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 1000000
#define LOG_INTERVAL_US 5000000
#define SIMULATED_OFFSET_TEMP_MAX 2.0
#define SIMULATED_OFFSET_HUM_MAX 5.0
#define SIMULATED_OFFSET_PERIOD_S 3600

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH_REP, MEASURE_CMD_LOW_REP};
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2] || crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "CRC mismatch (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = (buf[0] << 8) | buf[1];
        uint16_t raw_hum = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        *humidity = 100.0f * (float)raw_hum / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT35 after %d retries.\n", RETRY_COUNT);
    *temperature = NAN;
    *humidity = NAN;
    return -1;
}

static void simulate_offset(float *temperature, float *humidity) {
    time_t now = time(NULL);
    double elapsed = difftime(now, (time_t)0);
    double offset_temp = SIMULATED_OFFSET_TEMP_MAX * sin(2.0 * M_PI * elapsed / SIMULATED_OFFSET_PERIOD_S);
    double offset_hum = SIMULATED_OFFSET_HUM_MAX * sin(2.0 * M_PI * elapsed / SIMULATED_OFFSET_PERIOD_S);
    *temperature += (float)offset_temp;
    *humidity += (float)offset_hum;
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc);

    if (isnan(temperature) || isnan(humidity)) {
        fprintf(log_file, "%s, ERROR, ERROR\n", timestamp);
    } else {
        fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, humidity);
    }
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d\n", SHT35_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Greenhouse monitor started. Logging to environmental_data.txt every 5 seconds.\n");

    while (!terminate) {
        float temperature, humidity;

        if (read_sht35(i2c_handle, &temperature, &humidity) == 0) {
            simulate_offset(&temperature, &humidity);
            log_data(temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            log_data(NAN, NAN);
            fprintf(stderr, "Sensor read failed; logging NaN values.\n");
        }

        gpioDelay(LOG_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

