#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "environment.log"
#define READ_INTERVAL_SEC  5
#define MEAS_TIMEOUT_MS    100
#define MAX_RETRIES        3

#define CMD_MEASURE_RH_NOHOLD   0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_PREV_TEMP      0xE0
#define CMD_RESET                0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF\n");
            return -1;
        }
        total += (int)n;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw_out) {
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    for (int attempt = 0; attempt < MEAS_TIMEOUT_MS; attempt++) {
        usleep(1000);
        uint8_t buf[3];
        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch on measurement 0x%02X\n", cmd);
            return -1;
        }
        *raw_out = (uint16_t)((buf[0] << 8) | buf[1]);
        return 0;
    }
    fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
    return -1;
}

static int read_temperature(int fd, float *temp_c) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_TEMP_NOHOLD, &raw) < 0)
        return -1;
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *rh) {
    uint16_t raw;
    if (read_measurement(fd, CMD_MEASURE_RH_NOHOLD, &raw) < 0)
        return -1;
    *rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*rh < 0.0f)   *rh = 0.0f;
    if (*rh > 100.0f) *rh = 100.0f;
    return 0;
}

static int read_temperature_with_rh(int fd, float *temp_c, float *rh) {
    if (read_humidity(fd, rh) < 0)
        return -1;
    if (i2c_write_cmd(fd, CMD_READ_PREV_TEMP) < 0)
        return -1;
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0)
        return -1;
    if (crc8(buf, 2) != buf[1]) {
        fprintf(stderr, "CRC mismatch on temperature readback\n");
        return -1;
    }
    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

static int log_data(const char *filename, float temp_c, float rh) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fclose(fp);
    return 0;
}

static int log_error(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,ERROR,ERROR\n", ts);
    fclose(fp);
    return 0;
}

static int init_sensor(int fd) {
    if (i2c_write_cmd(fd, CMD_RESET) < 0) {
        fprintf(stderr, "Sensor reset failed (sensor may be absent)\n");
        return -1;
    }
    usleep(15000);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n", LOG_FILE, READ_INTERVAL_SEC);

    while (g_running) {
        float temp_c = 0.0f, rh = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_temperature_with_rh(g_i2c_fd, &temp_c, &rh) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; resetting sensor.\n", attempt + 1, MAX_RETRIES);
            if (init_sensor(g_i2c_fd) < 0) {
                fprintf(stderr, "Reset failed; will retry next cycle.\n");
            }
            sleep(1);
        }

        if (ok) {
            if (log_data(LOG_FILE, temp_c, rh) == 0) {
                printf("Logged: %.2f C, %.2f %%RH\n", temp_c, rh);
            } else {
                fprintf(stderr, "Failed to write log entry.\n");
            }
        } else {
            fprintf(stderr, "All read attempts failed; logging ERROR.\n");
