    terminate = 1;
}

static int read_sensor(int handle, float *pressure_out) {
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read error: expected 2 bytes, got %d\n", rc);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    raw &= 0xFFFC;
    int16_t flow_counts = (int16_t)(raw >> 2);
    *pressure_out = (flow_counts - 1638.0f) * 10.0f / 14745.0f;
    return 0;
}

