#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1 0x10
#define CTRL_REG1_VAL 0xB0
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    uint8_t xl, l, h;
    if (read_register(handle, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_L, &l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_H, &h) < 0) return -1;
    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
    if (raw & 0x00800000) raw |= 0xFF000000;
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t l, h;
    if (read_register(handle, TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(handle, TEMP_OUT_H, &h) < 0) return -1;
    int16_t raw = (int16_t)(((uint16_t)h << 8) | (uint16_t)l);
    *temperature = 42.5f + (float)raw / 480.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm_info;
    localtime_r(&t, &tm_info);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %s\n", LPS33HW_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i = 0;
    if (read_register(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, CTRL_REG1, CTRL_REG1_VAL) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("LPS33HW monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        float pressure = 0.0f, temperature = 0.0f;
        int p_ok = read_pressure(i2c_handle, &pressure);
        int t_ok = read_temperature(i2c_handle, &temperature);

        if (p_ok == 0 && t_ok == 0) {
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

