#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define THRESHOLD_C    28.0f
#define SAMPLE_US      1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * STLM75 returns a 16-bit two's-complement word with 9-bit resolution:
 *   [15]    sign
 *   [14:7]  temperature (8 bits)
 *   [6:0]   always 0
 * pigpio's i2cReadWordData returns the bytes in little-endian order, so
 * we swap them and right-shift by 7 to get the 9-bit value, then divide
 * by 2 to get degrees Celsius.
 */
static int read_temperature(int handle, float *out_temp)
{
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", TEMP_REG, raw);
        return -1;
    }

    /* Swap bytes: pigpio returns [low_byte, high_byte] in little-endian */
    uint16_t word = (uint16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));

    /* Extract 9-bit two's-complement value */
    int16_t temp_signed = (int16_t)(word << 7);
    temp_signed >>= 7;  /* arithmetic right-shift keeps sign */

    *out_temp = (float)temp_signed / 2.0f;
    return 0;
}

static void control_led(float avg_temp)
{
    int level = (avg_temp > THRESHOLD_C) ? 1 : 0;
    if (gpioWrite(LED_GPIO, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed\n", LED_GPIO, level);
    }
}

int main(void)
{
    float temp_buffer[BUFFER_SIZE];
    int   buf_index = 0;
    int   buf_count = 0;
    float sum = 0.0f;

    /* --- Initialize pigpio --- */
