#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD30_I2C_ADDR 0x61
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL_SEC 2
#define CO2_LOW_THRESHOLD 800
#define CO2_HIGH_THRESHOLD 1200

#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY_STATUS 0x0202
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define CMD_SET_ASC_0 0x0050
#define CMD_SET_ASC_1 0x0051
#define CMD_SET_ASC_2 0x0052

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int write_command(uint16_t cmd) {
    uint8_t buf[2];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int write_command_with_args(uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (cmd >> 8) & 0xFF;
    buf[1] = cmd & 0xFF;
    buf[2] = (arg >> 8) & 0xFF;
    buf[3] = arg & 0xFF;
    buf[4] = crc8(&buf[2], 2);
    if (i2cWriteDevice(i2c_handle, (char *)buf, 5) != 5) {
        fprintf(stderr, "Error: Failed to write command 0x%04X with arg 0x%04X\n", cmd, arg);
        return -1;
    }
    return 0;
}

static int read_response(uint8_t *buf, int len) {
    int bytes = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (bytes != len) {
        fprintf(stderr, "Error: Failed to read %d bytes (got %d)\n", len, bytes);
        return -1;
    }
    return 0;
}

static int init_scd30(void) {
    if (write_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) return -1;
    gpioDelay(10000);
    if (write_command_with_args(CMD_SET_MEASUREMENT_INTERVAL, MEASUREMENT_INTERVAL_SEC) != 0) return -1;
    if (write_command_with_args(CMD_SET_ASC_0, 0x0000) != 0) return -1;
    if (write_command_with_args(CMD_SET_ASC_1, 0x0000) != 0) return -1;
    if (write_command_with_args(CMD_SET_ASC_2, 0x0000) != 0) return -1;
    if (write_command(CMD_START_PERIODIC_MEASUREMENT) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int is_data_ready(int *ready) {
    if (write_command(CMD_GET_DATA_READY_STATUS) != 0) return -1;
    gpioDelay(3000);
    uint8_t buf[3];
    if (read_response(buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready status\n");
        return -1;
    }
    uint16_t val = (buf[0] << 8) | buf[1];
    *ready = (val & 0x07FF) != 0;
    return 0;
}

static int read_scd30(float *co2, float *temp, float *hum) {
    int ready = 0;
    if (is_data_ready(&ready) != 0) return -1;
    if (!ready) {
        fprintf(stderr, "Error: Data not ready\n");
        return -1;
    }
    if (write_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(3000);
    uint8_t buf[18];
    if (read_response(buf, 18) != 0) return -1;
    if (crc8(&buf[0], 2) != buf[2] || crc8(&buf[3], 2) != buf[5] || crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: CRC mismatch on measurement data\n");
        return -1;
    }
    uint16_t co2_raw = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t hum_raw = (buf[6] << 8) | buf[7];
    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *hum = (float)hum_raw / 100.0f;
    return 0;
}

static void log_data(float co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", t);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(log_file);
}

static void control_ventilation(float co2) {
    if (co2 < CO2_LOW_THRESHOLD) {
        printf("Ventilation: OFF (CO2: %.2f ppm)\n", co2);
    } else if (co2 < CO2_HIGH_THRESHOLD) {
        printf("Ventilation: LOW (CO2: %.2f ppm)\n", co2);
    } else {
        printf("Ventilation: HIGH (CO2: %.2f ppm)\n", co2);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X (handle=%d)\n", I2C_BUS, SCD30_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_scd30() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("SCD30 initialized. Logging to %s\n", LOG_FILE);

    while (!terminate) {
        float co2, temp, hum;
        if (read_scd30(&co2, &temp, &hum) == 0) {
            log_data(co2, temp, hum);
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Warning: Read failed, continuing\n");
        }
        gpioDelay(MEASUREMENT_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down...\n");
    write_command(CMD_STOP_PERIODIC_MEASUREMENT);
    gpioDelay(10000);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

