/*
 * SDP32 differential pressure reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Build: gcc -Wall -Wextra -O2 -o sdp32_reader sdp32_reader.c -lpigpio -lrt
 * Run:   sudo ./sdp32_reader [interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SDP32_ADDR             0x21
#define I2C_BUS                1
#define DEFAULT_SAMPLE_INTERVAL 1000
#define SDP32_MEAS_CMD_LEN     2
#define SDP32_MEAS_DATA_LEN    9
#define SDP32_SCALE_FACTOR     100.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8 polynomial for Sensirion: x^8 + x^5 + x^4 + 1 (0x31), init 0xFF */
static uint8_t sdp_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/*
 * Read one 9-byte measurement frame from the SDP32.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int read_sdp32(int handle, float *pressure_pa) {
    uint8_t cmd[SDP32_MEAS_CMD_LEN] = {0x36, 0x2F};
