#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_CONFIG_14BIT_T_H 0x1000  /* bit 12: enable 14-bit T & RH */

#define I2C_BUS             "/dev/i2c-1"
#define READ_INTERVAL_SEC   5
#define CONV_DELAY_MS       20

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): write pointer failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_init(int fd)
{
    /*
     * Configuration register (0x02):
     *   bit 12 = 1  -> enable 14-bit temperature
     *   bit 13 = 0  -> enable 14-bit humidity
     *   bits 11:10 = 00 -> heater off
     *   bits 9:6  = 0000 -> no interrupts
     *   bit 5     = 0   -> no mode change
     *   bit 4     = 0   -> no DRDY pin
     *   bits 3:0  = 0000 -> 14-bit resolution
     * Result = 0x1000.
     */
    if (i2c_write_reg16(fd, HDC1000_CONFIG_REG, HDC1000_CONFIG_14BIT_T_H) < 0)
        return -1;

    /* Allow the first 14-bit conversion to complete. */
    usleep(CONV_DELAY_MS * 1000);
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    uint16_t raw_t, raw_h;

    /*
     * Trigger a combined temperature-and-humidity measurement by
     * writing the temperature register pointer (0x00).  The HDC1000
     * returns the two 16-bit results in a single read transaction.
     */
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_t) < 0)
        return -1;

    /*
     * The HDC1000 does not have a dedicated DRDY pin; the 14-bit
     * conversion takes ~6.5 ms.  We wait 20 ms to be safe.
     */
    usleep(CONV_DELAY_MS * 1000);

    /*
     * Read the humidity register (0x01).  The HDC1000 auto-increments
     * the register pointer after the first read, so the second read
