#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/*
 * Raspberry Pi 4 Model B - MLX90833 Absolute Pressure Sensor
 *
 * Wiring:
 *   MLX90833 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MLX90833 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MLX90833 VDD -> 3.3V
 *   MLX90833 GND -> GND
 *
 * I2C Address: 0x60 (Manufacturer default 7-bit address)
 *
 * Pressure data is read from the sensor via I2C.
 * The program reads pressure data every 500ms and logs it to the console.
 */

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define READ_INTERVAL_MS 500

/*
 * Register map for the MLX90833 (example values, adjust based on datasheet)
 */
#define MLX90833_REG_PRESSURE_MSB 0x00
#define MLX90833_REG_PRESSURE_LSB 0x01
#define MLX90833_REG_TEMP_MSB 0x02
#define MLX90833_REG_TEMP_LSB 0x03
#define MLX90833_REG_STATUS 0x04

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/*
 * Signal handler for graceful shutdown.
 */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Reads a 16-bit big-endian value from the specified register.
 * Returns 0 on success, -1 on error.
 */
static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/*
 * Reads the pressure value from the sensor.
 * Returns 0 on success, -1 on error.
 */
static int read_pressure(int handle, float *pressure) {
    uint16_t raw_pressure;

    if (read_register16(handle, MLX90833_REG_PRESSURE_MSB, &raw_pressure) != 0) {
        return -1;
    }

    /*
     * Convert raw pressure to Pascals.
     * Adjust the scale factor based on the sensor's datasheet.
     */
    *pressure = (float)raw_pressure * 0.1f;
    return 0;
}

/*
 * Logs the pressure value with a timestamp.
 */
static void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];

    if (t == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(stdout);
}

int main(void) {
    /*
     * Initialize pigpio library.
     */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /*
     * Open I2C connection to the sensor.
     */
    i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", MLX90833_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Set up signal handlers for graceful shutdown.
     */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90833 Pressure Sensor Reader\n");
    printf("I2C Bus: %d, Address: 0x%02X\n", I2C_BUS, MLX90833_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    /*
     * Main loop.
     */
    while (running) {
        float pressure;

        if (read_pressure(i2c_handle, &pressure) == 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure data.\n");
        }

        /*
         * Sleep for 500ms.
         * gpioDelay uses microseconds, so 500000.
         */
        gpioDelay(READ_INTERVAL_MS * 1000);
    }

    /*
     * Clean resource release on exit.
     */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

