#define CMD_MEASURE    0x40
#define MEASURE_DELAY_US 7000
#define LOOP_DELAY_US   5000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void get_timestamp(char *buf, size_t len) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

static int read_otp(int handle, uint16_t *cal) {
    char cmd = CMD_READ_OTP;
    char data[8];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(1000);

    if (i2cReadDevice(handle, data, 8) != 8) {
        fprintf(stderr, "Error: failed to read 8 bytes of OTP data\n");
        return -1;
    }

    for (int i = 0; i < 8; i++) {
        if (data[i] == 0xFF) {
            fprintf(stderr, "Warning: OTP byte %d is 0xFF (sensor may be absent)\n", i);
        }
    }

    cal[0] = (uint16_t)((data[0] << 8) | data[1]);
    cal[1] = (uint16_t)((data[2] << 8) | data[3]);
    cal[2] = (uint16_t)((data[4] << 8) | data[5]);
    cal[3] = (uint16_t)((data[6] << 8) | data[7]);
    return 0;
}

static int read_measurement(int handle, uint16_t *cal, float *temp, float *press) {
    char cmd = CMD_MEASURE;
    char data[6];

    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, data, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes of measurement data\n");
        return -1;
    }

    uint16_t raw_t = (uint16_t)((data[0] << 8) | data[1]);
    uint32_t raw_p = ((uint32_t)(data[2] & 0x0F) << 16) | ((uint32_t)data[3] << 8) | (uint32_t)data[4];

    float t = (float)raw_t / 65535.0f * 165.0f - 40.0f;
    float p = (float)raw_p / 65535.0f * 12000.0f;

    float t_comp = t - 40.0f;
    float p_comp = p - 4000.0f;

    float sf_lut = (float)cal[0] / 65535.0f;
    float sf_h   = (float)cal[1] / 65535.0f;
    float sf_p   = (float)cal[2] / 65535.0f;
    float sf_t   = (float)cal[3] / 65535.0f;

    *temp = t_comp * sf_t;
    *press = p_comp * sf_p + 4000.0f;

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP_10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (code %d)\n", I2C_BUS, ICP_10101_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t cal[4];
    if (read_otp(i2c_handle, cal) != 0) {
        fprintf(stderr, "Error: OTP read failed — sensor may be absent or bus error\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICP-10101 sensor started on I2C bus %d, address 0x%02X\n", I2C_BUS, ICP_10101_ADDR);

    while (!terminate) {
        float temp, press;
        char ts[32];

        if (read_measurement(i2c_handle, cal, &temp, &press) == 0) {
            get_timestamp(ts, sizeof(ts));
            printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temp, press);
            fflush(stdout);
        } else {
            get_timestamp(ts, sizeof(ts));
            fprintf(stderr, "%s - Error: measurement read failed\n", ts);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

