#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define MEAS_DELAY_MS  45
#define LOG_FILE       "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) return -1;
        if (n == 0) return -1;
        total += n;
    }
    return 0;
}

static int read_sensor(int fd, float *pressure, float *temperature) {
    if (i2c_write_cmd(fd, CMD_CONT_MEAS) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[9];
    if (i2c_read_bytes(fd, data, 9) < 0) return -1;

    if (crc8(&data[0], 2) != data[2]) return -2;
    if (crc8(&data[3], 2) != data[5]) return -2;
    if (crc8(&data[6], 2) != data[8]) return -2;

    int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);

    *pressure    = (float)raw_p / 60.0f;
    *temperature = (float)raw_t / 200.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) { perror("open i2c"); return 1; }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    printf("SDP800 monitoring started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;
        int rc = read_sensor(g_i2c_fd, &pressure, &temperature);
        if (rc == 0) {
            log_data(pressure, temperature);
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "I2C read error\n");
        } else {
            fprintf(stderr, "CRC mismatch (sensor absent or bus error)\n");
        }
        sleep(1);
    }

    if (g_i2c_fd >= 0) close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

