#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define PRESSURE_SCALE 0.01f
#define SAFE_LOW_KPA   200.0f
#define SAFE_HIGH_KPA  250.0f
#define LOG_FILE       "pressure_log.csv"
#define READ_INTERVAL  1
#define MAX_RETRIES    2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData returned %d (expected 2)\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_out = (float)raw * PRESSURE_SCALE;
    return 0;
}

static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure);
    fflush(g_log_file);
}

static void check_pressure(float pressure)
{
    if (pressure < SAFE_LOW_KPA || pressure > SAFE_HIGH_KPA) {
        fprintf(stderr,
                "WARNING: Pressure %.2f kPa outside safe range [%.0f, %.0f] kPa\n",
                pressure, SAFE_LOW_KPA, SAFE_HIGH_KPA);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    long file_size = 0;
    FILE *check = fopen(LOG_FILE, "r");
    if (check) {
        fseek(check, 0, SEEK_END);
        file_size = ftell(check);
        fclose(check);
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen log");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (file_size == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    printf("Tire pressure monitoring started. Logging to %s\n", LOG_FILE);

    while (g_running) {
        float pressure;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_pressure(&pressure) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "I2C read failed (attempt %d/%d), reopening bus...\n",
                    attempt + 1, MAX_RETRIES);
            if (open_i2c() != 0) {
                fprintf(stderr, "Failed to reopen I2C bus, retrying in %d s...\n",
                        READ_INTERVAL);
                sleep(READ_INTERVAL);
                continue;
            }
        }

        if (ok) {
            log_pressure(pressure);
            check_pressure(pressure);
            printf("Pressure: %.2f kPa\n", pressure);
        } else {
            fprintf(stderr, "Failed to read pressure after %d attempts, continuing...\n",
                    MAX_RETRIES);
        }

        for (int s = 0; s < READ_INTERVAL && g_running; ++s) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

