#include <pigpio.h>

#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576
#define SAMPLE_INTERVAL_US 5000000
#define MEASUREMENT_DELAY_US 40000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return -1;
    }

    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        fclose(fp);
        return -1;
    }

    if (pos > LOG_FILE_SIZE_LIMIT) {
        fclose(fp);
        if (remove(LOG_FILE) != 0) {
            perror("remove log");
            return -1;
        }
        fp = fopen(LOG_FILE, "a");
        if (!fp) {
            perror("fopen log after remove");
            return -1;
        }
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
