#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENT_GPIO 4
#define TICK_US 3
#define SYNC_TICKS 56
#define MIN_PULSE_TICKS 12
#define MAX_PULSE_TICKS 271
#define TIMEOUT_US 100000
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sent_nibble(uint32_t *nibble) {
    uint32_t start_tick = gpioTick();
    uint32_t end_tick = start_tick;
    int level;

    while (1) {
        level = gpioRead(SENT_GPIO);
        if (level < 0) return -1;
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) return -2;
        if (end_tick - start_tick > 0 && (end_tick - start_tick) % TICK_US == 0) break;
    }

    uint32_t pulse_width = (end_tick - start_tick) / TICK_US;
    if (pulse_width < MIN_PULSE_TICKS || pulse_width > MAX_PULSE_TICKS) return -3;

    *nibble = pulse_width - MIN_PULSE_TICKS;
    return 0;
}

static int read_sent_data(uint32_t *status, uint32_t *data1, uint32_t *data2, uint32_t *data3, uint32_t *checksum) {
    if (read_sent_nibble(status) != 0) return -1;
    if (read_sent_nibble(data1) != 0) return -1;
    if (read_sent_nibble(data2) != 0) return -1;
    if (read_sent_nibble(data3) != 0) return -1;
    if (read_sent_nibble(checksum) != 0) return -1;

    uint32_t sum = *status + *data1 + *data2 + *data3;
    if (sum > 15) return -4;
    return 0;
}

static int read_pressure(float *pressure) {
    uint32_t status, data1, data2, data3, checksum;
    int rc = read_sent_data(&status, &data1, &data2, &data3, &checksum);
    if (rc != 0) return rc;

    uint32_t raw = (data1 << 8) | (data2 << 4) | data3;
    *pressure = (float)raw * 0.001f + 0.0f;
    return 0;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f Pa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float pressure;
        int rc = read_pressure(&pressure);

        if (rc == 0) {
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else if (rc == -2) {
            fprintf(stderr, "Sensor absent or bus error: timeout\n");
        } else if (rc == -3) {
            fprintf(stderr, "Bus error: invalid pulse width\n");
        } else if (rc == -4) {
            fprintf(stderr, "Bus error: checksum mismatch\n");
        } else {
            fprintf(stderr, "Bus error: GPIO read failure\n");
        }

        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

