#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_DEVICE_ID_REG 0x0F
#define TMP117_DEVICE_ID_EXPECTED 0x0117
#define TMP117_TEMP_REG 0x00
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_device_id(int handle) {
    int id = i2cReadWordData(handle, TMP117_DEVICE_ID_REG);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        return -1;
    }
    return id;
}

static int verify_device_id(int handle) {
    int id = read_device_id(handle);
    if (id < 0) return -1;
    if ((id & 0xFFFF) != TMP117_DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Device ID mismatch: got 0x%04X, expected 0x%04X\n", id & 0xFFFF, TMP117_DEVICE_ID_EXPECTED);
        return -1;
    }
    return 0;
}

static int read_temperature(int handle, float *temp) {
    int raw = i2cReadWordData(handle, TMP117_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw);
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temp = (float)signed_raw * 0.0078125f;
    return 0;
}

static int log_temperature(FILE *fp, float temp) {
    uint8_t buf[4];
    memcpy(buf, &temp, 4);
    if (fwrite(buf, 1, 4, fp) != 4) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (verify_device_id(i2c_handle) != 0) {
        fprintf(stderr, "TMP117 not detected at address 0x%02X\n", TMP117_ADDR);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "ab");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Greenhouse temperature monitoring started. Logging to %s\n", LOG_FILE);

    while (running) {
        float temp;
        if (read_temperature(i2c_handle, &temp) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Temperature: %.2f C\n", ts, temp);
            if (log_temperature(log_file, temp) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature, retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

