#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

static TemperatureReading circularBuffer[BUFFER_SIZE];
static int bufferIndex = 0;
static int bufferCount = 0;
static int i2cHandle = -1;
static volatile sig_atomic_t programRunning = 1;

static void signalHandler(int signal) {
    (void)signal;
    programRunning = 0;
}

static int readTemperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2cHandle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

static void addToCircularBuffer(float temperature) {
    circularBuffer[bufferIndex].timestamp = time(NULL);
    circularBuffer[bufferIndex].temperature = temperature;
    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
    if (bufferCount < BUFFER_SIZE) {
        bufferCount++;
    }
}

static void saveBufferToFile(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening log file for writing");
        return;
    }
    size_t elementsToWrite = (size_t)bufferCount;
    size_t bytesToWrite = elementsToWrite * sizeof(TemperatureReading);
    if (fwrite(circularBuffer, sizeof(TemperatureReading), elementsToWrite, fp) != elementsToWrite) {
        perror("Error writing to log file");
    }
    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

static void cleanup(void) {
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
        i2cHandle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2cHandle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", TMP117_ADDR, i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (programRunning) {
        float temperature;
        if (readTemperature(&temperature) == 0) {
            addToCircularBuffer(temperature);
            printf("Temperature: %.4f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping sample.\n");
        }

        if (saveBufferToFile(LOG_FILE) != 0) {
            fprintf(stderr, "Failed to save buffer to file.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && programRunning; i++) {
            sleep(1);
        }
    }

    saveBufferToFile(LOG_FILE);
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return EXIT_SUCCESS;
}

