#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 2
#define SAMPLE_INTERVAL_SEC 1

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register 0x%02X: %d\n", TEMP_REG, raw);
        return -1;
    }
    /* TMP117 returns MSB first, pigpio returns LSB first; swap bytes */
    int16_t swapped = (int16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));
    *temperature = (float)swapped * 0.0078125f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int consecutive_failures = 0;

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            consecutive_failures = 0;
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failed (%d/%d)\n", consecutive_failures, MAX_RETRIES);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
            if (init_i2c() != 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                break;
            }
            sleep(RETRY_DELAY_SEC);
            continue;
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

