#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define INIT_DELAY_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *flow_raw, uint16_t *temp_raw) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "I2C read failed: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *flow_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temp_raw = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float convert_flow(uint16_t raw) {
    return ((float)raw / 16384.0f - 0.1f) / 0.8f * 25.0f;
}

static float convert_temp(uint16_t raw) {
    return ((float)raw / 4096.0f - 0.1f) / 0.8f * 80.0f - 40.0f;
}

static void log_data(float flow, float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Flow: %.2f SLPM, Temp: %.2f C\n", timestamp, flow, temp);
    fflush(log_file);
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, ERROR: %s\n", timestamp, msg);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t flow_raw = 0, temp_raw = 0;
    int consecutive_failures = 0;

    while (!terminate) {
        if (read_sensor_data(&flow_raw, &temp_raw) == 0) {
            consecutive_failures = 0;
            float flow = convert_flow(flow_raw);
            float temp = convert_temp(temp_raw);
            log_data(flow, temp);
        } else {
            consecutive_failures++;
            if (consecutive_failures <= 2) {
                fprintf(stderr, "Attempting I2C re-initialization (%d/%d)...\n", consecutive_failures, 2);
                if (init_i2c() != 0) {
                    log_error("I2C re-initialization failed");
                }
            } else {
                log_error("I2C read failed after retries");
                if (init_i2c() != 0) {
                    log_error("I2C re-initialization failed after retries");
                }
                consecutive_failures = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

