    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint16_t flow_raw = 0, temp_raw = 0;
    int consecutive_failures = 0;

    while (!terminate) {
        if (read_sensor_data(&flow_raw, &temp_raw) == 0) {
            consecutive_failures = 0;
            float flow = convert_flow(flow_raw);
            float temp = convert_temp(temp_raw);
            log_data(flow, temp);
        } else {
            consecutive_failures++;
            if (consecutive_failures <= 2) {
                fprintf(stderr, "Attempting I2C re-initialization (%d/%d)...\n", consecutive_failures, 2);
                if (init_i2c() != 0) {
                    log_error("I2C re-initialization failed");
                }
            } else {
                log_error("I2C read failed after retries");
                if (init_i2c() != 0) {
                    log_error("I2C re-initialization failed after retries");
                }
                consecutive_failures = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

