#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_TIMEOUT_US 1000
#define DHT11_MAX_RETRIES 3
#define LOG_FILE "dht11_readings.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg, int status_code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,ERROR,%s,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg, status_code);
    fclose(fp);
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if (gpioTick() - start > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(int gpio, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i, j;

    for (int attempt = 0; attempt < DHT11_MAX_RETRIES; attempt++) {
        memset(data, 0, sizeof(data));

        gpioSetMode(gpio, PI_OUTPUT);
        gpioWrite(gpio, 0);
        gpioDelay(2000);
        gpioWrite(gpio, 1);
        gpioDelay(30);
        gpioSetMode(gpio, PI_INPUT);

        if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) {
            log_error("Timeout waiting for DHT11 start signal low", 101);
            continue;
        }
        if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) < 0) {
            log_error("Timeout waiting for DHT11 start signal high", 102);
            continue;
        }
        if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) {
            log_error("Timeout waiting for DHT11 response low", 103);
            continue;
        }

        for (j = 0; j < 40; j++) {
            if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) < 0) {
                log_error("Timeout waiting for bit start high", 104);
                goto next_attempt;
            }
            uint32_t high_start = gpioTick();
            if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) {
                log_error("Timeout waiting for bit start low", 105);
                goto next_attempt;
            }
            uint32_t high_duration = gpioTick() - high_start;
            data[j / 8] <<= 1;
            if (high_duration > 50) data[j / 8] |= 1;
        }

        uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
        if (checksum != data[4]) {
            log_error("Checksum mismatch", 106);
            goto next_attempt;
        }

        *humidity = (float)data[0];
        *temperature = (float)data[2];
        return 0;

    next_attempt:
        gpioDelay(2000000);
    }
    return -1;
}

static void log_reading(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,OK,%.1f,%.1f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temperature, humidity);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float temperature, humidity;
        if (read_dht11(DHT11_GPIO, &temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT11 sensor\n");
        }
        sleep(2);
    }

    gpioTerminate();
    return 0;
}

