#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define SHT31_ADDR 0x44
#define I2C_BUS 1
#define LOG_FILE "sht31d_data.log"
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define MEASURE_DELAY_US 20000
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_US 5000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht31d(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch\n");
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch\n");
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_hum  = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        *humidity    = (100.0f * (float)raw_hum / 65535.0f);

        return 0;
    }

    fprintf(stderr, "Sensor read failed after %d retries\n", RETRY_COUNT);
    return -1;
}

static void log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fflush(fp);
}

static void log_error(FILE *fp, const char *msg) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,ERROR,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, SHT31_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SHT31-D greenhouse monitor started. Logging to %s every 5 s.\n", LOG_FILE);

    while (!terminate) {
        float temperature, humidity;

        if (read_sht31d(i2c_handle, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            log_error(log_file, "Sensor read failed");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

