/*
 * Raspberry Pi Zero W — Dual ADPD105 Correlated Color Temperature Logger
 *
 * Reads 16-bit little-endian red, green, blue channel data from two
 * ADPD105 photometric front-end sensors on I2C bus 1 at addresses
 * 0x64 and 0x65, computes the average Correlated Color Temperature
 * (CCT), and logs the result to cct_log.csv every second.
 *
 * Build:  gcc -O2 -Wall -o cct_logger cct_logger.c -lpigpio -lrt
 * Run:    sudo ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADPD105 constants (from datasheet) ---- */
#define ADPD105_I2C_ADDR_1   0x64   /* Default 7-bit address */
#define ADPD105_I2C_ADDR_2   0x65   /* Alternate address pin tied high */
#define ADPD105_DEVID_REG    0x00
#define ADPD105_DEVID_VAL    0x2A
#define ADPD105_RED_REG      0x64
#define ADPD105_GREEN_REG    0x66
#define ADPD105_BLUE_REG     0x68
#define ADPD105_DATA_LEN     2       /* 16-bit little-endian per channel */

/* ---- Application constants ---- */
#define I2C_BUS              1
#define LOG_FILE             "cct_log.csv"
#define SAMPLE_PERIOD_US     1000000 /* 1 second */
#define MAX_RETRIES          3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static FILE *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register from an ADPD105 sensor.        */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int adpd105_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ADPD105] read reg 0x%02X failed (rc=%d)\n", reg, rc);
        return -1;
    }

    /* ADPD105 outputs little-endian: low byte first, high byte second */
    *out = (uint16_t)((uint8_t)buf[0] | ((uint16_t)(uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify the device ID register to confirm a sensor is present.      */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int adpd105_verify_device_id(int handle)
{
    uint16_t devid;

