#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 2000000

/* MLX90824 calibration constants (example values, replace with actual calibration) */
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0.0f
#define P_MAX_KPA 800.0f
#define TEMP_OFFSET 40.0f
#define TEMP_SCALE 0.01f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_register16(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    return 0;
}

static float convert_pressure(uint16_t raw) {
    return P_MIN_KPA + ((float)(raw - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (float)(OUTPUT_MAX - OUTPUT_MIN));
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * TEMP_SCALE - TEMP_OFFSET;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", timestamp, pressure, temperature);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    fprintf(fp, "%s, ERROR: %s\n", timestamp, message);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tire pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_pressure = 0, raw_temperature = 0;
        int pressure_ok = 0, temperature_ok = 0;

        if (read_register16(i2c_handle, PRESSURE_REG, &raw_pressure) == 0) {
            pressure_ok = 1;
        } else {
            fprintf(stderr, "Failed to read pressure register: %s\n", strerror(errno));
            log_error(log_file, "Failed to read pressure register");
        }

        if (read_register16(i2c_handle, TEMPERATURE_REG, &raw_temperature) == 0) {
            temperature_ok = 1;
        } else {
            fprintf(stderr, "Failed to read temperature register: %s\n", strerror(errno));
            log_error(log_file, "Failed to read temperature register");
        }

        if (pressure_ok && temperature_ok) {
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure, temperature);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

