        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", MLX90824_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Tire pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t raw_pressure = 0, raw_temperature = 0;
        int pressure_ok = 0, temperature_ok = 0;

        if (read_register16(i2c_handle, PRESSURE_REG, &raw_pressure) == 0) {
            pressure_ok = 1;
        } else {
            fprintf(stderr, "Failed to read pressure register: %s\n", strerror(errno));
            log_error(log_file, "Failed to read pressure register");
        }

        if (read_register16(i2c_handle, TEMPERATURE_REG, &raw_temperature) == 0) {
            temperature_ok = 1;
        } else {
            fprintf(stderr, "Failed to read temperature register: %s\n", strerror(errno));
            log_error(log_file, "Failed to read temperature register");
        }

        if (pressure_ok && temperature_ok) {
            float pressure = convert_pressure(raw_pressure);
            float temperature = convert_temperature(raw_temperature);
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure, temperature);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

