#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LM75B_ADDR        0x48
#define LM75B_TEMP_REG    0x00
#define FAN_GPIO          18
#define BUFFER_SIZE       60
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define SAMPLE_INTERVAL_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Read temperature from LM75B. Returns 0 on success, -1 on error. */
static int read_temperature(int handle, double *temperature) {
    char buf[2];
    int rc;

    rc = i2cReadI2CBlockData(handle, LM75B_TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }

    /* LM75B: 9-bit signed, 0.5 C resolution.
     * Bits D9..D1 hold the value (0..511), D0 is always 0. */
    int16_t raw = ((int16_t)buf[0] << 8) | (uint8_t)buf[1];
    raw >>= 7;                       /* arithmetic shift keeps sign */
    *temperature = (double)raw * 0.5;
    return 0;
}

static void control_fan(double avg_temp) {
    static int fan_on = 0;

    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    double temp_buffer[BUFFER_SIZE];
    int   buf_index = 0;
    double sum = 0.0;
    int   count = 0;
    double avg_temp;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X (rc=%d)\n",
                LM75B_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    printf("LM75B temperature monitor started. Ctrl+C to exit.\n");

    while (g_running) {
        double temperature;

        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            temp_buffer[buf_index] = temperature;
            buf_index = (buf_index + 1) % BUFFER_SIZE;
            if (count < BUFFER_SIZE) count++;

            sum -= temp_buffer[buf_index];
            sum += temperature;
            avg_temp = sum / count;

            printf("Temperature: %.2f C | Avg: %.2f C\n", temperature, avg_temp);
            control_fan(avg_temp);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    /* Graceful shutdown */
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

