#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_INTERVAL 60
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000
#define MEAS_DELAY_US  20000

/* Si7021 single-byte commands */
#define CMD_MEASURE_RH_NO_HOLD  0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_TEMP_PREV      0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];
    localtime_r(&now, &tm_buf);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static void log_reading(float temp_c, float rh_pct) {
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];
    localtime_r(&now, &tm_buf);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_buf);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
        fflush(fp);
        fclose(fp);
    }
    printf("%s,%.2f,%.2f\n", ts, temp_c, rh_pct);
}

/* Write a single command byte to the Si7021 (no data payload). */
static int si7021_write_cmd(uint8_t cmd) {
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cWriteDevice(g_i2c_handle, buf, 1) == 0)
            return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read 2 bytes from the Si7021 (no register address preamble). */
static int si7021_read_bytes(uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2cReadDevice(g_i2c_handle, (char *)buf, len) == len)
            return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Trigger a measurement and read the 2-byte result. */
static int si7021_measure(uint8_t cmd, uint16_t *raw) {
    if (si7021_write_cmd(cmd) != 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);
    uint8_t buf[2];
    if (si7021_read_bytes(buf, 2) != 0)
        return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Read temperature from the previous RH measurement (0xE0). */
static int si7021_read_temp(uint16_t *raw) {
    if (si7021_write_cmd(CMD_READ_TEMP_PREV) != 0)
        return -1;
    gpioDelay(MEAS_DELAY_US);
    uint8_t buf[2];
    if (si7021_read_bytes(buf, 2) != 0)
        return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int si7021_init(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    /* Read electronic ID byte 0 (should be non-zero for a valid Si7021). */
    uint8_t id[1];
    if (si7021_read_bytes(id, 1) != 0) {
        log_error("Si7021 not responding on I2C bus");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (id[0] == 0x00 || id[0] == 0xFF) {
        log_error("Si7021 not detected (ID byte 0x00 or 0xFF)");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (si7021_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7021 sensor initialized. Logging to %s every %d seconds.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    while (g_running) {
        uint16_t raw_rh = 0, raw_temp = 0;

        if (si7021_measure(CMD_MEASURE_RH_NO_HOLD, &raw_rh) != 0) {
            log_error("Failed to measure RH");
        } else if (si7021_read_temp(&raw_temp) != 0) {
            log_error("Failed to read temperature from RH measurement");
        } else {
            float rh = 125.0f * (float)raw_rh / 65536.0f - 6.0f;
            float temp = 175.72f * (float)raw_temp / 65536.0f - 46.85f;

            if (rh < 0.0f)   rh = 0.0f;
            if (rh > 100.0f) rh = 100.0f;

            log_reading(temp, rh);
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

