#include <signal.h>
#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define TEMP_REG 0x00
#define CONFIG_REG 0x02
#define CONFIG_VALUE 0x1000  /* 14-bit temp + 14-bit humidity, heater off */
#define LOG_FILE "enviro_log.txt"
#define I2C_BUS 1
#define CONVERSION_DELAY_US 25000  /* 25 ms > 14-bit conversion time */
#define SAMPLE_INTERVAL_S 5

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hdc1080(void) {
    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, HDC1080_ADDR, i2c_handle);
        return -1;
    }

    /* Write config: 14-bit temp + 14-bit humidity, heater off */
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error writing config register 0x%02X\n", CONFIG_REG);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_hdc1080(float *temperature, float *humidity) {
    char buf[4];
    int rc;

    /* Point to temperature register (0x00) */
    rc = i2cWriteByte(i2c_handle, TEMP_REG);
    if (rc < 0) {
        fprintf(stderr, "Error setting pointer to 0x%02X: %d\n", TEMP_REG, rc);
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    /* Read 4 bytes: temp MSB, temp LSB, humidity MSB, humidity LSB */
    rc = i2cReadDevice(i2c_handle, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "Error reading 4 bytes (got %d)\n", rc);
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint16_t raw_humidity = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_hdc1080() != 0) {
        fprintf(stderr, "HDC1080 initialization failed. Exiting.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HDC1080 initialized. Logging every %d seconds. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    while (!terminate) {
        float temperature, humidity;

        if (read_hdc1080(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping log entry\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && !terminate; i++) {
            gpioDelay(100000);
        }
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

