#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define ERROR_LOG "/var/log/scd40_error.log"
#define MEASUREMENT_INTERVAL_S 5
#define LOG_INTERVAL_S 60

#define CMD_START_PERIODIC 0x21B1
#define CMD_READ_MEASUREMENT 0xE000
#define CMD_STOP_PERIODIC 0x3F86

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static circular_buffer_t buffer;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(i2c_handle, (char *)buf, 2) != 0) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int read_measurement(float *co2, float *temperature, float *humidity) {
    if (send_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(1000);

    uint8_t buf[9];
    if (i2cReadDevice(i2c_handle, (char *)buf, 9) != 9) {
        log_error("I2C read measurement failed");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        log_error("CO2 CRC mismatch");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        log_error("Temperature CRC mismatch");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        log_error("Humidity CRC mismatch");
        return -1;
    }

    uint16_t raw_co2 = (buf[0] << 8) | buf[1];
    uint16_t raw_temp = (buf[3] << 8) | buf[4];
    uint16_t raw_hum = (buf[6] << 8) | buf[7];

    *co2 = (float)raw_co2;
    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = 100.0f * (float)raw_hum / 65535.0f;
    return 0;
}

static void add_to_buffer(float co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer.mutex);
    buffer.data[buffer.head].timestamp = time(NULL);
    buffer.data[buffer.head].co2 = co2;
    buffer.data[buffer.head].temperature = temperature;
    buffer.data[buffer.head].humidity = humidity;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) buffer.count++;
    pthread_mutex_unlock(&buffer.mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_S);
        if (!running) break;

        char filename[256];
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        snprintf(filename, sizeof(filename), "%s/scd40_data_%d%02d%02d_%02d%02d%02d.csv",
                 LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        FILE *fp = fopen(filename, "w");
        if (!fp) {
            log_error("Failed to open CSV file for writing");
            continue;
        }
        fprintf(fp, "Timestamp,CO2,Temperature,Humidity\n");

        pthread_mutex_lock(&buffer.mutex);
        int to_write = buffer.count;
        int start = (buffer.count == BUFFER_SIZE) ? buffer.head : 0;
        pthread_mutex_unlock(&buffer.mutex);

        for (int i = 0; i < to_write; i++) {
            int idx = (start + i) % BUFFER_SIZE;
            struct tm tm_local = *localtime(&buffer.data[idx].timestamp);
            fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                    tm_local.tm_year + 1900, tm_local.tm_mon + 1, tm_local.tm_mday,
                    tm_local.tm_hour, tm_local.tm_min, tm_local.tm_sec,
                    buffer.data[idx].co2, buffer.data[idx].temperature, buffer.data[idx].humidity);
        }
        fclose(fp);

        pthread_mutex_lock(&buffer.mutex);
        buffer.count = 0;
        buffer.head = 0;
        pthread_mutex_unlock(&buffer.mutex);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC);
        gpioDelay(1000);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    pthread_join(logging_thread, NULL);
    pthread_mutex_destroy(&buffer.mutex);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (send_command(CMD_START_PERIODIC) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        cleanup();
        return 1;
    }
    gpioDelay(1000);

    if (mkdir(LOG_DIR, 0755) == -1 && errno != EEXIST) {
        perror("mkdir");
        cleanup();
        return 1;
    }

    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        perror("mutex init");
        cleanup();
        return 1;
    }
    buffer.head = 0;
    buffer.count = 0;

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float co2, temperature, humidity;
    while (running) {
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            add_to_buffer(co2, temperature, humidity);
            printf("CO2: %.2f ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temperature, humidity);
        } else {
            fprintf(stderr, "Read failed, skipping\n");
        }
        sleep(MEASUREMENT_INTERVAL_S);
    }

    cleanup();
    return 0;
}

