#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_START_REG 0x05
#define MEAS_TRIGGER_REG 0x00
#define MEAS_DATA_REG 0x00
#define MEAS_DELAY_US 10000
#define SAMPLE_INTERVAL_S 5

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(int handle, uint16_t *cal) {
    char buf[4];
    if (i2cReadI2CBlockData(handle, CALIB_START_REG, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(uint8_t)buf[i] << 8) | (uint8_t)buf[i + 1];
    }
    return 0;
}

static int read_sensor(int handle, sensor_data_t *data, const uint16_t *cal) {
    char buf[6];
    if (i2cWriteByteData(handle, MEAS_TRIGGER_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);
    if (i2cReadI2CBlockData(handle, MEAS_DATA_REG, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read measurement data\n");
        return -1;
    }
    uint32_t raw_p = ((uint32_t)(uint8_t)buf[0] << 16) | ((uint32_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[2];
    uint32_t raw_t = ((uint32_t)(uint8_t)buf[3] << 16) | ((uint32_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5];
    float LUT_lower = 0.0f;
    float LUT_upper = 0.0f;
    if (raw_p < cal[0]) {
        LUT_lower = 0.0f;
        LUT_upper = 0.0f;
    } else if (raw_p < cal[1]) {
        LUT_lower = 0.0f;
        LUT_upper = 1.0f;
    } else if (raw_p < cal[2]) {
        LUT_lower = 1.0f;
        LUT_upper = 1.0f;
    } else {
        LUT_lower = 1.0f;
        LUT_upper = 2.0f;
    }
    float p_diff = (float)cal[3];
    float t_diff = (float)cal[4];
    data->pressure = LUT_lower + (raw_p - cal[0]) * (LUT_upper - LUT_lower) / p_diff;
    data->temperature = LUT_lower + (raw_t - cal[0]) * (LUT_upper - LUT_lower) / t_diff;
    return 0;
}

static void log_data(FILE *fp, const sensor_data_t *data) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, data->pressure, data->temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return 1;
    }
    uint16_t cal[4];
    if (read_calibration(i2c_handle, cal) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    while (running) {
        sensor_data_t data;
        if (read_sensor(i2c_handle, &data, cal) == 0) {
            log_data(log_file, &data);
            printf("Pressure: %.2f hPa, Temperature: %.2f C\n", data.pressure, data.temperature);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping sample\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

