#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_GPIO       17
#define POLL_INTERVAL  1
#define WARN_THRESHOLD 95000.0f

/* ICP-10125 OTP calibration registers (0x66..0x6B) */
#define REG_OTP_START  0x66
#define OTP_LEN        8

/* ICP-10125 command: high-accuracy measurement */
#define CMD_MEASURE    0x4011

/* CRC-8 polynomial used by ICP-10125 (x^8 + x^5 + x^4 + 1, init 0) */
#define CRC8_POLY      0x31
#define CRC8_INIT      0x00

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ICP-10125 CRC-8: polynomial x^8 + x^5 + x^4 + 1, init 0 */
static uint8_t icp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* Write a 16-bit command to the sensor */
static int i2c_write_cmd16(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read N bytes from the sensor */
static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

/* Read 8 bytes of OTP calibration coefficients */
static int read_otp(int fd, uint16_t *cal)
{
    uint8_t buf[OTP_LEN];
    if (i2c_write_cmd16(fd, REG_OTP_START) < 0)
        return -1;
    usleep(1000);
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    for (int i = 0; i < 4; i++)
        cal[i] = (uint16_t)((buf[i * 2] << 8) | buf[i * 2 + 1]);
    return 0;
}

/* Trigger a measurement and read 6 bytes (3 data words + CRC) */
static int read_measurement(int fd, uint16_t *cal,
                            float *pressure, float *temperature)
{
