#include <string.h>
#include <unistd.h>

#define MLX90614_ADDR        0x5A
#define MLX90614_TA           0x06
#define MLX90614_TO           0x07
#define FAN_GPIO              18
#define TEMP_THRESHOLD_HIGH   30.0
#define TEMP_THRESHOLD_LOW    28.0
#define LOG_FILE              "temperature_log.txt"
#define I2C_BUS               1
#define MAX_RETRIES           3
#define RETRY_DELAY_US        10000
#define SAMPLE_INTERVAL_US    2000000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp) {
    char buf[3];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2cWriteByte(handle, reg) < 0) {
            fprintf(stderr, "I2C write reg 0x%02X failed\n", reg);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(5000);

        if (i2cReadDevice(handle, buf, 3) != 3) {
            fprintf(stderr, "I2C read reg 0x%02X failed\n", reg);
            retries--;
            if (retries > 0) gpioDelay(RETRY_DELAY_US);
            continue;
        }

        int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
        *temp = (float)raw * 0.02 - 273.15;
        return 0;
    }
    return -1;
}

static void log_temperature(float ta, float to) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, ta, to);
    fclose(fp);
}

static void control_fan(float to) {
    static int fan_on = 0;
    if (to > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (T=%.2f C)\n", to);
    } else if (to < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (T=%.2f C)\n", to);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    printf("MLX90614 monitoring started. Ctrl+C to exit.\n");

    while (g_running) {
        float ta, to;

        if (read_temperature(g_i2c_handle, MLX90614_TA, &ta) != 0) {
            fprintf(stderr, "Ambient read failed; skipping cycle\n");
        } else if (read_temperature(g_i2c_handle, MLX90614_TO, &to) != 0) {
            fprintf(stderr, "Object read failed; skipping cycle\n");
        } else {
            log_temperature(ta, to);
            control_fan(to);
            printf("Ambient: %.2f C, Object: %.2f C\n", ta, to);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

