#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define HTTP_PORT 8080
#define MEASURE_CMD 0xFD
#define MEASURE_DELAY_US 10000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static int i2c_handle = -1;
static int server_fd = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    unsigned char cmd = MEASURE_CMD;
    unsigned char buf[6];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        unsigned int raw_t = (buf[0] << 8) | buf[1];
        unsigned int raw_h = (buf[3] << 8) | buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_h / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1;
}

static void handle_client(int client_fd) {
    sensor_data_t data;
    char html[512];
    int read_ok = 0;

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (read_sht40(i2c_handle, &data.temperature, &data.humidity) == 0) {
            read_ok = 1;
            break;
        }
        gpioDelay(RETRY_DELAY_US);
    }

    if (!read_ok) {
        snprintf(html, sizeof(html),
