#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUMID_LOW       0x02
#define REG_HUMID_HIGH      0x03
#define REG_MEAS_CFG        0x0E
#define REG_CONFIG          0x0F

#define MEAS_TRIGGER        0x01
#define MEAS_TIMEOUT_MS     500
#define MAX_RETRIES         3
#define POLL_DELAY_US       1000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_reg8(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int write_reg8(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_reg16(int handle, uint8_t reg_low, uint16_t *val) {
    uint8_t lo, hi;
    if (read_reg8(handle, reg_low, &lo) < 0) return -1;
    if (read_reg8(handle, reg_low + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int trigger_measurement(int handle) {
    if (write_reg8(handle, REG_MEAS_CFG, MEAS_TRIGGER) < 0) return -1;
    return 0;
}

static int wait_measurement(int handle) {
    uint8_t cfg;
    for (int i = 0; i < MEAS_TIMEOUT_MS; i += 10) {
        if (read_reg8(handle, REG_MEAS_CFG, &cfg) < 0) return -1;
        if ((cfg & MEAS_TRIGGER) == 0) return 0;
        gpioDelay(10000);
    }
    return -1;
}

static int read_hdc2010(int handle, float *temperature, float *humidity) {
    if (trigger_measurement(handle) < 0) return -1;
    if (wait_measurement(handle) < 0) return -1;

    uint16_t raw_temp, raw_hum;
    if (read_reg16(handle, REG_TEMP_LOW, &raw_temp) < 0) return -1;
    if (read_reg16(handle, REG_HUMID_LOW, &raw_hum) < 0) return -1;

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", HDC2010_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        float temperature, humidity;
        int success = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && !terminate; attempt++) {
            if (read_hdc2010(i2c_handle, &temperature, &humidity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);
        }

        if (success) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read HDC2010 after %d attempts\n", MAX_RETRIES);
        }

        for (int s = 0; s < 5 && !terminate; s++) {
            gpioDelay(1000000);
        }
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

