#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x25
#define CMD_CONT_MEAS  0x362F
#define MEAS_DELAY_US  45000   /* 45 ms for SDP800-500Pa */
#define LOOP_DELAY_US  500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_i2c(void) {
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int trigger_continuous(void) {
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONT_MEAS >> 8) & 0xFF),
        (uint8_t)(CMD_CONT_MEAS & 0xFF)
    };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing continuous-measurement command: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_measurement(int16_t *pressure, int16_t *temperature) {
    uint8_t buf[6];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
    if (rc != 6) {
        fprintf(stderr, "Error reading 6 bytes from sensor: %d\n", rc);
        return -1;
    }

    /* Verify CRC for pressure word */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc=0x%02X got=0x%02X)\n",
                crc8(&buf[0], 2), buf[2]);
        return -1;
    }

    /* Verify CRC for temperature word */
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X got=0x%02X)\n",
                crc8(&buf[3], 2), buf[5]);
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (trigger_continuous() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* First measurement is ready after the command */
    gpioDelay(MEAS_DELAY_US);

    while (g_running) {
        int16_t pressure, temperature;
        if (read_measurement(&pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C\n",
                   pressure, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read valid measurement\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

