#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define GPIO_CHIP "gpiochip0"
#define GPIO_RELAY 17
#define PROFILE_FILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define MAX_PROFILE_POINTS 100
#define SAMPLE_INTERVAL_US 1000000
#define SPI_READ_INTERVAL_US 1000000

volatile sig_atomic_t program_running = 1;

typedef struct {
    int time_seconds;
    float target_temperature;
} ProfilePoint;

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float previous_error;
} PIDController;

int spi_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *chip = NULL;
struct gpiod_line *relay_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }

    return 0;
}

int read_temperature(float *temperature) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];

    if (raw & 0x0004) {
        fprintf(stderr, "MAX6675 sensor open circuit\n");
        return -1;
    }

    int16_t temp_raw = (int16_t)(raw >> 3);
    *temperature = temp_raw * 0.25f;

    return 0;
}

int read_profile(ProfilePoint *profile, int *num_points) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        perror("Failed to open profile file");
        return -1;
    }

    *num_points = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && *num_points < MAX_PROFILE_POINTS) {
        if (sscanf(line, "%d,%f", &profile[*num_points].time_seconds, &profile[*num_points].target_temperature) == 2) {
            (*num_points)++;
        }
    }

    fclose(fp);
    return 0;
}

float pid_calculate(PIDController *pid, float current_temperature, float target_temperature) {
    float error = target_temperature - current_temperature;
    pid->integral += error;
    if (pid->integral > 100.0f) pid->integral = 100.0f;
    if (pid->integral < -100.0f) pid->integral = -100.0f;

    float derivative = error - pid->previous_error;
    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;

    pid->previous_error = error;
    return output;
}

void set_relay_state(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 1.0f) duty_cycle = 1.0f;

    int val = (int)(duty_cycle * 100.0f);
    if (gpiod_line_set_value(relay_line, val) < 0) {
        perror("Failed to set GPIO value");
    }
}

void log_data(float current_temperature, float target_temperature, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, current_temperature, target_temperature, duty_cycle);
    fflush(log_file);
}

void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Current Temperature (C),Target Temperature (C),Duty Cycle\n");
    }

    ProfilePoint profile[MAX_PROFILE_POINTS];
    int num_points = 0;
    if (read_profile(profile, &num_points) < 0) {
        cleanup();
        return 1;
    }

    PIDController pid = {0.1f, 0.01f, 0.001f, 0.0f, 0.0f};
    int current_time = 0;
    int profile_index = 0;

    while (program_running && current_time < profile[num_points - 1].time_seconds) {
        float current_temperature = 0.0f;
        if (read_temperature(&current_temperature) < 0) {
            fprintf(stderr, "Sensor read error at %d seconds\n", current_time);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float target_temperature = profile[profile_index].target_temperature;
        float duty_cycle = pid_calculate(&pid, current_temperature, target_temperature);
        set_relay_state(duty_cycle);
        log_data(current_temperature, target_temperature, duty_cycle);

        current_time++;
        if (current_time == profile[profile_index].time_seconds) {
            profile_index++;
            if (profile_index >= num_points) {
                profile_index = num_points - 1;
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

