    int num_points = 0;
    if (read_profile(profile, &num_points) < 0) {
        cleanup();
        return 1;
    }

    PIDController pid = {0.1f, 0.01f, 0.001f, 0.0f, 0.0f};
    int current_time = 0;
    int profile_index = 0;

    while (program_running && current_time < profile[num_points - 1].time_seconds) {
        float current_temperature = 0.0f;
        if (read_temperature(&current_temperature) < 0) {
            fprintf(stderr, "Sensor read error at %d seconds\n", current_time);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float target_temperature = profile[profile_index].target_temperature;
        float duty_cycle = pid_calculate(&pid, current_temperature, target_temperature);
        set_relay_state(duty_cycle);
        log_data(current_temperature, target_temperature, duty_cycle);

        current_time++;
        if (current_time == profile[profile_index].time_seconds) {
            profile_index++;
            if (profile_index >= num_points) {
                profile_index = num_points - 1;
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

