#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, unsigned char reg, unsigned short *value) {
    unsigned char buf[3];
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    usleep(10000);
    if (read(fd, buf, 3) != 3) {
        syslog(LOG_ERR, "I2C read reg 0x%02X failed: %s", reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned short raw;
    if (i2c_read_reg16(fd, 0xE5, &raw) < 0) return -1;
    *humidity = -46.85 + 175.72 * ((float)raw / 65536.0);
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;
    return 0;
}

static int post_humidity(float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }
    struct sockaddr_in servaddr = {0};
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);
    if (inet_pton(AF_INET, "api.example.com", &servaddr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        syslog(LOG_ERR, "Connection failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    char request[256];
    snprintf(request, sizeof(request),
             "POST /humidity HTTP/1.1\r\n"
             "Host: api.example.com\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: 20\r\n"
             "Connection: close\r\n"
             "\r\n"
             "{\"humidity\":%.2f}", humidity);
    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "Write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    char response[1024];
    ssize_t n = read(sockfd, response, sizeof(response) - 1);
    if (n > 0) {
        response[n] = '\0';
        if (strstr(response, "200 OK") != NULL) {
            syslog(LOG_INFO, "POST successful: %s", response);
            close(sockfd);
            return 0;
        }
    }
    syslog(LOG_ERR, "POST failed: %s", n < 0 ? strerror(errno) : "server error");
    close(sockfd);
    return -1;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Starting humidity monitoring (HTU21D at 0x%02X)", HTU21D_ADDR);
    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_humidity(humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }
        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }
    syslog(LOG_INFO, "Shutting down");
    close(fd);
    closelog();
    return 0;
}

