    c->dig_P4 = (int16_t)((buf[13] << 8) | buf[12]);
    c->dig_P5 = (int16_t)((buf[15] << 8) | buf[14]);
    c->dig_P6 = (int16_t)((buf[17] << 8) | buf[16]);
    c->dig_P7 = (int16_t)((buf[19] << 8) | buf[18]);
