}

static int read_bmp280(int handle, double *pressure) {
    char buf[6];
    if (i2cWriteByteData(handle, BMP280_CTRL_MEAS_REG, 0x27) < 0) {
        fprintf(stderr, "Error writing ctrl_meas\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    if (i2cReadI2CBlockData(handle, BMP280_DATA_REG, buf, 6) != 6) {
        fprintf(stderr, "Error reading data registers\n");
        return -1;
    }
    int32_t adc_P = (buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4);
    int32_t adc_T = (buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4);
    int32_t temp = compensate_temperature(adc_T);
    uint32_t p = compensate_pressure(adc_P);
