static int init_bmp280(int handle) {
    int id = i2cReadByteData(handle, BMP280_CHIP_ID_REG);
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (read_calibration_data(handle, &calib) != 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (init_bmp280(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    printf("BMP280 monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        double pressure;
        if (read_bmp280(i2c_handle, &pressure) == 0) {
            printf("Pressure: %.2f hPa\n", pressure);
            if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
                log_pressure(pressure);
            }
        } else {
            fprintf(stderr, "Read failed, retrying...\n");
            int retries = 0;
            while (retries < MAX_RETRIES && running) {
                i2cClose(i2c_handle);
                gpioDelay(100000);
                i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
                if (i2c_handle >= 0) {
                    if (init_bmp280(i2c_handle) == 0) break;
                }
                retries++;
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                running = 0;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

