/*
 * Raspberry Pi 4B - Environmental Monitoring Logger
 *
 * Hardware:
 *   - TMP117 temperature sensor  (I2C addr 0x48, reg 0x00)
 *   - AHT20 humidity/temperature sensor (I2C addr 0x38)
 *   - PIR motion sensor on GPIO 17 (gpiochip4, line 17)
 *
 * Build: gcc -o logger logger.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR        0x48
#define AHT20_ADDR         0x38
#define PIR_GPIO_CHIP      "gpiochip4"
#define PIR_GPIO_LINE      17
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE_PREFIX    "environmental_data"
#define SAMPLE_INTERVAL_S  1
#define MAX_RETRIES        3
#define RETRY_DELAY_MS     10

/* TMP117 register addresses */
#define TMP117_REG_TEMP    0x00

/* AHT20 commands */
#define AHT20_CMD_INIT     0xBE
#define AHT20_CMD_MEASURE  0xAC
#define AHT20_CMD_SOFTRESET 0xBA

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */

static int i2c_write_cmd(int fd, uint8_t addr, uint8_t *cmd, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed for 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t ret = write(fd, cmd, len);
    if (ret < 0 || (size_t)ret != len) {
        fprintf(stderr, "I2C write to 0x%02X failed: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t addr, uint8_t *buf, size_t len)
{
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed for 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    ssize_t ret = read(fd, buf, len);
    if (ret < 0 || (size_t)ret != len) {
        fprintf(stderr, "I2C read from 0x%02X failed: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---------- TMP117 ---------- */

static int read_tmp117_temperature(int fd, float *temperature)
{
    uint8_t reg = TMP117_REG_TEMP;
    uint8_t data[2];

    if (i2c_write_cmd(fd, TMP117_ADDR, &reg, 1) < 0)
        return -1;

    if (i2c_read_data(fd, TMP117_ADDR, data, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw * 0.0078125f;
    return 0;
}

/* ---------- AHT20 ---------- */

static int aht20_soft_reset(int fd)
{
    uint8_t cmd = AHT20_CMD_SOFTRESET;
    return i2c_write_cmd(fd, AHT20_ADDR, &cmd, 1);
}

static int aht20_init(int fd)
{
    uint8_t init_cmd[] = {AHT20_CMD_INIT, 0x08, 0x00};
    return i2c_write_cmd(fd, AHT20_ADDR, init_cmd, sizeof(init_cmd));
}

static int aht20_read_data(int fd, float *temperature, float *humidity)
{
    uint8_t measure_cmd[] = {AHT20_CMD_MEASURE, 0x33, 0x00};
    uint8_t data[7];

    if (aht20_soft_reset(fd) < 0)
        return -1;

    if (aht20_init(fd) < 0)
        return -1;

    if (i2c_write_cmd(fd, AHT20_ADDR, measure_cmd, sizeof(measure_cmd)) < 0)
        return -1;

    usleep(80000); /* 80 ms measurement wait */

    if (i2c_read_data(fd, AHT20_ADDR, data, sizeof(data)) < 0)
        return -1;

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy (0x%02X)\n", data[0]);
        return -1;
    }

    uint32_t hum_raw = ((uint32_t)data[1] << 12) |
                       ((uint32_t)data[2] << 4) |
                       ((uint32_t)data[3] >> 4);
    uint32_t temp_raw = ((uint32_t)(data[3] & 0x0F) << 16) |
                        ((uint32_t)data[4] << 8) |
                        (uint32_t)data[5];

    *humidity = (float)hum_raw / 1048576.0f * 100.0f;
    *temperature = (float)temp_raw / 1048576.0f * 200.0f - 50.0f;

    return 0;
}

/* ---------- PIR ---------- */

static int read_pir_sensor(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "PIR GPIO read failed: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

/* ---------- Logging ---------- */

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", tm_info);
}

static int log_data(const char *filename, float temperature, float humidity, int motion_detected)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char ts[32];
    get_timestamp(ts, sizeof(ts));

    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temperature, humidity, motion_detected);
    fclose(fp);
    return 0;
}

static int create_log_file(const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Failed to create log file %s: %s\n", filename, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    fclose(fp);
    return 0;
}

/* ---------- Main ---------- */

int main(void)
{
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and line */
    chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", PIR_GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        fprintf(stderr, "Failed to request PIR line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Verify sensor presence */
    if (i2c_write_cmd(i2c_fd, TMP117_ADDR, NULL, 0) < 0)
        fprintf(stderr, "Warning: TMP117 sensor not detected at 0x%02X\n", TMP117_ADDR);
    if (i2c_write_cmd(i2c_fd, AHT20_ADDR, NULL, 0) < 0)
        fprintf(stderr, "Warning: AHT20 sensor not detected at 0x%02X\n", AHT20_ADDR);

    /* Create initial log file */
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char filename[256];
    strftime(filename, sizeof(filename), LOG_FILE_PREFIX "_%Y-%m-%d.csv", tm_info);

    if (create_log_file(filename) < 0) {
        fprintf(stderr, "Failed to create initial log file\n");
        goto cleanup;
    }

