#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_INPUT_1_PIN 23
#define MOTOR_INPUT_2_PIN 24
#define GPIO_CHIP_NAME "gpiochip4"
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_TIME_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int set_motor_direction(struct gpiod_line *in1, struct gpiod_line *in2, int forward) {
    if (gpiod_line_set_value(in1, forward ? 1 : 0) < 0) {
        log_event("Error setting IN1");
        return -1;
    }
    if (gpiod_line_set_value(in2, forward ? 0 : 1) < 0) {
        log_event("Error setting IN2");
        return -1;
    }
    return 0;
}

static int run_motor(struct gpiod_line *enable, struct gpiod_line *in1, struct gpiod_line *in2, int duration_sec) {
    if (gpiod_line_set_value(enable, 1) < 0) {
        log_event("Error enabling motor");
        return -1;
    }
    if (set_motor_direction(in1, in2, 1) < 0) {
        gpiod_line_set_value(enable, 0);
        return -1;
    }
    sleep(duration_sec);
    if (gpiod_line_set_value(enable, 0) < 0) {
        log_event("Error disabling motor");
        return -1;
    }
    if (set_motor_direction(in1, in2, 0) < 0) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *enable_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_INPUT_1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_INPUT_2_PIN);

    if (!rain_line || !enable_line || !in1_line || !in2_line) {
        perror("gpiod_chip_get_line");
        log_event("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain)");
        log_event("Failed to request rain sensor line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        perror("gpiod_line_request_output(enable)");
        log_event("Failed to request motor enable line as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1)");
        log_event("Failed to request motor IN1 line as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2)");
        log_event("Failed to request motor IN2 line as output");
        goto cleanup;
    }

    log_event("Rain sensor monitoring started");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            perror("gpiod_line_get_value(rain)");
            log_event("Error reading rain sensor");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (rain_value == 0) {
            log_event("Rain detected!");
            if (run_motor(enable_line, in1_line, in2_line, MOTOR_RUN_TIME_SEC) < 0) {
                log_event("Motor control failed");
            } else {
                log_event("Window closed");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_event("Shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    if (rain_line) gpiod_line_release(rain_line);
    if (enable_line) gpiod_line_release(enable_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

