#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_MODE        0
#define BUFFER_SIZE     20
#define PWM_FREQUENCY   1000
#define PWM_RANGE       255
#define SAMPLE_PERIOD   1.0

#define TEMP_MIN        25.0
#define TEMP_MAX        60.0
#define TEMP_STEP       5.0

#define FAULT_OPEN      0x01
#define FAULT_SCG       0x02
#define FAULT_SCV       0x04

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static int      spi_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d) failed\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, 0) initial off failed\n", FAN_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen(%d, %d, %d) failed: %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE, spi_handle);
        return -1;
    }
    return 0;
}

static int read_max31855(uint32_t *raw) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    uint32_t word = ((uint32_t)(uint8_t)rx[0] << 24) |
                    ((uint32_t)(uint8_t)rx[1] << 16) |
                    ((uint32_t)(uint8_t)rx[2] <<  8) |
                    ((uint32_t)(uint8_t)rx[3]);

    if (word & 0x00010000) {
        uint8_t fault = word & 0x07;
        if (fault & FAULT_OPEN)
            fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (fault & FAULT_SCG)
            fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (fault & FAULT_SCV)
            fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -1;
    }

    *raw = word;
    return 0;
}

static float convert_temperature(uint32_t raw) {
    int16_t temp_raw = (int16_t)(raw >> 18);
    return (float)temp_raw * 0.25f;
}

static int calculate_pwm(float temp) {
    if (temp < TEMP_MIN) return 0;
    if (temp >= TEMP_MAX) return PWM_RANGE;

    if (temp < TEMP_MIN + TEMP_STEP)
        return (int)((temp - TEMP_MIN) / TEMP_STEP * (PWM_RANGE / 5));
    if (temp < TEMP_MIN + 2 * TEMP_STEP)
        return (int)((temp - TEMP_MIN - TEMP_STEP) / TEMP_STEP * (PWM_RANGE / 5) + (PWM_RANGE / 5));
    return (int)((temp - TEMP_MIN - 2 * TEMP_STEP) / TEMP_STEP * (PWM_RANGE / 5) + (2 * PWM_RANGE / 5));
}

static void set_fan_speed(int duty) {
    if (gpioPWM(FAN_GPIO, duty) < 0)
        fprintf(stderr, "Warning: gpioPWM(%d, %d) failed\n", FAN_GPIO, duty);
}

static void log_data(float temp, int duty) {
    log_buffer[buffer_index].timestamp  = time(NULL);
    log_buffer[buffer_index].temperature = temp;
    log_buffer[buffer_index].pwm_duty    = duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, PWM: %d\n", ts,
               log_buffer[idx].temperature, log_buffer[idx].pwm_duty);
    }
    printf("--- End of Log Buffer ---\n\n");
}

static void cleanup(void) {
    set_fan_speed(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_pigpio() != 0) return 1;
    if (init_spi() != 0) { cleanup(); return 1; }

    printf("MAX31855 Fan Controller running. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t raw = 0;
        if (read_max31855(&raw) != 0) {
            set_fan_speed(0);
            time_sleep(SAMPLE_PERIOD);
            continue;
        }

        float temp = convert_temperature(raw);
        int duty = calculate_pwm(temp);
        set_fan_speed(duty);
        log_data(temp, duty);

        printf("Temperature: %.2f C, PWM: %d\n", temp, duty);
        time_sleep(SAMPLE_PERIOD);
    }

    print_buffer();
    cleanup();
    return 0;
}

