#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5
#define RTD_A 3.9083e-3
#define RTD_B -5.775e-7
#define R0 100.0
#define RTD_REF_RES 430.0

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_rtd(float *temperature) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};
    if (spi_transfer(tx, rx, 4) < 0) {
        return -1;
    }
    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) | ((uint32_t)rx[2] << 8) | rx[3];
    if (raw & 0x00010000) {
        return -2;
    }
    uint16_t rtd_raw = (raw >> 18) & 0x3FFF;
    if (rtd_raw == 0) {
        return -3;
    }
    float rtd_res = (float)rtd_raw * RTD_REF_RES;
    float rtd_inv = rtd_res / R0;
    float rtd_z = -RTD_A + sqrtf(RTD_A * RTD_A - 4 * RTD_B * rtd_inv);
    *temperature = (rtd_z / RTD_B) - 273.15;
    return 0;
}

static void log_data(float temperature, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (error_code == 0) {
        fprintf(log_fp, "%s,%.2f\n", timestamp, temperature);
    } else {
        fprintf(log_fp, "%s,ERROR,%d\n", timestamp, error_code);
    }
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 || ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to configure SPI mode");
        close(spi_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "Timestamp,Temperature (C),ErrorCode\n");
    }

    printf("RTD logger started. Press Ctrl+C to stop.\n");

    while (running) {
        float temperature;
        int ret = read_rtd(&temperature);
        log_data(temperature, ret);
        if (ret != 0) {
            fprintf(stderr, "Sensor read error: %d\n", ret);
        }
        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

