#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "bme280_log.csv"
#define SAMPLE_INTERVAL_SEC 5

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_PRESS_MSB 0xF7
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_HUM_MSB 0xFD

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, buf, len) != len) return -1;
    return 0;
}

static int bme280_init(void) {
    uint8_t id;
    if (i2c_read_reg(BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error: Failed to read BME280 chip ID.\n");
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X).\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset BME280.\n");
        return -1;
    }
    usleep(2000);

    if (i2c_write_reg(BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(float *temp, float *hum, float *press) {
    uint8_t status;
    int timeout = 0;
    do {
        if (i2c_read_reg(BME280_REG_STATUS, &status) < 0) return -1;
        if (status & 0x01) break;
        usleep(2000);
        timeout++;
    } while (timeout < 20);
    if (timeout >= 20) {
        fprintf(stderr, "Error: BME280 measurement timeout.\n");
        return -1;
    }

    uint8_t data[8];
    if (i2c_read_burst(BME280_REG_PRESS_MSB, data, 8) < 0) return -1;

    int32_t raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_h = (data[6] << 8) | data[7];

    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)0x7FFF))) * ((int32_t)0x4000)) / 0x10000;
    var2 = (((((raw_t >> 4) - ((int32_t)0x7FFF)) * ((raw_t >> 4) - ((int32_t)0x7FFF))) >> 12) * ((int32_t)0xC000)) / 0x10000;
    int32_t t_fine = var1 + var2;
    *temp = (var1 + var2) / 5120.0f;

    var1 = (t_fine / 2) - 64000;
    var2 = var1 * var1 * (int32_t)0x200000;
    var2 = (var2 + (var1 * (int32_t)0x8000)) / 0x10000000;
    var2 = var2 + ((var1 * var1) / 0x40000000);
    var2 = (var2 + ((int32_t)0x2000)) / 0x4000;
    *press = (var2 * 100) + (((raw_p - (var2 * 160)) * 100) / 0x10000);

    *hum = (100.0f * raw_h) / 0x10000;
    if (*hum > 100.0f) *hum = 100.0f;
    if (*hum < 0.0f) *hum = 0.0f;

    return 0;
}

static void cleanup(void) {
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return 1;
    }

    if (bme280_init() < 0) {
        fprintf(stderr, "Error: BME280 initialization failed.\n");
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fseek(log_fp, 0, SEEK_END);
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }

    while (running) {
        float temp, hum, press;
        if (bme280_read(&temp, &hum, &press) == 0) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char ts[20];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_fp, "%s,%.2f,%.2f,%.2f\n", ts, temp, hum, press);
            fflush(log_fp);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

