#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_START 0xAA
#define BMP180_REG_ID 0xD0
#define BMP180_CHIP_ID 0x55
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 50
#define PRESSURE_THRESHOLD 5.0

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;
static float pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    int v;
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START)) < 0) return -1;
    cal.ac1 = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 1));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 2)) < 0) return -1;
    cal.ac2 = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 3));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 4)) < 0) return -1;
    cal.ac3 = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 5));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 6)) < 0) return -1;
    cal.ac4 = (uint16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 7));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 8)) < 0) return -1;
    cal.ac5 = (uint16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 9));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 10)) < 0) return -1;
    cal.ac6 = (uint16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 11));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 12)) < 0) return -1;
    cal.b1 = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 13));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 14)) < 0) return -1;
    cal.b2 = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 15));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 16)) < 0) return -1;
    cal.mb = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 17));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 18)) < 0) return -1;
    cal.mc = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 19));
    if ((v = i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 20)) < 0) return -1;
    cal.md = (int16_t)((v << 8) | i2cReadByteData(i2c_handle, BMP180_REG_CAL_START + 21));
    return 0;
}

static int read_raw_temperature(void) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (msb < 0 || lsb < 0) return -1;
    return (msb << 8) | lsb;
}

static int read_raw_pressure(void) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    return ((msb << 16) | (lsb << 8) | xlsb) >> 8;
}

static float calculate_pressure(int ut, int up) {
    int32_t x1 = ((int32_t)ut - (int32_t)cal.ac6) * (int32_t)cal.ac5 / 32768;
    int32_t x2 = ((int32_t)cal.mc * 2048) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal.b2 * (b6 * b6 / 4096)) / 2048;
    x2 = ((int32_t)cal.ac2 * b6) / 2048;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((int32_t)cal.ac1 * 4 + x3) << 0) / 4;
    x1 = ((int32_t)cal.ac3 * b6) / 8192;
    x2 = ((int32_t)cal.b1 * (b6 * b6 / 4096)) / 65536;
    x3 = ((x1 + x2) + 2) / 4;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) / 32768;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p / 256) * (p / 256);
    x1 = (x1 * 3038) / 65536;
    x2 = (-7357 * p) / 65536;
    p = p + (x1 + x2 + 3791) / 16;
    return (float)p / 100.0f;
}

static float rolling_average(void) {
    if (buffer_count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i];
    return sum / buffer_count;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int ut = read_raw_temperature();
    if (ut < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    int up = read_raw_pressure();
    if (up < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    float pressure = calculate_pressure(ut, up);
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
    float avg = rolling_average();
    if (buffer_count >= 2 && fabsf(pressure - avg) > PRESSURE_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        gpioDelay(100000);
        gpioWrite(ALERT_GPIO, 0);
    }
    printf("Pressure: %.2f hPa, Avg: %.2f hPa\n", pressure, avg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    int id = i2cReadByteData(i2c_handle, BMP180_REG_ID);
    if (id != BMP180_CHIP_ID) {
        fprintf(stderr, "BMP180 not found (id=0x%02X)\n", id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration() < 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Timer setup failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) gpioDelay(100000);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

