    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temp(i2c_handle, &ut) < 0) {
        fprintf(stderr, "Error: Failed to read temperature\n");
        return;
    }
    if (read_raw_pressure(i2c_handle, &up) < 0) {
        fprintf(stderr, "Error: Failed to read pressure\n");
        return;
    }
    float temp = calc_temp(ut, &cal);
    float press = calc_pressure(up, ut, &cal);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, %.2f, %.2f\n", ts, temp, press);
    fflush(log_file);
}

