#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define MIN_TEMP 40.0f
#define MAX_TEMP 70.0f
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(float *temp) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temp");
        return -1;
    }
    int raw;
    if (fscanf(fp, "%d", &raw) != 1) {
        fprintf(stderr, "fscanf temp failed\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    *temp = (float)raw / 1000.0f;
    return 0;
}

static int set_fan_speed(float temp) {
    if (temp < MIN_TEMP) temp = MIN_TEMP;
    if (temp > MAX_TEMP) temp = MAX_TEMP;
    float duty = (temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP) * (float)PWM_RANGE;
    if (duty < 0.0f) duty = 0.0f;
    if (duty > (float)PWM_RANGE) duty = (float)PWM_RANGE;
    int val = (int)duty;
    if (gpioPWM(FAN_GPIO, val) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return val;
}

static int log_data(float temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(log_fp, "%s,%.2f,%d\n", ts, temp, duty) < 0) {
        perror("fprintf log");
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Temp read failed, keeping last duty\n");
        } else {
            int duty = set_fan_speed(temp);
            if (duty < 0) {
                fprintf(stderr, "Fan set failed\n");
            } else {
                if (log_data(temp, duty) != 0) {
                    fprintf(stderr, "Log write failed\n");
                }
            }
        }
        sleep(SAMPLE_INTERVAL);
    }

    gpioPWM(FAN_GPIO, 0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

