#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define I2C_BUS         "/dev/i2c-1"
#define LM75_ADDR       0x48
#define LM75_TEMP_REG   0x00
#define GPIO_CHIP       "gpiochip4"
#define LED_PIN         18
#define BUFFER_SIZE     60
#define TEMP_THRESHOLD  28.0f
#define POLL_INTERVAL   1

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static CircularBuffer temp_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_temperature(int fd, float *temp_out) {
    uint8_t reg = LM75_TEMP_REG;
    uint8_t data[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp_out = (float)raw / 256.0f;
    return 0;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

static void buffer_add(CircularBuffer *cb, float value) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
    pthread_mutex_unlock(&cb->mutex);
}

static float buffer_average(const CircularBuffer *cb) {
    pthread_mutex_lock(&cb->mutex);
    float sum = 0.0f;
    int n = cb->count;
    if (n == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return 0.0f;
    }
    for (int i = 0; i < n; i++) sum += cb->buffer[i];
    pthread_mutex_unlock(&cb->mutex);
    return sum / (float)n;
}

static void *sensor_thread(void *arg) {
    (void)arg;
    while (running) {
        float temp;
        if (read_temperature(i2c_fd, &temp) == 0) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            if (temp > TEMP_THRESHOLD) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Error setting LED on: %s\n", strerror(errno));
                }
            } else {
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Error setting LED off: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Re-initializing I2C.\n");
            if (i2c_fd >= 0) close(i2c_fd);
            i2c_fd = i2c_init();
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                running = 0;
            }
        }
        sleep(POLL_INTERVAL);
    }
    return NULL;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lm75_led", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    buffer_init(&temp_buffer);

    pthread_t sensor_tid;
    if (pthread_create(&sensor_tid, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Error creating sensor thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pthread_join(sensor_tid, NULL);
    cleanup();
    return 0;
}

