static float buffer_average(const CircularBuffer *cb) {
    pthread_mutex_lock(&cb->mutex);
    float sum = 0.0f;
    int n = cb->count;
    if (n == 0) {
        pthread_mutex_unlock(&cb->mutex);
        return 0.0f;
    }
    for (int i = 0; i < n; i++) sum += cb->buffer[i];
    pthread_mutex_unlock(&cb->mutex);
    return sum / (float)n;
}

static void *sensor_thread(void *arg) {
    (void)arg;
    while (running) {
        float temp;
        if (read_temperature(i2c_fd, &temp) == 0) {
            buffer_add(&temp_buffer, temp);
            float avg = buffer_average(&temp_buffer);
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            if (temp > TEMP_THRESHOLD) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Error setting LED on: %s\n", strerror(errno));
                }
            } else {
                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Error setting LED off: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Re-initializing I2C.\n");
            if (i2c_fd >= 0) close(i2c_fd);
            i2c_fd = i2c_init();
            if (i2c_fd < 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                running = 0;
            }
        }
        sleep(POLL_INTERVAL);
    }
    return NULL;
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    pthread_mutex_destroy(&temp_buffer.mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lm75_led", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    buffer_init(&temp_buffer);

    pthread_t sensor_tid;
    if (pthread_create(&sensor_tid, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Error creating sensor thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    pthread_join(sensor_tid, NULL);
    cleanup();
    return 0;
}

