#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B -0.0000005775
#define MAX_TEMP 80.0
#define CONFIG_FILE "config.json"
#define LOG_FILE "heater_log.txt"

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

typedef struct {
    double target_temperature;
    double Kp;
    double Ki;
    double Kd;
} Config;

static Config config = {25.0, 1.0, 0.1, 0.01};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return -1;
    char buf[256];
    while (fgets(buf, sizeof(buf), fp)) {
        if (strstr(buf, "\"target_temperature\"")) {
            if (sscanf(buf, " \"target_temperature\" : %lf", &config.target_temperature) != 1) {
                fprintf(stderr, "Invalid target_temperature\n");
                fclose(fp);
                return -1;
            }
        } else if (strstr(buf, "\"Kp\"")) {
            if (sscanf(buf, " \"Kp\" : %lf", &config.Kp) != 1) {
                fprintf(strderr, "Invalid Kp\n");
                fclose(fp);
                return -1;
            }
        } else if (strstr(buf, "\"Ki\"")) {
            if (sscanf(buf, " \"Ki\" : %lf", &config.Ki) != 1) {
                fprintf(stderr, "Invalid Ki\n");
                fclose(fp);
                return -1;
            }
        } else if (strstr(buf, "\"Kd\"")) {
            if (sscanf(buf, " \"Kd\" : %lf", &config.Kd) != 1) {
                fprintf(stderr, "Invalid Kd\n");
                fclose(fp);
                return -1;
            }
        }
    }
    fclose(fp);
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 1);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int init_max31865(void) {
    char tx[3] = {0x80, 0xC1, 0x00};
    char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "MAX31865 config write failed\n");
        return -1;
    }
    return 0;
}

static int read_rtd(double *temp) {
    char tx[3] = {0x01, 0x00, 0x00};
    char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI read failed\n");
        return -1;
    }
    if (rx[0] & 0x01) {
        fprintf(stderr, "MAX31865 fault bit set\n");
        return -1;
    }
    int code = ((rx[1] & 0x1F) << 8) | rx[2];
    double r_rtd = (code / 32768.0) * R_REF;
    double r = r_rtd;
    double z1 = -R0;
    double z2 = r - R0;
    double z3 = sqrt(z1 * z1 - 4 * B * (1 - A * A) * z2);
    double t = (z3 - z1) / (2 * B);
    if (t < 0) {
        fprintf(stderr, "RTD temperature below 0°C\n");
        return -1;
    }
    *temp = t;
    return 0;
}

static int read_fault(void) {
    char tx[3] = {0x07, 0x00, 0x00};
    char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI fault read failed\n");
        return -1;
    }
    if (rx[1] & 0x01) {
        fprintf(stderr, "MAX31865 open circuit fault\n");
        return 1;
    }
    if (rx[1] & 0x02) {
        fprintf(stderr, "MAX31865 short to GND fault\n");
        return 1;
    }
    if (rx[1] & 0x04) {
        fprintf(stderr, "MAX31865 short to VCC fault\n");
        return 1;
    }
    if (rx[1] & 0x08) {
        fprintf(stderr, "MAX31865 over-voltage fault\n");
        return 1;
    }
    if (rx[1] & 0x10) {
        fprintf(stderr, "MAX31865 under-voltage fault\n");
        return 1;
    }
    return 0;
}

static double calculate_pid(double setpoint, double actual, double Kp, double Ki, double Kd, double *integral, double *prev_error) {
    double error = setpoint - actual;
    *integral += error;
    double derivative = error - *prev_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *prev_error = error;
    if (output < 0) output = 0;
    if (output > 100) output = 100;
    return output;
}

static void log_data(double temp, double pid_output) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    fprintf(fp, "%.2f,%.2f\n", temp, pid_output);
    fclose(fp);
}

static void cleanup(void) {
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioPWM(HEATER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    if (read_config(CONFIG_FILE) != 0) {
        fprintf(stderr, "Using defaults\n");
    }
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }
    if (init_max31865() != 0) {
        cleanup();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    double integral = 0, prev_error = 0;
    while (running) {
        double temp;
        if (read_rtd(&temp) != 0) {
            if (read_fault() != 0) {
                fprintf(stderr, "Fault detected, shutting down\n");
                break;
            }
            gpioPWM(HEATER_GPIO, 0);
            log_data(temp, 0);
            gpioDelay(100000);
            continue;
        }
        double pid_output = calculate_pid(config.target_temperature, temp, config.Kp, config.Ki, config.Kd, &integral, &prev_error);
        gpioPWM(HEATER_GPIO, (int)(pid_output * PWM_RANGE / 100.0));
        log_data(temp, pid_output);
        if (temp > MAX_TEMP) {
            fprintf(stderr, "Over-temperature, shutting down\n");
            break;
        }
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

