#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"
#define TEMP_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0
#define MAX_RETRIES 3

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS0 0x34

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(10000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == len) return 0;
        }
        usleep(10000);
    }
    return -1;
}

static int read_calibration(int fd, int32_t *ac1, int32_t *ac2, int32_t *ac3,
                            uint32_t *ac4, uint32_t *ac5, uint32_t *ac6,
                            int32_t *b1, int32_t *b2, int32_t *mb, int32_t *mc, int32_t *md) {
    uint8_t buf[22];
    if (i2c_read_bytes(fd, 0xAA, buf, 22) < 0) return -1;
    *ac1 = (int32_t)((buf[0] << 8) | buf[1]);
    *ac2 = (int32_t)((buf[2] << 8) | buf[3]);
    *ac3 = (int32_t)((buf[4] << 8) | buf[5]);
    *ac4 = (uint32_t)((buf[6] << 8) | buf[7]);
    *ac5 = (uint32_t)((buf[8] << 8) | buf[9]);
    *ac6 = (uint32_t)((buf[10] << 8) | buf[11]);
    *b1 = (int32_t)((buf[12] << 8) | buf[13]);
    *b2 = (int32_t)((buf[14] << 8) | buf[15]);
    *mb = (int32_t)((buf[16] << 8) | buf[17]);
    *mc = (int32_t)((buf[18] << 8) | buf[19]);
    *md = (int32_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 2) < 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS0) < 0) return -1;
    usleep(5000);
    uint8_t buf[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, buf, 3) < 0) return -1;
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> 8;
    return 0;
}

static int32_t compute_b5(int32_t ut, int32_t ac1, int32_t ac2, int32_t ac3, uint32_t ac4, uint32_t ac5, uint32_t ac6,
                          int32_t b1, int32_t mb, int32_t mc, int32_t md) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    return b5;
}

static float calculate_temperature(int32_t ut, int32_t ac1, int32_t ac2, int32_t ac3, uint32_t ac4, uint32_t ac5, uint32_t ac6,
                                   int32_t b1, int32_t mb, int32_t mc, int32_t md) {
    int32_t b5 = compute_b5(ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, mb, mc, md);
    int32_t t = (b5 + 8) >> 4;
    return (float)t / 10.0f;
}

static float calculate_pressure(int32_t up, int32_t ut, int32_t ac1, int32_t ac2, int32_t ac3, uint32_t ac4, uint32_t ac5, uint32_t ac6,
                                 int32_t b1, int32_t b2, int32_t mb, int32_t mc, int32_t md) {
    int32_t b5 = compute_b5(ut, ac1, ac2, ac3, ac4, ac5, ac6, b1, mb, mc, md);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << 0) + 2) >> 2);
    uint32_t x1_u = ((uint32_t)ac3 * (uint32_t)b6) >> 13;
    uint32_t x2_u = ((uint32_t)b1 * ((uint32_t)b6 * (uint32_t)b6) >> 12) >> 16;
    uint32_t x3_u = ((uint32_t)x1_u + x2_u + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3_u + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
