        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) gpioDelay(100000);
    gpioWrite(FAN_GPIO, 0);
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

