    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) != 0) return;
    if (read_raw_pressure(&up) != 0) return;
    float temperature = calculate_temperature(ut);
    float pressure    = calculate_pressure(up, ut);
    store_reading(temperature, pressure);
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
    if (temperature > TEMP_THRESHOLD) gpioWrite(FAN_GPIO, 1);
    else                              gpioWrite(FAN_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
