#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE_OSS 0x34
#define GPIO_PIN 27
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_MS 200
#define SAMPLE_INTERVAL_S 2

static volatile sig_atomic_t logging_enabled = 0;
static volatile sig_atomic_t running = 1;
static volatile uint32_t last_toggle_tick = 0;
static int i2c_handle = -1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void toggle_logging(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    if (tick - last_toggle_tick < DEBOUNCE_MS * 1000) return;
    last_toggle_tick = tick;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    int v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_AC1)) < 0) return -1;
    c->ac1 = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_AC2)) < 0) return -1;
    c->ac2 = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_AC3)) < 0) return -1;
    c->ac3 = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_AC4)) < 0) return -1;
    c->ac4 = (uint16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_AC5)) < 0) return -1;
    c->ac5 = (uint16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_AC6)) < 0) return -1;
    c->ac6 = (uint16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_B1)) < 0) return -1;
    c->b1 = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_B2)) < 0) return -1;
    c->b2 = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_MB)) < 0) return -1;
    c->mb = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_MC)) < 0) return -1;
    c->mc = (int16_t)v;
    if ((v = i2cReadWordData(handle, BMP180_REG_CAL_MD)) < 0) return -1;
    c->md = (int16_t)v;
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadWordData(handle, BMP180_REG_MSB);
    if (v < 0) return -1;
    *ut = (int16_t)v;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE_OSS) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadWordData(handle, BMP180_REG_MSB);
    if (v < 0) return -1;
    *up = (int32_t)(((uint32_t)v << 8) | (i2cReadByteData(handle, BMP180_REG_LSB) & 0xFF));
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << 0) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> 0);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void log_pressure(int32_t pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Pressure: %d Pa\n", ts, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetAlertFuncEx(GPIO_PIN, toggle_logging, NULL) < 0) {
        fprintf(stderr, "Failed to set alert\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Pressure logger started. Toggle logging with GPIO27.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(i2c_handle, &ut) < 0) {
                fprintf(stderr, "Temp read error\n");
            } else if (read_raw_pressure(i2c_handle, &up) < 0) {
                fprintf(stderr, "Pressure read error\n");
            } else {
                int32_t b5 = compute_b5(ut, &cal);
                int32_t pressure = compute_pressure(up, b5, &cal);
                log_pressure(pressure);
            }
        }
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && running; i++) gpioDelay(100000);
    }

    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Clean exit.\n");
    return 0;
}

