#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define SPI_FLAGS 0
#define LOG_FILE "heater_log.csv"
#define MAX_DUTY_CYCLE 80.0
#define KP 1.0
#define KI 0.1
#define TARGET_TEMP 25.0
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_thermocouple(double *temperature) {
    char tx[4] = {0x00, 0x00, 0x00, 0x00};
    char rx[4] = {0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected (");
        if (raw & 0x00000001) fprintf(stderr, "Open circuit ");
        if (raw & 0x00000002) fprintf(stderr, "Short to GND ");
        if (raw & 0x00000004) fprintf(stderr, "Short to VCC ");
        fprintf(stderr, ")\n");
        return -1;
    }

    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    *temperature = thermocouple_temp * 0.25;
    return 0;
}

static int set_heater_duty(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > MAX_DUTY_CYCLE) duty_cycle = MAX_DUTY_CYCLE;

    int pwm_value = (int)(duty_cycle * 10000.0);
    if (gpioPWM(HEATER_GPIO, pwm_value) != 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d\n", HEATER_GPIO);
        return -1;
    }
    return 0;
}

static double pi_control(double current_temp, double *integral, double *previous_error) {
    double error = TARGET_TEMP - current_temp;
    *integral += error;

    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KP * derivative;

    *previous_error = error;

    if (output < 0.0) output = 0.0;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;

    return output;
}

static void log_data(double temperature, double duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, 1000) != 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, 100000) != 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d\n", HEATER_GPIO);
        gpioTerminate();
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double integral = 0.0;
    double previous_error = 0.0;

    while (running) {
        double temperature;
        if (read_thermocouple(&temperature) != 0) {
            set_heater_duty(0.0);
            log_data(temperature, 0.0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double duty_cycle = pi_control(temperature, &integral, &previous_error);
        if (set_heater_duty(duty_cycle) != 0) {
            fprintf(stderr, "Error setting heater duty cycle\n");
        }

        log_data(temperature, duty_cycle);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    set_heater_duty(0.0);
    cleanup();
    return 0;
}

