#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_RANGE  255
#define PWM_OFF    255   /* common-anode: 255 = off, 0 = on */
#define PWM_FULL   0     /* common-anode: 0 = off, 255 = on */

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_SEC  0.5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read CPU temperature in millidegrees Celsius. Returns 0 on success, -1 on error. */
static int read_cpu_temp(int *temp_out)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s: %s\n",
                TEMP_FILE, ferror(fp) ? strerror(errno) : "unexpected format");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: error closing %s: %s\n",
                TEMP_FILE, strerror(errno));
        /* non-fatal: we already have the value */
    }

    *temp_out = temp;
    return 0;
}

/* Map temperature to RGB values (common-anode: 0 = full on, 255 = off). */
static void temp_to_rgb(int temp, int *r, int *g, int *b)
{
    if (temp < 40000) {
        *r = 0;
        *g = 0;
        *b = PWM_FULL;
    } else if (temp < 60000) {
        *r = 0;
        *g = PWM_FULL;
        *b = 0;
    } else {
        *r = PWM_FULL;
        *g = 0;
        *b = 0;
    }
}

/* Set a single PWM channel; returns 0 on success, -1 on error. */
static int set_pwm(int pin, int duty)
{
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error setting PWM on GPIO %d to %d: %s\n",
                pin, duty, pigpio_error(gpioPWM(pin, duty)));
        return -1;
    }
    return 0;
}

/* Turn off all three channels (common-anode: 255 = off). */
static void all_off(void)
{
    set_pwm(RED_PIN,   PWM_OFF);
    set_pwm(GREEN_PIN, PWM_OFF);
    set_pwm(BLUE_PIN,  PWM_OFF);
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on each pin --- */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n",
                RED_PIN, pigpio_error(gpioSetMode(RED_PIN, PI_OUTPUT)));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n",
                GREEN_PIN, pigpio_error(gpioSetMode(GREEN_PIN, PI_OUTPUT)));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n",
                BLUE_PIN, pigpio_error(gpioSetMode(BLUE_PIN, PI_OUTPUT)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n",
                RED_PIN, pigpio_error(gpioSetPWMrange(RED_PIN, PWM_RANGE)));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n",
                GREEN_PIN, pigpio_error(gpioSetPWMrange(GREEN_PIN, PWM_RANGE)));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n",
                BLUE_PIN, pigpio_error(gpioSetPWMrange(BLUE_PIN, PWM_RANGE)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with all LEDs off */
    all_off();

    /* --- Main loop --- */
    while (g_running) {
        int temp = -1;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Temperature read failed; skipping update.\n");
        } else {
            int r, g, b;
            temp_to_rgb(temp, &r, &g, &b);

            if (set_pwm(RED_PIN,   r) != 0 ||
                set_pwm(GREEN_PIN, g) != 0 ||
                set_pwm(BLUE_PIN,  b) != 0) {
                fprintf(stderr, "PWM update failed; skipping print.\n");
            } else {
                printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
                       temp, r, g, b);
                fflush(stdout);
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            time_sleep(POLL_SEC / 10.0);
        }
    }

    /* --- Clean shutdown --- */
    all_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

