#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define READ_INTERVAL_MS 5000

volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    int data_bits[40] = {0};
    int timeout;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000); // 2ms low
    gpioWrite(gpio, 1);
    gpioDelay(30);   // 30us high

    gpioSetMode(gpio, PI_INPUT);

    // Wait for sensor response (low then high)
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        if (++timeout > 100) return -1; // Timeout
    }
    timeout = 0;
    while (gpioRead(gpio) == 0) {
        gpioDelay(1);
        if (++timeout > 100) return -1;
    }
    timeout = 0;
    while (gpioRead(gpio) == 1) {
        gpioDelay(1);
        if (++timeout > 100) return -1;
    }

    // Read 40 bits
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            if (++timeout > 100) return -1;
        }
        // Wait for 50us low to high transition
        timeout = 0;
        while (gpioRead(gpio) == 1) {
            gpioDelay(1);
            if (++timeout > 100) return -1;
        }
        // Measure high duration to determine bit value
        timeout = 0;
        while (gpioRead(gpio) == 0) {
            gpioDelay(1);
            if (++timeout > 100) return -1;
        }
        data_bits[i] = timeout;
    }

    // Parse data
    int humidity_int = 0;
    int humidity_dec = 0;
    int temp_int = 0;
    int temp_dec = 0;

    for (i = 0; i < 16; i++) {
        if (data_bits[i]) humidity_int |= (1 << (15 - i));
        if (data_bits[i + 16]) temp_int |= (1 << (15 - i));
    }
    for (i = 24; i < 32; i++) {
        if (data_bits[i]) humidity_dec |= (1 << (31 - i));
        if (data_bits[i + 16]) temp_dec |= (1 << (31 - i));
    }

    data->humidity = humidity_int + (float)humidity_dec / 10.0;
    data->temperature = temp_int + (float)temp_dec / 10.0;

    // Checksum validation
    int checksum = (data_bits[0] + data_bits[1] + data_bits[2] + data_bits[3] + data_bits[4] + data_bits[5] + data_bits[6] + data_bits[7]) & 0xFF;
    if ((checksum & 0xFF) != (data_bits[8] & 0xFF)) {
        fprintf(stderr, "Checksum error: calculated 0x%02X, received 0x%02X\n", checksum & 0xFF, data_bits[8] & 0xFF);
        return -2;
    }

    return 0;
}

size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    (void)contents;
    (void)userp;
    return size * nmemb;
}

int post_data(const char *url, float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    long http_code = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (!curl) {
            fprintf(stderr, "curl_easy_init() failed\n");
            curl_global_cleanup();
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        char json_payload[256];
        snprintf(json_payload, sizeof(json_payload), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code != 200) {
            fprintf(stderr, "HTTP request failed with code: %ld\n", http_code);
            curl_easy_cleanup(curl);
            curl_global_cleanup();
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return 0;
    }

    fprintf(stderr, "Failed to post data after %d retries\n", MAX_RETRIES);
    return -1;
}

