#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_START 0xAA
#define BMP180_CAL_LEN 22
#define BMP180_OSS 3
#define BMP180_CONV_DELAY_US 26000
#define BUTTON_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define DEBOUNCE_US 200000

static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;
static int i2c_handle = -1;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    logging_enabled = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 0 && (tick - last_interrupt_tick) > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        last_interrupt_tick = tick;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        fflush(stdout);
    }
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t buf[BMP180_CAL_LEN];
    if (i2cReadI2CBlockData(handle, BMP180_REG_CAL_START, (char *)buf, BMP180_CAL_LEN) != BMP180_CAL_LEN) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        return -1;
    }
    c->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    c->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    c->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    c->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    c->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    c->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    c->b1  = (int16_t)((buf[12] << 8) | buf[13]);
    c->b2  = (int16_t)((buf[14] << 8) | buf[15]);
    c->mb  = (int16_t)((buf[16] << 8) | buf[17]);
    c->mc  = (int16_t)((buf[18] << 8) | buf[19]);
    c->md  = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    uint8_t cmd = 0x2E;
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) return -1;
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 2) != 2) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    uint8_t cmd = 0x34 + (BMP180_OSS << 6);
    if (i2cWriteI2CBlockData(handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) return -1;
    gpioDelay(BMP180_CONV_DELAY_US);
    uint8_t buf[3];
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, (char *)buf, 3) != 3) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5, const bmp180_cal_t *c) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)c->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)c->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)c->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)c->ac3 * b6) >> 13;
    x2 = ((int32_t)c->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)c->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;
    return p;
}

static void log_pressure(int32_t pressure_pa) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f hPa\n", ts, pressure_pa / 100.0);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_calibration(i2c_handle, &cal) != 0) {
        fprintf(stderr, "BMP180 not detected or calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d\n", BUTTON_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Press button on GPIO%d to toggle logging. Ctrl+C to exit.\n", BUTTON_GPIO);

    while (1) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temp(i2c_handle, &ut) != 0) {
                fprintf(stderr, "Failed to read temperature\n");
                gpioDelay(2000000);
                continue;
            }
            if (read_raw_pressure(i2c_handle, &up) != 0) {
                fprintf(stderr, "Failed to read pressure\n");
                gpioDelay(2000000);
                continue;
            }
            int32_t b5 = compute_b5(ut, &cal);
            int32_t pressure_pa = compute_pressure(up, b5, &cal);
            log_pressure(pressure_pa);
        } else {
            printf("Logging disabled. Press button to enable.\n");
        }
        gpioDelay(2000000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

