#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define READ_INTERVAL_SEC 10
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"

static volatile sig_atomic_t terminate = 0;
static char *server_url = NULL;

typedef struct {
    float humidity;
    int status;
} DHT22Data;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
