static int read_dht22(DHT22Data *data) {
    int i, j;
    unsigned char bits[5] = {0, 0, 0, 0, 0};
    uint32_t start_tick, end_tick, timeout;

    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            timeout = gpioTick();
            while (gpioRead(DHT22_GPIO) == 1) {
                if (gpioTick() - timeout > 1000) return -1;
            }
            timeout = gpioTick();
            while (gpioRead(DHT22_GPIO) == 0) {
                if (gpioTick() - timeout > 1000) return -1;
            }
            timeout = gpioTick();
            while (gpioRead(DHT22_GPIO) == 1) {
                if (gpioTick() - timeout > 1000) return -1;
            }
            if (gpioTick() - timeout > 50) {
                bits[i] |= (1 << j);
            }
        }
