#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int read_fan_max_state(void) {
    FILE *fp = fopen(FAN_MAX_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_FILE, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_MAX_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int set_fan_speed(int state) {
    FILE *fp = fopen(FAN_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return 0;
}

static int log_fan_speed(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Fan speed set to state: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, state);
    } else {
        fprintf(fp, "Timestamp error - Fan speed set to state: %d\n", state);
    }
    fclose(fp);
    return 0;
}

static int map_temperature_to_fan_speed(int temp) {
    if (temp < 45000) return 0;
    if (temp < 55000) return 1;
    if (temp < 65000) return 2;
    return 3;
}

