    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    int last_state = -1;
    int retries = 0;
    const int max_retries = 3;

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            retries++;
            if (retries > max_retries) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            sleep(1);
            continue;
        }
        retries = 0;

        int max_state = read_fan_max_state();
        if (max_state < 0) {
            fprintf(stderr, "Failed to read max_state, retrying...\n");
            sleep(1);
            continue;
        }

        int speed = map_temperature_to_fan_speed(temp);
        if (speed > max_state) {
            fprintf(stderr, "Requested speed %d exceeds max_state %d, capping.\n", speed, max_state);
            speed = max_state;
        }

        if (set_fan_speed(speed) != 0) {
            fprintf(stderr, "Failed to set fan speed.\n");
        }

        if (speed != last_state) {
            if (log_fan_speed(speed) != 0) {
                fprintf(stderr, "Failed to log fan speed change.\n");
            }
            last_state = speed;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (running == 0) {
        set_fan_speed(0);
        log_fan_speed(0);
    }

    return 0;
}

