#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (handle %d), retry %d/%d\n", handle, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(20000);

        if (i2cReadDevice(handle, (char *)buf, 3) != 3) {
            fprintf(stderr, "I2C read failed (handle %d), retry %d/%d\n", handle, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(100000);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "CRC mismatch (handle %d), retry %d/%d\n", handle, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(100000);
            continue;
        }

        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        *flow_rate = (float)raw * 0.01f;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate from handle %d after %d retries\n", handle, MAX_RETRIES);
    return -1;
}

static int log_data(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow monitoring. Press Ctrl+C to stop.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(i2c_handle1, &flow1);
        int ok2 = read_flow_rate(i2c_handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            if (log_data(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Sensor read error (s1=%d, s2=%d)\n", ok1, ok2);
        }

        gpioSleep(PI_TIME_RELATIVE, POLL_INTERVAL_SEC, 0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

