#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor_a() {
    return gpioRead(SENSOR_A_PIN);
}

int read_sensor_b() {
    return gpioRead(SENSOR_B_PIN);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    return 0;
}

int log_data(int state, float angular_position) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, State: %d, Angular Position: %.2f\n", timestamp, state, angular_position);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    int current_state = 0;
    int previous_state = 0;
    float angular_position = 0.0;

    while (program_running) {
        int a = read_sensor_a();
        int b = read_sensor_b();

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error reading GPIO pins\n");
            break;
        }

        int new_state = (a << 1) | b;

        if (new_state != current_state) {
            int increment = 0;

            switch (new_state) {
                case 0b00: increment = 0; break;
                case 0b01: increment = 1; break;
                case 0b11: increment = -1; break;
                case 0b10: increment = 0; break;
            }

            current_state = new_state;
            angular_position += (float)increment / PULSES_PER_REVOLUTION * 360.0;

            if (angular_position < 0.0) angular_position += 360.0;
            if (angular_position >= 360.0) angular_position -= 360.0;

            if (log_data(new_state, angular_position) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    return 0;
}

