/*
 * ADPD144RI IR/Red Photometric Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Uses libgpiod for GPIO 17 (LED) and the Linux I2C character-device interface
 * (i2c-dev.h).  Reads 16-bit red and IR channel data from the FIFO data
 * register (0x60) on the ADPD144RI at I2C address 0x39 on bus 1.
 *
 * Build:  gcc -O2 -Wall -Wextra -o adpd144ri_reader adpd144ri_reader.c -lgpiod
 *
 * Wiring:
 *   ADPD144RI SDA  -> GPIO 2 (I2C1 SDA, pin 3)
 *   ADPD144RI SCL  -> GPIO 3 (I2C1 SCL, pin 5)
 *   ADPD144RI VDD -> 3.3 V
 *   ADPD144RI GND -> GND
 *   LED anode     -> GPIO 17 (pin 11) via 330 ohm resistor
 *   LED cathode   -> GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS          "/dev/i2c-1"
#define ADPD144RI_ADDR   0x39
#define FIFO_DATA_REG    0x60
#define RED_CHANNEL      0x00
#define IR_CHANNEL       0x01
#define LED_GPIO_LINE    17
#define IR_THRESHOLD     2000
#define SAMPLE_PERIOD_MS 100
#define LOG_FILE         "adpd144ri_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit little-endian register pair from the ADPD144RI.
 * Returns 0 on success, -1 on error.
 */
static int read_adpd144ri_channel(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            red, ir);
    fflush(fp);
}

int main(void)
{
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus and set slave address --- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request LED line --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri_reader", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    printf("ADPD144RI reader started.  I2C addr=0x%02X  LED=GPIO%d  Threshold=%d\n",
           ADPD144RI_ADDR, LED_GPIO_LINE, IR_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (read_adpd144ri_channel(i2c_fd, RED_CHANNEL, &red) != 0) {
            fprintf(stderr, "Red channel read failed; continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        if (read_adpd144ri_channel(i2c_fd, IR_CHANNEL, &ir) != 0) {
            fprintf(stderr, "IR channel read failed; continuing.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        log_data(log_fp, red, ir);

        int led_state = (ir > IR_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Warning: failed to set LED: %s\n",
                    strerror(errno));
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (i2c_fd >= 0)
        close(i2c_fd);
    if (log_fp)
        fclose(log_fp);

    return ret;
}

