#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define EXPECTED_PART_ID 0x44
#define RED_DATA_REG 0x02
#define IR_DATA_REG 0x04
#define LED_GPIO_LINE 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int verify_sensor(void) {
    uint8_t part_id;
    if (i2c_read_reg8(i2c_fd, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }
    printf("ADPD144RI detected (PART_ID=0x%02X)\n", part_id);
    return 0;
}

static int read_sensor_data(uint16_t *red, uint16_t *ir) {
    if (i2c_read_reg16(i2c_fd, RED_DATA_REG, red) < 0) {
        fprintf(stderr, "Error: Failed to read RED data\n");
        return -1;
    }
    if (i2c_read_reg16(i2c_fd, IR_DATA_REG, ir) < 0) {
        fprintf(stderr, "Error: Failed to read IR data\n");
        return -1;
    }
    return 0;
}

static void control_led(int on) {
    if (led_line) gpiod_line_set_value(led_line, on ? 1 : 0);
}

static void log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fflush(log_file);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_i2c() < 0) return 1;
    if (verify_sensor() < 0) { cleanup(); return 1; }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("Failed to get GPIO line 17");
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "adpd144ri_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        cleanup();
        return 1;
    }

    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("Starting ADPD144RI data acquisition...\n");
    while (running) {
        uint16_t red, ir;
        if (read_sensor_data(&red, &ir) == 0) {
            control_led(ir > IR_THRESHOLD);
            log_data(red, ir);
        } else {
            control_led(0);
        }
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

