#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000
#define FLOW_SCALE_FACTOR 1000.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int initialize_sensor(void) {
    /* Start continuous measurement command for SLF3S-4000B */
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send start measurement command to sensor.\n");
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle time */
    return 0;
}

static int read_flow_rate(float *flow_rate) {
    uint8_t buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error: I2C read failed (got %d bytes, expected 3).\n", bytes_read);
        return -1;
    }

    /* Validate CRC-8 */
    if (sensirion_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Error: CRC mismatch on flow data.\n");
        return -1;
    }

    int16_t raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    *flow_rate = (float)raw_flow / FLOW_SCALE_FACTOR;
    return 0;
}

static int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d.\n",
                SLF3S_ADDR, I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'.\n", FLOW_LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler.\n");
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float flow_rate;
        if (read_flow_rate(&flow_rate) == 0) {
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error: Failed to log flow rate.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read flow rate.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

