#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define STATE_REG 0x00
#define STATE_LEN 7
#define LOG_FILE "air_quality_log.csv"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint8_t *buf) {
    int rc = i2cReadI2CBlockData(handle, STATE_REG, (char *)buf, STATE_LEN);
    if (rc != STATE_LEN) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }
    return 0;
}

static int parse_tvoc(const uint8_t *buf) {
    return (buf[1] << 8) | buf[0];
}

static int parse_eco2(const uint8_t *buf) {
    return (buf[5] << 8) | buf[4];
}

static float calculate_iaq(int tvoc, int eco2) {
    float iaq = 100.0f - (float)tvoc / 10.0f - ((float)eco2 - 400.0f) / 50.0f;
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;
    return iaq;
}

static int log_data(FILE *fp, float iaq, int tvoc, int eco2) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%d,%d\n", ts, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen log");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "# timestamp,IAQ,TVOC,eCO2\n");
    fflush(log_file);

    uint8_t buf[STATE_LEN];
    while (running) {
        if (read_sensor_data(i2c_handle, buf) == 0) {
            int tvoc = parse_tvoc(buf);
            int eco2 = parse_eco2(buf);
            float iaq = calculate_iaq(tvoc, eco2);
            if (log_data(log_file, iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

