#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define TAMPER_THRESHOLD_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec poll_ts = {0, POLL_INTERVAL_MS * 1000000L};
    struct timespec start_time;
    int ret;
    int last_value = -1;
    int alert_fired = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B on %s line %d (active-high). Press Ctrl+C to exit.\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (value != last_value) {
            if (value == 1) {
                clock_gettime(CLOCK_MONOTONIC, &start_time);
                alert_fired = 0;
            } else {
                alert_fired = 1;
            }
            last_value = value;
        }

        if (value == 1 && !alert_fired) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - start_time.tv_sec) +
                             (now.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed >= TAMPER_THRESHOLD_SEC) {
                print_timestamp();
                printf("Intrusion detected! Sensor touched for %.1f seconds.\n", elapsed);
                fflush(stdout);
                alert_fired = 1;
            }
        }

        nanosleep(&poll_ts, NULL);
    }

    printf("\nExiting gracefully...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

