        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "ttp223_tamper");
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring TTP223B on %s line %d (active-high). Press Ctrl+C to exit.\n",
           GPIO_CHIP_NAME, GPIO_LINE_OFFSET);

    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        if (value != last_value) {
            if (value == 1) {
                clock_gettime(CLOCK_MONOTONIC, &start_time);
                alert_fired = 0;
            } else {
                alert_fired = 1;
            }
            last_value = value;
        }

        if (value == 1 && !alert_fired) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed = (now.tv_sec - start_time.tv_sec) +
                             (now.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed >= TAMPER_THRESHOLD_SEC) {
                print_timestamp();
                printf("Intrusion detected! Sensor touched for %.1f seconds.\n", elapsed);
                fflush(stdout);
                alert_fired = 1;
            }
        }

        nanosleep(&poll_ts, NULL);
    }

    printf("\nExiting gracefully...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

