#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_OFFSET 17
#define PCM_DEVICE "/dev/snd/pcmC0D0c"
#define SAMPLE_RATE 48000
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 16
#define FRAME_SIZE 4
#define BUFFER_SIZE 4096

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2s(int *fd) {
    int fd_pcm = open(PCM_DEVICE, O_RDWR);
    if (fd_pcm < 0) {
        fprintf(stderr, "Error opening %s: %s\n", PCM_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S32_LE;
    if (ioctl(fd_pcm, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd_pcm);
        return -1;
    }

    int channels = NUM_CHANNELS;
    if (ioctl(fd_pcm, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", strerror(errno));
        close(fd_pcm);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd_pcm, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", strerror(errno));
        close(fd_pcm);
        return -1;
    }

    *fd = fd_pcm;
    return 0;
}

static int init_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_LINE_OFFSET);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line, "inmp441_select", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

static int select_channel(struct gpiod_line *line, int left) {
    int val = left ? 0 : 1;
    if (gpiod_line_set_value(line, val) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_i2s_data(int fd, int16_t *buffer, int buffer_size) {
    int bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from I2S device: %s\n", strerror(errno));
        return -1;
    }
    if (bytes_read == 0) {
        fprintf(stderr, "I2S device closed unexpectedly.\n");
        return -1;
    }
    return bytes_read;
}

static int write_pcm_data(FILE *fp, int16_t *buffer, int buffer_size) {
    size_t elements_written = fwrite(buffer, sizeof(int16_t), buffer_size, fp);
    if (elements_written != (size_t)buffer_size) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int pcm_fd = -1;
    FILE *pcm_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int16_t *audio_buffer = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    audio_buffer = (int16_t *)malloc(BUFFER_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2s(&pcm_fd) < 0) {
        goto cleanup;
    }

    if (init_gpio(&chip, &line) < 0) {
        goto cleanup;
    }

    pcm_file = fopen("audio_capture.pcm", "wb");
    if (!pcm_file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting audio capture. Press Ctrl+C to stop.\n");

    while (running) {
        if (select_channel(line, 1) < 0) {
            goto cleanup;
        }

        int bytes_read = read_i2s_data(pcm_fd, audio_buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            goto cleanup;
        }

        int samples_to_process = bytes_read / FRAME_SIZE;
        for (int i = 0; i < samples_to_process; i++) {
            int32_t sample = ((int32_t *)audio_buffer)[i];
            int32_t shifted = sample >> 8;
            if (shifted > 32767) shifted = 32767;
            if (shifted < -32768) shifted = -32768;
            audio_buffer[i] = (int16_t)shifted;
        }

        if (write_pcm_data(pcm_file, audio_buffer, samples_to_process) < 0) {
            goto cleanup;
        }
    }

    printf("\nCapture stopped.\n");
    ret = 0;

cleanup:
    if (pcm_file) fclose(pcm_file);
    if (pcm_fd >= 0) close(pcm_fd);
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (audio_buffer) free(audio_buffer);
    return ret;
}

