#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define POLL_INTERVAL_US 50000
#define DEBOUNCE_DELAY_US 50000
#define FLAME_TIMEOUT_S 10
#define LOG_FILE "flame_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int read_flame_sensor(void) {
    int val = gpioRead(FLAME_SENSOR_PIN);
    if (val < 0) {
        log_event("Error: gpioRead failed on flame sensor pin");
        return -1;
    }
    return val;
}

static void control_fan(int flame_detected, int duration_ms) {
    if (flame_detected) {
        int duty = 0;
        if (duration_ms < 500) {
            duty = 0;
        } else if (duration_ms < 1000) {
            duty = 20;
        } else if (duration_ms < 2000) {
            duty = 40;
        } else if (duration_ms < 4000) {
            duty = 60;
        } else {
            duty = 80;
        }
        if (gpioPWM(FAN_PIN, duty) < 0) {
            log_event("Error: gpioPWM failed to set duty cycle");
        }
    } else {
        if (gpioPWM(FAN_PIN, 0) < 0) {
            log_event("Error: gpioPWM failed to stop fan");
        }
    }
}

static void cleanup(void) {
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
    if (log_file) {
        log_event("System shutdown");
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        log_event("Error: gpioSetMode failed for flame sensor pin");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        log_event("Error: gpioSetMode failed for fan pin");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        log_event("Error: gpioSetPWMfrequency failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_PIN, 0) < 0) {
        log_event("Error: gpioPWM failed to initialize fan to 0");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    int flame_active = 0;
    time_t flame_start_time = 0;
    time_t last_poll_time = time(NULL);

    while (running) {
        int sensor_val = read_flame_sensor();
        if (sensor_val < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (sensor_val == 0) {
            if (!flame_active) {
                flame_active = 1;
                flame_start_time = time(NULL);
                log_event("Flame detected");
            }
        } else {
            if (flame_active) {
                flame_active = 0;
                time_t end_time = time(NULL);
                double duration = difftime(end_time, flame_start_time);
                char msg[128];
                snprintf(msg, sizeof(msg), "Flame ended, duration: %.2f seconds", duration);
                log_event(msg);
            }
        }

        if (flame_active) {
            time_t current_time = time(NULL);
            if (difftime(current_time, flame_start_time) > FLAME_TIMEOUT_S) {
                flame_active = 0;
                log_event("Flame timeout - sensor absent or fault");
            }
        }

        control_fan(flame_active, (int)difftime(time(NULL), flame_start_time) * 1000);

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

