#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define FRAME_SIZE 32768
#define LOG_FILE "radar_data.bin"

#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} __attribute__((packed)) config_t;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting data-ready pin mode\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error writing trigger pin\n");
        return -1;
    }
    return 0;
}

static int write_config(FILE *fp, uint32_t start_freq, uint32_t end_freq, uint32_t num_chirps, uint32_t num_samples, uint32_t frame_period_ms) {
    config_t cfg;
    cfg.magic = MAGIC_NUMBER;
    cfg.timestamp = (uint64_t)time(NULL);
    cfg.start_frequency = start_freq;
    cfg.end_frequency = end_freq;
    cfg.num_chirps = num_chirps;
    cfg.num_samples = num_samples;
    cfg.frame_period_ms = frame_period_ms;

    if (fwrite(&cfg, sizeof(config_t), 1, fp) != 1) {
        fprintf(stderr, "Error writing config header\n");
        return -1;
    }
    return 0;
}

static int read_frame(uint8_t *data, int len) {
