        return -1;
    }
    if (fwrite(&frame_num, sizeof(uint32_t), 1, fp) != 1) {
        fprintf(stderr, "Error writing frame number\n");
        return -1;
    }
    if (fwrite(data, 1, FRAME_SIZE, fp) != FRAME_SIZE) {
        fprintf(stderr, "Error writing frame data\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

