    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t frame_num = 0;
    uint8_t *frame_data = malloc(FRAME_SIZE);
    if (!frame_data) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (running) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(1000);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t timeout = 0;
        while (gpioRead(DATA_READY_PIN) == 0 && running) {
            gpioDelay(1000);
            timeout++;
            if (timeout > 100) {
                fprintf(stderr, "Timeout waiting for data ready\n");
                break;
            }
        }
        if (!running) break;

        if (read_frame(frame_data, FRAME_SIZE) != 0) {
            fprintf(stderr, "Frame read failed\n");
            continue;
        }

        if (log_frame(log_file, frame_data, frame_num) != 0) {
            fprintf(stderr, "Frame logging failed\n");
        }

        frame_num++;
    }

    free(frame_data);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Radar data acquisition stopped.\n");
    return 0;
}

