/*
 * Raspberry Pi 3 Model B+ - SainSmart IR Flame Detection Sensor Module
 *
 * Wiring:
 *   VCC -> 3.3V (Pin 1)
 *   GND -> GND  (Pin 9)
 *   DOUT-> GPIO17 (Pin 11)
 *
 * Digital output is active-low: 0 = flame detected, 1 = no flame.
 *
 * Build: gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[%s] ", buf);
            return;
        }
    }
    printf("[unknown time] ");
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure the line as input with bias pulled up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error: failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup_settings;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, GPIO_LINE_OFFSET, 1,
                                               settings);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to add line settings for GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_line_cfg;
    }

    /* Request the line */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup_line_cfg;
    }

    gpiod_request_config_set_consumer(req_cfg, "flame-detect");

    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        fprintf(stderr, "Error: failed to request GPIO %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_req_cfg;
    }

    printf("Flame detection started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* Main polling loop */
    while (g_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            break;
        }

        print_timestamp();
        if (value == 0) {
            printf("Flame Detected: YES\n");
        } else {
            printf("Flame Detected: NO\n");
        }
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_SEC seconds, checking g_running every second */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    /* Cleanup */
    gpiod_line_request_release(line_req);
    gpiod_request_config_free(req_cfg);
    gpiod_line_config_free(line_cfg);
    gpiod_line_settings_free(settings);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;

cleanup_req_cfg:
    gpiod_request_config_free(req_cfg);
cleanup_line_cfg:
    gpiod_line_config_free(line_cfg);
cleanup_settings:
    gpiod_line_settings_free(settings);
cleanup_chip:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

