#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN  27
#define POLL_DELAY_US     50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Warning: gpioRead error (L=%d C=%d R=%d).\n",
                    left, center, right);
        } else {
            printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
            fflush(stdout);
        }

        usleep(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

