        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", channel_pins[i]);
            gpioTerminate();
            return -1;
