#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {2, 3, 4, 17, 27, 22, 10, 9};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        perror("gpiod_line_settings_new");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_DISABLED);

    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        perror("gpiod_line_config_new");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(line_cfg, &gpio_pins[i], 1, settings) != 0) {
            fprintf(stderr, "Failed to add line settings for GPIO %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    request = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!request) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    printf("Timestamp,Channel1,Channel2,Channel3,Channel4,Channel5,Channel6,Channel7,Channel8\n");
    fflush(stdout);

    while (program_running) {
        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_request_get_value(request, gpio_pins[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n",
                        gpio_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
            values[i] = val;
        }

        if (read_ok) {
            printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
                   timestamp,
                   values[0], values[1], values[2], values[3],
                   values[4], values[5], values[6], values[7]);
            fflush(stdout);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (request)
        gpiod_line_request_release(request);
    if (line_cfg)
        gpiod_line_config_free(line_cfg);
    if (settings)
        gpiod_line_settings_free(settings);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

