        if (first_read) {
            last_state = current_state;
            first_read = 0;
        } else if (current_state != last_state) {
            log_tilt_state(current_state == 0);
            last_state = current_state;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

