#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_CHLIST 0x01
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UVINDEX 0x2C
#define SI1145_REG_COMMAND 0x18
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    uint8_t part_id;
    if (read_register(handle, SI1145_REG_PARTID, &part_id) != 0) {
        fprintf(stderr, "Sensor not responding on I2C bus.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (write_register(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) != 0) return -1;
    if (write_register(handle, SI1145_REG_CHLIST, 0x01) != 0) return -1;
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) != 0) return -1;
    return 0;
}

static int read_uv_index(int handle, uint8_t *uv_index) {
    return read_register(handle, SI1145_REG_UVINDEX, uv_index);
}

static int read_als_visible(int handle, uint16_t *als_visible) {
    uint8_t data[2];
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0, &data[0]) != 0) return -1;
    if (read_register(handle, SI1145_REG_ALS_VIS_DATA0 + 1, &data[1]) != 0) return -1;
    *als_visible = ((uint16_t)data[1] << 8) | data[0];
    return 0;
}

static void log_data(FILE *fp, uint8_t uv_index, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, uv_index, als_visible);
    fflush(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        uint8_t uv_index;
        uint16_t als_visible;

        if (read_uv_index(i2c_handle, &uv_index) == 0 && read_als_visible(i2c_handle, &als_visible) == 0) {
            printf("UV Index: %u, ALS Visible: %u\n", uv_index, als_visible);
            log_data(log_file, uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(1000000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

