#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define ALARM_GPIO     17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define MEAS_DELAY_MS  100
#define LOOP_DELAY_MS  1000

#define REG_MEAS       0x00
#define REG_CMD        0x08
#define CMD_START      0x3608
#define CRC_POLY       0x31
#define CRC_INIT       0xFF

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;
static int i2c_fd1 = -1, i2c_fd2 = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *alarm_line = NULL;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80) crc = (crc << 1) ^ CRC_POLY;
            else           crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_flow_rate(int fd, float *flow_out) {
    if (i2c_write_cmd(fd, CMD_START) < 0) {
        fprintf(stderr, "Error: failed to send start command: %s\n", strerror(errno));
        return -1;
    }
    usleep(MEAS_DELAY_MS * 1000);

    uint8_t buf[9];
    if (i2c_read_bytes(fd, buf, 9) < 0) {
        fprintf(stderr, "Error: failed to read 9 bytes: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Error: flow CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Error: temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Error: scale factor CRC mismatch\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw * 0.036f;
    return 0;
}

static void log_flow_rate(float f1, float f2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s, Sensor1: %.2f, Sensor2: %.2f, Average: %.2f\n", ts, f1, f2, avg);
    fflush(log_fp);
}

static void set_alarm(float avg) {
    int val = (avg < FLOW_THRESHOLD) ? 1 : 0;
    if (gpiod_line_set_value(alarm_line, val) < 0) {
        fprintf(stderr, "Warning: failed to set alarm GPIO: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, 0);
        gpiod_line_release(alarm_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd1 >= 0) close(i2c_fd1);
    if (i2c_fd2 >= 0) close(i2c_fd2);
    if (log_fp) fclose(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    i2c_fd1 = open(I2C_BUS, O_RDWR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(log_fp);
        return 1;
    }
    if (ioctl(i2c_fd1, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", SENSOR1_ADDR, strerror(errno));
        close(i2c_fd1); fclose(log_fp); return 1;
    }

    i2c_fd2 = open(I2C_BUS, O_RDWR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", I2C_BUS, strerror(errno));
        close(i2c_fd1); fclose(log_fp); return 1;
    }
    if (ioctl(i2c_fd2, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Error: cannot set I2C slave 0x%02X: %s\n", SENSOR2_ADDR, strerror(errno));
        close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: cannot open gpiochip4: %s\n", strerror(errno));
        close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }
    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip); close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_monitor", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO output: %s\n", strerror(errno));
        gpiod_line_release(alarm_line); gpiod_chip_close(chip);
        close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(i2c_fd1, &f1) == 0);
        int ok2 = (read_flow_rate(i2c_fd2, &f2) == 0);

        if (ok1 && ok2) {
            float avg = (f1 + f2) / 2.0f;
            log_flow_rate(f1, f2, avg);
            set_alarm(avg);
        } else {
            fprintf(stderr, "Warning: sensor read failure, skipping cycle\n");
        }

        for (int i = 0; i < LOOP_DELAY_MS / 10 && running; i++) {
            usleep(10000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

