        fprintf(stderr, "Error: cannot open gpiochip4: %s\n", strerror(errno));
        close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }
    alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Error: cannot get GPIO line %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip); close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_monitor", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO output: %s\n", strerror(errno));
        gpiod_line_release(alarm_line); gpiod_chip_close(chip);
        close(i2c_fd1); close(i2c_fd2); fclose(log_fp); return 1;
    }

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = (read_flow_rate(i2c_fd1, &f1) == 0);
        int ok2 = (read_flow_rate(i2c_fd2, &f2) == 0);

        if (ok1 && ok2) {
            float avg = (f1 + f2) / 2.0f;
            log_flow_rate(f1, f2, avg);
            set_alarm(avg);
        } else {
            fprintf(stderr, "Warning: sensor read failure, skipping cycle\n");
        }

        for (int i = 0; i < LOOP_DELAY_MS / 10 && running; i++) {
            usleep(10000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

