#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4
#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

static SensorData buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(time_t ts, int val) {
    buffer[buffer_index].timestamp = ts;
    buffer[buffer_index].reading = val;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Sensor Data Buffer (%d entries) ---\n", buffer_count);
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("[%s] Reading: %d\n", time_str, buffer[idx].reading);
    }
    printf("--- End of Buffer ---\n\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Obstacle avoidance sensor monitoring started on GPIO %d.\n", SENSOR_PIN);
    printf("Press Ctrl+C to exit and view the buffer contents.\n");

    while (running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d\n", SENSOR_PIN);
            break;
        }

        if (reading == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
                break;
            }
            add_to_buffer(now, reading);
            printf("Obstacle detected! Reading: %d\n", reading);
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_buffer();
    gpioTerminate();
    return EXIT_SUCCESS;
}

