/*
 * fan_health.c — Raspberry Pi 5 (64-bit Bookworm)
 *
 * Reads vibration data from an Omron D7S (I2C 7-bit address 0x55)
 * over /dev/i2c-1 and logs timestamped X/Y/Z acceleration (g) to
 * fan_health.csv every 500 ms.  Includes a sensor-activation
 * timeout so the program exits if the sensor fails to respond.
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 * Run:    ./fan_health
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

/* ---- Omron D7S constants (per datasheet) ---- */
#define D7S_I2C_ADDR        0x55
#define D7S_REG_MODE_CTRL   0x1D
#define D7S_REG_OP_STATUS   0x1B
#define D7S_REG_X_LSB       0x2A
#define D7S_REG_X_MSB       0x2B
#define D7S_REG_Y_LSB       0x2C
#define D7S_REG_Y_MSB       0x2D
#define D7S_REG_Z_LSB       0x2E
#define D7S_REG_Z_MSB       0x2F

#define D7S_MODE_ACTIVE     0x10
#define D7S_OP_STATUS_ACTIVE 0x01

#define I2C_BUS            "/dev/i2c-1"
#define CSV_FILENAME       "fan_health.csv"
#define SAMPLE_PERIOD_MS   500
#define ACTIVATION_TIMEOUT_MS 1000

/* Scaling: 0.0009765625 g/LSB  (1/1048576 g) */
#define SCALE_FACTOR       0.0009765625f

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a D7S register.                                   */
/* ------------------------------------------------------------------ */
static int d7s_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "write(reg=0x%02X, val=0x%02X) failed: %s (wrote %zd)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a D7S register.                                  */
/* ------------------------------------------------------------------ */
static int d7s_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg=0x%02X) for read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "read(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian signed value from two consecutive regs. */
/* ------------------------------------------------------------------ */
static int d7s_read_axis(int fd, uint8_t lsb_reg, int16_t *out)
{
    uint8_t lsb, msb;
    if (d7s_read_reg(fd, lsb_reg, &lsb) != 0)
        return -1;
    if (d7s_read_reg(fd, lsb_reg + 1, &msb) != 0)
        return -1;
    *out = (int16_t)((uint16_t)lsb | ((uint16_t)msb << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate the D7S in active-measurement mode.                        */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int d7s_activate(int fd)
{
    if (d7s_write_reg(fd, D7S_REG_MODE_CTRL, D7S_MODE_ACTIVE) != 0)
        return -1;

    /* Poll operating-status bit 0 until the sensor is ready. */
    for (int waited = 0; waited < ACTIVATION_TIMEOUT_MS; waited += 50) {
        uint8_t status;
        if (d7s_read_reg(fd, D7S_REG_OP_STATUS, &status) != 0)
            return -1;
        if (status & D7S_OP_STATUS_ACTIVE)
            return 0;
        usleep(50 * 1000);
    }

    fprintf(stderr, "D7S did not become active within %d ms\n",
            ACTIVATION_TIMEOUT_MS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row with an ISO-8601 timestamp.                      */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Activate sensor ---- */
    if (d7s_activate(g_i2c_fd) != 0) {
        fprintf(stderr, "D7S activation failed — check wiring/address.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open CSV (append; write header if empty) ---- */
    g_csv = fopen(CSV_FILENAME, "a+");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Determine whether file is empty so we can write a header. */
    long pos = ftell(g_csv);
    if (pos == 0) {
        if (fprintf(g_csv, "timestamp,x_g,y_g,z_g\n") < 0) {
            fprintf(stderr, "fprintf(header) failed: %s\n", strerror(errno));
            fclose(g_csv);
            g_csv = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
        fflush(g_csv);
    }

    printf("D7S vibration monitoring started.  Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (d7s_read_axis(g_i2c_fd, D7S_REG_X_LSB, &raw_x) != 0 ||
            d7s_read_axis(g_i2c_fd, D7S_REG_Y_LSB, &raw_y) != 0 ||
            d7s_read_axis(g_i2c_fd, D7S_REG_Z_LSB, &raw_z) != 0) {
            fprintf(stderr, "I2C read error — retrying next cycle.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float x = (float)raw_x * SCALE_FACTOR;
        float y = (float)raw_y * SCALE_FACTOR;
        float z = (float)raw_z * SCALE_FACTOR;

        if (log_data(g_csv, x, y, z) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

