    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Activate sensor ---- */
    if (d7s_activate(g_i2c_fd) != 0) {
        fprintf(stderr, "D7S activation failed — check wiring/address.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open CSV (append; write header if empty) ---- */
    g_csv = fopen(CSV_FILENAME, "a+");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Determine whether file is empty so we can write a header. */
    long pos = ftell(g_csv);
    if (pos == 0) {
        if (fprintf(g_csv, "timestamp,x_g,y_g,z_g\n") < 0) {
            fprintf(stderr, "fprintf(header) failed: %s\n", strerror(errno));
            fclose(g_csv);
            g_csv = NULL;
            close(g_i2c_fd);
            g_i2c_fd = -1;
            return EXIT_FAILURE;
        }
        fflush(g_csv);
    }

    printf("D7S vibration monitoring started.  Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (d7s_read_axis(g_i2c_fd, D7S_REG_X_LSB, &raw_x) != 0 ||
            d7s_read_axis(g_i2c_fd, D7S_REG_Y_LSB, &raw_y) != 0 ||
            d7s_read_axis(g_i2c_fd, D7S_REG_Z_LSB, &raw_z) != 0) {
            fprintf(stderr, "I2C read error — retrying next cycle.\n");
            usleep(SAMPLE_PERIOD_MS * 1000);
            continue;
        }

        float x = (float)raw_x * SCALE_FACTOR;
        float y = (float)raw_y * SCALE_FACTOR;
        float z = (float)raw_z * SCALE_FACTOR;

        if (log_data(g_csv, x, y, z) != 0) {
            fprintf(stderr, "Logging failed — continuing.\n");
        }

        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

