#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_sensor(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(val));
        return -1;
    }
    return val;
}

static int is_stall_confirmed(int s1, int s2) {
    return (s1 == 0 && s2 == 0);
}

static void log_stall_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time() failed");
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Stall confirmed\n", timestamp) < 0) {
        perror("Error writing to log file");
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    int stall_active = 0;
    time_t stall_start_time = 0;

    while (program_running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (is_stall_confirmed(s1, s2)) {
            if (!stall_active) {
                stall_active = 1;
                stall_start_time = time(NULL);
            } else {
                if (difftime(time(NULL), stall_start_time) >= STALL_DURATION_SEC) {
                    log_stall_event();
                    stall_active = 0;
                }
            }
        } else {
            stall_active = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

