#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TMAG5170-Q1 I2C address (A0=A1=0) */
#define TMAG5170_ADDR 0x0E

/* TMAG5170 register addresses */
#define TMAG5170_REG_DEVICE_ID   0x00
#define TMAG5170_REG_CONFIG      0x01
#define TMAG5170_REG_X_MSB       0x02
#define TMAG5170_REG_X_LSB       0x03
#define TMAG5170_REG_Y_MSB       0x04
#define TMAG5170_REG_Y_LSB       0x05
#define TMAG5170_REG_Z_MSB       0x06
#define TMAG5170_REG_Z_LSB       0x07

/* Expected device ID for TMAG5170-Q1 */
#define TMAG5170_DEVICE_ID       0x8D

/*
 * Configuration register value:
 *   [15:14] = 0x0 (continuous conversion mode)
 *   [13:12] = 0x0 (50 mT range)
 *   [11:10] = 0x0 (no averaging)
 *   [9:8]   = 0x0 (no averaging)
 *   [7:6]   = 0x0 (no averaging)
 *   [5:4]   = 0x0 (no averaging)
 *   [3:2]   = 0x0 (no averaging)
 *   [1:0]   = 0x3 (X, Y, Z axes enabled)
 * => 0x0003
 */
#define TMAG5170_CONFIG_VALUE    0x0003

/* LSB scale factor for 50 mT range: 1 LSB = 0.05 mT */
#define TMAG5170_LSB_50MT        0.05f

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US       100000

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a single byte register                                         */
/* ------------------------------------------------------------------ */
static int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte register                                        */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian two's-complement value                     */
/* ------------------------------------------------------------------ */
static int read_axis_raw(int handle, uint8_t msb_reg, uint8_t lsb_reg,
                         int16_t *out)
{
    uint8_t msb, lsb;
    if (read_register(handle, msb_reg, &msb) != 0)
        return -1;
    if (read_register(handle, lsb_reg, &lsb) != 0)
        return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all three axes and convert to mT                               */
/* ------------------------------------------------------------------ */
static int read_magnetic_data(int handle, float *x_mt, float *y_mt,
                              float *z_mt)
{
    int16_t raw_x, raw_y, raw_z;

    if (read_axis_raw(handle, TMAG5170_REG_X_MSB, TMAG5170_REG_X_LSB,
                      &raw_x) != 0)
        return -1;
    if (read_axis_raw(handle, TMAG5170_REG_Y_MSB, TMAG5170_REG_Y_LSB,
                      &raw_y) != 0)
        return -1;
    if (read_axis_raw(handle, TMAG5170_REG_Z_MSB, TMAG5170_REG_Z_LSB,
                      &raw_z) != 0)
        return -1;

    *x_mt = (float)raw_x * TMAG5170_LSB_50MT;
    *y_mt = (float)raw_y * TMAG5170_LSB_50MT;
    *z_mt = (float)raw_z * TMAG5170_LSB_50MT;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to CSV                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x_mt, float y_mt, float z_mt)
{
    time_t t = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n",
                timestamp, x_mt, y_mt, z_mt) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the TMAG5170 address */
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device ID */
    uint8_t device_id = 0;
    if (read_register(i2c_handle, TMAG5170_REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Cannot read device ID - sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                device_id, TMAG5170_DEVICE_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure sensor: continuous conversion, X/Y/Z axes enabled */
    if (write_register(i2c_handle, TMAG5170_REG_CONFIG,
                       TMAG5170_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to configure TMAG5170\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode; write header if empty */
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.csv\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (fseek(log_file, 0, SEEK_END) == 0) {
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,x_mt,y_mt,z_mt\n");
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "fseek failed; continuing without header\n");
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x_mt, y_mt, z_mt;

        if (read_magnetic_data(i2c_handle, &x_mt, &y_mt, &z_mt) == 0) {
            if (log_data(log_file, x_mt, y_mt, z_mt) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Sensor read error; continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

