#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <stdatomic.h>
#include <string.h>
#include <errno.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */
#define PULSES_PER_REV 1       /* one pulse per revolution */

static atomic_int pulse_count = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

/*
 * pigpio alert callback — fires on every edge of the sensor pin.
 * We count rising edges only.
 */
static void sensor_callback(int gpio, int level, uint32_t tick)
{
    (void)tick;
    if (gpio != SENSOR_PIN)
        return;
    if (level == 1)
        atomic_fetch_add(&pulse_count, 1);
}

/*
 * Timer callback — resets the pulse counter and logs the RPM.
 * Runs every SAMPLE_INTERVAL_US microseconds.
 */
static void timer_callback(void)
{
    int pulses = atomic_exchange(&pulse_count, 0);
    int rpm = pulses * 60;          /* one pulse per revolution */

    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s %d\n", timestamp, rpm) < 0)
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        if (fflush(log_file) != 0)
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }

    printf("%s RPM: %d\n", timestamp, rpm);
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    log_file = fopen("rpm_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening rpm_log.txt: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- configure sensor pin --- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- register alert callback --- */
    if (gpioSetAlertFunc(SENSOR_PIN, sensor_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc failed for pin %d\n", SENSOR_PIN);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- register timer callback --- */
    if (gpioSetTimerFunc(0, SAMPLE_INTERVAL_US, timer_callback) != 0) {
        fprintf(stderr, "gpioSetTimerFunc failed\n");
        gpioSetAlertFunc(SENSOR_PIN, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioSetTimerFunc(0, 0, NULL);
        gpioSetAlertFunc(SENSOR_PIN, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioSetTimerFunc(0, 0, NULL);
        gpioSetAlertFunc(SENSOR_PIN, NULL);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);

    /* --- main loop --- */
    while (running)
        gpioDelay(100000);  /* 100 ms sleep to reduce CPU usage */

    /* --- cleanup --- */
    gpioSetTimerFunc(0, 0, NULL);
    gpioSetAlertFunc(SENSOR_PIN, NULL);

    if (log_file != NULL) {
        if (fclose(log_file) != 0)
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        log_file = NULL;
    }

    gpioTerminate();
    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

