#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"

/* Quadrature states: A=0, B=0 -> idle; A=1, B=0 -> CW; A=0, B=1 -> CCW */
typedef enum { STATE_IDLE, STATE_CW, STATE_CCW } QuadratureState;

static volatile QuadratureState g_state = STATE_IDLE;
static pthread_mutex_t g_state_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_state_cond = PTHREAD_COND_INITIALIZER;
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
    pthread_cond_signal(&g_state_cond);
}

static void log_rotation(const char *direction) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[64];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s - %s\n", timestamp, direction);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;

    if (gpio == SENSOR_A_GPIO) {
        pthread_mutex_lock(&g_state_mutex);
        if (level == 1) {
            if (g_state == STATE_IDLE) {
                g_state = STATE_CW;
            } else if (g_state == STATE_CCW) {
                g_state = STATE_IDLE;
            }
        } else if (level == 0) {
            if (g_state == STATE_CW) {
                g_state = STATE_IDLE;
            } else if (g_state == STATE_IDLE) {
                g_state = STATE_CCW;
            }
        }
        pthread_mutex_unlock(&g_state_mutex);
        pthread_cond_signal(&g_state_cond);
    }
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %d\n", SENSOR_A_GPIO, ret);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %d\n", SENSOR_B_GPIO, ret);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %d\n", SENSOR_A_GPIO, ret);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %d\n", SENSOR_B_GPIO, ret);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetAlertFunc(SENSOR_A_GPIO, sensor_callback);
    if (ret != 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d: %d\n", SENSOR_A_GPIO, ret);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetAlertFunc(SENSOR_B_GPIO, sensor_callback);
    if (ret != 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d: %d\n", SENSOR_B_GPIO, ret);
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Rotation detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        pthread_mutex_lock(&g_state_mutex);
        while (g_state == STATE_IDLE && g_running) {
            pthread_cond_wait(&g_state_cond, &g_state_mutex);
        }
        QuadratureState current_state = g_state;
        pthread_mutex_unlock(&g_state_mutex);

        if (!g_running) {
            break;
        }

        if (current_state == STATE_CW) {
            log_rotation("CW");
        } else if (current_state == STATE_CCW) {
            log_rotation("CCW");
        }
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(SENSOR_A_GPIO, NULL);
    gpioSetAlertFunc(SENSOR_B_GPIO, NULL);
    gpioTerminate();

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    pthread_mutex_destroy(&g_state_mutex);
    pthread_cond_destroy(&g_state_cond);

    return EXIT_SUCCESS;
}

