#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define CHIP_NAME  "gpiochip0"
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int led_state = 0;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("gpiod_chip_get_line(touch)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(touch_line, "ttp223b-touch");
    if (ret < 0) {
        perror("gpiod_line_request_input(touch)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(led_line, "ttp223b-led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("Touch sensor application started. Press Ctrl+C to exit.\n");

    while (running) {
        struct gpiod_line_event event;
        int wait_ret = gpiod_line_event_wait(touch_line, NULL);
        if (wait_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("gpiod_line_event_wait");
            break;
        }
        if (wait_ret == 0) {
            continue;
        }

        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            usleep(DEBOUNCE_MS * 1000);

            led_state = !led_state;
            ret = gpiod_line_set_value(led_line, led_state);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                break;
            }
            printf("Touch detected! LED toggled to %s\n", led_state ? "ON" : "OFF");
        }
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
