#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22
#define BUFFER_SIZE  100
#define POLL_US      50000   /* 50 ms */

typedef struct {
    int sensor_pin;
    int led_pin;
    int state;          /* 0 = released, 1 = touched */
    time_t timestamp;
} TouchEvent;

static TouchEvent log_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_overflows = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %u\n", pin);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %u\n", pin);
        return -1;
    }
    return v;
}

static void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed\n");
        return;
    }

    log_buffer[buffer_index].sensor_pin = sensor_pin;
    log_buffer[buffer_index].state      = state;
    log_buffer[buffer_index].timestamp  = now;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) buffer_overflows++;
}

static void print_log(void) {
    printf("\n--- Touch Event Log (%d entries, %d overflows) ---\n",
           BUFFER_SIZE - buffer_overflows, buffer_overflows);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        if (log_buffer[idx].timestamp == 0) continue;
        char ts[32];
        struct tm tmv;
        if (localtime_r(&log_buffer[idx].timestamp, &tmv) != NULL &&
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv) > 0) {
            printf("[%s] Sensor %d -> %s\n",
                   ts, log_buffer[idx].sensor_pin,
                   log_buffer[idx].state ? "TOUCHED" : "RELEASED");
        } else {
            printf("[?] Sensor %d -> %s\n",
                   log_buffer[idx].sensor_pin,
                   log_buffer[idx].state ? "TOUCHED" : "RELEASED");
        }
    }
    printf("--- End of Log ---\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        safe_set_mode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        safe_set_mode(LED_1_PIN,    PI_OUTPUT) < 0 ||
        safe_set_mode(LED_2_PIN,    PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(LED_1_PIN, 0) < 0 || safe_write(LED_2_PIN, 0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        safe_write(LED_1_PIN, 0);
        safe_write(LED_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Sensor 1: GPIO %d -> LED GPIO %d\n", SENSOR_1_PIN, LED_1_PIN);
    printf("  Sensor 2: GPIO %d -> LED GPIO %d\n", SENSOR_2_PIN, LED_2_PIN);
    printf("Press Ctrl+C to exit.\n");

    int prev1 = safe_read(SENSOR_1_PIN);
    int prev2 = safe_read(SENSOR_2_PIN);
    if (prev1 < 0 || prev2 < 0) {
        safe_write(LED_1_PIN, 0);
        safe_write(LED_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int cur1 = safe_read(SENSOR_1_PIN);
        int cur2 = safe_read(SENSOR_2_PIN);
        if (cur1 < 0 || cur2 < 0) {
            gpioDelay(POLL_US);
            continue;
        }

        if (cur1 != prev1) {
            if (safe_write(LED_1_PIN, cur1) == 0) {
                log_event(SENSOR_1_PIN, cur1);
            }
            prev1 = cur1;
        }

        if (cur2 != prev2) {
            if (safe_write(LED_2_PIN, cur2) == 0) {
                log_event(SENSOR_2_PIN, cur2);
            }
            prev2 = cur2;
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down...\n");
    safe_write(LED_1_PIN, 0);
    safe_write(LED_2_PIN, 0);
    gpioTerminate();
    print_log();
    return EXIT_SUCCESS;
}

