#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_DELAY_US 5000
#define PULSES_PER_REVOLUTION 2
#define LOG_FILE "shaft_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    signal(SIGINT, signal_handler);

    int last_sensor1_state = read_sensor(SENSOR_1_GPIO);
    int last_sensor2_state = read_sensor(SENSOR_2_GPIO);

    int pulse_count = 0;
    uint32_t last_tick = gpioTick();

    while (program_running) {
        int current_sensor1_state = read_sensor(SENSOR_1_GPIO);
        int current_sensor2_state = read_sensor(SENSOR_2_GPIO);

        if (current_sensor1_state != last_sensor1_state) {
            uint32_t current_tick = gpioTick();
            if (current_tick - last_tick > DEBOUNCE_DELAY_US) {
                pulse_count++;
                last_tick = current_tick;
            }
            last_sensor1_state = current_sensor1_state;
        }

        if (current_sensor2_state != last_sensor2_state) {
            uint32_t current_tick = gpioTick();
            if (current_tick - last_tick > DEBOUNCE_DELAY_US) {
                pulse_count++;
                last_tick = current_tick;
            }
            last_sensor2_state = current_sensor2_state;
        }

        if (pulse_count >= PULSES_PER_REVOLUTION) {
            double rpm = (pulse_count * 60000000.0) / (DEBOUNCE_DELAY_US * PULSES_PER_REVOLUTION);
            printf("RPM: %.2f\n", rpm);
            pulse_count = 0;
        }

        log_data(current_sensor1_state, current_sensor2_state);
        gpioDelay(1000);
    }

    gpioTerminate();
    return 0;
}

