#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_DATA_REG 0x02
#define SPO2_DATA_REG 0x04

#define LOG_FILE "biometric_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_hr_data(int handle, uint8_t *hr_data) {
    return read_register(handle, HR_DATA_REG, hr_data);
}

static int read_spo2_data(int handle, uint8_t *spo2_data) {
    return read_register(handle, SPO2_DATA_REG, spo2_data);
}

static int log_data(FILE *fp, uint8_t hr_data, uint8_t spo2_data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, hr_data, spo2_data) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t part_id = 0;
    if (read_register(i2c_handle, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Sensor not detected at address 0x%02X\n", SI1182_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Si1182 detected, PART_ID: 0x%02X\n", part_id);

    if (write_register(i2c_handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Error configuring sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Logging data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (!terminate) {
        uint8_t hr_data = 0, spo2_data = 0;

        if (read_hr_data(i2c_handle, &hr_data) == 0 && read_spo2_data(i2c_handle, &spo2_data) == 0) {
            if (log_data(log_file, hr_data, spo2_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    printf("\nCleaning up...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

