#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27
#define TILT_THRESHOLD_SEC 2
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file);
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void set_alarm(int state) {
    int rc = gpioWrite(ALARM_GPIO, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d: %s\n", ALARM_GPIO, pigpio_error(rc));
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("bridge_integrity.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) < 0 ||
        gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite failed to initialize alarm LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Bridge integrity monitor started. Press Ctrl+C to exit.\n");
    log_event("Monitor started");

    int alarm_active = 0;
    time_t tilt_start_time = 0;

    while (program_running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (s1 == 1 && s2 == 1) {
            if (!alarm_active) {
                alarm_active = 1;
                set_alarm(1);
                log_event("Alarm activated");
                tilt_start_time = time(NULL);
            } else {
                if (difftime(time(NULL), tilt_start_time) >= TILT_THRESHOLD_SEC) {
                    log_event("Threshold exceeded");
                }
            }
        } else {
            if (alarm_active) {
                alarm_active = 0;
                set_alarm(0);
                log_event("Alarm deactivated");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    set_alarm(0);
    log_event("Monitor stopped");
    fclose(log_file);
    gpioTerminate();
    printf("Bridge integrity monitor stopped.\n");
    return EXIT_SUCCESS;
}

