/*
 * Raspberry Pi 3 Model B+ — Omron D7S-A0011 seismic vibration monitor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   D7S SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *   LED anode -> GPIO17 (pin 11) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x1D          /* D7S-A0011 default 7-bit address */
#define CTRL1_REG            0x1F          /* Control register 1 */
#define CTRL1_POWER_DOWN     0x01          /* Bit 0: power-down / standby */
#define CTRL1_RESET          0x80          /* Bit 7: software reset */
#define ACCEL_X_REG          0x28          /* X-axis acceleration (little-endian) */
#define ACCEL_Y_REG          0x2A          /* Y-axis acceleration */
#define ACCEL_Z_REG          0x2C          /* Z-axis acceleration */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0         /* raw magnitude threshold */
#define POLL_INTERVAL_US     100000        /* 100 ms */
#define LED_ON_TIME_US       1000000       /* 1 s */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(float *x, float *y, float *z);
static float calculate_magnitude(float x, float y, float z);
static void log_event(float magnitude);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* --------------------------- Sensor initialization ------------------------ */
static int init_sensor(void)
{
    /*
     * D7S-A0011: CTRL1 = 0x80 (reset) then 0x00 (normal operation).
     * Bit 0 (POWER_DOWN) is cleared to enable measurement.
     */
    if (i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_RESET) < 0) {
        fprintf(stderr, "[ERROR] Sensor reset write failed\n");
        return -1;
    }
    gpioDelay(2000);  /* 2 ms settle after reset */

    if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Sensor power-down clear failed\n");
        return -1;
    }
    gpioDelay(2000);  /* 2 ms for sensor to stabilize */

    return 0;
}

/* --------------------- Read 6-byte acceleration block --------------------- */
static int read_acceleration(float *x, float *y, float *z)
{
    char buf[6];
    int  retries = 0;

    while (retries < MAX_RETRIES) {
        int n = i2cReadI2CBlockData(i2c_handle, ACCEL_X_REG, buf, 6);
        if (n == 6) {
            /* D7S outputs little-endian: [X_L, X_H, Y_L, Y_H, Z_L, Z_H] */
            int16_t raw_x = (int16_t)((uint16_t)buf[1] << 8 | (uint8_t)buf[0]);
            int16_t raw_y = (int16_t)((uint16_t)buf[3] << 8 | (uint8_t)buf[2]);
            int16_t raw_z = (int16_t)((uint16_t)buf[5] << 8 | (uint8_t)buf[4]);

            /*
             * Conversion factor depends on the sensor's full-scale range
             * (default is +/-2g, 16384 LSB/g).  Adjust if your breakout
             * provides a different sensitivity.
             */
            *x = (float)raw_x / 16384.0f;
            *y = (float)raw_y / 16384.0f;
            *z = (float)raw_z / 16384.0f;
            return 0;
        }

        fprintf(stderr, "[WARN] I2C block read failed (attempt %d/%d): %d\n",
                retries + 1, MAX_RETRIES, n);
        retries++;
        gpioDelay(10000);  /* 10 ms back-off before retry */
    }

    fprintf(stderr, "[ERROR] I2C block read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

/* ----------------------- Calculate Euclidean magnitude -------------------- */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------ Log event -------------------------------- */
static void log_event(float magnitude)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s - Vibration magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file);
}

/* ------------------------------ Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    float x, y, z, magnitude;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed — check wiring and address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Seismic monitoring started. Threshold: %.1f. Press Ctrl+C to exit.\n",
           VIBRATION_THRESHOLD);

    /* Main polling loop */
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > VIBRATION_THRESHOLD) {
                printf("[ALERT] Vibration magnitude %.2f exceeds threshold — logging\n",
                       magnitude);
                log_event(magnitude);

                gpioWrite(LED_GPIO, 1);
                gpioDelay(LED_ON_TIME_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed — continuing\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

