/*
 * flame_monitor.c — 5-sensor flame monitor using libgpiod (v1.6+)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Sensors (Keyes KY-026):
 *   BCM 2, 3, 4, 17, 27  (physical pins 3, 5, 7, 11, 13)
 *   Digital output: LOW  = flame detected
 *                   HIGH = no flame
 *   VCC/GND to 3.3 V / GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define CHIP_NAME        "gpiochip4"   /* BCM GPIO bank on Pi 3B+ */

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {"SENSOR_1", "SENSOR_2",
                                              "SENSOR_3", "SENSOR_4",
                                              "SENSOR_5"};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Return a static ISO-8601 UTC timestamp string. */
static const char *iso8601_utc(void)
{
    static char buf[32];
    time_t now = time(NULL);
    struct tm tm_utc;

    if (gmtime_r(&now, &tm_utc) == NULL) {
        snprintf(buf, sizeof(buf), "1970-01-01T00:00:00Z");
        return buf;
    }
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    return buf;
}

/*
 * Append one flame-detection event line to the log file.
 * Returns 0 on success, -1 on error (message already logged).
 */
static int log_event(const char *id, unsigned int pin)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "fopen(%s): %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sensor ID: %s (GPIO %u) - Flame Detected\n",
                iso8601_utc(), id, pin) < 0) {
        syslog(LOG_ERR, "fprintf: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "flock unlock: %s", strerror(errno));
    }

