#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000

/* TTP226 OUT0-OUT7 -> BCM GPIO pins */
static const unsigned int touch_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request_config req_cfg;
    int prev_values[NUM_CHANNELS];
    int ret;
    int i;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Resolve all 8 lines into a bulk handle */
    gpiod_line_bulk_init(&lines);
    for (i = 0; i < NUM_CHANNELS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, touch_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Error: cannot get line %u: %s\n", touch_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* Configure all lines as inputs */
    memset(&req_cfg, 0, sizeof(req_cfg));
    req_cfg.consumer = "ttp226-touch";
    req_cfg.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request_bulk(&lines, &req_cfg, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: cannot request lines as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Read initial states */
    for (i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(gpiod_line_bulk_get_line(&lines, i));
        if (val < 0) {
            fprintf(stderr, "Error: cannot read initial value for channel %d (pin %u): %s\n",
                    i, touch_pins[i], strerror(errno));
            gpiod_line_release_bulk(&lines, 0);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        prev_values[i] = val;
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(gpiod_line_bulk_get_line(&lines, i));
            if (val < 0) {
                fprintf(stderr, "Error: cannot read channel %d (pin %u): %s\n",
                        i, touch_pins[i], strerror(errno));
                continue;
            }

            if (val != prev_values[i]) {
                print_timestamp();
                printf("Channel %d (BCM %u): %s\n", i, touch_pins[i],
                       val ? "Touch Detected" : "Released");
                fflush(stdout);
                prev_values[i] = val;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    /* Clean up */
    gpiod_line_release_bulk(&lines, 0);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

