#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VEML7700_ADDR  0x10
#define ALS_REG        0x04
#define CONFIG_REG     0x00
#define LED_GPIO       18
#define PWM_FREQ       1000
#define PWM_RANGE      100
#define LOG_FILE       "grow_log.txt"
#define SAMPLE_US      1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int veml7700_init(int handle) {
    /* ALS gain 1/8 (0x00), ALS integration time 100 ms (0x00) -> 0x0000 */
    char config[2] = {0x00, 0x00};
    int rc = i2cWriteI2CBlockData(handle, CONFIG_REG, config, 2);
    if (rc < 0) {
        fprintf(stderr, "Error writing config register: %d\n", rc);
        return -1;
    }
    return 0;
}

static int veml7700_read_lux(int handle, float *lux_out) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, ALS_REG, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error reading ALS register: %d\n", rc);
        return -1;
    }
    if (rc != 2) {
        fprintf(stderr, "Short read: got %d bytes, expected 2\n", rc);
        return -1;
    }
    unsigned int raw = (unsigned int)((unsigned char)buf[1] << 8) | (unsigned char)buf[0];
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    int rc = gpioPWM(LED_GPIO, brightness);
    if (rc < 0) {
        fprintf(stderr, "Error setting PWM: %d\n", rc);
        return -1;
    }
    return 0;
}

static int calculate_brightness(float lux) {
    if (lux < 100.0f) return PWM_RANGE;
    if (lux < 500.0f) return (int)(PWM_RANGE * 0.75f);
    if (lux < 1000.0f) return (int)(PWM_RANGE * 0.50f);
    return (int)(PWM_RANGE * 0.25f);
}

static void log_data(FILE *fp, float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Brightness: %d, Error: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, brightness, error_code);
