#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000  /* 50 ms */

static const int channel_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to touch_log.txt: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing touch_log.txt: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure channel pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(channel_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(channel_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO %d\n", channel_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it starts off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security keypad started. Press Ctrl+C to exit.\n");

    int prev_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = 0;
    }

    while (running) {
        int any_touched = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int level = gpioRead(channel_pins[i]);
            if (level < 0) {
                fprintf(stderr, "Error reading GPIO %d\n", channel_pins[i]);
                continue;
            }

            /* Detect rising edge (touch) */
            if (level == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
            }
            prev_state[i] = level;
            any_touched |= level;
        }

        if (gpioWrite(LED_PIN, any_touched) != 0) {
            fprintf(stderr, "Failed to write to LED pin\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

