#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define OPT3001_ADDR        0x44
#define OPT3001_RESULT_REG  0x00
#define OPT3001_CONFIG_REG  0x01
#define OPT3001_CONFIG_WORD 0xC810  /* Continuous, auto-range, 100 ms */
#define I2C_BUS             1
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_WAIT_US        100000   /* 100 ms for first conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Swap bytes: OPT3001 sends MSB first, pigpio returns LSB first. */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int opt3001_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (pigpio code %d)\n",
                I2C_BUS, OPT3001_ADDR, g_i2c_handle);
        return -1;
    }

    /* Write configuration: big-endian word, swap bytes before writing. */
    uint16_t cfg = swap16(OPT3001_CONFIG_WORD);
    int rc = i2cWriteWordData(g_i2c_handle, OPT3001_CONFIG_REG, cfg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteWordData (config) failed (pigpio code %d)\n", rc);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    /* Allow first conversion to complete. */
    gpioDelay(CONV_WAIT_US);
    return 0;
}

static int opt3001_read_lux(float *lux_out)
{
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle invalid\n");
        return -1;
    }

    int raw = i2cReadWordData(g_i2c_handle, OPT3001_RESULT_REG);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData (result) failed (pigpio code %d)\n", raw);
        return -1;
    }

    /* pigpio returns LSB-first; OPT3001 sends MSB-first. */
    uint16_t swapped = swap16((uint16_t)raw);

    uint16_t exponent = (swapped >> 12) & 0x0F;
    uint16_t mantissa = swapped & 0x0FFF;

    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error: fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error: localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, lux) < 0) {
        perror("Error: fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error: fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (opt3001_init() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 greenhouse light monitor started. Logging to '%s'.\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float lux;
        if (opt3001_read_lux(&lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping sample\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    printf("\nShutting down...\n");

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

