#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(FILE *fp, int flame_detected) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s - Flame %s\n", timestamp, flame_detected ? "Detected" : "Not Detected") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int trigger_alert(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return -1;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
        return -1;
    }
    return 0;
}

