        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin %d as input\n", FLAME_SENSOR_PIN);
        goto cleanup;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin %d as output\n", ALERT_PIN);
        goto cleanup;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin %d to LOW\n", ALERT_PIN);
        goto cleanup;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read flame sensor pin %d\n", FLAME_SENSOR_PIN);
            if (log_event(log_file, -1) != 0) {
                fprintf(stderr, "Failed to log read error\n");
            }
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int flame_detected = (sensor_value == 0);

        if (log_event(log_file, flame_detected) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        if (flame_detected) {
            printf("Flame detected!\n");
            if (trigger_alert(ALERT_PIN) != 0) {
                fprintf(stderr, "Failed to trigger alert\n");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    gpioWrite(ALERT_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return ret;
}

