#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x08
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_US      1000000   /* 1 second */
#define FLOW_MIN       0.0f
#define FLOW_MAX       100.0f
#define RAW_MAX        32767     /* SLF3S-1300F signed 16-bit max */
#define RAW_MIN        (-32768)
#define FLOW_SCALE     90.0f     /* raw counts per ml/min */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_fp    = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Start continuous measurement on the SLF3S-1300F.
 * Command 0x3608 writes the register pointer to 0x08 (flow) and
 * then the sensor begins continuous reads of 3 bytes: [MSB][LSB][CRC].
 */
static int start_measurement(void)
{
    uint8_t cmd[2] = { 0x36, 0x08 };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteDevice (start) failed: %d\n", rc);
        return -1;
    }
    gpioDelay(2000); /* 2 ms settle */
    return 0;
}

/*
 * Read one 3-byte frame and convert to ml/min.
 * Returns 0 on success, -1 on I2C error, -2 on CRC error.
 */
static int read_flow_rate(float *flow_out)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "i2cReadDevice failed: %d\n", rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -2;
    }

