#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define LEFT_SENSOR_PIN  17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE_NAME "path_log.csv"
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, const char *ts, int left, int middle, int right)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    const unsigned int pins[3] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    lines[0] = lines[1] = lines[2] = NULL;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: cannot get GPIO line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033_logger") < 0) {
            fprintf(stderr, "Error: cannot request GPIO line %u as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup;
    }

    if (fprintf(fp, "# timestamp,left,middle,right\n") < 0) {
        fprintf(stderr, "Error: cannot write CSV header: %s\n", strerror(errno));
        goto cleanup;
    }
    fflush(fp);

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    while (program_running) {
        char ts[32];
        int left, middle, right;

        if (get_timestamp(ts, sizeof(ts)) != 0) {
            fprintf(stderr, "Error: failed to generate timestamp\n");
            break;
        }

        left   = gpiod_line_get_value(lines[0]);
        middle = gpiod_line_get_value(lines[1]);
        right  = gpiod_line_get_value(lines[2]);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error: failed to read GPIO line: %s\n", strerror(errno));
            break;
        }

        if (log_data(fp, ts, left, middle, right) != 0) {
            fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
            break;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

