/*
 * Flame Detection Safety System — Raspberry Pi 3 Model B+
 * Sensor : Keyes KY-026 flame sensor (digital OUT)
 * Wiring : KY-026 DO  -> GPIO17 (physical pin 11)
 *          KY-026 VCC -> 3.3 V
 *          KY-026 GND -> GND
 *          Buzzer +   -> GPIO18 (physical pin 12)
 *          Buzzer -   -> GND
 *
 * The KY-026 digital output is active-low: it reads LOW when a flame is
 * detected and HIGH otherwise.  The buzzer is active-high.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_PIN    17          /* GPIO17, physical pin 11 */
#define BUZZER_PIN   18          /* GPIO18, physical pin 12 */
#define POLL_MS      500         /* main-loop poll interval   */
#define BUZZER_MS    2000        /* buzzer on duration         */
#define BUZZER_STEP  100         /* 100 ms slices              */
#define LOG_FILE     "alert_log.txt"
#define CHIP_NAME    "gpiochip0"

static volatile sig_atomic_t g_running = 1;
static FILE                 *g_log     = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    time_t     t  = time(NULL);
    struct tm  tm;
    char       ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (g_log) {
        fprintf(g_log, "%s: %s\n", ts, msg);
        fflush(g_log);
    }
    printf("%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *flame,
                    struct gpiod_line *buzzer)
{
    if (buzzer) {
        (void)gpiod_line_set_value(buzzer, 0);   /* buzzer off */
        gpiod_line_release(buzzer);
    }
    if (flame)
        gpiod_line_release(flame);
    if (chip)
        gpiod_chip_close(chip);
    if (g_log) {
        log_event("System stopped");
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame = NULL;
    struct gpiod_line *buzzer = NULL;
    int                prev_flame = 1;   /* assume no flame at startup */
    int                ret;

    /* ---- signal handlers ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open log file -------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open GPIO chip ------------------------------------------- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                CHIP_NAME, strerror(errno));
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    /* ---- get lines ------------------------------------------------ */
    flame = gpiod_chip_get_line(chip, FLAME_PIN);
    if (!flame) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                FLAME_PIN, strerror(errno));
        cleanup(chip, NULL, NULL);
        return EXIT_FAILURE;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        cleanup(chip, flame, NULL);
        return EXIT_FAILURE;
    }

    /* ---- request lines -------------------------------------------- */
    ret = gpiod_line_request_input(flame, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_input(%d): %s\n",
                FLAME_PIN, strerror(errno));
        cleanup(chip, flame, buzzer);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(buzzer, "buzzer", 0);
    if (ret < 0) {
        fprintf(stderr, "gpiod_line_request_output(%d): %s\n",
                BUZZER_PIN, strerror(errno));
        cleanup(chip, flame, buzzer);
        return EXIT_FAILURE;
    }

    log_event("System started");

    /* ---- main loop ------------------------------------------------ */
    while (g_running) {
        int val = gpiod_line_get_value(flame);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(%d): %s\n",
                    FLAME_PIN, strerror(errno));
            break;
        }

        /* KY-026 DO is active-low: LOW => flame detected */
        if (val == 0 && prev_flame == 1) {
            log_event("Flame detected!");

            /* 2-second buzzer burst: 100 ms slices */
            for (int i = 0; i < BUZZER_MS / BUZZER_STEP && g_running; i++) {
                ret = gpiod_line_set_value(buzzer, 1);
                if (ret < 0) {
                    fprintf(stderr, "gpiod_line_set_value(buzzer ON): %s\n",
                            strerror(errno));
                    break;
                }
                usleep(BUZZER_STEP * 1000);
                ret = gpiod_line_set_value(buzzer, 0);
                if (ret < 0) {
                    fprintf(stderr, "gpiod_line_set_value(buzzer OFF): %s\n",
                            strerror(errno));
                    break;
                }
                usleep(BUZZER_STEP * 1000);
            }
        }
        prev_flame = val;

        /* 500 ms poll interval: 100 ms slices */
        for (int i = 0; i < POLL_MS / BUZZER_STEP && g_running; i++)
            usleep(BUZZER_STEP * 1000);
    }

    /* ---- graceful shutdown ---------------------------------------- */
    cleanup(chip, flame, buzzer);
    return EXIT_SUCCESS;
}

