            ret = 1;
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            led_state = !led_state;
            if (gpioWrite(LED_GPIO, led_state) != 0) {
                fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n", LED_GPIO);
                ret = 1;
                break;
            }

            if (log_touch_event() != 0) {
                fprintf(stderr, "Warning: failed to log touch event.\n");
            }

            gpioDelay(DEBOUNCE_DELAY_US);
        }

        last_touch_state = touch_state;
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn off LED during shutdown.\n");
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();

    return ret;
}

