#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/*
 * TMAG5110A1 Hall-effect latch sensor (open-drain OUT variant).
 * The OUT pin is driven low (0 V) when a south pole is present,
 * and released high (3.3 V) when the south pole is absent.
 * A pull-up resistor keeps the line high when the sensor is absent.
 */

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define LOG_FILE "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor: returns 0 or 1, or -1 on error                       */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(v));
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped state-change record to the log file            */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor %d: %s\n",
                timestamp, sensor_id,
                state ? "Magnet Present" : "Magnet Removed");
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open; event lost: %s - Sensor %d: %s\n",
                timestamp, sensor_id,
                state ? "Magnet Present" : "Magnet Removed");
    }
}

/* ------------------------------------------------------------------ */
/* Configure one GPIO as input with pull-up                            */
/* ------------------------------------------------------------------ */
static int configure_sensor(int pin)
{
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev1 = -1, prev2 = -1, prev3 = -1;
    int first_read = 1;

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins --- */
    if (configure_sensor(SENSOR_1_PIN) != 0 ||
        configure_sensor(SENSOR_2_PIN) != 0 ||
        configure_sensor(SENSOR_3_PIN) != 0) {
        fprintf(stderr, "Failed to configure sensor GPIOs\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Magnet sensor monitoring started.\n");
    printf("  Sensor 1: GPIO%d\n  Sensor 2: GPIO%d\n  Sensor 3: GPIO%d\n",
           SENSOR_1_PIN, SENSOR_2_PIN, SENSOR_3_PIN);
    printf("  Logging to: %s\n  Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (program_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);
        int s3 = read_sensor(SENSOR_3_PIN);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            /* Error already reported to stderr; keep running */
        } else {
            if (first_read) {
                /* Record initial state without logging a false transition */
                prev1 = s1;
                prev2 = s2;
                prev3 = s3;
                first_read = 0;
            } else {
                if (s1 != prev1) { log_event(1, s1); prev1 = s1; }
                if (s2 != prev2) { log_event(2, s2); prev2 = s2; }
                if (s3 != prev3) { log_event(3, s3); prev3 = s3; }
            }
        }

        gpioDelay(POLL_DELAY_US);  /* 100 ms */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

