#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVERAGING 0x04
#define REG_ENABLE 0x01
#define REG_HR_DATA 0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01
#define MIN_BPM 30
#define MAX_BPM 220
#define MOVING_AVG_SIZE 5
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static int moving_avg_index = 0;
static int moving_avg_buffer[MOVING_AVG_SIZE];
static int moving_avg_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_register(int handle, int reg) {
    int val = i2cReadByteData(handle, reg);
    if (val < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, val);
    }
    return val;
}

static int write_register(int handle, int reg, int val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, val, rc);
    }
    return rc;
}

static int initialize_sensor(int handle) {
    int part_id = read_register(handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read PART_ID - sensor may be absent\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    int hw_rev = read_register(handle, REG_HW_REV);
    if (hw_rev < 0) {
        fprintf(stderr, "Cannot read HW_REV\n");
        return -1;
    }
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_register(handle, REG_LED_CURRENT, 0x3F) < 0) return -1;
    if (write_register(handle, REG_AVERAGING, 0x04) < 0) return -1;
    if (write_register(handle, REG_ENABLE, 0x01) < 0) return -1;

    return 0;
}

static int read_heart_rate(int handle) {
    int raw = i2cReadWordData(handle, REG_HR_DATA);
    if (raw < 0) {
        fprintf(stderr, "Error reading HR_DATA: %d\n", raw);
        return -1;
    }
    return raw;
}

static int calculate_bpm(int raw) {
    return raw * 0.5;
}

static int update_moving_average(int new_value) {
    moving_avg_buffer[moving_avg_index] = new_value;
    moving_avg_index = (moving_avg_index + 1) % MOVING_AVG_SIZE;
    if (moving_avg_count < MOVING_AVG_SIZE) {
        moving_avg_count++;
    }

    int sum = 0;
    for (int i = 0; i < moving_avg_count; i++) {
        sum += moving_avg_buffer[i];
    }
    return sum / moving_avg_count;
}

static int is_valid_bpm(int bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

static void log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting heart-rate monitoring. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw = read_heart_rate(i2c_handle);
        if (raw < 0) {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int bpm = calculate_bpm(raw);
        int filtered_bpm = update_moving_average(bpm);

        if (is_valid_bpm(filtered_bpm)) {
            log_data(filtered_bpm);
            printf("Heart Rate: %d BPM\n", filtered_bpm);
        } else {
            fprintf(stderr, "Invalid heart rate: %d BPM\n", filtered_bpm);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

