/*
 * touch_counter.c — 8-channel TTP226 capacitive touch sensor reader
 * with 8-bit binary counter on GPIO17..GPIO24 (BCM) and logging to
 * touch_log.txt.  Uses libgpiod v2+ bulk/config API (no sysfs, no
 * wiringPi, no libgpiod v1 simple API).
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    ./touch_counter   (needs gpiod group membership or root)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define STABILIZE_DELAY_MS 200
#define LOG_FILE "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    while (ms > 0 && g_running) {
        unsigned int chunk = (ms > 100) ? 100 : ms;
        usleep(chunk * 1000U);
        ms -= chunk;
    }
}

static void log_touch_event(int channel, int counter)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm);
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
    }
    fclose(fp);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *counter_req = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Sensor line request (inputs) --- */
    struct gpiod_line_settings *in_settings = gpiod_line_settings_new();
    if (!in_settings) {
        fprintf(stderr, "gpiod_line_settings_new (input): %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(in_settings, GPIOD_LINE_DIRECTION_INPUT);

    struct gpiod_line_config *in_cfg = gpiod_line_config_new();
    if (!in_cfg) {
        fprintf(stderr, "gpiod_line_config_new (input): %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(in_cfg, &sensor_pins[i], 1, in_settings) < 0) {
            fprintf(stderr, "add_line_settings sensor pin %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, in_cfg);
    if (!sensor_req) {
        fprintf(stderr, "request_lines (sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Counter line request (outputs) --- */
    struct gpiod_line_settings *out_settings = gpiod_line_settings_new();
    if (!out_settings) {
        fprintf(stderr, "gpiod_line_settings_new (output): %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_line_settings_set_direction(out_settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(out_settings, GPIOD_LINE_VALUE_INACTIVE);

    struct gpiod_line_config *out_cfg = gpiod_line_config_new();
    if (!out_cfg) {
        fprintf(stderr, "gpiod_line_config_new (output): %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(out_cfg, &counter_pins[i], 1, out_settings) < 0) {
            fprintf(stderr, "add_line_settings counter pin %u: %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    counter_req = gpiod_chip_request_lines(chip, NULL, out_cfg);
    if (!counter_req) {
        fprintf(stderr, "request_lines (counter): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Stabilize: sensor lines settle, outputs idle --- */
    sleep_ms(STABILIZE_DELAY_MS);

    /* --- Main polling loop --- */
    int prev_state[NUM_CHANNELS];
    int counter = 0;

    for (int i = 0; i < NUM_CHANNELS; i++)
        prev_state[i] = 0;

    while (g_running) {
        int values[NUM_CHANNELS];
        int err = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            enum gpiod_line_value v =
                gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (v == GPIOD_LINE_VALUE_ERROR) {
                fprintf(stderr, "read sensor pin %u: %s\n",
                        sensor_pins[i], strerror(errno));
                err = 1;
                break;
            }
            values[i] = (v == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;
        }

        if (err) {
            sleep_ms(POLL_INTERVAL_US);
            continue;
        }

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (values[i] && !prev_state[i]) {
                /* Rising edge: new touch */
                counter++;
                if (counter > 255)
                    counter = 0;

                /* Update counter display: bit b -> GPIO17+b */
                int b = counter & 1;
                if (gpiod_line_request_set_value(counter_req, counter_pins[i],
                                                  b ? GPIOD_LINE_VALUE_ACTIVE
                                                    : GPIOD_LINE_VALUE_INACTIVE) < 0) {
                    fprintf(stderr, "set counter pin %u: %s\n",
                            counter_pins[i], strerror(errno));
                }

                log_touch_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev_state[i] = values[i];
        }

        sleep_ms(POLL_INTERVAL_US);
    }

    /* --- Graceful shutdown: reset outputs, release, close --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_set_value(counter_req, counter_pins[i],
                                          GPIOD_LINE_VALUE_INACTIVE) < 0) {
