#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_17 17
#define GPIO_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_US 50000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(int sensor_id) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[20];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_id);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open\n");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int prev17 = 1, prev18 = 1;
    int ret;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (line17 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (line18 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_18, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line17, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", GPIO_17, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input_flags(line18, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d as input: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO %d and %d. Press Ctrl+C to exit.\n", GPIO_17, GPIO_18);

    while (program_running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);

        if (val17 < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_17, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }
        if (val18 < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_18, strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val17 == 0 && prev17 == 1) {
            log_event(1);
            usleep(DEBOUNCE_US);
            val17 = gpiod_line_get_value(line17);
            if (val17 < 0) {
                fprintf(stderr, "Read error during debounce: %s\n", strerror(errno));
            }
        }
        if (val18 == 0 && prev18 == 1) {
            log_event(2);
            usleep(DEBOUNCE_US);
            val18 = gpiod_line_get_value(line18);
            if (val18 < 0) {
                fprintf(stderr, "Read error during debounce: %s\n", strerror(errno));
            }
        }

        prev17 = val17;
        prev18 = val18;
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");

    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

