#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_DURATION_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        printf("[%ld.%03ld] ", (long)ts.tv_sec, ts.tv_nsec / 1000000);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIC_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Sound-activated LED alert started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int level = gpioRead(MIC_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", MIC_GPIO);
            break;
        }

        if (level == 1) {
            print_timestamp();
            printf("Peak detected!\n");
            fflush(stdout);

            if (gpioWrite(LED_GPIO, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn LED ON.\n");
                break;
            }

            gpioDelay(LED_ON_DURATION_US);

            if (gpioWrite(LED_GPIO, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite failed to turn LED OFF.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nProgram terminated cleanly.\n");
    return EXIT_SUCCESS;
}

