    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as input */
    if (gpiod_line_request_input(left_line, "keywish-sensor") < 0) {
        fprintf(stderr, "Failed to request left line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "keywish-sensor") < 0) {
        fprintf(stderr, "Failed to request middle line as input: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "keywish-sensor") < 0) {
        fprintf(stderr, "Failed to request right line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Main polling loop */
    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            fprintf(stderr, "Failed to read sensor values: %s\n", strerror(errno));
            break;
        }

        printf("L:%d M:%d R:%d\n", left_val, middle_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

