/*
 * TTP226 8-channel capacitive touch sensor reader using libgpiod (v1.x API).
 *
 * Wiring (TTP226 -> Raspberry Pi 3 Model B+):
 *   TP1 -> BCM 5   TP2 -> BCM 6   TP3 -> BCM 13  TP4 -> BCM 19
 *   TP5 -> BCM 26  TP6 -> BCM 12  TP7 -> BCM 16  TP8 -> BCM 20
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 *
 * Run:
 *   ./ttp226_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200
#define GPIO_CHIP_NAME "gpiochip0"

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == 0) {
        printf("[%.3fs] ", ts.tv_sec + ts.tv_nsec / 1e9);
    } else {
        printf("[?s] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get and request each GPIO line as input */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get line %u: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ttp226_reader") < 0) {
            fprintf(stderr, "Failed to request line %u as input: %s\n", touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int values[NUM_CHANNELS];
        int read_ok = 1;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Failed to read line %u: %s\n", touch_pins[i], strerror(errno));
                read_ok = 0;
                break;
            }
            values[i] = v;
        }

        if (read_ok) {
            print_timestamp();
            printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
                   values[0], values[1], values[2], values[3],
                   values[4], values[5], values[6], values[7]);
            fflush(stdout);
        }

        /* Sleep 200 ms using nanosleep for portability */
        struct timespec req = { .tv_sec = 0, .tv_nsec = POLL_INTERVAL_MS * 1000000L };
        while (nanosleep(&req, &req) == -1 && errno == EINTR && program_running) {
            /* Retry if interrupted by signal */
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all lines and close the chip */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

