}

/* ------------------------------------------------------------------ */
/* HSV -> RGB (common-anode: inverted PWM duty)                         */
/* ------------------------------------------------------------------ */
static void hsv_to_rgb(float h, float s, float v,
                        uint8_t *r, uint8_t *g, uint8_t *b)
{
    if (s <= 0.0f) {
        *r = *g = *b = (uint8_t)(v * 255.0f);
        return;
    }

    h = fmodf(h, 360.0f);
    if (h < 0.0f) h += 360.0f;

    float hh = h / 60.0f;
    int   i  = (int)hh;
    float f  = hh - (float)i;
    float p  = v * (1.0f - s);
    float q  = v * (1.0f - s * f);
    float t  = v * (1.0f - s * (1.0f - f));

    switch (i) {
        case 0: *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(t * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 1: *r = (uint8_t)(q * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(p * 255.0f); break;
        case 2: *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(v * 255.0f); *b = (uint8_t)(t * 255.0f); break;
        case 3: *r = (uint8_t)(p * 255.0f); *g = (uint8_t)(q * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        case 4: *r = (uint8_t)(t * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(v * 255.0f); break;
        default: *r = (uint8_t)(v * 255.0f); *g = (uint8_t)(p * 255.0f); *b = (uint8_t)(q * 255.0f); break;
    }
}

/* ------------------------------------------------------------------ */
/* Set one channel with error checking                                  */
/* ------------------------------------------------------------------ */
static int set_channel(int pin, uint8_t val)
{
    int rc = gpioPWM(pin, 255 - val);   /* common-anode: invert duty */
    if (rc < 0) {
        syslog(LOG_ERR, "gpioPWM(%d, %u) failed: %d", pin, 255 - val, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fade from current -> target color over FADE_STEPS steps            */
/* ------------------------------------------------------------------ */
static int fade_to(uint8_t r_cur, uint8_t g_cur, uint8_t b_cur,
                   uint8_t r_tgt, uint8_t g_tgt, uint8_t b_tgt)
{
    for (int i = 1; i <= FADE_STEPS && g_running; i++) {
        uint8_t r = (uint8_t)(((float)i / (float)FADE_STEPS) * (float)r_tgt +
                              ((1.0f - (float)i / (float)FADE_STEPS)) * (float)r_cur);
        uint8_t g = (uint8_t)(((float)i / (float)FADE_STEPS) * (float)g_tgt +
                              ((1.0f - (float)i / (float)FADE_STEPS)) * (float)g_cur);
        uint8_t b = (uint8_t)(((float)i / (float)FADE_STEPS) * (float)b_tgt +
                              ((1.0f - (float)i / (float)FADE_STEPS)) * (float)b_cur);

        if (set_channel(RED_PIN,   r) < 0) return -1;
        if (set_channel(GREEN_PIN, g) < 0) return -1;
        if (set_channel(BLUE_PIN,  b) < 0) return -1;

