    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Turn off all channels                                               */
/* ------------------------------------------------------------------ */
static void all_off(void)
{
    gpioPWM(RED_PIN,   0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN,  0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure pins as outputs */
    if (gpioSetMode(RED_PIN,   PI_OUTPUT) < 0) {
