        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN,  PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", BLUE_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 1 kHz */
    if (gpioSetPWMfrequency(RED_PIN,   FADE_HZ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency(%d, %d) failed", RED_PIN, FADE_HZ);
        gpioTerminate();
