    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write_reg8(fd, TCS34725_ENABLE, TCS34725_PON | TCS34725_AEN) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;
    return 0;
}

static int tcs34725_powerdown(int fd) {
    return i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
}

static int tcs34725_read_channels(int fd, uint16_t *c, uint16_t *r, uint16_t *g, uint16_t *b) {
    if (i2c_read_reg16_le(fd, TCS34725_CDATAL, c) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_RDATAL, r) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_GDATAL, g) < 0) return -1;
    if (i2c_read_reg16_le(fd, TCS34725_BDATAL, b) < 0) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", TCS34725_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 init failed\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open failed: %s\n", strerror(errno));
        tcs34725_powerdown(i2c_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        fprintf(stderr, "gpiod get line %d failed: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        tcs34725_powerdown(i2c_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "gpiod request output failed: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        tcs34725_powerdown(i2c_fd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int rc = EXIT_SUCCESS;
    while (running) {
        uint16_t c, r, g, b;
        if (tcs34725_read_channels(i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read failed, re-initializing...\n");
            tcs34725_powerdown(i2c_fd);
            usleep(10000);
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "Re-init failed, exiting\n");
                rc = EXIT_FAILURE;
                break;
            }
            continue;
        }
        int red_cal = (int)r - 100;
        if (red_cal < 0) red_cal = 0;
        if (gpiod_line_set_value(led, red_cal > RED_THRESHOLD ? 1 : 0) < 0) {
            fprintf(stderr, "LED write failed: %s\n", strerror(errno));
        }
        printf("C=%u R=%u G=%u B=%u | red_cal=%d\n", c, r, g, b, red_cal);
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    tcs34725_powerdown(i2c_fd);
    close(i2c_fd);
    return rc;
}

