#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define BH1750_MEAS_DELAY_US 180000
#define MAX_RETRIES 3
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_read_lux(int handle, float *lux_out) {
    char cmd = BH1750_CONT_HIGH_RES;
    char buf[2];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2cWriteDevice(handle, &cmd, 1) != 0) {
            fprintf(stderr, "BH1750 write failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(BH1750_MEAS_DELAY_US);

        if (i2cReadDevice(handle, buf, 2) != 2) {
            fprintf(stderr, "BH1750 read failed (retries left: %d)\n", retries - 1);
            retries--;
            gpioDelay(10000);
            continue;
        }

        uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        *lux_out = (float)raw / 1.2f;
        return 0;
    }

    return -1;
}

static int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > 1000.0f) lux = 1000.0f;

    float normalized = lux / 1000.0f;
    float log_scaled = log10f(1.0f + normalized * 9.0f);
    int brightness = (int)(log_scaled * 255.0f);

    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return brightness;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;

    uint8_t gpio_bit = 1 << LED_PIN;
    uint32_t mask = gpio_bit;
    uint32_t not_mask = 0;

    if (brightness == 0) {
        gpioWaveClear();
        gpioWaveAddNew();
        gpioPulse_t pulse;
        pulse.gpioOn = 0;
        pulse.gpioOff = 0;
        pulse.usDelay = 0;
        gpioWaveAddGeneric(1, &pulse);
        int wave_id = gpioWaveCreate();
        if (wave_id >= 0) {
            gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
            gpioWaveDelete(wave_id);
        }
        return;
    }

    uint32_t high_us = (uint32_t)(((255 - brightness) * 11) / 255);
    uint32_t low_us = (uint32_t)((brightness * 11) / 255);

    gpioWaveClear();
    gpioWaveAddNew();

    gpioPulse_t pulses[NUM_LEDS * 2];
    int idx = 0;

    for (int i = 0; i < NUM_LEDS; i++) {
        pulses[idx].gpioOn = gpio_bit;
        pulses[idx].gpioOff = 0;
        pulses[idx].usDelay = high_us;
        idx++;

        pulses[idx].gpioOn = 0;
        pulses[idx].gpioOff = gpio_bit;
        pulses[idx].usDelay = low_us;
        idx++;
    }

    gpioWaveAddGeneric(idx, pulses);
    int wave_id = gpioWaveCreate();
    if (wave_id >= 0) {
        gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
        gpioWaveDelete(wave_id);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float lux = 0.0f;
        if (bh1750_read_lux(i2c_handle, &lux) != 0) {
            fprintf(stderr, "Sensor read failed after retries; skipping cycle\n");
        } else {
            int brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        }
        gpioDelay(LOOP_DELAY_US);
    }

    set_led_brightness(0);
    gpioDelay(100000);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

