#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define NUM_LEDS 10
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USECS 0

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(int fd) {
    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        return -1;
    }
    if (i2c_write_byte(fd, BH1750_ONE_TIME_HIGH_RES) < 0) {
        return -1;
    }
    usleep(120000);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux) {
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) {
        return -1;
    }
    uint16_t raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = SPI_DELAY_USECS,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int apa102_send_frame(int fd, uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red) {
    uint8_t tx[4] = {0xE0 | (brightness & 0x1F), blue, green, red};
    uint8_t rx[4] = {0};
    return spi_transfer(fd, tx, rx, 4);
}

static int apa102_send_zero_frame(int fd) {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0};
    return spi_transfer(fd, tx, rx, 4);
}

static int apa102_send_end_frame(int fd) {
    uint8_t tx[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t rx[4] = {0};
    return spi_transfer(fd, tx, rx, 4);
}

static int apa102_set_all(int fd, uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red) {
    for (int i = 0; i < NUM_LEDS; i++) {
        if (apa102_send_frame(fd, brightness, blue, green, red) < 0) {
            return -1;
        }
    }
    if (apa102_send_end_frame(fd) < 0) {
        return -1;
    }
    return 0;
}

static int apa102_off(int fd) {
    return apa102_set_all(fd, 0, 0, 0, 0);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = SPI_BITS_PER_WORD;
    uint32_t spi_speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Failed to configure SPI: %s\n", strerror(errno));
        goto cleanup;
    }

    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed. Check wiring and sensor presence.\n");
        goto cleanup;
    }

    if (apa102_off(spi_fd) < 0) {
        fprintf(stderr, "Failed to initialize APA102 LEDs.\n");
        goto cleanup;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read BH1750. Retrying...\n");
            usleep(100000);
            continue;
        }

        uint8_t brightness = 0;
        if (lux >= 10.0f && lux <= 300.0f) {
            brightness = (uint8_t)((lux - 10.0f) / 290.0f * 31.0f);
        }

        if (apa102_set_all(spi_fd, brightness, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to update APA102 LEDs.\n");
        }

        printf("Lux: %.2f, Brightness: %u\n", lux, brightness);
        usleep(100000);
    }

cleanup:
    apa102_off(spi_fd);
    if (spi_fd >= 0) close(spi_fd);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

