#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define SPI_CHANNEL 0
#define SPI_SPEED 4000000
#define SPI_FLAGS 0
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180
#define FADE_MS 500
#define LOOP_DELAY_MS 100
#define MAX_BRIGHTNESS 31

static int i2c_handles[NUM_SENSORS];
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CMD_OT_HRES2) < 0) {
        fprintf(stderr, "Error: Failed to write OT_HRES2 command to BH1750 handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_bh1750(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read 2 bytes from BH1750 handle %d\n", handle);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (int)(raw / 1.2);
}

static int map_lux_to_brightness(int lux) {
    if (lux < 0) lux = 0;
    if (lux > 65535) lux = 65535;
    return (int)(((float)lux / 65535.0f) * MAX_BRIGHTNESS);
}

static void set_apa102_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

    uint8_t buf[4 + (NUM_SENSORS * 4)];
    buf[0] = 0x00;
    buf[1] = 0x00;
    buf[2] = 0x00;
    buf[3] = (uint8_t)(0xE0 | (brightness & 0x1F));

    for (int i = 0; i < NUM_SENSORS; i++) {
        int idx = 4 + (i * 4);
        buf[idx] = 0xE0;
        buf[idx + 1] = 0x00;
        buf[idx + 2] = 0x00;
        buf[idx + 3] = (uint8_t)(0xE0 | (brightness & 0x1F));
    }

    if (spiWrite(spi_handle, (char *)buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error: SPI write failed\n");
    }
}

static void fade_brightness(int target_brightness) {
    int current = 0;
    int step = (target_brightness > current) ? 1 : -1;
    int steps = FADE_MS / 10;
    for (int i = 0; i < steps && running; i++) {
        current += step;
        if (current > MAX_BRIGHTNESS) current = MAX_BRIGHTNESS;
        if (current < 0) current = 0;
        set_apa102_brightness(current);
        gpioDelay(10000);
    }
    set_apa102_brightness(target_brightness);
}

static void cleanup(void) {
    set_apa102_brightness(0);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    int sensor_addrs[NUM_SENSORS] = {BH1750_ADDR_LOW, BH1750_ADDR_HIGH};
    int valid_handles = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(1, sensor_addrs[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: BH1750 at 0x%02X not found (handle %d)\n", sensor_addrs[i], i2c_handles[i]);
            i2c_handles[i] = -1;
        } else {
            if (init_bh1750(i2c_handles[i]) < 0) {
                i2cClose(i2c_handles[i]);
                i2c_handles[i] = -1;
            } else {
                valid_handles++;
            }
        }
    }

    if (valid_handles == 0) {
        fprintf(stderr, "Error: No valid BH1750 sensors found. Exiting.\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int sum = 0;
        int count = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] >= 0) {
                int lux = read_bh1750(i2c_handles[i]);
                if (lux >= 0) {
                    sum += lux;
                    count++;
                }
            }
        }

        if (count == 0) {
            fprintf(stderr, "Error: No valid sensor readings, skipping cycle\n");
            gpioDelay(LOOP_DELAY_MS * 1000);
            continue;
        }

        int avg_lux = sum / count;
        int target_brightness = map_lux_to_brightness(avg_lux);
        fade_brightness(target_brightness);
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

