void set_led_brightness(int brightness);
void cleanup(void);
void signal_handler(int sig);

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (keep_running) {
        uint16_t raw;
        int retries = 0;
        int success = 0;

        // Retry loop for reading sensor
        while (retries < RETRY_COUNT && !success) {
            if (read_veml7700(i2c_fd, &raw) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < RETRY_COUNT) {
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }

        if (!success) {
            fprintf(stderr, "Failed to read VEML7700 after %d retries\n", RETRY_COUNT);
            // Continue with previous value or default? For simplicity, skip this iteration
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        float lux = calculate_lux(raw);
        int brightness = map_lux_to_brightness(lux);

        set_led_brightness(brightness);

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

int init_i2c(void) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(line, "veml7700_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        line = NULL;
        return -1;
    }
    return 0;
}

int init_veml7700(int fd) {
    // Configuration: 0x0000 = integration time 100ms, gain 1/8, no shutdown
    uint16_t config = 0x0000;
    uint8_t buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Failed to write VEML7700 config: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); // Wait 100ms for first integration
    return 0;
}

int read_veml7700(int fd, uint16_t *raw) {
    uint8_t reg = ALS_REG;
    uint8_t data[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write ALS register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }
    *raw = (data[0] << 8) | data[1];
    return 0;
}

float calculate_lux(uint16_t raw) {
    // Default settings: gain 1/8, integration time 100ms
    // lux = raw * 0.0036 * (1/gain) * (100ms/integration_time)
    // For default settings: lux = raw * 0.0288
    return (float)raw * 0.0288f;
}

int map_lux_to_brightness(float lux) {
    if (lux < 0.0f) lux = 0.0f;
    if (lux > MAX_LUX) lux = MAX_LUX;
    float normalized = lux / MAX_LUX;
    int brightness = (int)(normalized * MAX_BRIGHTNESS);
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return brightness;
}

void set_led_brightness(int brightness) {
    // Simple on/off control for WS2812B
    // In a real implementation, we would use bit-banging to drive the LED strip
    // For this example, we assume a single GPIO line is connected to the data pin
    // We set the line high for brightness > 0, low for 0
    gpiod_line_set_value(line, brightness > 0 ? 1 : 0);
}

void cleanup(void) {
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

