#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO_LED 17
#define BUFFER_SIZE 60
#define BH1750_CONT_HIGH_RES 0x10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

float read_bh1750(int fd) {
    if (i2c_write_cmd(fd, BH1750_CONT_HIGH_RES) < 0) return -1.0f;
    usleep(180000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1.0f;
    uint16_t raw = (buf[0] << 8) | buf[1];
    return (float)raw / 1.2f;
}

void add_to_buffer(float *buf, int size, float value) {
    for (int i = size - 1; i > 0; i--) {
        buf[i] = buf[i - 1];
    }
    buf[0] = value;
}

float calculate_average(float *buf, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += buf[i];
    }
    return sum / size;
}

int gpio_export(int pin) {
    char buf[64];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) return -1;
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    usleep(100000);
    return 0;
}

int gpio_unexport(int pin) {
    char buf[64];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) return -1;
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    if (write(fd, dir, strlen(dir)) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_write(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val = value ? '1' : '0';
    if (write(fd, &val, 1) < 0) {
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

