#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define CHIP_NAME "gpiochip0"

/* Segment patterns for digits 0-9 (common cathode, active high) */
static const unsigned char digit_patterns[10] = {
    0x3F, /* 0: a b c d e f */
    0x06, /* 1: b c */
    0x5B, /* 2: a b d e g */
    0x4F, /* 3: a b c d g */
    0x66, /* 4: b c f g */
    0x6D, /* 5: a c d f g */
    0x7D, /* 6: a c d e f g */
    0x07, /* 7: a b c */
    0x7F, /* 8: a b c d e f g */
    0x6F  /* 9: a b c d f g */
};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *data_line = NULL;
static struct gpiod_line *clock_line = NULL;
static struct gpiod_line *latch_line = NULL;

static void cleanup(void) {
    if (data_line)  gpiod_line_release(data_line);
    if (clock_line) gpiod_line_release(clock_line);
    if (latch_line) gpiod_line_release(latch_line);
    if (chip)       gpiod_chip_close(chip);
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    data_line  = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        cleanup();
        return -1;
    }

    if (gpiod_line_request_output(data_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(clock_line, "seven-seg", 0) < 0 ||
        gpiod_line_request_output(latch_line, "seven-seg", 0) < 0) {
        perror("gpiod_line_request_output");
        cleanup();
        return -1;
    }
    return 0;
}

/* Shift out 8 bits MSB-first, then latch to display */
static void shift_out(unsigned char data) {
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data_line, (data >> i) & 1);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
    }
    gpiod_line_set_value(latch_line, 1);
    usleep(1);
    gpiod_line_set_value(latch_line, 0);
}

static void display_digit(int digit) {
    if (digit < 0 || digit > 9) return;
    shift_out(digit_patterns[digit]);
}

int main(void) {
    if (setup_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    while (1) {
        display_digit(5);
        usleep(500000);
        display_digit(0);
        usleep(500000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

