#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5
#define DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    if (gpioWrite(LED_GPIO, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d to LOW.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(LED_GPIO, 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d HIGH.\n", LED_GPIO);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);

        if (!running) break;

        if (gpioWrite(LED_GPIO, 0) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d LOW.\n", LED_GPIO);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        time_sleep(DELAY_MS / 1000.0);
    }

    /* Clean shutdown: turn LED off and release pigpio resources */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

