#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000  /* 10 ms = 100 Hz */
#define STEP_NS       1000000   /* 1 ms granularity */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ns(long ns) {
    struct timespec req = { .tv_sec = 0, .tv_nsec = ns };
    while (clock_nanosleep(CLOCK_MONOTONIC, 0, &req, &req) == EINTR) {
        if (!running) break;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "rgb-pwm", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb-pwm", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb-pwm", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int r = rand() % 101;
        int g = rand() % 101;
        int b = rand() % 101;

        /* Software PWM: run one full period, then check running flag */
        long elapsed = 0;
        while (elapsed < PWM_PERIOD_NS && running) {
            int duty_r = (r * (PWM_PERIOD_NS - elapsed) / 100) / 100;
            int duty_g = (g * (PWM_PERIOD_NS - elapsed) / 100) / 100;
            int duty_b = (b * (PWM_PERIOD_NS - elapsed) / 100) / 100;

            if (duty_r > 0) {
                gpiod_line_set_value(red_line, 1);
                sleep_ns(duty_r);
                gpiod_line_set_value(red_line, 0);
                sleep_ns(duty_r);
            }
            if (duty_g > 0) {
                gpiod_line_set_value(green_line, 1);
                sleep_ns(duty_g);
                gpiod_line_set_value(green_line, 0);
                sleep_ns(duty_g);
            }
            if (duty_b > 0) {
                gpiod_line_set_value(blue_line, 1);
                sleep_ns(duty_b);
                gpiod_line_set_value(blue_line, 0);
                sleep_ns(duty_b);
            }
            elapsed += STEP_NS;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red_line)   gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line)  gpiod_line_release(blue_line);
    if (chip)       gpiod_chip_close(chip);
    return ret;
}

