#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C address (SA0 tied to GND) */
#define LSM303_ADDR 0x19

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A   0x28

/* GPIO pin for impact indicator */
#define GPIO_PIN 17

/* Default impact threshold in G */
#define DEFAULT_THRESHOLD 2.0

/* Sensitivity for 2G full-scale: 16384 LSB/G */
#define SENSITIVITY 16384.0

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a single byte to a register; returns 0 on success, -1 on error */
static int write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X (pigpio rc=%d)\n", value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read N bytes starting from a register; returns 0 on success, -1 on error */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading %u bytes from reg 0x%02X (rc=%d)\n", len, reg, rc);
        return -1;
    }
    return 0;
}

/* Initialize LSM303DLHC accelerometer */
static int init_accelerometer(int handle) {
    /* CTRL_REG1_A: 0x27 = 0b00100111
     *   ODR[3:0] = 100 (100 Hz), all axes enabled
     */
    if (write_reg(handle, CTRL_REG1_A, 0x27) != 0) return -1;

    /* CTRL_REG4_A: 0x00 = 0b00000000
     *   FS[1:0] = 00 (2G), BLE = 0 (no low-power)
     */
    if (write_reg(handle, CTRL_REG4_A, 0x00) != 0) return -1;

    return 0;
}

/* Read accelerometer data (6 bytes) and convert to G-force */
static int read_acceleration(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];

    /* Read 6 bytes starting at OUT_X_L_A with auto-increment (0x80) */
    if (read_block(handle, OUT_X_L_A | 0x80, buf, 6) != 0) return -1;

    /* Combine little-endian low/high pairs (little-endian on LSM303DLHC) */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* Convert to G-force: raw / sensitivity */
    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Calculate total G-force magnitude */
static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

/* Log impact data to file */
static void log_impact(float x, float y, float z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f G, Y: %.3f G, Z: %.3f G, Magnitude: %.3f G\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, magnitude);
    } else {
        fprintf(fp, "(timestamp error), X: %.3f G, Y: %.3f G, Z: %.3f G, Magnitude: %.3f G\n",
                x, y, z, magnitude);
    }

    fclose(fp);
}

/* Trigger impact indicator (pulse HIGH for 50 ms) */
static void trigger_indicator(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(50000); /* 50 ms in microseconds */
    gpioWrite(gpio_pin, 0);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;

    /* Parse command-line threshold */
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold '%s'. Using default %.2f G.\n", argv[1], DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    printf("Impact detection started. Threshold: %.2f G\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n", I2C_BUS, LSM303_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (init_accelerometer(i2c_handle) != 0) {
        fprintf(stderr, "Accelerometer initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main polling loop */
    while (running) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > threshold) {
            printf("Impact detected! Magnitude: %.3f G\n", magnitude);
            log_impact(x, y, z, magnitude);
            trigger_indicator(GPIO_PIN);
        }

        gpioDelay(100000); /* 10 Hz polling */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

