    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f G, Y: %.3f G, Z: %.3f G, Magnitude: %.3f G\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, magnitude);
    } else {
        fprintf(fp, "(timestamp error), X: %.3f G, Y: %.3f G, Z: %.3f G, Magnitude: %.3f G\n",
                x, y, z, magnitude);
    }

    fclose(fp);
}

/* Trigger impact indicator (pulse HIGH for 50 ms) */
static void trigger_indicator(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(50000); /* 50 ms in microseconds */
    gpioWrite(gpio_pin, 0);
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;

    /* Parse command-line threshold */
    if (argc > 1) {
        threshold = atof(argv[1]);
        if (threshold <= 0.0) {
            fprintf(stderr, "Invalid threshold '%s'. Using default %.2f G.\n", argv[1], DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    printf("Impact detection started. Threshold: %.2f G\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (pigpio rc=%d)\n", I2C_BUS, LSM303_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (init_accelerometer(i2c_handle) != 0) {
        fprintf(stderr, "Accelerometer initialization failed (sensor absent or bus error)\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output */
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main polling loop */
    while (running) {
        float x, y, z;

        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > threshold) {
            printf("Impact detected! Magnitude: %.3f G\n", magnitude);
            log_impact(x, y, z, magnitude);
            trigger_indicator(GPIO_PIN);
        }

        gpioDelay(100000); /* 10 Hz polling */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

