#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define LED_GPIO 18
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

#define REG_MODE 0x0D
#define REG_ALS_LSB 0x64
#define REG_ALS_MSB 0x65
#define REG_RED_LSB 0x66
#define REG_GREEN_LSB 0x68
#define REG_BLUE_LSB 0x6A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg(uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(uint8_t lsb_reg, uint16_t *out) {
    char reg = (char)lsb_reg;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", lsb_reg);
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed\n", lsb_reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[1] << 8) | (uint8_t)data[0];
    return 0;
}

static int init_adpd188bi(void) {
    if (i2c_write_reg(REG_MODE, 0x01) != 0) {
        fprintf(stderr, "Failed to set ADPD188BI normal mode\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file);
}

static void set_led_brightness(uint16_t als) {
    uint8_t duty = (uint8_t)((als * 255) / 65535);
    gpioPWM(LED_GPIO, duty);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_adpd188bi() != 0) {
        fprintf(stderr, "ADPD188BI initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 1000);
    gpioPWM(LED_GPIO, 0);

    log_file = fopen("color_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open color_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting ADPD188BI color logging...\n");

    while (!terminate) {
        uint16_t als, red, green, blue;

        if (i2c_read_reg16(REG_ALS_LSB, &als) != 0 ||
            i2c_read_reg16(REG_RED_LSB, &red) != 0 ||
            i2c_read_reg16(REG_GREEN_LSB, &green) != 0 ||
            i2c_read_reg16(REG_BLUE_LSB, &blue) != 0) {
            fprintf(stderr, "Sensor read error, retrying in 100 ms...\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        log_data(als, red, green, blue);
        set_led_brightness(als);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioPWM(LED_GPIO, 0);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

