        fprintf(stderr, "Error: I2C write failed for register 0x%02X (rc=%d)\n",
                reg, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the FXOS8700CQ accelerometer/magnetometer                */
/* ------------------------------------------------------------------ */
static int initialize_fxos8700(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (read_register(handle, FXOS8700_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr,
                "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit (CTRL_REG1 bit 0) */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set standby mode.\n");
        return -1;
    }

    /* Set ±2g range (XYZ_DATA_CFG = 0x00) */
    if (write_register(handle, FXOS8700_XYZ_DATA_CFG, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set data range.\n");
        return -1;
    }

    /* Active mode, 200 Hz ODR: set ACTIVE bit (CTRL_REG1 bit 0) */
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set active mode.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (14-bit left-justified)           */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle,
                             float *x, float *y, float *z)
{
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Point to OUT_X_MSB and read 6 consecutive bytes */
    int rc = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6);
    if (rc != 6) {
        fprintf(stderr, "Error: I2C block read failed (rc=%d).\n", rc);
        return -1;
    }

    /* Assemble 16-bit values (14-bit left-justified) */
    raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]);
    raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]);
    raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]);

    /* Right-shift by 2 to get 14-bit value */
    raw_x >>= 2;
    raw_y >>= 2;
    raw_z >>= 2;

    /* Convert to g: raw counts / sensitivity * g/count */
    *x = (float)raw_x / ACCEL_SENSITIVITY * 9.81f;
    *y = (float)raw_y / ACCEL_SENSITIVITY * 9.81f;
    *z = (float)raw_z / ACCEL_SENSITIVITY * 9.81f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute magnitude of acceleration vector                            */
/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Log an impact event to the impact log file                           */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    FILE *fp = fopen(IMPACT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", IMPACT_LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, x, y, z, magnitude);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the FXOS8700CQ address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDRESS, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (initialize_fxos8700(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: FXOS8700CQ initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");
    printf("Threshold: %.2f m/s^2 (2g)\n", IMPACT_THRESHOLD_MPS);

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            float magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD_MPS) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        }
        /* On read error, we continue the loop; do not crash */

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

