#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I_REG   0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define GYRO_SENSITIVITY 0.00875f
#define THRESHOLD_DPS  50.0f
#define LOG_FILE       "gyro_log.txt"
#define SAMPLE_PERIOD_US 50000
#define CALIB_SAMPLES  100

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;
static FILE *g_log = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "i2c_read_block read(0x%02X, %d) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gyro(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I_REG, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L | 0x80, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx * GYRO_SENSITIVITY;
    *y = (float)ry * GYRO_SENSITIVITY;
    *z = (float)rz * GYRO_SENSITIVITY;
    return 0;
}

static int calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off) {
    float sx = 0, sy = 0, sz = 0;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        float x, y, z;
        if (read_gyro(fd, &x, &y, &z) < 0) return -1;
        sx += x; sy += y; sz += z;
        usleep(10000);
    }
    *x_off = sx / CALIB_SAMPLES;
    *y_off = sy / CALIB_SAMPLES;
    *z_off = sz / CALIB_SAMPLES;
    printf("Calibration offsets: X=%.3f Y=%.3f Z=%.3f dps\n",
           *x_off, *y_off, *z_off);
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log) { fclose(g_log); g_log = NULL; }
    if (g_fd >= 0) { close(g_fd); g_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                GYRO_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (init_gyro(g_fd) < 0) {
        fprintf(stderr, "Gyro init failed\n");
        cleanup();
        return 1;
    }

    float x_off = 0, y_off = 0, z_off = 0;
    if (calibrate_gyro(g_fd, &x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Calibration failed\n");
        cleanup();
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Logging to %s at 20 Hz. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        float x, y, z;
        if (read_gyro(g_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }
        x -= x_off; y -= y_off; z -= z_off;
        log_data(g_log, x, y, z);
        if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS || fabsf(z) > THRESHOLD_DPS) {
            fprintf(stderr, "ALERT: X=%.2f Y=%.2f Z=%.2f dps\n", x, y, z);
            fprintf(g_log, "#ALERT: X=%.2f Y=%.2f Z=%.2f dps\n", x, y, z);
            fflush(g_log);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return 0;
}

