#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28
#define LSM303_MAG_MR_REG_M      0x02
#define LSM303_MAG_OUT_X_H_M     0x03

/* Scaling factors */
#define ACCEL_SCALE 0.000244f  /* 2 g / 4096 */
#define MAG_SCALE   0.00014f   /* 1.3 gauss / 4096 */

static volatile sig_atomic_t running = 1;
static int i2c_accel = -1;
static int i2c_mag   = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm303(void) {
    if (i2cWriteByteData(i2c_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_accel, LSM303_ACCEL_OUT_X_L_A | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static int read_mag(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_mag, LSM303_MAG_OUT_X_H_M, buf, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_z = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_y = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

static float calculate_heading(float ax, float ay, float az,
                               float mx, float my, float mz) {
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float cy = cosf(pitch);
    if (cy > 0.0001f) {
        float xh = mx * cosf(pitch) + mz * sinf(pitch);
        float yh = mx * sinf(roll) * sinf(pitch) +
                   my * cosf(roll) -
                   mz * sinf(roll) * cosf(pitch);
        return atan2f(yh, xh) * 180.0f / M_PI;
    }
    return 0.0f;
}

static void log_data(float heading, float ax, float ay, float az,
                     float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_accel < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer: %d\n", i2c_accel);
        gpioTerminate();
        return 1;
    }

    i2c_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_mag < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer: %d\n", i2c_mag);
        i2cClose(i2c_accel);
        gpioTerminate();
        return 1;
    }

    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        i2cClose(i2c_accel);
        i2cClose(i2c_mag);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *fp = fopen("compass_log.txt", "r");
    int write_header = (fp == NULL);
    if (fp) fclose(fp);
    if (write_header) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
            fclose(fp);
        }
    }

    while (running) {
        float ax, ay, az, mx, my, mz;
        if (read_accel(&ax, &ay, &az) < 0 || read_mag(&mx, &my, &mz) < 0) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }
        float heading = calculate_heading(ax, ay, az, mx, my, mz);
        log_data(heading, ax, ay, az, mx, my, mz);
        gpioDelay(100000);
    }

    i2cClose(i2c_accel);
    i2cClose(i2c_mag);
    gpioTerminate();
    return 0;
}

