#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL6180X_ADDR 0x29
#define LOG_FILE "distance_log.txt"
#define DISTANCE_THRESHOLD 100
#define SAMPLE_INTERVAL_US 100000

/* VL6180X register addresses */
#define REG_SYSRANGE_START 0x000
#define REG_RESULT_RANGE_STATUS 0x04d
#define REG_SYSTEM_INTERRUPT_CONFIG 0x014
#define REG_SYSTEM_INTERRUPT_CLEAR 0x015
#define REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define REG_SYSRANGE_CONFIG_A 0x0207

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg16(int handle, uint16_t reg, uint16_t val) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int read_reg16(int handle, uint16_t reg, uint16_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int init_vl6180x(int handle) {
    uint16_t fresh;
    if (read_reg16(handle, REG_SYSTEM_FRESH_OUT_OF_RESET, &fresh) < 0) {
        fprintf(stderr, "Error: cannot read fresh-out-of-reset register.\n");
        return -1;
    }
    if (fresh != 0x01) {
        fprintf(stderr, "Warning: sensor not fresh out of reset (0x%04x). Continuing anyway.\n", fresh);
    }

    /* Mandatory init sequence from ST datasheet / Adafruit VL6180X library */
    if (write_reg16(handle, 0x0207, 0x01) < 0) return -1;
    if (write_reg16(handle, 0x0208, 0x01) < 0) return -1;
    if (write_reg16(handle, 0x0096, 0x00) < 0) return -1;
    if (write_reg16(handle, 0x0097, 0xfd) < 0) return -1;
    if (write_reg16(handle, 0x00e3, 0x00) < 0) return -1;
    if (write_reg16(handle, 0x00e4, 0x04) < 0) return -1;
    if (write_reg16(handle, 0x00e5, 0x02) < 0) return -1;
    if (write_reg16(handle, 0x00e6, 0x01) < 0) return -1;
    if (write_reg16(handle, 0x00e7, 0x03) < 0) return -1;
    if (write_reg16(handle, 0x00f5, 0x02) < 0) return -1;
    if (write_reg16(handle, 0x00d9, 0x05) < 0) return -1;
    if (write_reg16(handle, 0x00db, 0xce) < 0) return -1;
    if (write_reg16(handle, 0x00dc, 0x03) < 0) return -1;
    if (write_reg16(handle, 0x00dd, 0xf8) < 0) return -1;
    if (write_reg16(handle, 0x009f, 0x00) < 0) return -1;
    if (write_reg16(handle, 0x00a3, 0x3c) < 0) return -1;
    if (write_reg16(handle, 0x00b7, 0x00) < 0) return -1;
    if (write_reg16(handle, 0x00bb, 0x3c) < 0) return -1;
    if (write_reg16(handle, 0x00b2, 0x09) < 0) return -1;
    if (write_reg16(handle, 0x00ca, 0x09) < 0) return -1;
    if (write_reg16(handle, 0x0198, 0x01) < 0) return -1;
    if (write_reg16(handle, 0x01b0, 0x17) < 0) return -1;
    if (write_reg16(handle, 0x01ad, 0x00) < 0) return -1;
    if (write_reg16(handle, 0x00ff, 0x05) < 0) return -1;
    if (write_reg16(handle, 0x0100, 0x05) < 0) return -1;
    if (write_reg16(handle, 0x0199, 0x05) < 0) return -1;
    if (write_reg16(handle, 0x01a6, 0x1b) < 0) return -1;
    if (write_reg16(handle, 0x01ac, 0x3e) < 0) return -1;
    if (write_reg16(handle, 0x01a7, 0x1f) < 0) return -1;
    if (write_reg16(handle, 0x0030, 0x00) < 0) return -1;

    /* Clear any pending interrupts */
    if (write_reg16(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x07) < 0) return -1;

    return 0;
}

static int read_distance(int handle) {
    uint16_t status;
    uint16_t range;

    /* Start a single range measurement */
    if (write_reg16(handle, REG_SYSRANGE_START, 0x01) < 0) return -1;

    /* Poll for completion (poll bit 0 of REG_RESULT_RANGE_STATUS) */
    for (int i = 0; i < 50; i++) {
        if (read_reg16(handle, REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(2000); /* 2 ms */
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Error: range measurement timeout.\n");
        return -1;
    }

    /* Read range value */
    if (read_reg16(handle, 0x0062, &range) < 0) return -1;

    /* Check error bits (bits 4-7 of status) */
    if (status & 0x0F) {
        fprintf(stderr, "Error: range status error bits set (0x%04x).\n", status);
        return -1;
    }

    return (int)range;
}

static void log_data(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02x: %d\n", I2C_BUS, VL6180X_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_vl6180x(i2c_handle) < 0) {
        fprintf(stderr, "VL6180X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("VL6180X initialized. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (running) {
        int distance = read_distance(i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Attempting re-initialization...\n");
            log_data("SENSOR_ERROR");
            gpioDelay(1000000);
            if (init_vl6180x(i2c_handle) < 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                break;
            }
            continue;
        }

        if (distance < DISTANCE_THRESHOLD) {
            log_data("DOOR_OPEN");
            printf("DOOR_OPEN (%d mm)\n", distance);
        } else {
            log_data("DOOR_CLOSED");
            printf("DOOR_CLOSED (%d mm)\n", distance);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return 0;
}

