#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_INTERVAL_US 10000
#define AUDIO_REG 0x01
#define CTRL_REG 0x00
#define CTRL_MEASURE_CMD 0x80
#define LOG_FILE "audio_log.dat"

static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_MEASURE_CMD) < 0) {
        fprintf(stderr, "Error writing control register to handle %d: %s\n", handle, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_audio_sample(int handle, int16_t *sample) {
    int raw = i2cReadWordData(handle, AUDIO_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading audio data from handle %d: %s\n", handle, strerror(errno));
        return -1;
    }
    *sample = (int16_t)raw;
    return 0;
}

static void log_data(struct timespec ts, int16_t s1, int16_t s2, int32_t tdoa) {
    if (log_file) {
        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1 (0x%02X): %s\n", SENSOR1_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2 (0x%02X): %s\n", SENSOR2_ADDR, strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) != 0 || init_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (!terminate) {
        int16_t s1 = 0, s2 = 0;
        struct timespec ts;

        if (read_audio_sample(i2c_handle1, &s1) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_audio_sample(i2c_handle2, &s2) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        int32_t tdoa = (int32_t)s1 - (int32_t)s2;
        log_data(ts, s1, s2, tdoa);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

