        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (!terminate) {
        int16_t s1 = 0, s2 = 0;
        struct timespec ts;

        if (read_audio_sample(i2c_handle1, &s1) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        if (read_audio_sample(i2c_handle2, &s2) != 0) {
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            perror("clock_gettime");
            gpioDelay(SAMPLE_INTERVAL_US);
