/*
 * ADIS16488A IMU SPI reader for Raspberry Pi 4 Model B
 * Library : pigpio (SPI)
 * Wiring  : SPI0 MOSI=G11, MISO=G9, SCLK=G10, CE0=G8 (pigpio SPI channel 0)
 *           VDD=3V3, GND=GND
 * Build   : gcc -O2 -Wall -o imu_log imu_log.c -lpigpio -lrt
 * Run     : sudo ./imu_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16488A register map (per datasheet) ---- */
#define REG_X_GYRO  0x04
#define REG_Y_GYRO  0x06
#define REG_Z_GYRO  0x08
#define REG_X_ACCEL 0x0A
#define REG_Y_ACCEL 0x0C
#define REG_Z_ACCEL 0x0E

/* ---- SPI configuration ---- */
#define SPI_CHANNEL 0          /* CE0 on GPIO8 */
#define SPI_SPEED   1000000    /* 1 MHz */
#define SPI_FLAGS   0b11000000000  /* mode 3: CPOL=1, CPHA=1, aux SPI off */
#define READ_DELAY_US 40       /* >40 us between request and data-retrieval */

/* ---- Sensitivities ---- */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* ---- Globals for cleanup ---- */
static int  spi_handle = -1;
static FILE *fp        = NULL;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static int  read_register(uint8_t reg, int16_t *out);
static int  read_gyro(float *x, float *y, float *z);
static int  read_accel(float *x, float *y, float *z);
static void log_data(float gx, float gy, float gz, float ax, float ay, float az);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------------------------------------------ */
/*  Read one 16-bit register from the ADIS16488A                       */
/*  Returns 0 on success, -1 on SPI error.                             */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];

    /*
     * ADIS16488A SPI read protocol (mode 3, MSB-first):
     *   tx[0] = 0x00                       (don't-care)
     *   tx[1] = 0x80 | (reg & 0x7F)        (read bit + 7-bit reg addr)
     * The 16-bit word returned on the *next* transfer contains:
     *   rx[0] = [don't care][reg data MSB]
     *   rx[1] = [reg data LSB][don't care]
     */
    tx[0] = 0x00;
    tx[1] = (char)(0x80 | (reg & 0x7F));

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Data is in the lower 7 bits of rx[1] (MSB) and rx[0] (LSB) */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Read all three gyroscope axes                                      */
/* ------------------------------------------------------------------ */
static int read_gyro(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (read_register(REG_X_GYRO, &raw_x) != 0) return -1;
    if (read_register(REG_Y_GYRO, &raw_y) != 0) return -1;
    if (read_register(REG_Z_GYRO, &raw_z) != 0) return -1;

    *x = (float)raw_x * GYRO_SENSITIVITY;
    *y = (float)raw_y * GYRO_SENSITIVITY;
    *z = (float)raw_z * GYRO_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Read all three accelerometer axes                                  */
/* ------------------------------------------------------------------ */
static int read_accel(float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (read_register(REG_X_ACCEL, &raw_x) != 0) return -1;
    if (read_register(REG_Y_ACCEL, &raw_y) != 0) return -1;
    if (read_register(REG_Z_ACCEL, &raw_z) != 0) return -1;

    *x = (float)raw_x * ACCEL_SENSITIVITY;
    *y = (float)raw_y * ACCEL_SENSITIVITY;
    *z = (float)raw_z * ACCEL_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/*  Append one CSV row with a millisecond-precision timestamp          */
/* ------------------------------------------------------------------ */
static void log_data(float gx, float gy, float gz, float ax, float ay, float az)
{
    struct timespec ts;
    struct tm tm_info;
    char ts_buf[40];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(ts_buf + strlen(ts_buf),
             sizeof(ts_buf) - strlen(ts_buf),
             ".%03ld", ts.tv_nsec / 1000000L);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            ts_buf, gx, gy, gz, ax, ay, az);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/*  Release all resources                                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Signal handler — set flag so main loop exits promptly              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/*  Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- SPI open ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d, flags 0x%X): %d\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- CSV file ---- */
    fp = fopen("imu_data.csv", "w");
    if (!fp) {
        perror("fopen(\"imu_data.csv\")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(fp);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- atexit for cleanup ---- */
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Warning: atexit(cleanup) failed\n");
    }

    /* ---- Main sampling loop ---- */
    while (running) {
        float gx, gy, gz, ax, ay, az;

        if (read_gyro(&gx, &gy, &gz) != 0) {
            fprintf(stderr, "Gyro read error — skipping sample\n");
        } else if (read_accel(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accel read error — skipping sample\n");
        } else {
            log_data(gx, gy, gz, ax, ay, az);
        }

        /* Non-blocking 100 ms delay so signals are caught promptly */
        for (int i = 0; i < 10 && running; i++)
            gpioDelay(10000); /* 10 ms slices */
    }

    return EXIT_SUCCESS;
}

