#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8

#define REG_XGYRO_OUT 0x04
#define REG_YGYRO_OUT 0x06
#define REG_ZGYRO_OUT 0x08
#define REG_XACCL_OUT 0x0A
#define REG_YACCL_OUT 0x0C
#define REG_ZACCL_OUT 0x0E

#define GYRO_SCALE 0.02f
#define ACCL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_register(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }
    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }
    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    *value = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(cs_line, "adis16448_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        goto cleanup_chip;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup_cs;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup_spi;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup_spi;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup_spi;
    }

    printf("ADIS16448 SPI reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_xg, raw_yg, raw_zg, raw_xa, raw_ya, raw_za;

        if (read_register(spi_fd, cs_line, REG_XGYRO_OUT, &raw_xg) < 0 ||
            read_register(spi_fd, cs_line, REG_YGYRO_OUT, &raw_yg) < 0 ||
            read_register(spi_fd, cs_line, REG_ZGYRO_OUT, &raw_zg) < 0 ||
            read_register(spi_fd, cs_line, REG_XACCL_OUT, &raw_xa) < 0 ||
            read_register(spi_fd, cs_line, REG_YACCL_OUT, &raw_ya) < 0 ||
            read_register(spi_fd, cs_line, REG_ZACCL_OUT, &raw_za) < 0) {
            fprintf(stderr, "Error reading IMU data. Retrying...\n");
            usleep(100000);
            continue;
        }

        float gx = (float)raw_xg * GYRO_SCALE;
        float gy = (float)raw_yg * GYRO_SCALE;
        float gz = (float)raw_zg * GYRO_SCALE;
        float ax = (float)raw_xa * ACCL_SCALE;
        float ay = (float)raw_ya * ACCL_SCALE;
