#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* Scaling factors (from ADIS16448 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.00025f /* g/LSB */

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_FLAGS   0       /* Mode 0, active-low CE */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ADIS16448 SPI read requires a two-cycle transfer:
 *   Cycle 1: send read command (register address | 0x8000)
 *   Cycle 2: send dummy 0x0000 to clock out the 16-bit data
 *
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int adis_read_register(uint16_t reg, int16_t *value) {
    char tx_cmd[2];
    char rx_cmd[2];
    char tx_dummy[2] = {0x00, 0x00};
    char rx_data[2];

    /* Cycle 1: send read command */
    tx_cmd[0] = (reg >> 8) & 0xFF;
    tx_cmd[1] = reg & 0xFF;

    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for read command (reg 0x%02X)\n", reg);
        return -1;
    }

    /* Stall time per ADIS16448 datasheet */
    gpioDelay(40);

    /* Cycle 2: dummy transfer to clock out data */
    if (spiXfer(spi_handle, tx_dummy, rx_data, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for data read (reg 0x%02X)\n", reg);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(rx_data[0] & 0xFF) << 8) | (uint8_t)rx_data[1]);
    return 0;
}

static int read_gyro_x(float *x) {
    int16_t raw;
    if (adis_read_register(X_GYRO_OUT, &raw) != 0) return -1;
    *x = (float)raw * GYRO_SCALE;
    return 0;
}

static int read_gyro_y(float *y) {
    int16_t raw;
    if (adis_read_register(Y_GYRO_OUT, &raw) != 0) return -1;
    *y = (float)raw * GYRO_SCALE;
    return 0;
}

static int read_gyro_z(float *z) {
    int16_t raw;
    if (adis_read_register(Z_GYRO_OUT, &raw) != 0) return -1;
    *z = (float)raw * GYRO_SCALE;
    return 0;
}

static int read_accl_x(float *x) {
    int16_t raw;
    if (adis_read_register(X_ACCL_OUT, &raw) != 0) return -1;
    *x = (float)raw * ACCL_SCALE;
    return 0;
}

static int read_accl_y(float *y) {
    int16_t raw;
    if (adis_read_register(Y_ACCL_OUT, &raw) != 0) return -1;
    *y = (float)raw * ACCL_SCALE;
    return 0;
}

static int read_accl_z(float *z) {
    int16_t raw;
    if (adis_read_register(Z_ACCL_OUT, &raw) != 0) return -1;
    *z = (float)raw * ACCL_SCALE;
    return 0;
}

int main(void) {
    float gyro_x, gyro_y, gyro_z;
    float accl_x, accl_y, accl_z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 IMU reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int err = 0;

        if (read_gyro_x(&gyro_x) != 0) err = 1;
        if (read_gyro_y(&gyro_y) != 0) err = 1;
        if (read_gyro_z(&gyro_z) != 0) err = 1;
        if (read_accl_x(&accl_x) != 0) err = 1;
        if (read_accl_y(&accl_y) != 0) err = 1;
        if (read_accl_z(&accl_z) != 0) err = 1;

        if (err) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s  "
                   "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
                   gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

