#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6886_ADDR 0x68
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x86
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((uint16_t)high << 8 | (uint16_t)low);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access for 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        close(fd);
        return 1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X. Sensor not present?\n", WHO_AM_I_VAL, who_am_i);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6886.\n");
        close(fd);
        return 1;
    }
    usleep(100000);

    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer.\n");
        close(fd);
        return 1;
    }
    if (i2c_write_reg(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure gyroscope.\n");
        close(fd);
        return 1;
    }

    printf("MPU-6886 initialized. Reading accelerometer and gyroscope data...\n");

    while (running) {
        uint8_t accel_buf[6];
        uint8_t gyro_buf[6];

        int accel_ok = 0, gyro_ok = 0;
        for (int attempt = 0; attempt < 3 && (running || accel_ok || gyro_ok); attempt++) {
            if (!accel_ok) {
                if (i2c_read_burst(fd, ACCEL_XOUT_H, accel_buf, 6) == 0) {
                    accel_ok = 1;
                } else {
                    usleep(1000);
                }
            }
            if (!gyro_ok) {
                if (i2c_read_burst(fd, GYRO_XOUT_H, gyro_buf, 6) == 0) {
                    gyro_ok = 1;
                } else {
                    usleep(1000);
                }
            }
        }

        if (!accel_ok || !gyro_ok) {
            fprintf(stderr, "Failed to read sensor data after retries.\n");
            break;
        }

        int16_t accel_x = combine_bytes(accel_buf[0], accel_buf[1]);
        int16_t accel_y = combine_bytes(accel_buf[2], accel_buf[3]);
        int16_t accel_z = combine_bytes(accel_buf[4], accel_buf[5]);
        int16_t gyro_x = combine_bytes(gyro_buf[0], gyro_buf[1]);
        int16_t gyro_y = combine_bytes(gyro_buf[2], gyro_buf[3]);
        int16_t gyro_z = combine_bytes(gyro_buf[4], gyro_buf[5]);

        printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        usleep(50000);
    }

    printf("\nExiting gracefully...\n");
    close(fd);
    return 0;
}

