#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDRESS 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32
#define ADXL345_FIFO_CTL    0x38

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* Full resolution, +-2g range => 256 LSB/g */
#define ADXL345_SCALE_FACTOR 256.0f

/* Impact threshold (2.5 g) */
#define IMPACT_THRESHOLD 2.5f

/* LED GPIO pin */
#define LED_PIN 17

/* Polling interval (microseconds) */
#define POLL_INTERVAL_US 10000

/* LED on duration (microseconds) */
#define LED_ON_US 500000

/* Log file path */
#define LOG_FILE "impact_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a byte to an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error: I2C write failed (reg 0x%02X, val 0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

/* Read a byte from an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error: I2C read failed (reg 0x%02X)\n", reg);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* Initialize the ADXL345: verify device ID, set full-resolution +-2g, enable measurement. */
static int adxl345_init(int handle) {
    uint8_t devid = 0;

    if (adxl345_read_reg(handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Error: Cannot read ADXL345 device ID (sensor absent or bus error)\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: Unexpected device ID 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x00) != 0) return -1;

    /* Full resolution, +-2g range */
    if (adxl345_write_reg(handle, ADXL345_DATA_FORMAT, 0x0B) != 0) return -1;

    /* Enable measurement mode */
    if (adxl345_write_reg(handle, ADXL345_POWER_CTL, 0x08) != 0) return -1;

    return 0;
}

/* Read 6 bytes of acceleration data (DATAX0..DATAZ1). */
static int adxl345_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read 6-byte acceleration block\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    return 0;
}

/* Compute total acceleration magnitude in g. */
static float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float xg = (float)x / ADXL345_SCALE_FACTOR;
    float yg = (float)y / ADXL345_SCALE_FACTOR;
    float zg = (float)z / ADXL345_SCALE_FACTOR;
    return sqrtf(xg * xg + yg * yg + zg * zg);
}

/* Log an impact event to the log file. */
static void log_impact(FILE *fp, float magnitude, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s - Impact detected: magnitude=%.2f g, X=%d, Y=%d, Z=%d\n",
            timestamp, magnitude, x, y, z);
    fflush(fp);
}

int main(void) {
    int i2c_handle = -1;
    FILE *log_file = NULL;
    int ret_code = EXIT_FAILURE;

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADXL345 address */
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        goto cleanup_gpio;
    }

    /* Initialize the ADXL345 */
    if (adxl345_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        goto cleanup_i2c;
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", LED_PIN);
        goto cleanup_i2c;
    }
    gpioWrite(LED_PIN, 0);

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: fopen failed for log file");
        goto cleanup_i2c;
    }

    printf("ADXL345 impact detection started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        int16_t x, y, z;

        if (adxl345_read_accel(i2c_handle, &x, &y, &z) != 0) {
            /* Bus error or sensor absent: wait and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float magnitude = calculate_magnitude(x, y, z);

        if (magnitude > IMPACT_THRESHOLD) {
            /* Turn on the LED */
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_US);
            gpioWrite(LED_PIN, 0);

            /* Log the impact */
            log_impact(log_file, magnitude, x, y, z);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    ret_code = EXIT_SUCCESS;

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
cleanup_i2c:
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
cleanup_gpio:
    gpioTerminate();

    return ret_code;
}

