#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I       0x75
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define GYRO_CONFIG    0x1B
#define ACCEL_XOUT_H   0x3B
#define GYRO_XOUT_H    0x43

/* Expected WHO_AM_I value for ICM-20602 */
#define ICM20602_WHO_AM_I 0x12

/* Scaling factors for default ranges (+/-2g and +/-250 dps) */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_imu(void) {
    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != ICM20602_WHO_AM_I) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, ICM20602_WHO_AM_I);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Set accelerometer range to +/-2g (AFS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG\n");
        return -1;
    }

    /* Set gyroscope range to +/-250 dps (FS_SEL = 0) */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

static int read_imu_data(imu_data_t *data) {
    char buf[6];

    /* Burst read 6 bytes of accelerometer data (X, Y, Z high and low) */
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }
    int16_t raw_accel_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_accel_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
