#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8451_ADDR   0x1D
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x1A
#define OUT_X_MSB      0x01
#define OUT_X_LSB      0x02
#define OUT_Y_MSB      0x03
#define OUT_Y_LSB      0x04
#define OUT_Z_MSB      0x05
#define OUT_Z_LSB      0x06
#define CTRL_REG1      0x2A
#define CTRL_REG2      0x2B
#define LED_GPIO_LINE  17
#define IMPACT_THRESH  2.0f
#define POLL_MS        100
#define LED_ON_MS      500
#define SCALE_FACTOR   1024.0f

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C burst read (reg 0x%02X, len %d) failed: %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int mma8451_init(int fd) {
    uint8_t who;
    if (i2c_read_reg(fd, WHO_AM_I, &who) < 0) return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG2, 0x40) < 0) return -1;
    return 0;
}

static int read_accel(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_MSB, buf, 6) < 0) return -1;
    int16_t rx = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t ry = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t rz = (int16_t)((buf[4] << 8) | buf[5]);
    *x = (float)rx / SCALE_FACTOR;
    *y = (float)ry / SCALE_FACTOR;
    *z = (float)rz / SCALE_FACTOR;
    return 0;
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, X: %.2f, Y: %.2f, Z: %.2f\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", MMA8451_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (mma8451_init(i2c_fd) < 0) {
        fprintf(stderr, "MMA8451 init failed\n");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(led, "mma8451_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("MMA8451 impact monitor running. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (fabsf(x) > IMPACT_THRESH || fabsf(y) > IMPACT_THRESH || fabsf(z) > IMPACT_THRESH) {
            printf("Impact detected! X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
            gpiod_line_set_value(led, 1);
            log_impact(x, y, z);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

