    printf("MMA8451 impact monitor running. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;
        if (read_accel(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, continuing...\n");
            usleep(POLL_MS * 1000);
            continue;
        }
        if (fabsf(x) > IMPACT_THRESH || fabsf(y) > IMPACT_THRESH || fabsf(z) > IMPACT_THRESH) {
            printf("Impact detected! X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
            gpiod_line_set_value(led, 1);
            log_impact(x, y, z);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

