#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE    "/dev/i2c-1"
#define TMAG5273_ADDR 0x35
#define X_REG         0x10
#define Y_REG         0x11
#define Z_REG         0x12
#define LOG_FILE      "magnetic_field_log.csv"
#define SAMPLE_US     1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then read 2 bytes (little-endian). */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static int read_magnetic_field(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, X_REG, x) != 0) return -1;
    if (i2c_read_reg16(fd, Y_REG, y) != 0) return -1;
    if (i2c_read_reg16(fd, Z_REG, z) != 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    int16_t x, y, z;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                TMAG5273_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_fp);
        if (sz == 0) {
            fprintf(g_log_fp, "timestamp,x,y,z\n");
            fflush(g_log_fp);
        }
    } else {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
    }

    printf("Logging TMAG5273 magnetic field data to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        if (read_magnetic_field(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log_fp, x, y, z);
        } else {
            fprintf(stderr, "Sensor read error; continuing.\n");
        }
        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) != 0) {
            fprintf(stderr, "close(i2c) failed: %s\n", strerror(errno));
        }
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

