    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", ADXL345_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (adxl345_init(i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 init failed\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (gpiod_line_request_falling_edge_events(line, "adxl345_freefall") < 0) {
        fprintf(stderr, "Cannot request falling edge events on GPIO%d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    fprintf(log_fp, "timestamp,x,y,z\n");
    fflush(log_fp);

    printf("Freefall detection running. Press Ctrl+C to exit.\n");

    while (running) {
        struct pollfd pfd = { .fd = gpiod_line_event_get_fd(line), .events = POLLIN };
        int pr = poll(&pfd, 1, 1000);
        if (pr < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "poll error: %s\n", strerror(errno));
            break;
        }
        if (pr == 0) continue;

        struct gpiod_line_event ev;
        if (gpiod_line_event_read(line, &ev) < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "gpiod_line_event_read error: %s\n", strerror(errno));
            break;
        }
        if (ev.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        uint8_t intsrc;
        if (i2c_read_reg8(i2c_fd, REG_INT_SOURCE, &intsrc) < 0) continue;
        if (!(intsrc & 0x04)) continue;

        uint8_t buf[6];
        if (i2c_read_block(i2c_fd, REG_DATAX0, buf, 6) < 0) continue;

        int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
        int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
        int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

        log_data(log_fp, x, y, z);
        printf("Freefall detected: X=%d Y=%d Z=%d\n", x, y, z);
    }

    if (i2c_fd >= 0) {
        i2c_write_reg8(i2c_fd, REG_INT_ENABLE, 0x00);
        i2c_write_reg8(i2c_fd, REG_POWER_CTL, 0x00);
        close(i2c_fd);
    }
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    printf("\nExiting cleanly.\n");
    return 0;
}

