#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6A
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_SCALE 0.000244f
#define GYRO_SCALE 0.00875f

#define FREEFALL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define IMPACT_WINDOW 1.0

#define STATE_IDLE 0
#define STATE_FREEFALL 1
#define STATE_IMPACT 2

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_lsm6dsr(void) {
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer ODR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope ODR.\n");
        return -1;
    }
    return 0;
}

static int read_accel_gyro(float *ax, float *ay, float *az, float *gx, float *gy, float *gz) {
    char buf[12];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buf, 12) < 0) {
        fprintf(stderr, "Error: Could not read gyro data.\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buf, 12) < 0) {
        fprintf(stderr, "Error: Could not read accel data.\n");
        return -1;
    }
    int16_t raw_ax = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_ay = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_az = (int16_t)((buf[5] << 8) | buf[4]);
    int16_t raw_gx = (int16_t)((buf[7] << 8) | buf[6]);
    int16_t raw_gy = (int16_t)((buf[9] << 8) | buf[8]);
    int16_t raw_gz = (int16_t)((buf[11] << 8) | buf[10]);
    *ax = raw_ax * ACCEL_SCALE;
    *ay = raw_ay * ACCEL_SCALE;
    *az = raw_az * ACCEL_SCALE;
    *gx = raw_gx * GYRO_SCALE;
    *gy = raw_gy * GYRO_SCALE;
    *gz = raw_gz * GYRO_SCALE;
    return 0;
}

static void log_data(float ax, float ay, float az, float gx, float gy, float gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n", timestamp, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at 0x%02X.\n", LSM6DSR_ADDR);
        gpioTerminate();
        return 1;
    }
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). Sensor absent or wrong address.\n", who, WHO_AM_I_VAL);
        cleanup();
        return 1;
    }
    if (init_lsm6dsr() < 0) {
        cleanup();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        cleanup();
        return 1;
    }
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    float ax, ay, az, gx, gy, gz;
    int state = STATE_IDLE;
    time_t fall_start = 0;
    printf("LSM6DSR logging started. Press Ctrl+C to exit.\n");
    while (running) {
        if (read_accel_gyro(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(ax, ay, az, gx, gy, gz);
            float mag = sqrtf(ax * ax + ay * ay + az * az);
            if (state == STATE_IDLE) {
                if (mag < FREEFALL_THRESHOLD) {
                    state = STATE_FREEFALL;
                    fall_start = time(NULL);
                }
            } else if (state == STATE_FREEFALL) {
                if (mag > IMPACT_THRESHOLD) {
                    time_t now = time(NULL);
                    if (difftime(now, fall_start) <= IMPACT_WINDOW) {
                        state = STATE_IMPACT;
                        printf("Impact detected!\n");
                    }
                } else {
                    state = STATE_IDLE;
                }
            }
        }
        gpioDelay(10000);
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

