#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 SPI configuration */
#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0x03       /* mode 3: CPOL=1, CPHA=1 */

/* ADIS16266 register addresses */
#define REG_X_GYRO_OUT 0x14
#define REG_WHO_AM_I   0x02
#define REG_GLOB_CMD   0x68
#define REG_SMPL_PRD   0x36

/* Scaling factor for X_GYRO_OUT (deg/sec per LSB) */
#define GYRO_SCALE     0.0305f

/* Expected device ID (ADIS16266) */
#define EXPECTED_WHO_AM_I 0x3F5A

/* Glob_cmd bits */
#define GLOB_CMD_READ_BIT  0x80
#define GLOB_CMD_WRITE_BIT 0x00

/* Sample period register value (1 kHz / 1000 Hz) */
#define SMPL_PRD_VAL       0x000A

/* Global command register value to start sampling */
#define GLOB_CMD_START     0x0004

/* Log file name */
#define LOG_FILE_NAME "gyro_log.csv"

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* SPI transfer timeout in microseconds (1 ms) */
#define SPI_TIMEOUT_US 1000

/* Global state */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* SPI transfer helper                                                 */
/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, int len)
{
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed: returned %d (expected %d)\n",
                ret, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266                           */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *value)
{
    uint8_t tx[2];
    uint8_t rx[2];

    /* Phase 1: send read command (reg | 0x80) */
    tx[0] = reg | GLOB_CMD_READ_BIT;
    tx[1] = 0x00;

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    /* Small delay to let the device prepare the response */
    gpioDelay(10);

    /* Phase 2: dummy write to clock out the response */
    tx[0] = 0x00;
    tx[1] = 0x00;

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    *value = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register to the ADIS16266                            */
/* ------------------------------------------------------------------ */
static int write_register(uint8_t reg, uint16_t value)
{
    uint8_t tx[2];
    uint8_t rx[2];

    tx[0] = reg & GLOB_CMD_WRITE_BIT;
    tx[1] = (uint8_t)(value & 0xFF);

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    tx[0] = (reg & GLOB_CMD_WRITE_BIT) | 0x40;
    tx[1] = (uint8_t)((value >> 8) & 0xFF);

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADIS16266                                            */
/* ------------------------------------------------------------------ */
static int initialize_adis16266(void)
{
    int16_t who_am_i = 0;

    /* Read WHO_AM_I register */
    if (read_register(REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != EXPECTED_WHO_AM_I) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, EXPECTED_WHO_AM_I);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* Set sample period to 1 kHz / 1000 Hz */
    if (write_register(REG_SMPL_PRD, SMPL_PRD_VAL) != 0) {
        fprintf(stderr, "Failed to write SMPL_PRD register\n");
        return -1;
    }

    /* Start sampling */
    if (write_register(REG_GLOB_CMD, GLOB_CMD_START) != 0) {
        fprintf(stderr, "Failed to start sampling\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read angular rate and log to CSV                                    */
/* ------------------------------------------------------------------ */
static int read_and_log_gyro(void)
{
    int16_t raw_gyro = 0;
    float angular_rate = 0.0f;
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (read_register(REG_X_GYRO_OUT, &raw_gyro) != 0) {
        fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
        return -1;
    }

    angular_rate = (float)raw_gyro * GYRO_SCALE;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s.%06ld,%.4f\n",
                timestamp, ts.tv_nsec / 1000, angular_rate) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(log_file) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen(LOG_FILE_NAME, "w");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(log_file, "timestamp,angular_rate_dps\n") < 0) {
        perror("fprintf header");
        cleanup();
        return EXIT_FAILURE;
    }
    fflush(log_file);

    /* Initialize ADIS16266 */
    if (initialize_adis16266() != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
