/* L3G4200D I2C address (SA0 tied to GND) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG4    0x23
#define OUT_X_L      0x28

/* Expected WHO_AM_I value for L3G4200D */
#define L3G4200D_WHO_AM_I 0xD3

/* Sensitivity: 8.75 mdps/LSB at +-250 dps full-scale */
#define SENSITIVITY 114.285f

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds (10 ms) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum consecutive I2C write retries */
#define MAX_RETRIES 3

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a register with retry */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

/* Read a block of bytes starting at reg with retry */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
        if (result == (int)len) {
            return 0;
        }
        fprintf(stderr, "I2C block read from reg 0x%02X failed (attempt %d/%d): %s\n",
                reg, attempt + 1, MAX_RETRIES, strerror(errno));
        gpioDelay(1000);
    }
    return -1;
}

/* Initialize the L3G4200D gyroscope */
static int init_gyro(int handle) {
    /* Verify device identity */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who != L3G4200D_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, L3G4200D_WHO_AM_I);
        return -1;
    }

    /* CTRL_REG1: normal mode, all axes enabled, 100 Hz ODR */
    if (write_register(handle, CTRL_REG1, 0x0F) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1\n");
        return -1;
    }

    /* CTRL_REG4: +-250 dps full-scale, continuous update, little-endian */
    if (write_register(handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data and convert to degrees per second */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint8_t buf[6];

    if (read_block(handle, OUT_X_L, buf, 6) != 0) {
        fprintf(stderr, "Failed to read gyroscope data block\n");
        return -1;
    }

    /* Little-endian: LSB first, then MSB */
    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / SENSITIVITY;
    *y = (float)raw_y / SENSITIVITY;
    *z = (float)raw_z / SENSITIVITY;

    return 0;
}

/* Log data to CSV file with nanosecond timestamp */
static void log_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(fp, "%ld.%09ld,%.3f,%.3f,%.3f\n",
            (long)ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, L3G4200D_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope */
    if (init_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)\n");

    /* Main sampling loop */
    while (!terminate) {
        float x, y, z;

        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

