#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the flame sensor.  Returns 0 (flame), 1 (no flame), or -1 on   */
/* error (PI_BAD_GPIO).                                               */
/* ------------------------------------------------------------------ */
static int read_flame_sensor(void)
{
    int level = gpioRead(FLAME_SENSOR_GPIO);
    if (level == PI_BAD_GPIO) {
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped line to the log file.                          */
/* ------------------------------------------------------------------ */
static void log_event(int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
