/*
 * Structural Integrity Monitoring System — Omron D7S-0001 vibration sensor
 * Raspberry Pi 5, I2C bus /dev/i2c-1, slave address 0x53
 *
 * Build:  gcc -O2 -Wall -Wextra -o vib_monitor vib_monitor.c
 * Run:    ./vib_monitor
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x53
#define CSV_FILENAME   "vibration_log.csv"
#define SAMPLE_MS      100
#define ACCEL_REG_BASE 0x28
#define ACCEL_REG_COUNT 6
#define ACCEL_BYTES    6

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read `len` bytes starting at `reg` from the I2C device.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read (reg 0x%02X, want %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read acceleration from the D7S-0001.
 * Returns 0 on success, -1 on error.
 */
static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[ACCEL_BYTES];

    if (i2c_read_regs(fd, ACCEL_REG_BASE, buf, ACCEL_BYTES) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/*
 * Write one CSV row: "YYYY-MM-DDThh:mm:ssZ,X,Y,Z\n".
 * Returns 0 on success, -1 on error.
 */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open CSV file (append; write header if empty) --- */
    fp = fopen(CSV_FILENAME, "a+");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        goto cleanup;
    }

    /* Determine whether file is empty so we can write a header */
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell() failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "fprintf(header) failed: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush(header) failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t x, y, z;

        if (read_acceleration(fd, &x, &y, &z) != 0) {
            /*
             * Sensor-absent or bus-level error: skip this sample
             * and keep running so transient glitches do not kill us.
             */
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        if (log_data(fp, x, y, z) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        if (close(fd) != 0)
            fprintf(stderr, "close(fd) failed: %s\n", strerror(errno));
    }
    return rc;
}

