#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* LIS3MDL I2C address (SA1 tied to GND) */
#define LIS3MDL_ADDR 0x1E

/* LIS3MDL register addresses */
#define WHO_AM_I     0x0F
#define CTRL_REG1    0x20
#define CTRL_REG2    0x21
#define CTRL_REG3    0x22
#define CTRL_REG4    0x23
#define OUT_X_L      0x28
#define OUT_X_H      0x29
#define OUT_Y_L      0x2A
#define OUT_Y_H      0x2B
#define OUT_Z_L      0x2C
#define OUT_Z_H      0x2D

/* Expected chip ID */
#define WHO_AM_I_VAL 0x3D

/* Calibration constants (replace with your calibrated values) */
#define X_OFFSET 0.0f
#define Y_OFFSET 0.0f
#define Z_OFFSET 0.0f
#define X_SCALE  1.0f
#define Y_SCALE  1.0f
#define Z_SCALE  1.0f

/* Metal detection threshold in milliGauss */
#define METAL_THRESHOLD 800.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS "/dev/i2c-1"

/* Log file name */
#define LOG_FILE "magnetic_log.txt"

/* Sampling interval in microseconds (100 ms = 10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Maximum retries for I2C initialization */
#define MAX_INIT_RETRIES 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C register access                                                 */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_lis3mdl(int fd)
{
    uint8_t who_am_i = 0;

    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) < 0)
        return -1;

    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: temp enable | ODR=80 Hz | LP/HP mode | X/Y/Z axes enabled */
    if (i2c_write_reg(fd, CTRL_REG1, 0x70) < 0)
        return -1;

    /* CTRL_REG2: full-scale = +-4 gauss (default) */
    if (i2c_write_reg(fd, CTRL_REG2, 0x00) < 0)
        return -1;

    /* CTRL_REG3: continuous-conversion mode */
    if (i2c_write_reg(fd, CTRL_REG3, 0x00) < 0)
        return -1;

    /* CTRL_REG4: high-performance mode */
    if (i2c_write_reg(fd, CTRL_REG4, 0x0C) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw magnetic data and convert to milliGauss                    */
/* ------------------------------------------------------------------ */
static int read_magnetic_data(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* Apply calibration */
    *x = ((float)raw_x - X_OFFSET) * X_SCALE;
    *y = ((float)raw_y - Y_OFFSET) * Y_SCALE;
    *z = ((float)raw_z - Z_OFFSET) * Z_SCALE;

    /* Convert to milliGauss (sensitivity at +-4 gauss is 0.146 mG/LSB) */
    *x *= 0.146f;
    *y *= 0.146f;
    *z *= 0.146f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Metal detection                                                     */
/* ------------------------------------------------------------------ */
static void detect_metal(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr,
                "METAL DETECTED! Magnitude: %.2f mG (X: %.2f, Y: %.2f, Z: %.2f)\n",
                magnitude, x, y, z);
    }
}

