/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x, float y, float z)
{
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
