#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SAMPLE_INTERVAL_US 100000
#define SENSITIVITY 0.0000039f
#define LOG_FILE "vibration_log.txt"
#define MAX_RETRIES 3

#define ADXL354B_REG_PARTID 0x01
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_XDATA_H 0x08
#define ADXL354B_REG_YDATA_H 0x0B
#define ADXL354B_REG_ZDATA_H 0x0E

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int spi_read_register(uint8_t reg, uint8_t *value) {
    char tx[2] = { (char)(reg | 0x81), 0x00 };
    char rx[2] = { 0 };
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx, rx, 2) == 2) {
            *value = (uint8_t)rx[1];
            return 0;
        }
        retries++;
        gpioDelay(1000);
    }
    fprintf(stderr, "SPI read failed for reg 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1;
}

static int spi_write_register(uint8_t reg, uint8_t value) {
    char tx[2] = { (char)(reg & 0x7F), (char)value };
    char rx[2] = { 0 };
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, tx, rx, 2) == 2) {
            return 0;
        }
        retries++;
        gpioDelay(1000);
    }
    fprintf(stderr, "SPI write failed for reg 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1;
}

static int read_acceleration(float *x, float *y, float *z) {
    uint8_t x_h, x_l, x_x, y_h, y_l, y_x, z_h, z_l, z_x;
    int32_t x_raw, y_raw, z_raw;

    if (spi_read_register(ADXL354B_REG_XDATA_H, &x_h) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_XDATA_H + 1, &x_l) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_XDATA_H + 2, &x_x) != 0) return -1;

    if (spi_read_register(ADXL354B_REG_YDATA_H, &y_h) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_YDATA_H + 1, &y_l) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_YDATA_H + 2, &y_x) != 0) return -1;

    if (spi_read_register(ADXL354B_REG_ZDATA_H, &z_h) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_ZDATA_H + 1, &z_l) != 0) return -1;
    if (spi_read_register(ADXL354B_REG_ZDATA_H + 2, &z_x) != 0) return -1;

    x_raw = ((int32_t)x_h << 12) | ((int32_t)x_l << 4) | ((int32_t)x_x >> 4);
    y_raw = ((int32_t)y_h << 12) | ((int32_t)y_l << 4) | ((int32_t)y_x >> 4);
    z_raw = ((int32_t)z_h << 12) | ((int32_t)z_l << 4) | ((int32_t)z_x >> 4);

    *x = (float)x_raw * SENSITIVITY;
    *y = (float)y_raw * SENSITIVITY;
    *z = (float)z_raw * SENSITIVITY;

    return 0;
}

static int initialize_adxl354b(void) {
    uint8_t partid;
    if (spi_read_register(ADXL354B_REG_PARTID, &partid) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != 0x1D) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x1D)\n", partid);
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_RESET, 0x52) != 0) return -1;
    gpioDelay(1000);

    uint8_t status;
    int stable = 0;
    for (int i = 0; i < 100; i++) {
        if (spi_read_register(ADXL354B_REG_STATUS, &status) != 0) return -1;
        if (status & 0x01) { stable = 1; break; }
        gpioDelay(1000);
    }
    if (!stable) {
        fprintf(stderr, "ADXL354B not stable after reset\n");
        return -1;
    }

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x00) != 0) return -1;
    gpioDelay(1000);

    if (spi_write_register(ADXL354B_REG_POWER_CTL, 0x02) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, X: %.4f, Y: %.4f, Z: %.4f\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_adxl354b() != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Read error, continuing...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(log_file, "Program terminated gracefully.\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

