#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* Scaling factors (from ADIS16362 datasheet) */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.0025f /* g/LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x03    /* Mode 3: active-high clock, sampled on trailing edge */

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int read_register(uint8_t address, int16_t *data);
static int read_gyro_axis(uint8_t address, float *value);
static int read_accel_axis(uint8_t address, float *value);
static int log_data(float x_gyro, float y_gyro, float z_gyro,
                    float x_accel, float y_accel, float z_accel);
static void signal_handler(int signal);
static void cleanup(void);

/*
 * Read a 16-bit register from the ADIS16362.
 * Protocol: send address (MSB set) then dummy byte, then read 2 bytes.
 * Returns 0 on success, -1 on SPI transfer error.
 */
static int read_register(uint8_t address, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    /* Send read command: address with MSB set, then dummy byte */
    tx_buf[0] = (char)(address | 0x80);
    tx_buf[1] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error for address 0x%02X (returned %d): %s\n",
                address, result, strerror(errno));
        return -1;
    }

    /* Small delay to allow conversion to complete (datasheet: ~10 us) */
    gpioDelay(10);

    /* Read data: send dummy address, receive 2 data bytes */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI transfer error for data read of address 0x%02X (returned %d): %s\n",
                address, result, strerror(errno));
        return -1;
    }

    /* Data is returned little-endian: rx_buf[0] is low byte, rx_buf[1] is high byte */
    *data = (int16_t)(((uint16_t)(uint8_t)rx_buf[1] << 8) | (uint8_t)rx_buf[0]);
    return 0;
}

/* Read a single gyroscope axis and convert to degrees/second */
static int read_gyro_axis(uint8_t address, float *value) {
    int16_t raw;
    if (read_register(address, &raw) != 0) {
        return -1;
    }
    *value = (float)raw * GYRO_SCALE;
    return 0;
}

/* Read a single accelerometer axis and convert to g */
static int read_accel_axis(uint8_t address, float *value) {
    int16_t raw;
    if (read_register(address, &raw) != 0) {
        return -1;
    }
    *value = (float)raw * ACCL_SCALE;
    return 0;
}

/* Log data to CSV file with high-precision timestamp */
static int log_data(float x_gyro, float y_gyro, float z_gyro,
                    float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%ld.%09ld,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro,
                x_accel, y_accel, z_accel) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Signal handler for graceful shutdown (Ctrl+C) */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0 (CE0/GPIO8), 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, baud %d, flags 0x%02X): %s\n",
                SPI_CHANNEL, SPI_BAUD, SPI_FLAGS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        float x_gyro, y_gyro, z_gyro;
        float x_accel, y_accel, z_accel;

        if (read_gyro_axis(X_GYRO_OUT, &x_gyro) != 0 ||
            read_gyro_axis(Y_GYRO_OUT, &y_gyro) != 0 ||
            read_gyro_axis(Z_GYRO_OUT, &z_gyro) != 0 ||
            read_accel_axis(X_ACCL_OUT, &x_accel) != 0 ||
            read_accel_axis(Y_ACCL_OUT, &y_accel) != 0 ||
            read_accel_axis(Z_ACCL_OUT, &z_accel) != 0) {
            fprintf(stderr, "Error reading IMU data, skipping log entry.\n");
        } else {
            if (log_data(x_gyro, y_gyro, z_gyro,
                         x_accel, y_accel, z_accel) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

