/*
 * KY-032 IR Obstacle Avoidance Sensors - Collision Avoidance System
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (v2 API)
 *
 * Wiring:
 *   KY-032 OUT1 -> GPIO17 (BCM 17, physical pin 11)
 *   KY-032 OUT2 -> GPIO27 (BCM 27, physical pin 13)
 *   KY-032 VCC  -> 3.3 V (physical pin 1)
 *   KY-032 GND  -> GND   (physical pin 9)
 *
 * The KY-032 output is active-low:
 *   0 = obstacle detected
 *   1 = path clear
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o obstacle_avoidance obstacle_avoidance.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip0"
#define SENSOR1_OFFSET   17
#define SENSOR2_OFFSET   27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the gpiochip --- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure both lines as inputs --- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new failed\n");
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new failed\n");
        goto cleanup;
    }

    unsigned int offsets[2] = { SENSOR1_OFFSET, SENSOR2_OFFSET };
    if (gpiod_line_config_add_line_settings(line_cfg, offsets, 2, settings) != 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new failed\n");
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-obstacle");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines %u and %u: %s\n",
                SENSOR1_OFFSET, SENSOR2_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance system started.\n");
    printf("  Sensor 1: GPIO%u (BCM 17, physical pin 11)\n", SENSOR1_OFFSET);
    printf("  Sensor 2: GPIO%u (BCM 27, physical pin 13)\n", SENSOR2_OFFSET);
    printf("  Poll interval: %d ms. Press Ctrl+C to exit.\n\n", POLL_INTERVAL_MS);

    /* --- Main polling loop --- */
    while (g_running) {
        enum gpiod_line_value values[2];

        int rv = gpiod_line_request_get_values(request, values);
        if (rv != 0) {
            fprintf(stderr, "gpiod_line_request_get_values failed: %s\n",
                    strerror(errno));
            break;
        }

        int s1 = (values[0] == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;
        int s2 = (values[1] == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;

        print_timestamp();
        printf("Sensor 1 (GPIO%u): %s\n", SENSOR1_OFFSET, s1 ? "Obstacle" : "Clear");
        print_timestamp();
        printf("Sensor 2 (GPIO%u): %s\n", SENSOR2_OFFSET, s2 ? "Obstacle" : "Clear");
        printf("--------------------------------\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (request != NULL)
        gpiod_line_request_release(request);
    if (req_cfg != NULL)
        gpiod_request_config_free(req_cfg);
    if (line_cfg != NULL)
        gpiod_line_config_free(line_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

