#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip4"
#define CS_LINE 8

#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_MSC_CTRL 0x24

#define ADIS16266_SCALE_FACTOR 0.02f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int adis16266_read_register(int fd, struct gpiod_line *cs, uint8_t reg, int16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    *value = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int adis16266_write_register(int fd, struct gpiod_line *cs, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = { 0 };

    if (gpiod_line_set_value(cs, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (spi_transfer(fd, tx, rx, 2) < 0) {
        gpiod_line_set_value(cs, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    return 0;
}

int main(void) {
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE);
    if (!cs_line) {
        perror("Failed to get CS line");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(cs_line, "adis16266_cs", 1) < 0) {
        perror("Failed to request CS line as output");
        goto cleanup_chip;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup_cs;
    }

    uint8_t mode = SPI_MODE_3;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup_spi;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup_spi;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        goto cleanup_spi;
    }

    if (adis16266_write_register(spi_fd, cs_line, ADIS16266_REG_MSC_CTRL, 0x00) < 0) {
        fprintf(stderr, "Failed to configure MSC_CTRL (sensor may be absent)\n");
        goto cleanup_spi;
    }

    printf("ADIS16266 initialized. Reading gyroscope data...\n");

    while (running) {
        int16_t x_raw, y_raw, z_raw;

        if (adis16266_read_register(spi_fd, cs_line, ADIS16266_REG_XGYRO_OUT, &x_raw) < 0 ||
            adis16266_read_register(spi_fd, cs_line, ADIS16266_REG_YGYRO_OUT, &y_raw) < 0 ||
            adis16266_read_register(spi_fd, cs_line, ADIS16266_REG_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        float x_rate = (float)x_raw * ADIS16266_SCALE_FACTOR;
        float y_rate = (float)y_raw * ADIS16266_SCALE_FACTOR;
        float z_rate = (float)z_raw * ADIS16266_SCALE_FACTOR;

        printf("X: %+.2f deg/s, Y: %+.2f deg/s, Z: %+.2f deg/s\n", x_rate, y_rate, z_rate);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup_spi:
    if (spi_fd >= 0) close(spi_fd);
cleanup_cs:
    if (cs_line) gpiod_line_release(cs_line);
cleanup_chip:
    if (chip) gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

