        fprintf(stderr, "Failed to configure MSC_CTRL (sensor may be absent)\n");
        goto cleanup_spi;
    }

    printf("ADIS16266 initialized. Reading gyroscope data...\n");

    while (running) {
        int16_t x_raw, y_raw, z_raw;

        if (adis16266_read_register(spi_fd, cs_line, ADIS16266_REG_XGYRO_OUT, &x_raw) < 0 ||
            adis16266_read_register(spi_fd, cs_line, ADIS16266_REG_YGYRO_OUT, &y_raw) < 0 ||
            adis16266_read_register(spi_fd, cs_line, ADIS16266_REG_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            break;
        }

        float x_rate = (float)x_raw * ADIS16266_SCALE_FACTOR;
        float y_rate = (float)y_raw * ADIS16266_SCALE_FACTOR;
        float z_rate = (float)z_raw * ADIS16266_SCALE_FACTOR;

        printf("X: %+.2f deg/s, Y: %+.2f deg/s, Z: %+.2f deg/s\n", x_rate, y_rate, z_rate);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup_spi:
    if (spi_fd >= 0) close(spi_fd);
cleanup_cs:
    if (cs_line) gpiod_line_release(cs_line);
cleanup_chip:
    if (chip) gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

