#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR 7-bit I2C address (SA0 tied high on LSM6DSR breakout) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I     0x0F
#define CTRL1_XL     0x10
#define CTRL2_G      0x11
#define OUTX_L_G     0x22
#define STATUS_REG   0x1E

/* Expected chip ID */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities for +-2g and +-250 dps */
#define ACCEL_SENSITIVITY 0.000061f   /* mg/LSB */
#define GYRO_SENSITIVITY  0.00875f    /* mdps/LSB */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (pigpio rc=%d)\n",
                val, reg, rc);
        return -1;
    }
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading %u bytes from register 0x%02X (rc=%d)\n",
                len, reg, rc);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register (pigpio rc=%d)\n", who);
        return -1;
    }
    if (who != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LSM6DSR_WHO_AM_I);
        return -1;
    }

    /* Gyro: +-250 dps, 104 Hz -> 0x42 */
    if (write_reg(handle, CTRL2_G, 0x42) < 0)
        return -1;

    /* Accel: +-2g, 104 Hz -> 0x42 */
    if (write_reg(handle, CTRL1_XL, 0x42) < 0)
        return -1;

    return 0;
}

static int read_sensor_data(int handle,
                            float *ax, float *ay, float *az,
                            float *gx, float *gy, float *gz)
{
    uint8_t buf[12];

    /* Burst read 12 bytes: gyro (6) + temperature (2) + accel (6) */
    if (read_burst(handle, OUTX_L_G, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_gx = (int16_t)((buf[1]  << 8) | buf[0]);
    int16_t raw_gy = (int16_t)((buf[3]  << 8) | buf[2]);
    int16_t raw_gz = (int16_t)((buf[5]  << 8) | buf[4]);
    /* buf[6..7] = temperature, skipped */
    int16_t raw_ax = (int16_t)((buf[8]  << 8) | buf[7]);
    int16_t raw_ay = (int16_t)((buf[10] << 8) | buf[9]);
    int16_t raw_az = (int16_t)((buf[12] << 8) | buf[11]);

    *gx = (float)raw_gx * GYRO_SENSITIVITY;
    *gy = (float)raw_gy * GYRO_SENSITIVITY;
    *gz = (float)raw_gz * GYRO_SENSITIVITY;
    *ax = (float)raw_ax * ACCEL_SENSITIVITY / 1000.0f;
    *ay = (float)raw_ay * ACCEL_SENSITIVITY / 1000.0f;
    *az = (float)raw_az * ACCEL_SENSITIVITY / 1000.0f;

    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X (pigpio rc=%d)\n",
                LSM6DSR_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR initialized. Reading every 100 ms. Press Ctrl+C to stop.\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g  "
                   "Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Sensor read error; continuing\n");
        }

        /* 100 ms delay that honors the signal flag */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(10000); /* 10 ms */
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

