#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700 I2C address (SA0 tied to GND) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_WHO_AM_I_VAL 0xC7
#define FXOS8700_OUT_X_MSB  0x01
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C

/* Scaling factor for accelerometer: 1 g = 256 LSB */
#define ACCEL_SCALE 256.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a single byte register; returns -1 on error */
static int read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0)
        return -1;
    *val = (uint8_t)rc;
    return 0;
}

/* Write a single byte register; returns -1 on error */
static int write_reg(int handle, uint8_t reg, uint8_t val)
{
    return i2cWriteByteData(handle, reg, val);
}

/* Read a block of bytes starting at reg; returns -1 on error */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len)
        return -1;
    return 0;
}

/* Initialize FXOS8700 into hybrid mode: accel + magnetometer */
static int init_fxos8700(int handle)
{
    uint8_t whoami = 0;

    /* Verify device identity */
    if (read_reg(handle, FXOS8700_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I register\n");
        return -1;
    }
    if (whoami != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                whoami, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (write_reg(handle, FXOS8700_CTRL_REG1, 0x00) != 0) {
        fprintf(stderr, "Error: cannot write CTRL_REG1 (standby)\n");
        return -1;
    }

    /* Configure accelerometer: hybrid mode, 14-bit, +/-2g range */
    if (write_reg(handle, FXOS8700_CTRL_REG1, 0x0D) != 0) {
        fprintf(stderr, "Error: cannot write CTRL_REG1 (accel config)\n");
        return -1;
    }

    /* Configure magnetometer: hybrid mode, OSR=1 (6.64 LSB/gauss) */
    if (write_reg(handle, FXOS8700_M_CTRL_REG1, 0x1F) != 0) {
        fprintf(stderr, "Error: cannot write M_CTRL_REG1 (mag config)\n");
        return -1;
    }

    /* Active mode, 100 Hz ODR */
    if (write_reg(handle, FXOS8700_CTRL_REG2, 0x20) != 0) {
        fprintf(stderr, "Error: cannot write CTRL_REG2 (active)\n");
        return -1;
    }

    return 0;
}

/* Read and convert combined 12-byte data block */
static int read_sensor_data(int handle,
                            float *ax, float *ay, float *az,
                            float *mx, float *my, float *mz)
{
    uint8_t buf[12];

    if (read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: cannot read 12-byte data block\n");
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 */
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit */
    int16_t raw_mx = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t raw_my = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t raw_mz = (int16_t)((buf[10] << 8) | buf[11]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *mx = (float)raw_mx;
    *my = (float)raw_my;
    *mz = (float)raw_mz;

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C device (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor with retries */
    int init_ok = 0;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (init_fxos8700(g_i2c_handle) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Init attempt %d failed, retrying...\n", attempt + 1);
        gpioDelay(100000); /* 100 ms */
    }

    if (!init_ok) {
        fprintf(stderr, "Error: FXOS8700 initialization failed after 3 attempts\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging accelerometer and magnetometer data...\n");

    /* Main loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g  |  Mag: X=%.3f gauss, Y=%.3f gauss, Z=%.3f gauss\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

