    if (read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) != 0) {
        fprintf(stderr, "Error: cannot read 12-byte data block\n");
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 */
    int16_t raw_ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    int16_t raw_ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    int16_t raw_az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit */
    int16_t raw_mx = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t raw_my = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t raw_mz = (int16_t)((buf[10] << 8) | buf[11]);

    *ax = (float)raw_ax / ACCEL_SCALE;
    *ay = (float)raw_ay / ACCEL_SCALE;
    *az = (float)raw_az / ACCEL_SCALE;
    *mx = (float)raw_mx;
    *my = (float)raw_my;
    *mz = (float)raw_mz;

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at FXOS8700 address */
    g_i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: cannot open I2C device (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor with retries */
    int init_ok = 0;
    for (int attempt = 0; attempt < 3; attempt++) {
        if (init_fxos8700(g_i2c_handle) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Init attempt %d failed, retrying...\n", attempt + 1);
        gpioDelay(100000); /* 100 ms */
    }

    if (!init_ok) {
        fprintf(stderr, "Error: FXOS8700 initialization failed after 3 attempts\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialized. Logging accelerometer and magnetometer data...\n");

    /* Main loop */
    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (read_sensor_data(g_i2c_handle, &ax, &ay, &az, &mx, &my, &mz) == 0) {
            printf("Accel: X=%.3f g, Y=%.3f g, Z=%.3f g  |  Mag: X=%.3f gauss, Y=%.3f gauss, Z=%.3f gauss\n",
                   ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Warning: sensor read failed, continuing...\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

