#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Tilt angle threshold in degrees
#define TILT_THRESHOLD 30.0

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int init_i2c(void);
int read_accelerometer_data(accelerometer_data_t *data);
double calculate_tilt_angle(accelerometer_data_t data);
void log_tilt_event(double tilt_angle);
void signal_handler(int signal);
void cleanup(void);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Verify sensor presence by reading POWER_CTL register
    uint8_t reg = ADXL345_POWER_CTL;
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device (presence check): %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t buf[1];
    if (read(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device (presence check): %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Enable measurement mode
    uint8_t power_ctl = 0x08; // Measure bit
    if (write(i2c_fd, &power_ctl, 1) != 1) {
        fprintf(stderr, "Error enabling measurement mode: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read accelerometer data from the ADXL345
int read_accelerometer_data(accelerometer_data_t *data) {
    uint8_t reg = ADXL345_DATAX0;
    uint8_t buf[6];

    // Write register address
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Calculate the tilt angle in degrees
double calculate_tilt_angle(accelerometer_data_t data) {
    double x = (double)data.x;
    double y = (double)data.y;
    double z = (double)data.z;

    double tilt_angle = atan2(sqrt(x * x + y * y), z) * 180.0 / M_PI;
    return tilt_angle;
}

// Log tilt events to a file
void log_tilt_event(double tilt_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fflush(log_file);
}

int main(void) {
    // Set up signal handling for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Tilt detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        accelerometer_data_t data;

        if (read_accelerometer_data(&data) == 0) {
            double tilt_angle = calculate_tilt_angle(data);

            if (tilt_angle > TILT_THRESHOLD) {
                log_tilt_event(tilt_angle);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        usleep(100000); // 100 ms delay
    }

    printf("\nExiting gracefully.\n");
    cleanup();

    return 0;
}

