#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define SAMPLE_WINDOW_SEC 5
#define LOOP_PAUSE_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    } else {
        printf("[unknown time] ");
    }
}

static int parse_threshold(const char *arg, int *out)
{
    char *endptr = NULL;
    long val = strtol(arg, &endptr, 10);

    if (endptr == arg || *endptr != '\0') {
        fprintf(stderr, "Error: '%s' is not a valid integer.\n", arg);
        return -1;
    }
    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer (got %ld).\n", val);
        return -1;
    }
    *out = (int)val;
    return 0;
}

int main(int argc, char *argv[])
{
    int threshold = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        fprintf(stderr, "  threshold: minimum number of high readings in a 5-second window\n");
        return EXIT_FAILURE;
    }

    if (parse_threshold(argv[1], &threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d. Threshold: %d high readings in %d s.\n",
           SOUND_SENSOR_GPIO, threshold, SAMPLE_WINDOW_SEC);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int high_count = 0;
        uint32_t start_tick = gpioTick();

        while (g_running && (gpioTick() - start_tick) < (uint32_t)(SAMPLE_WINDOW_SEC * 1000000)) {
            if (gpioRead(SOUND_SENSOR_GPIO) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (!g_running) {
            break;
        }

        if (high_count > threshold) {
            print_timestamp();
            printf("ALERT: Noise detected! High readings: %d (threshold: %d)\n",
                   high_count, threshold);
        } else {
            print_timestamp();
            printf("Status: Noise level normal. High readings: %d (threshold: %d)\n",
                   high_count, threshold);
        }
        fflush(stdout);

        /* Sleep for the remainder of the 1-second loop window */
        if (g_running) {
            gpioDelay((LOOP_PAUSE_SEC * 1000000) -
                      (uint32_t)(SAMPLE_WINDOW_SEC * 1000000));
        }
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

