/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Two 12V electromagnetic door locks (via 5V active-HIGH relay modules
 * driven by TIP120 transistors) controlled via libgpiod.
 *
 *   Door A: GPIO17 (active-HIGH = unlocked)
 *   Door B: GPIO27 (active-HIGH = unlocked)
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
