static int unlock_door(struct gpiod_line *line, int gpio)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    printf("Door unlocked on GPIO%d.\n", gpio);

    sleep(UNLOCK_SEC);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    printf("Door locked on GPIO%d.\n", gpio);
    return 0;
}

