static int mpr121_write(uint8_t reg, uint8_t val) {
    char buf[2] = {(char)reg, (char)val};
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

