    char buf[1] = {(char)reg};
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
