#define PWM_PERIOD_NS 10000000  // 100 Hz
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error (0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

int init_lsm303(int fd) {
    if (i2c_write_reg(fd, CTRL_REG1_M, 0x18) < 0) {
        return -1;
    }
    return 0;
}

int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L_M, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

void set_led_brightness(struct gpiod_line *line, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;
    int duty_ns = (PWM_PERIOD_NS * brightness) / 100;
    if (duty_ns > PWM_PERIOD_NS) duty_ns = PWM_PERIOD_NS;
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set LED high: %s\n", strerror(errno));
        return;
    }
    usleep(duty_ns / 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set LED low: %s\n", strerror(errno));
    }
    usleep((PWM_PERIOD_NS - duty_ns) / 1000);
}

void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_lsm303(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303DLHC\n");
        close(i2c_fd);
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "magnetometer_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    printf("LSM303DLHC magnetometer reading. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Sensor read error, skipping sample\n");
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }
        double magnitude = sqrt((double)z * z);
        int brightness = (int)(magnitude / 1000.0 * 100.0);
        if (brightness > 100) brightness = 100;
        set_led_brightness(led_line, brightness);
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

