#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define SAMPLE_WINDOW 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hmc5883l_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write error: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int hmc5883l_init(void) {
    if (hmc5883l_write_reg(HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (hmc5883l_write_reg(HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (hmc5883l_write_reg(HMC5883L_MODE, 0x00) < 0) return -1;
    return 0;
}

static int hmc5883l_read_raw(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int rc = i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "I2C read error: rc=%d\n", rc);
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *z = (int16_t)((buf[2] << 8) | buf[3]);
    *y = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void calculate_offsets(const int16_t *raw, int n,
                              int16_t *x_off, int16_t *y_off, int16_t *z_off) {
    double sx = 0, sy = 0, sz = 0;
    for (int i = 0; i < n; i++) {
        sx += raw[i * 3];
        sy += raw[i * 3 + 1];
        sz += raw[i * 3 + 2];
    }
    *x_off = (int16_t)(sx / n);
    *y_off = (int16_t)(sy / n);
    *z_off = (int16_t)(sz / n);
}

static void apply_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z,
                          int16_t x_off, int16_t y_off, int16_t z_off,
                          int16_t *corr_x, int16_t *corr_y, int16_t *corr_z) {
    *corr_x = raw_x - x_off;
    *corr_y = raw_y - y_off;
    *corr_z = raw_z - z_off;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hmc5883l_init() < 0) {
        fprintf(stderr, "HMC5883L init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t *raw_buf = malloc(SAMPLE_WINDOW * 3 * sizeof(int16_t));
    if (!raw_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int idx = 0;
    int16_t x_off = 0, y_off = 0, z_off = 0;

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (hmc5883l_read_raw(&raw_x, &raw_y, &raw_z) < 0) {
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        raw_buf[idx * 3] = raw_x;
        raw_buf[idx * 3 + 1] = raw_y;
        raw_buf[idx * 3 + 2] = raw_z;
        idx = (idx + 1) % SAMPLE_WINDOW;

        if (idx == 0) {
            calculate_offsets(raw_buf, SAMPLE_WINDOW, &x_off, &y_off, &z_off);
        }

        int16_t corr_x, corr_y, corr_z;
        apply_offsets(raw_x, raw_y, raw_z, x_off, y_off, z_off,
                      &corr_x, &corr_y, &corr_z);

        printf("X: %d, Y: %d, Z: %d\n", corr_x, corr_y, corr_z);
        fflush(stdout);

        gpioDelay(SAMPLE_DELAY_US);
    }

    free(raw_buf);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

