code:
/*
 * LSM303D accelerometer monitor with GPIO interrupt-driven dump on Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   LSM303D SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> GPIO23 (pin 16, BCM 23)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Run:
 *   sudo ./lsm303d_mon
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D   /* SA0 tied high */
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49
#define CTRL_REG1_A         0x20
#define CTRL_REG4_A         0x23
#define OUT_X_L_A           0x28
#define INT1_CFG_A          0x30
#define INT1_SRC_A          0x31
#define INT1_THS_A          0x32
#define INT1_DURATION_A     0x33

/* ---- GPIO constants ---- */
#define GPIO_CHIP           "gpiochip4"   /* BCM2711 on Pi Zero W */
#define INT1_OFFSET         23            /* BCM 23 */

/* ---- Application constants ---- */
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_MS    10
#define DUMP_WINDOW_SAMPLES 10

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buffer[BUFFER_SIZE];
static int g_head = 0;   /* next write slot */
static int g_count = 0;  /* number of valid samples (<= BUFFER_SIZE) */

/* ---- Prototypes ---- */
static int  i2c_read_byte(int fd, uint8_t reg);
static int  i2c_write_byte(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len);
static int  init_lsm303d(int fd);
static int  read_accel(int fd, int16_t *x, int16_t *y, int16_t *z);
static void store_sample(int16_t x, int16_t y, int16_t z);
static void dump_buffer(void);
static void cleanup(void);
static void sigint_handler(int sig);

/* ---- I2C helpers ---- */
static int i2c_read_byte(int fd, uint8_t reg)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    args.read_write = I2C_SMBUS_READ;
    args.command = reg;
    args.size = I2C_SMBUS_BYTE_DATA;
    args.data = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C read byte from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return data.byte & 0xFF;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    data.byte = val;
    args.read_write = I2C_SMBUS_WRITE;
    args.command = reg;
    args.size = I2C_SMBUS_BYTE_DATA;
    args.data = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C write byte to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    args.read_write = I2C_SMBUS_READ;
    args.command = reg;
    args.size = I2C_SMBUS_I2C_BLOCK_DATA;
    args.data = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (data.block[0] != len) {
        fprintf(stderr, "I2C block read short: got %u bytes, expected %u\n",
                data.block[0], len);
        return -1;
    }
    memcpy(buf, data.block + 1, len);
    return 0;
}

/* ---- LSM303D init ---- */
static int init_lsm303d(int fd)
{
    int who;

    who = i2c_read_byte(fd, WHO_AM_I);
    if (who < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 50 Hz ODR, XYZ axes enabled, normal mode */
    if (i2c_write_byte(fd, CTRL_REG1_A, 0x57) < 0)
        return -1;

    /* CTRL_REG4: full-scale +-2g (FS = 00), high-resolution disabled */
    if (i2c_write_byte(fd, CTRL_REG4_A, 0x00) < 0)
        return -1;

    /* INT1_CFG: any-axis-high event on INT1 */
    if (i2c_write_byte(fd, INT1_CFG_A, 0x2A) < 0)
        return -1;

    /* INT1_THS: 2000 mg threshold (16 LSB = 1 mg) */
    if (i2c_write_byte(fd, INT1_THS_A, 0x7D) < 0)
        return -1;

    /* INT1_DURATION: 0 = immediate */
    if (i2c_write_byte(fd, INT1_DURATION_A, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];

    /* Auto-increment: MSB of register address = 0x80 */
    if (i2c_read_block(fd, OUT_X_L_A | 0x80, raw, 6) < 0)
        return -1;

    *x = (int16_t)((raw[1] << 8) | raw[0]);
    *y = (int16_t)((raw[3] << 8) | raw[2]);
    *z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Store a sample ---- */
static void store_sample(int16_t x, int16_t y, int16_t z)
{
    g_buffer[g_head] = (accel_sample_t){x, y, z};
    g_head = (g_head + 1) % BUFFER_SIZE;
    if (g_count < BUFFER_SIZE)
        g_count++;
}

/* ---- Dump the most recent DUMP_WINDOW_SAMPLES ---- */
static void dump_buffer(void)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    printf("\n--- Interrupt event dump at %s ---\n", ts);

    int start = (g_head - DUMP_WINDOW_SAMPLES + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < DUMP_WINDOW_SAMPLES; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] X=%6d  Y=%6d  Z=%6d  mg\n",
