/*
 * LSM303D accelerometer monitor with GPIO interrupt-driven dump on Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303D SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   LSM303D SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D INT1 -> GPIO23 (pin 16, BCM 23)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Run:
 *   sudo ./lsm303d_mon
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D   /* SA0 tied high */
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x49
#define CTRL_REG1_A         0x20
#define CTRL_REG4_A         0x23
#define OUT_X_L_A           0x28
#define INT1_CFG_A          0x30
#define INT1_SRC_A          0x31
#define INT1_THS_A          0x32
#define INT1_DURATION_A     0x33

