static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- Circular buffer ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

static accel_sample_t g_buffer[BUFFER_SIZE];
static int g_head = 0;   /* next write slot */
static int g_count = 0;  /* number of valid samples (<= BUFFER_SIZE) */

/* ---- Prototypes ---- */
static int  i2c_read_byte(int fd, uint8_t reg);
static int  i2c_write_byte(int fd, uint8_t reg, uint8_t val);
static int  i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len);
static int  init_lsm303d(int fd);
static int  read_accel(int fd, int16_t *x, int16_t *y, int16_t *z);
static void store_sample(int16_t x, int16_t y, int16_t z);
static void dump_buffer(void);
static void cleanup(void);
static void sigint_handler(int sig);

