#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define LOCK_1_GPIO      17
#define LOCK_2_GPIO      27
#define SERIAL_PORT_1    "/dev/serial0"
#define SERIAL_PORT_2    "/dev/serial1"
#define BAUD_RATE        9600
#define CODE_LENGTH      6
#define EXPECTED_CODE    "123456"
#define UNLOCK_DURATION  2
#define POLL_INTERVAL_US 100000
#define TIMEOUT_SEC      5

static volatile sig_atomic_t g_running = 1;
static int g_serial_handle_1 = -1;
static int g_serial_handle_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

static void set_lock_state(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Error: gpioWrite(%d, %d) failed", gpio, state);
        log_message(buf);
    }
}

static int open_serial_port(const char *port, int baud) {
    int handle = serOpen((char *)port, baud, 0);
    if (handle < 0) {
        char buf[256];
        snprintf(buf, sizeof(buf), "Error: serOpen(%s, %d) failed: %d", port, baud, handle);
        log_message(buf);
        return -1;
    }
    return handle;
}

static int read_code(int handle, char *buffer, size_t buffer_size, int timeout_sec) {
    time_t start = time(NULL);
    size_t idx = 0;
    char ch;

    while (g_running && (time(NULL) - start) < timeout_sec) {
        int n = serRead(handle, &ch, 1);
        if (n > 0) {
            if (ch >= '0' && ch <= '9') {
                if (idx < buffer_size - 1) {
                    buffer[idx++] = ch;
                }
            } else if (ch == '\r' || ch == '\n') {
                buffer[idx] = '\0';
                return (int)idx;
            } else {
                buffer[0] = '\0';
                return -1;
            }
        } else if (n < 0) {
            buffer[0] = '\0';
            return -1;
        }
        gpioDelay(1000);
    }

    buffer[0] = '\0';
    return -2;
}

static int compare_codes(const char *c1, const char *c2) {
    int diff = 0;
    for (int i = 0; i < CODE_LENGTH; i++) {
        diff |= (unsigned char)c1[i] ^ (unsigned char)c2[i];
    }
    return (diff == 0) ? 0 : -1;
}

static void cleanup(void) {
    set_lock_state(LOCK_1_GPIO, 0);
    set_lock_state(LOCK_2_GPIO, 0);

    if (g_serial_handle_1 >= 0) {
        serClose(g_serial_handle_1);
        g_serial_handle_1 = -1;
    }
    if (g_serial_handle_2 >= 0) {
        serClose(g_serial_handle_2);
        g_serial_handle_2 = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_message("Error: pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    set_lock_state(LOCK_1_GPIO, 0);
    set_lock_state(LOCK_2_GPIO, 0);

    g_serial_handle_1 = open_serial_port(SERIAL_PORT_1, BAUD_RATE);
    if (g_serial_handle_1 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    g_serial_handle_2 = open_serial_port(SERIAL_PORT_2, BAUD_RATE);
    if (g_serial_handle_2 < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    char code1[CODE_LENGTH + 1];
    char code2[CODE_LENGTH + 1];
    int code1_ok = 0, code2_ok = 0;

    while (g_running) {
        int r1 = read_code(g_serial_handle_1, code1, sizeof(code1), TIMEOUT_SEC);
        int r2 = read_code(g_serial_handle_2, code2, sizeof(code2), TIMEOUT_SEC);

        if (r1 > 0 && r2 > 0) {
            code1[CODE_LENGTH] = '\0';
            code2[CODE_LENGTH] = '\0';

            if (compare_codes(code1, code2) == 0 &&
                compare_codes(code1, EXPECTED_CODE) == 0) {

                set_lock_state(LOCK_1_GPIO, 1);
                set_lock_state(LOCK_2_GPIO, 1);
                log_message("Both locks unlocked.");

                for (int i = 0; i < UNLOCK_DURATION && g_running; i++) {
                    gpioDelay(1000000);
                }

                set_lock_state(LOCK_1_GPIO, 0);
                set_lock_state(LOCK_2_GPIO, 0);
                log_message("Both locks re-locked.");

                code1_ok = 0;
                code2_ok = 0;
            } else {
                log_message("Codes do not match or do not match expected code.");
                code1_ok = 0;
                code2_ok = 0;
            }
        } else if (r1 < 0) {
            log_message("Error reading code from serial port 1.");
            code1_ok = 0;
        } else if (r2 < 0) {
            log_message("Error reading code from serial port 2.");
            code2_ok = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_message("Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

