#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>

#define PIR_PIN        4
#define RELAY_PIN      17
#define STRIKE_DURATION_SEC 1
#define POLL_INTERVAL_MS    50
#define FAILSAFE_TIMEOUT_SEC 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(int priority, const char *msg)
{
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, "%s", msg);
    closelog();
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *pir_line = NULL;
    struct gpiod_line *relay_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        log_event(LOG_ERR, "Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line (PIR)");
        log_event(LOG_ERR, "Failed to get PIR line");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("gpiod_chip_get_line (relay)");
        log_event(LOG_ERR, "Failed to get relay line");
        goto cleanup;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        perror("gpiod_line_request_input (PIR)");
        log_event(LOG_ERR, "Failed to request PIR line as input");
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        perror("gpiod_line_request_output (relay)");
        log_event(LOG_ERR, "Failed to request relay line as output");
        goto cleanup;
    }

    log_event(LOG_INFO, "Door strike system started");

    int relay_state = 0;
    time_t last_motion_time = time(NULL);
    int motion_active = 0;

    while (program_running) {
        int pir_val = gpiod_line_get_value(pir_line);
        if (pir_val < 0) {
            perror("gpiod_line_get_value (PIR)");
            log_event(LOG_ERR, "PIR read error");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (pir_val == 1) {
            if (!motion_active) {
                motion_active = 1;
                last_motion_time = time(NULL);
                log_event(LOG_INFO, "Motion detected");
            }

            if (!relay_state) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    perror("gpiod_line_set_value (relay ON)");
                    log_event(LOG_ERR, "Failed to energize relay");
                } else {
                    relay_state = 1;
                    log_event(LOG_INFO, "Relay energized");
                }
            }

            if (relay_state) {
                sleep(STRIKE_DURATION_SEC);
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    perror("gpiod_line_set_value (relay OFF)");
                    log_event(LOG_ERR, "Failed to de-energize relay");
                } else {
                    relay_state = 0;
                    log_event(LOG_INFO, "Relay de-energized");
                }
            }
        } else {
            if (motion_active) {
                motion_active = 0;
                log_event(LOG_INFO, "Motion ended");
            }
        }

        if (motion_active && (time(NULL) - last_motion_time) > FAILSAFE_TIMEOUT_SEC) {
            if (relay_state) {
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    perror("gpiod_line_set_value (relay OFF failsafe)");
                    log_event(LOG_ERR, "Failsafe: failed to de-energize relay");
                } else {
                    relay_state = 0;
                    log_event(LOG_WARNING, "Failsafe: PIR stuck HIGH for >10s - relay de-energized");
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    log_event(LOG_INFO, "Shutting down");
    ret = EXIT_SUCCESS;

cleanup:
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
    }
    if (pir_line)
        gpiod_line_release(pir_line);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

