#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define ACTIVATION_DURATION 300  /* seconds */
#define PAUSE_DURATION      60   /* seconds */
#define TIMER_INTERVAL      60   /* seconds */

static volatile sig_atomic_t g_running = 1;

static const int relay_pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static const int num_relays =
    sizeof(relay_pins) / sizeof(relay_pins[0]);

/* Timer callback context */
typedef struct {
    int relay_index;
    int state;          /* 0 = off, 1 = on, 2 = pause */
    int elapsed;        /* seconds since state started */
} timer_ctx_t;

static timer_ctx_t g_timer_ctx = {0, 2, 0};  /* start in pause */

/* ------------------------------------------------------------------ */
/* Logging helper                                                      */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    syslog(LOG_INFO, "[%s] %s", ts, event);
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int set_relay(int pin, int on)
{
    int level = on ? 0 : 1;  /* active-LOW: LOW = ON, HIGH = OFF */
    if (gpioWrite(pin, level) != 0) {
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", pin, level);
        return -1;
    }
    return 0;
}

static int deactivate_all(void)
{
    int rc = 0;
    for (int i = 0; i < num_relays; i++) {
        if (set_relay(relay_pins[i], 0) != 0) {
            rc = -1;
        }
    }
    return rc;
}

/* ------------------------------------------------------------------ */
