#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/timerfd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <poll.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B

#define ACCEL_SCALE 16384.0f
#define BUFFER_SIZE 100
#define SAMPLE_PERIOD_NS 10000000L

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int timer_fd = -1;
static int sysfs_fd = -1;

typedef struct {
    float x, y, z;
} accel_data_t;

static accel_data_t accel_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, MPU6050_ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel_data(int fd, accel_data_t *data) {
    uint8_t buf[6];
    if (i2c_read_regs(fd, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);
    data->x = (float)raw_x / ACCEL_SCALE;
    data->y = (float)raw_y / ACCEL_SCALE;
    data->z = (float)raw_z / ACCEL_SCALE;
    return 0;
}

static void timer_handler(int sig, siginfo_t *si, void *ctx) {
    (void)sig; (void)si; (void)ctx;
    accel_data_t data;
    if (read_accel_data(i2c_fd, &data) == 0) {
        accel_buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    }
}

static int create_sysfs_file(const char *path) {
    if (mkdir("/sys/kernel/mpu6050_accel", 0755) < 0 && errno != EEXIST) {
        fprintf(stderr, "mkdir failed: %s\n", strerror(errno));
        return -1;
    }
    sysfs_fd = open(path, O_RDWR | O_CREAT | O_TRUNC, 0644);
    if (sysfs_fd < 0) {
        fprintf(stderr, "open sysfs file failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int write_sysfs(const char *data) {
    if (sysfs_fd < 0) return -1;
    size_t len = strlen(data);
    ssize_t written = write(sysfs_fd, data, len);
    if (written < 0 || (size_t)written != len) {
        fprintf(stderr, "write sysfs failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (timer_fd >= 0) { close(timer_fd); timer_fd = -1; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (sysfs_fd >= 0) { close(sysfs_fd); sysfs_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 init failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    if (create_sysfs_file("/sys/kernel/mpu6050_accel/latest") < 0) {
        cleanup();
        return 1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timer_fd;
    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_id) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = SAMPLE_PERIOD_NS;
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = SAMPLE_PERIOD_NS;
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct sigaction sa_timer;
    memset(&sa_timer, 0, sizeof(sa_timer));
    sa_timer.sa_sigaction = timer_handler;
    sigemptyset(&sa_timer.sa_mask);
    sa_timer.sa_flags = SA_SIGINFO;
    if (sigaction(SIGRTMIN, &sa_timer, NULL) < 0) {
        fprintf(stderr, "sigaction SIGRTMIN failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU6050 data logging started. Press Ctrl+C to exit.\n");

    while (running) {
        struct pollfd pfd;
        pfd.fd = timer_fd;
        pfd.events = POLLIN;
        int pr = poll(&pfd, 1, 1000);
        if (pr < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "poll failed: %s\n", strerror(errno));
            break;
        }
        if (pr > 0 && (pfd.revents & POLLIN)) {
            uint64_t expirations;
            ssize_t nr = read(timer_fd, &expirations, sizeof(expirations));
            if (nr < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "read timerfd failed: %s\n", strerror(errno));
                break;
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

