            uint64_t expirations;
            ssize_t nr = read(timer_fd, &expirations, sizeof(expirations));
            if (nr < 0) {
                if (errno == EINTR) continue;
                fprintf(stderr, "read timerfd failed: %s\n", strerror(errno));
                break;
            }
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

