#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define CONSUMER "smart_lighting"

// BCM GPIO pins for the four relay control lines
const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};

// Prime number intervals in seconds
const int intervals[NUM_RELAYS] = {2, 3, 5, 7};

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Initialize all relay lines as outputs, initially low (off)
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *lines[], unsigned int pins[], int num_relays) {
    for (int i = 0; i < num_relays; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get GPIO line %u\n", pins[i]);
            return -1;
        }

        int ret = gpiod_line_request_output(lines[i], CONSUMER, 0);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to request GPIO line %u as output\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

// Set a relay line high (on) or low (off)
int set_relay(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line value\n");
        return -1;
    }
    return 0;
}

// Cleanup: turn off all relays and release lines
void cleanup_gpio(struct gpiod_line *lines[], unsigned int pins[], int num_relays) {
    for (int i = 0; i < num_relays; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
}

int main() {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};
    int ret;

    // Open GPIO chip 0 (gpiochip0 on Raspberry Pi 3 B+)
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0\n");
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(chip, relay_lines, relay_pins, NUM_RELAYS) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop: toggle relays based on prime number intervals
    while (program_running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        for (int i = 0; i < NUM_RELAYS; i++) {
            // Calculate elapsed time since last toggle
            struct timespec last_toggle;
            last_toggle.tv_sec = now.tv_sec - intervals[i];
            last_toggle.tv_nsec = now.tv_nsec;

            // Check if interval has elapsed (handles clock_gettime rollover)
            long diff_sec = now.tv_sec - last_toggle.tv_sec;
            long diff_nsec = now.tv_nsec - last_toggle.tv_nsec;
            if (diff_nsec < 0) {
                diff_sec--;
                diff_nsec += 1000000000L;
            }

            if (diff_sec >= 0 && diff_nsec >= 0) {
                // Toggle the relay
                int current_state = gpiod_line_get_value(relay_lines[i]);
                if (current_state < 0) {
                    fprintf(stderr, "Error: Failed to read GPIO line value\n");
                    program_running = 0;
                    break;
                }

                int new_state = !current_state;
                if (set_relay(relay_lines[i], new_state) < 0) {
                    program_running = 0;
                    break;
                }

                printf("Relay %d toggled to %s\n", i + 1, new_state ? "ON" : "OFF");
            }
        }

        // Sleep for 100ms to avoid excessive CPU usage
        struct timespec sleep_time = {0, 100000000L};
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    cleanup_gpio(relay_lines, relay_pins, NUM_RELAYS);
    gpiod_chip_close(chip);

    printf("Smart Lighting System stopped.\n");
    return 0;
}

