#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define GYRO_SENSITIVITY 131.0f // LSB per deg/s for +-250 dps
#define BUFFER_SIZE 100
#define THRESHOLD 50.0f

// Data structure for gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
static int i2c_fd = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Initialize MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); // Wait 100ms for sensor to stabilize

    // Verify device identity
    uint8_t who_am_i = 0;
    buf[0] = WHO_AM_I;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x68, got 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buf[6];

    // Write register address
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    data->x = (float)raw_x / GYRO_SENSITIVITY;
    data->y = (float)raw_y / GYRO_SENSITIVITY;
    data->z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Check if angular velocity exceeds threshold
void check_threshold(gyro_data_t data) {
    float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f deg/s\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main() {
    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        cleanup();
        return 1;
    }

    printf("MPU-6050 initialized successfully. Reading gyroscope data...\n");

    // Main loop
    while (running) {
        gyro_data_t gyro_data;
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            add_to_buffer(&gyro_buffer, gyro_data);
            check_threshold(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }
        usleep(10000); // 10ms delay
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

