/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART: /dev/serial0 (TXD=GPIO14, RXD=GPIO15) at 9600 baud
 * Library: pigpio (userspace serial)
 *
 * Build: gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lpigpio -lrt
 * Run:   sudo ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE   "/dev/serial0"
#define BAUD_RATE     9600
#define LOG_FILE      "co2_log.json"
#define ERROR_LOG     "co2_error.log"
#define READ_INTERVAL 5          /* seconds between readings */
#define READ_TIMEOUT  1000000    /* microseconds (1 s) for 9-byte read */
#define READ_RETRIES  10
#define READ_RETRY_US 10000      /* 10 ms between retries */

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_log_file   = NULL;
static FILE *g_err_file   = NULL;

/* ------------------------------------------------------------------ */
/* Logging helpers                                                     */
/* ------------------------------------------------------------------ */

static void log_error(const char *msg)
{
    if (!g_err_file) return;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    fprintf(g_err_file,
            "[%04d-%02d-%02d %02d:%02d:%02d.%06ld] ERROR: %s\n",
            tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
            tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
            ts.tv_nsec / 1000, msg);
    fflush(g_err_file);
}

static void log_data(int co2_ppm, int error_flag)
{
    if (!g_log_file) return;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    fprintf(g_log_file,
            "{\"timestamp\": \"%04d-%02d-%02dT%02d:%02d:%02d.%06ld\", "
            "\"co2_ppm\": %d, \"error_flag\": %d}\n",
            tm_info.tm_year + 1900, tm_info.tm_mon + 1, tm_info.tm_mday,
            tm_info.tm_hour, tm_info.tm_min, tm_info.tm_sec,
            ts.tv_nsec / 1000, co2_ppm, error_flag);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* MH-Z19B protocol                                                    */
/* ------------------------------------------------------------------ */

/*
 * 9-byte response from MH-Z19B after a 9-byte command:
 *   response[0] = 0xFF
 *   response[1] = 0x86  (command echo)
 *   response[2..3] = CO2 ppm (big-endian)
 *   response[4..5] = temperature (x0.1 °C, valid only in range)
 *   response[6..7] = status (0 = OK, 1 = warning, 2 = error)
 *   response[8]   = checksum (sum of bytes 1..7, inverted, +1)
 */
static int validate_checksum(const uint8_t *resp)
{
    uint8_t sum = 0;
    for (int i = 1; i <= 7; i++)
        sum += resp[i];
    sum = (uint8_t)(~sum + 1);
    return (sum == resp[8]);
}

/*
 * Send the 9-byte read command and read back 9 bytes.
 * Returns 0 on success, -1 on error.
 */
static int read_co2(int handle, int *co2_ppm, int *error_flag)
{
    uint8_t cmd[9] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    uint8_t resp[9];

    *co2_ppm     = -1;
    *error_flag  = 1;

    if (serWrite(handle, (char *)cmd, sizeof(cmd)) != (int)sizeof(cmd)) {
        log_error("serWrite failed (command send)");
        return -1;
    }

    /* MH-Z19B needs ~100 ms after the command is sent */
    gpioDelay(100000); /* 100 ms */

    int total = 0;
    int retries = 0;
    while (total < 9 && retries < READ_RETRIES) {
        int avail = serDataAvailable(handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail == 0) {
            gpioDelay(READ_RETRY_US);
            retries++;
            continue;
        }

        int to_read = (avail < (9 - total)) ? avail : (9 - total);
        int n = serRead(handle, (char *)(resp + total), to_read);
        if (n <= 0) {
            log_error("serRead failed");
            return -1;
        }
        total += n;
        retries = 0;
    }

    if (total < 9) {
        log_error("Timeout waiting for full 9-byte response");
        return -1;
    }

    if (!validate_checksum(resp)) {
        log_error("Checksum mismatch on response");
        return -1;
    }

    *co2_ppm     = (resp[2] << 8) | resp[3];
    *error_flag  = resp[6] & 0x03;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_err_file) {
        fclose(g_err_file);
        g_err_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- open error log ---- */
    g_err_file = fopen(ERROR_LOG, "a");
    if (!g_err_file) {
        perror("fopen(" ERROR_LOG ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open data log ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        fclose(g_err_file);
        g_err_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- open UART ---- */
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        log_error("serOpen failed");
        fprintf(stderr, "Failed to open UART %s\n", UART_DEVICE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MH-Z19B CO2 monitor started on %s @ %d baud\n",
           UART_DEVICE, BAUD_RATE);
    printf("Logging to %s every %d s. Press Ctrl-C to exit.\n",
           LOG_FILE, READ_INTERVAL);

    /* ---- main loop ---- */
    while (g_running) {
        int co2_ppm = -1;
        int error_flag = 1;

        if (read_co2(g_uart_handle, &co2_ppm, &error_flag) == 0) {
            log_data(co2_ppm, error_flag);
            printf("{\"co2_ppm\": %d, \"error_flag\": %d}\n",
                   co2_ppm, error_flag);
            fflush(stdout);
        } else {
            log_error("read_co2 failed; skipping this sample");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

