#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_ID_REG_A 0x0A

#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer = {{0.0f}, 0, 0};

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int hmc5883l_init(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);
