#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_PIN    17
#define GREEN_PIN  27
#define BLUE_PIN   22
#define I2C_BUS    1
#define BH1750_ADDR 0x23
#define BH1750_CONT_HRES 0x10
#define LUX_DIVISOR 1.2f
#define LUX_THRESHOLD_RED   50
#define LUX_THRESHOLD_GREEN 150
#define LUX_THRESHOLD_BLUE  300
#define LOG_FILE "lighting_log.txt"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(int fd, float *lux_out) {
    unsigned char buf[2];
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;
    usleep(120000);
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / LUX_DIVISOR;
    return 0;
}

static void log_data(FILE *log_file, float lux, int red_on, int green_on, int blue_on) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, RED: %d, GREEN: %d, BLUE: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, lux, red_on, green_on, blue_on);
    fflush(log_file);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int i2c_fd = -1;
    FILE *log_file = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        goto cleanup;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        float lux = 0.0f;
        int red_on = 0, green_on = 0, blue_on = 0;

        if (read_bh1750(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; turning off all relays.\n");
            gpiod_line_set_value(red_line, 0);
            gpiod_line_set_value(green_line, 0);
            gpiod_line_set_value(blue_line, 0);
        } else {
            printf("Lux: %.2f\n", lux);
            if (lux < LUX_THRESHOLD_RED) {
                red_on = 1;
            } else if (lux < LUX_THRESHOLD_GREEN) {
                green_on = 1;
            } else if (lux < LUX_THRESHOLD_BLUE) {
                blue_on = 1;
            } else {
                red_on = 1; green_on = 1; blue_on = 1;
            }
            gpiod_line_set_value(red_line, red_on);
            gpiod_line_set_value(green_line, green_on);
            gpiod_line_set_value(blue_line, blue_on);
        }

        log_data(log_file, lux, red_on, green_on, blue_on);
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    ret = 0;

cleanup:
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    return ret;
}

