#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

#define DISTANCE_MIN 10
#define DISTANCE_MAX 100
#define DISTANCE_THRESHOLD 50

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_motor_direction(int in1, int in2, int pwm_pin, int forward) {
    if (gpioWrite(in1, forward ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", in1);
        return -1;
    }
    if (gpioWrite(in2, forward ? 0 : 1) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", in2);
        return -1;
    }
    if (gpioPWM(pwm_pin, forward ? PWM_RANGE : 0) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pwm_pin);
        return -1;
    }
    return 0;
}

static int set_motor_speed(int in1, int in2, int pwm_pin, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (gpioPWM(pwm_pin, speed) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pwm_pin);
        return -1;
    }
    return 0;
}

static int stop_motor(int in1, int in2, int pwm_pin) {
    if (gpioWrite(in1, 0) < 0) return -1;
    if (gpioWrite(in2, 0) < 0) return -1;
    if (gpioPWM(pwm_pin, 0) < 0) return -1;
    return 0;
}

static int map_distance_to_speed(int distance) {
    if (distance < DISTANCE_MIN) distance = DISTANCE_MIN;
    if (distance > DISTANCE_MAX) distance = DISTANCE_MAX;
    int speed = (int)(((float)(DISTANCE_MAX - distance) / (DISTANCE_MAX - DISTANCE_MIN)) * PWM_RANGE);
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    return speed;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        return -1;
    }
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        return -1;
    }
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    stop_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_A_IN2);
    stop_motor(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_B_IN4);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (g_running) {
        int distance_a = 70;
        int distance_b = 80;

        int speed_a = map_distance_to_speed(distance_a);
        int speed_b = map_distance_to_speed(distance_b);

        int forward_a = (distance_a < DISTANCE_THRESHOLD) ? 1 : 0;
        int forward_b = (distance_b < DISTANCE_THRESHOLD) ? 1 : 0;

        if (set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_A_IN2, forward_a) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_A_IN2, speed_a) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (set_motor_direction(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_B_IN4, forward_b) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }
        if (set_motor_speed(MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_B_IN4, speed_b) < 0) {
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        usleep(100000);
    }

    cleanup_gpio();
    return EXIT_SUCCESS;
}

