#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEP_DELAY_US 2000
#define STEPS_PER_QUARTER 512

static volatile sig_atomic_t running = 1;

static const int coils[4] = {IN1, IN2, IN3, IN4};

static const int step_sequence[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned p) {
    if (gpioSetPullUpDown(gpio, p) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, p);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    for (int i = 0; i < 4; i++)
        gpioWrite(coils[i], 0);
}

static void rotate_clockwise(int steps) {
    for (int i = 0; i < steps && running; i++) {
        for (int j = 0; j < 4; j++)
            safe_write(coils[j], step_sequence[i % 4][j]);
        gpioDelay(STEP_DELAY_US);
    }
}

static void rotate_counter_clockwise(int steps) {
    for (int i = 0; i < steps && running; i++) {
        for (int j = 0; j < 4; j++)
            safe_write(coils[j], step_sequence[(3 - (i % 4)) % 4][j]);
        gpioDelay(STEP_DELAY_US);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0 ||
        safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0)
        goto fail;

    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0)
        goto fail;

    for (int i = 0; i < 4; i++)
        if (safe_set_mode(coils[i], PI_OUTPUT) < 0)
            goto fail;

    deenergize();

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Automatic Door Lock Simulation\n");
    printf("Lock Button: BCM GPIO24 (active-low, pull-up)\n");
    printf("Unlock Button: BCM GPIO23 (active-low, pull-up)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            rotate_clockwise(STEPS_PER_QUARTER);
            while (gpioRead(LOCK_BUTTON) == 0 && running)
                gpioDelay(10000);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            rotate_counter_clockwise(STEPS_PER_QUARTER);
            while (gpioRead(UNLOCK_BUTTON) == 0 && running)
                gpioDelay(10000);
        }

        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;

fail:
    deenergize();
    gpioTerminate();
    return EXIT_FAILURE;
}

