#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define PWM_DUTY_MAX_NS 1000000
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_exported = 0;
static int pwm_enabled = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(i2c_fd, buf, 2) == 2) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_regs(uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(i2c_fd, &reg, 1) != 1) { usleep(I2C_RETRY_DELAY_MS * 1000); continue; }
        if (read(i2c_fd, buf, len) == len) return 0;
        usleep(I2C_RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int init_mpu6050(void) {
    if (i2c_write_reg(PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU-6050\n");
        return -1;
    }
    usleep(100000);
    if (i2c_write_reg(ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accel config\n");
        return -1;
    }
    if (i2c_write_reg(GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set gyro config\n");
        return -1;
    }
    return 0;
}

static int read_accel(float *pitch, float *roll) {
    uint8_t buf[6];
    if (i2c_read_regs(ACCEL_XOUT_H, buf, 6) < 0) return -1;
    int16_t ax = (buf[0] << 8) | buf[1];
    int16_t ay = (buf[2] << 8) | buf[3];
    int16_t az = (buf[4] << 8) | buf[5];
    *pitch = atan2f(ax, sqrtf(ay * ay + az * az)) * 180.0f / M_PI;
    *roll = atan2f(ay, sqrtf(ax * ax + az * az)) * 180.0f / M_PI;
    return 0;
}

static int set_servo_angle(float angle) {
    if (angle < 0.0f) angle = 0.0f;
    if (angle > 180.0f) angle = 180.0f;
    int duty_ns = (int)((angle / 180.0f) * PWM_DUTY_MAX_NS);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val[32];
    snprintf(val, sizeof(val), "%d", duty_ns);
    if (write(fd, val, strlen(val)) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int log_data(float pitch, float roll, int servo_pos) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return -1;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, pitch, roll, servo_pos);
    fclose(fp);
    return 0;
}

static int pwm_export(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val[4] = "0";
    if (write(fd, val, 1) < 0) { close(fd); return -1; }
    close(fd);
    usleep(100000);
    return 0;
}

static int pwm_unexport(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val[4] = "0";
    if (write(fd, val, 1) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int pwm_enable(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val[4] = "1";
    if (write(fd, val, 1) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int pwm_disable(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val[4] = "0";
    if (write(fd, val, 1) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static int pwm_set_period(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) return -1;
    char val[20];
    snprintf(val, sizeof(val), "%d", PWM_PERIOD_NS);
    if (write(fd, val, strlen(val)) < 0) { close(fd); return -1; }
    close(fd);
    return 0;
}

static void cleanup(void) {
    if (pwm_enabled) pwm_disable();
    if (pwm_exported) pwm_unexport();
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error: Cannot set I2C slave 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 init failed\n");
        close(i2c_fd);
        return 1;
    }
    if (pwm_export() < 0) {
        fprintf(stderr, "Error: Failed to export PWM\n");
        close(i2c_fd);
        return 1;
    }
    pwm_exported = 1;
    if (pwm_set_period() < 0) {
        fprintf(stderr, "Error: Failed to set PWM period\n");
        cleanup();
        return 1;
    }
    if (pwm_enable() < 0) {
        fprintf(stderr, "Error: Failed to enable PWM\n");
        cleanup();
        return 1;
    }
    pwm_enabled = 1;

    while (running) {
        float pitch, roll;
        if (read_accel(&pitch, &roll) < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            usleep(100000);
            continue;
        }
        float angle = pitch * 0.5f;
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Warning: Failed to set servo angle\n");
        }
        int servo_pos = (int)angle;
        if (log_data(pitch, roll, servo_pos) < 0) {
            fprintf(stderr, "Warning: Failed to log data\n");
        }
        usleep(100000);
    }

    cleanup();
    return 0;
}

