#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQ 100
#define PWM_RANGE 100

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

static schedule_entry_t schedule[100];
static int schedule_size = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int line_num = 0;
    while (fgets(line, sizeof(line), fp) && line_num < 100) {
        if (line[0] == '#' || line[0] == '\n') continue;
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &schedule[line_num].hour,
                   &schedule[line_num].minute,
                   &schedule[line_num].second,
                   &schedule[line_num].relay_number,
                   &schedule[line_num].on_off) != 5) {
            fprintf(stderr, "Invalid schedule entry at line %d: %s", line_num + 1, line);
            line_num++;
            continue;
        }
        if (schedule[line_num].relay_number < 1 || schedule[line_num].relay_number > NUM_RELAYS) {
            fprintf(stderr, "Invalid relay number %d at line %d\n", schedule[line_num].relay_number, line_num + 1);
            line_num++;
            continue;
        }
        if (schedule[line_num].on_off != 0 && schedule[line_num].on_off != 1) {
            fprintf(stderr, "Invalid on/off value %d at line %d\n", schedule[line_num].on_off, line_num + 1);
            line_num++;
            continue;
        }
        line_num++;
    }
    fclose(fp);
    return line_num;
}

static int find_schedule_entry(int relay_number, int on_off) {
    for (int i = 0; i < schedule_size; i++) {
        if (schedule[i].relay_number == relay_number && schedule[i].on_off == on_off)
            return i;
    }
    return -1;
}

static int set_relay(int relay_number, int on_off) {
    int pin = relay_pins[relay_number - 1];
    if (gpioWrite(pin, on_off) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_relay(int relay_number, int on_off) {
    int pin = relay_pins[relay_number - 1];
    int current_brightness = 0;
    int step = 100 / FADE_DURATION;
    if (step <= 0) step = 1;

    for (int i = 0; i <= FADE_DURATION && running; i++) {
        if (on_off) {
            current_brightness += step;
            if (current_brightness > 100) current_brightness = 100;
        } else {
            current_brightness -= step;
            if (current_brightness < 0) current_brightness = 0;
        }
        if (gpioPWM(pin, current_brightness) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pin);
            return -1;
        }
        gpioDelay(1000000 / FADE_DURATION);
    }
    if (gpioPWM(pin, on_off ? 100 : 0) != 0) {
        fprintf(stderr, "Failed to set final PWM on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQ);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
        gpioWrite(relay_pins[i], 0);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    schedule_size = read_schedule("lighting_schedule.txt");
    if (schedule_size <= 0) {
        fprintf(stderr, "No valid schedule entries found. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Smart Home Lighting System started. Schedule loaded: %d entries\n", schedule_size);

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        if (!tm_info) {
            fprintf(stderr, "localtime failed\n");
            sleep(1);
            continue;
        }

        int current_hour = tm_info->tm_hour;
        int current_minute = tm_info->tm_min;
        int current_second = tm_info->tm_sec;

        for (int i = 0; i < schedule_size; i++) {
            if (schedule[i].hour == current_hour &&
                schedule[i].minute == current_minute &&
                schedule[i].second == current_second) {

                int relay_num = schedule[i].relay_number;
                int on_off = schedule[i].on_off;

                if (find_schedule_entry(relay_num, on_off) == i) {
                    if (set_relay(relay_num, on_off) != 0) {
                        fprintf(stderr, "Failed to set relay %d\n", relay_num);
                    } else if (on_off) {
                        if (fade_relay(relay_num, on_off) != 0) {
                            fprintf(stderr, "Fade failed for relay %d\n", relay_num);
                        }
                    }
                }
            }
        }
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

