#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define BUZZER_PIN  18

#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define MIN_DISTANCE  2.0
#define MAX_DISTANCE  30.0

#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    20000
#define MEASURE_GAP_US   60000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise BUZZER_PIN low.\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void trigger_sensor(void) {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double measure_distance(void) {
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start;

    trigger_sensor();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - timeout_start) > 100000) {
            fprintf(stderr, "Error: echo pin stuck low (sensor absent?).\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    timeout_start = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - timeout_start) > 100000) {
            fprintf(stderr, "Error: echo pin stuck high (timeout).\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;
    double distance = (pulse_width / 1000000.0) * 34300.0 / 2.0;

    if (distance < 2.0 || distance > 400.0) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range.\n", distance);
        return -1.0;
    }

    return distance;
}

static int map_distance_to_frequency(double distance) {
    if (distance < 0.0) return -1;

    double frequency = MIN_FREQUENCY +
        (distance - MIN_DISTANCE) *
        (MAX_FREQUENCY - MIN_FREQUENCY) /
        (MAX_DISTANCE - MIN_DISTANCE);

    if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
    if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

    return (int)frequency;
}

static void set_buzzer_frequency(int frequency) {
    if (frequency < 0) {
        gpioWrite(BUZZER_PIN, 0);
        return;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency %d Hz.\n", frequency);
        return;
    }

    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: failed to start PWM on BUZZER_PIN.\n");
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            set_buzzer_frequency(-1);
        } else {
            int frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

