#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_pwm(unsigned pin, unsigned duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %u) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static int set_led_color(float proximity) {
    if (proximity < 0.0f || proximity > 1.0f) {
        fprintf(stderr, "Error: Proximity value out of range: %.2f\n", proximity);
        return -1;
    }

    int red_duty   = (int)(proximity * 255.0f);
    int green_duty = (int)((1.0f - proximity) * 255.0f);
    int blue_duty  = 0;

    if (safe_pwm(RED_PIN,   red_duty)   < 0) return -1;
    if (safe_pwm(GREEN_PIN, green_duty) < 0) return -1;
    if (safe_pwm(BLUE_PIN,  blue_duty)  < 0) return -1;

    return 0;
}

static float simulate_proximity(void) {
    static float phase = 0.0f;
    phase += 0.01f;
    if (phase > 2.0f * (float)M_PI) phase -= 2.0f * (float)M_PI;
    return 0.5f + 0.5f * sinf(phase);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RED_PIN,   PI_OUTPUT) < 0 ||
        safe_set_mode(GREEN_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(BLUE_PIN,  PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN,   PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_pwm(RED_PIN,   0) < 0 ||
        safe_pwm(GREEN_PIN, 0) < 0 ||
        safe_pwm(BLUE_PIN,  0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity alert simulation running. Press Ctrl+C to exit.\n");

    while (running) {
        float proximity = simulate_proximity();
        if (set_led_color(proximity) < 0) {
            fprintf(stderr, "Warning: LED update failed\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    safe_pwm(RED_PIN,   0);
    safe_pwm(GREEN_PIN, 0);
    safe_pwm(BLUE_PIN,  0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

