#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_DATA_LEN  6
#define SAMPLE_MS      100
#define LOG_FILE       "gyro_log.txt"
#define SENSITIVITY    131.0f  /* LSB per deg/s for ±250 deg/s range */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_block: read %zd bytes from 0x%02X failed: %s\n",
                n, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */
    return 0;
}

static int read_gyro(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[GYRO_DATA_LEN];
    if (i2c_read_block(fd, GYRO_XOUT_H, buf, GYRO_DATA_LEN) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / SENSITIVITY;
    *gy = (float)raw_y / SENSITIVITY;
    *gz = (float)raw_z / SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float gx, float gy, float gz)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 init failed (sensor absent or bus error)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float gx, gy, gz;
        if (read_gyro(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "read_gyro failed; continuing\n");
        } else {
            log_data(fp, gx, gy, gz);
        }
        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

