#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define EARTHQUAKE_THRESHOLD 3
#define EVENT_WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_file, int value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - GPIO%d: %d\n", timestamp, GPIO_LINE_OFFSET, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void check_earthquake(int window[], int idx, int value)
{
    window[idx] = value;
    int count = 0;
    for (int i = 0; i < EVENT_WINDOW_SIZE; i++) {
        if (window[i] == 1) {
            count++;
        }
    }
    if (count >= EARTHQUAKE_THRESHOLD) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL &&
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
            printf("EARTHQUAKE ALERT - %s\n", timestamp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to generate timestamp for alert\n");
        }
    }
}

int main(int argc, char *argv[])
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_file = NULL;
    int window[EVENT_WINDOW_SIZE] = {0};
    int window_idx = 0;
    int ret = EXIT_FAILURE;
    int timeout_ms = DEFAULT_TIMEOUT_MS;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout '%s', using default %d ms\n", argv[1], DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    fflush(stdout);

    while (program_running) {
        struct timespec ts;
        ts.tv_sec = timeout_ms / 1000;
        ts.tv_nsec = (timeout_ms % 1000) * 1000000L;

        int rv = gpiod_line_event_wait(line, &ts);
        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (rv == 0) {
            continue;
        }

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) != 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            log_event(log_file, 1);
            check_earthquake(window, window_idx, 1);
            window_idx = (window_idx + 1) % EVENT_WINDOW_SIZE;
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            log_event(log_file, 0);
            check_earthquake(window, window_idx, 0);
            window_idx = (window_idx + 1) % EVENT_WINDOW_SIZE;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }
    return ret;
}

