/*
 * LSM303DLHC Magnetometer reader for Raspberry Pi Zero W
 * Uses Linux I2C-dev (no wiringPi dependency).
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (physical pin 3)
 *   LSM303DLHC SCL -> GPIO3 (physical pin 5)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build:  gcc -O2 -Wall -o mag_log mag_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC magnetometer constants ---- */
#define LSM303_MAG_ADDR        0x1E   /* 7-bit I2C address (SA1 tied to GND) */
#define LSM303_MAG_MR_REG_M    0x02   /* Mode register */
#define LSM303_MAG_CRA_REG_M   0x00   /* Control register A */
#define LSM303_MAG_OUT_X_H_M   0x03   /* X MSB (auto-increment reads 6 bytes) */

/* ---- Calibration offsets (replace with your calibrated values) ---- */
#define X_OFFSET  10.0f
#define Y_OFFSET  -5.0f
#define Z_OFFSET  20.0f

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit register using SMBus-style ioctl.       */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at an 8-bit register using SMBus-style ioctl. */
/* ------------------------------------------------------------------ */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *dst, size_t n)
{
    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_regs: write reg pointer 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* Read data bytes */
    ssize_t got = read(fd, dst, n);
    if (got < 0 || (size_t)got != n) {
        fprintf(stderr, "i2c_read_regs: read 0x%02X failed: %s (got %zd, want %zu)\n",
                reg, strerror(errno), got, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of magnetometer data (X, Z, Y order per datasheet).   */
/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (i2c_read_regs(fd, LSM303_MAG_OUT_X_H_M, raw, sizeof(raw)) != 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibrate raw magnetometer values using hard-iron offsets.         */
/* ------------------------------------------------------------------ */
static void calibrate_magnetometer(int16_t raw_x, int16_t raw_y,
                                   int16_t raw_z,
                                   float *cal_x, float *cal_y, float *cal_z)
{
    *cal_x = (float)raw_x - X_OFFSET;
    *cal_y = (float)raw_y - Y_OFFSET;
    *cal_z = (float)raw_z - Z_OFFSET;
}

/* ------------------------------------------------------------------ */
/* Compute compass heading from calibrated X and Y (degrees 0-360).   */
/* ------------------------------------------------------------------ */
static float calculate_heading(float cal_x, float cal_y)
{
    float heading = atan2f(cal_y, cal_x) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

/* ------------------------------------------------------------------ */
/* Map heading to one of eight compass directions.                    */
/* ------------------------------------------------------------------ */
static const char *heading_to_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f)  return "N";
    if (heading < 67.5f)                       return "NE";
    if (heading < 112.5f)                      return "E";
    if (heading < 157.5f)                      return "SE";
    if (heading < 202.5f)                      return "S";
    if (heading < 247.5f)                      return "SW";
    if (heading < 292.5f)                      return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
/* Append one CSV row; write header if file is empty.                  */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float cal_x, float cal_y, float cal_z,
                    float heading, const char *direction)
{
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n") < 0) {
            fprintf(stderr, "fprintf header failed: %s\n", strerror(errno));
            return -1;
        }
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%s\n",
                ts, cal_x, cal_y, cal_z, heading, direction) < 0) {
        fprintf(stderr, "fprintf data failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire the magnetometer slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure magnetometer: continuous-conversion mode ---- */
    if (i2c_write_reg8(g_i2c_fd, LSM303_MAG_MR_REG_M, 0x00) != 0) {
        fprintf(stderr, "Failed to set magnetometer mode register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Optionally set output data rate to 15 Hz ---- */
    if (i2c_write_reg8(g_i2c_fd, LSM303_MAG_CRA_REG_M, 0x14) != 0) {
        fprintf(stderr, "Warning: could not set magnetometer CRA_REG_M\n");
        /* non-fatal: continue with default */
    }

    /* ---- Open log file (append mode) ---- */
    g_log_fp = fopen("mag_log.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen mag_log.csv failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (read_magnetometer(g_i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Skipping sample due to I2C read failure\n");
            sleep(1);
            continue;
        }

        float cal_x, cal_y, cal_z;
        calibrate_magnetometer(raw_x, raw_y, raw_z, &cal_x, &cal_y, &cal_z);

        float heading = calculate_heading(cal_x, cal_y);
        const char *direction = heading_to_direction(heading);

        printf("Heading: %6.2f deg  %s\n", heading, direction);

        if (log_data(g_log_fp, cal_x, cal_y, cal_z, heading, direction) != 0)
            fprintf(stderr, "Logging failed (continuing)\n");

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

