#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define LOG_FILE "relay_log.json"
#define DEBOUNCE_US 200000  /* 200 ms */

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t relay_state = 0;
static volatile uint32_t last_touch_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int toggle_relay(void) {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN) failed\n");
        return -1;
    }
    return 0;
}

static int log_relay_state(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t rawtime = time(NULL);
    if (rawtime == (time_t)-1) {
        perror("Error getting time");
        fclose(fp);
        return -1;
    }

    struct tm timeinfo;
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("Error converting time");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            timestamp, relay_state ? "ON" : "OFF");
    fclose(fp);
    return 0;
}

static void touch_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;

    if (level != 1) {
        return; /* Only act on rising edge (touch) */
    }

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_US) {
        return; /* Debounce: ignore touches within 200 ms */
    }
    last_touch_tick = tick;

    if (toggle_relay() == 0) {
        if (log_relay_state() != 0) {
            fprintf(stderr, "Warning: failed to log relay state\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_SENSOR_PIN, RISING_EDGE, 0, touch_callback) != 0) {
        fprintf(stderr, "Error: gpioSetISRFunc failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: sigaction(SIGINT) failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control program running. Touch GPIO%d to toggle relay on GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); /* 100 ms sleep */
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (log_relay_state() != 0) {
        fprintf(stderr, "Warning: failed to log final relay state\n");
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

