#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_OFF_TIME 1
#define POLL_INTERVAL 10
#define LOG_FILE "irrigation_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static FILE *log_fp = NULL;
static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n", relay_pins[i], strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int activate_relay(int relay_num) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return -1;
    }
    if (gpiod_line_set_value(lines[relay_num], 0) < 0) {
        fprintf(stderr, "Failed to set line %u low: %s\n", relay_pins[relay_num], strerror(errno));
        return -1;
    }
    return 0;
}

static int deactivate_relay(int relay_num) {
    if (relay_num < 0 || relay_num >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_num);
        return -1;
    }
    if (gpiod_line_set_value(lines[relay_num], 1) < 0) {
        fprintf(stderr, "Failed to set line %u high: %s\n", relay_pins[relay_num], strerror(errno));
        return -1;
    }
    return 0;
}

static int log_event(int relay_num, int moisture_level) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(log_fp, "%s - Relay %d activated. Moisture level: %d\n", timestamp, relay_num + 1, moisture_level) < 0) {
        fprintf(stderr, "Failed to write to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_fp) == EOF) {
        fprintf(stderr, "Failed to flush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    srand((unsigned int)time(NULL));

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_fp);
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = rand() % 101;
        printf("Simulated moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS && running; i++) {
                if (activate_relay(i) < 0) {
                    fprintf(stderr, "Failed to activate relay %d\n", i + 1);
                    continue;
                }
                printf("Relay %d activated\n", i + 1);
                if (log_event(i, moisture_level) < 0) {
                    fprintf(stderr, "Failed to log event for relay %d\n", i + 1);
                }
                sleep(RELAY_ON_TIME);
                if (deactivate_relay(i) < 0) {
                    fprintf(stderr, "Failed to deactivate relay %d\n", i + 1);
                }
                printf("Relay %d deactivated\n", i + 1);
                sleep(RELAY_OFF_TIME);
            }
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

