/*
 * Automated plant watering system — Raspberry Pi Zero W
 * Library : pigpio (modern, actively maintained)
 * Servos  : SG90
 *   Valve  (GPIO17, pin 11) — 0° = closed, 90° = open
 *   Nozzle (GPIO18, pin 12) — 0°, 45°, 90°, 135°, 180°
 *
 * Build  : gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run    : sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PIN        17
#define NOZZLE_PIN       18

#define MOISTURE_THRESHOLD 50

/* SG90 pulse-width range (microseconds) */
#define SERVO_MIN_PULSE  500   /* 0°   */
#define SERVO_MAX_PULSE  2500  /* 180° */

/* Valve positions (pulse widths) */
#define VALVE_CLOSED     500   /* 0°   */
#define VALVE_OPEN       1500  /* 90°  */

/* Nozzle angles (degrees) and corresponding pulse widths */
static const int nozzle_angles[] = {0, 45, 90, 135, 180};
static const int nozzle_pw[]     = {500, 1000, 1500, 1800, 2500};
#define NOZZLE_COUNT (int)(sizeof(nozzle_angles) / sizeof(nozzle_angles[0]))

/* Simulated moisture readings (percent) */
static const int moisture_readings[] = {20, 40, 60, 80, 100};
#define MOISTURE_READINGS_COUNT \
    (int)(sizeof(moisture_readings) / sizeof(moisture_readings[0]))

#define SERVO_SETTLE_US  300000   /* 300 ms — let servo reach position */
#define WATERING_HOLD_S  5
#define CYCLE_DELAY_S    5
#define RETRY_DELAY_US   100000   /* 100 ms */
#define MAX_RETRIES       3

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Servo helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Set a servo pulse width on the given GPIO.
 * Returns 0 on success, -1 on failure after MAX_RETRIES.
 */
static int set_servo_pulse(int pin, int pulse_width)
{
    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (gpioServo(pin, pulse_width) == 0)
            return 0;
        fprintf(stderr,
                "Warning: gpioServo(pin=%d, pw=%d) failed (attempt %d/%d)\n",
                pin, pulse_width, attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_US);
    }
    fprintf(stderr,
            "Error: failed to set servo on GPIO%d after %d retries\n",
            pin, MAX_RETRIES);
    return -1;
}

/*
 * Stop a servo (pulse width 0) and release the pin.
 * Safe to call even if the servo was never started.
 */
static void stop_servo(int pin)
{
    gpioServo(pin, 0);   /* stop sending pulses */
}

/* ------------------------------------------------------------------ */
/* Watering logic                                                      */
/* ------------------------------------------------------------------ */
static void water_plant(void)
{
    printf("Watering plant...\n");
    fflush(stdout);

    /* Open valve to 90° */
    if (set_servo_pulse(VALVE_PIN, VALVE_OPEN) != 0) {
        fprintf(stderr, "Critical: valve failed to open — skipping watering\n");
        return;
    }
    usleep(SERVO_SETTLE_US);

    /* Sweep nozzle through all five angles */
    for (int i = 0; i < NOZZLE_COUNT && g_running; ++i) {
        if (set_servo_pulse(NOZZLE_PIN, nozzle_pw[i]) != 0) {
            fprintf(stderr,
                    "Warning: nozzle failed to reach %d° — skipping to next\n",
                    nozzle_angles[i]);
            continue;
        }
        usleep(SERVO_SETTLE_US);
        printf("  Nozzle at %d°\n", nozzle_angles[i]);
        fflush(stdout);
        sleep(WATERING_HOLD_S);
    }

    /* Close valve to 0° */
    if (set_servo_pulse(VALVE_PIN, VALVE_CLOSED) != 0) {
        fprintf(stderr, "Critical: valve failed to close\n");
    }
    usleep(SERVO_SETTLE_US);

    printf("Watering complete.\n");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers early ----------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Main loop -------------------------------------------------- */
    for (int i = 0; i < MOISTURE_READINGS_COUNT && g_running; ++i) {
        int moisture = moisture_readings[i];
        printf("Moisture reading: %d%%\n", moisture);
        fflush(stdout);

        if (moisture < MOISTURE_THRESHOLD) {
            water_plant();
        } else {
            printf("Skipping watering — moisture above threshold (%d%%).\n",
                   moisture);
            fflush(stdout);
        }

        if (g_running)
            sleep(CYCLE_DELAY_S);
    }

    /* --- Clean shutdown -------------------------------------------- */
    stop_servo(VALVE_PIN);
    stop_servo(NOZZLE_PIN);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

