#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEP_DELAY_US 3000
#define DEBOUNCE_US 50000
#define STEPS_PER_REV 512

static volatile sig_atomic_t running = 1;

static const int coil_pins[4] = {IN1, IN2, IN3, IN4};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, int level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_set_pull(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    for (int i = 0; i < 4; i++)
        safe_write(coil_pins[i], 0);
}

static void step(int phase) {
    deenergize();
    if (safe_write(coil_pins[phase], 1) < 0) return;
    gpioDelay(STEP_DELAY_US);
}

static void rotate_clockwise(int steps) {
    for (int i = 0; i < steps && running; i++) {
        step(0); step(1); step(2); step(3);
    }
}

static void rotate_counter_clockwise(int steps) {
    for (int i = 0; i < steps && running; i++) {
        step(3); step(2); step(1); step(0);
    }
}

static void lock_door(void) {
    printf("Locking door...\n");
    fflush(stdout);
    rotate_clockwise(STEPS_PER_REV);
    deenergize();
    printf("Door locked.\n");
    fflush(stdout);
}

static void unlock_door(void) {
    printf("Unlocking door...\n");
    fflush(stdout);
    rotate_counter_clockwise(STEPS_PER_REV);
    deenergize();
    printf("Door unlocked.\n");
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (safe_set_mode(coil_pins[i], PI_OUTPUT) < 0) goto fail;
        if (safe_write(coil_pins[i], 0) < 0) goto fail;
    }
    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0) goto fail;
    if (safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) goto fail;
    if (safe_set_pull(LOCK_BUTTON, PI_PUD_UP) < 0) goto fail;
    if (safe_set_pull(UNLOCK_BUTTON, PI_PUD_UP) < 0) goto fail;

    printf("Automatic Door Lock System\n");
    printf("Press the LOCK button (BCM %d) to lock the door.\n", LOCK_BUTTON);
    printf("Press the UNLOCK button (BCM %d) to unlock the door.\n", UNLOCK_BUTTON);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) lock_door();
        }
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) unlock_door();
        }
        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;

fail:
    deenergize();
    gpioTerminate();
    return EXIT_FAILURE;
}

