#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN  17
#define ECHO_PIN     18
#define LOG_FILE     "distance_log.txt"
#define TIMEOUT_US   50000   /* 50 ms per edge */
#define SETTLE_MS    60      /* 60 ms guard between measurements */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

/* Busy-wait for a line to reach the requested value or timeout. */
static int wait_for_line(struct gpiod_line *line, int value, int timeout_us)
{
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    long long deadline = (long long)t0.tv_sec * 1000000LL + t0.tv_nsec / 1000LL;
    deadline += timeout_us;

    for (;;) {
        int v = gpiod_line_get_value(line);
        if (v < 0)
            return -1;
        if (v == value)
            return 0;
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long long now = (long long)t1.tv_sec * 1000000LL + t1.tv_nsec / 1000LL;
        if (now > deadline)
            return 1;  /* timeout */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *logf = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    logf = fopen(LOG_FILE, "a");
    if (!logf) {
        perror("fopen");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low for a clean pulse. */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig, 0)");
            break;
        }
        usleep(5);

        /* 10 us trigger pulse. */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig, 1)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig, 0)");
            break;
        }

        /* Wait for echo rising edge. */
        int r = wait_for_line(echo, 1, TIMEOUT_US);
        if (r < 0) {
            fprintf(stderr, "Error reading echo rising edge.\n");
            fprintf(logf, "-1\n");
            fflush(logf);
            usleep(SETTLE_MS * 1000);
            continue;
        }
        if (r == 1) {
            fprintf(stderr, "Timeout waiting for echo rising edge.\n");
            fprintf(logf, "-1\n");
            fflush(logf);
            usleep(SETTLE_MS * 1000);
            continue;
        }

        struct timespec t_rise;
        clock_gettime(CLOCK_MONOTONIC, &t_rise);

        /* Wait for echo falling edge. */
        r = wait_for_line(echo, 0, TIMEOUT_US);
        if (r < 0) {
            fprintf(stderr, "Error reading echo falling edge.\n");
            fprintf(logf, "-1\n");
            fflush(logf);
            usleep(SETTLE_MS * 1000);
            continue;
        }
        if (r == 1) {
            fprintf(stderr, "Timeout waiting for echo falling edge.\n");
            fprintf(logf, "-1\n");
            fflush(logf);
            usleep(SETTLE_MS * 1000);
            continue;
        }

        struct timespec t_fall;
        clock_gettime(CLOCK_MONOTONIC, &t_fall);

        long long dur_us =
            (long long)(t_fall.tv_sec - t_rise.tv_sec) * 1000000LL +
            (t_fall.tv_nsec - t_rise.tv_nsec) / 1000LL;

        float dist_cm = (float)dur_us * 0.01715f;

        fprintf(logf, "%.2f\n", dist_cm);
        fflush(logf);
        printf("Distance: %.2f cm\n", dist_cm);

        usleep(SETTLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (logf)
        fclose(logf);
    if (trig)
        gpiod_line_release(trig);
    if (echo)
        gpiod_line_release(echo);
    if (chip)
        gpiod_chip_close(chip);
    return rc;
}

