#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define VL53L1X_ADDR   0x29
#define RELAY_GPIO     18
#define THRESHOLD_MM   500   /* 50 cm in mm */
#define POLL_DELAY_US  100000 /* 100 ms */

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET       0x0000
#define REG_SYSTEM_MODE      0x0080
#define REG_INT_STATUS       0x0044
#define REG_RESULT_DISTANCE  0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address + 1 byte value via pigpio I2C.
 * VL53L1X expects 16-bit register address (big-endian) followed by data byte. */
static int vl53l1x_write_reg(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read a 16-bit register address + 1 byte value via pigpio I2C.
 * Returns 0 on success, -1 on error. */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *value) {
    char addr[2];
    char data[1];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data[0];
    return 0;
}

/* Read a 16-bit register address + 2 bytes value via pigpio I2C.
 * Returns 0 on success, -1 on error. */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char addr[2];
    char data[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;

    /* Read model ID to confirm sensor is present */
    if (vl53l1x_read_reg(handle, 0x010F, &model_id) < 0) {
        fprintf(stderr, "Error: Cannot read VL53L1X model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Unexpected VL53L1X model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write_reg(handle, REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    /* Start continuous ranging */
    if (vl53l1x_write_reg(handle, REG_SYSTEM_MODE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int read_distance(int handle, uint16_t *distance_mm) {
    uint8_t int_status = 0;
    uint16_t dist = 0;

    /* Check if data is ready */
    if (vl53l1x_read_reg(handle, REG_INT_STATUS, &int_status) < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }
    if ((int_status & 0x07) == 0) {
        return 1; /* No new data yet */
    }

    /* Read 16-bit distance */
    if (vl53l1x_read_reg16(handle, REG_RESULT_DISTANCE, &dist) < 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }

    *distance_mm = dist;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

