/*
 * Automated plant watering system using libgpiod v1 API.
 *
 * Relays on BCM GPIO17, GPIO18, GPIO27, GPIO22 (pins 11, 12, 13, 15).
 * Active-low: LOW = relay energized (water ON).
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATERING_SECS   5
#define CYCLE_INTERVAL  60          /* seconds between cycles */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_watering_start(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s - Watering cycle started\n", ts);
    } else {
        fprintf(fp, "<unknown time> - Watering cycle started\n");
    }

    if (fclose(fp) != 0)
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
static void sleep_seconds(unsigned int seconds)
{
    while (seconds > 0 && g_running) {
        unsigned int chunk = (seconds > 10) ? 10 : seconds;
        sleep(chunk);
        seconds -= chunk;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int rc = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    /* ---- signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open gpiochip0 ------------------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- request relay lines as outputs, active-low --------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering-system", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* ---- main loop ------------------------------------------------- */
    while (g_running) {
        printf("Starting watering cycle...\n");
        log_watering_start();

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        sleep_seconds(WATERING_SECS);

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %u HIGH: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        printf("Watering cycle complete.\n");

        /* Sleep for the remainder of the 24-hour cycle, but wake every
         * second so signals are checked promptly. */
        unsigned int remaining = CYCLE_INTERVAL;
        while (remaining > 0 && g_running) {
            sleep_seconds(1);
            remaining--;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure all relays are de-energized (HIGH = inactive) before exit */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            (void)gpiod_line_set_value(lines[i], 1);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }

    if (chip)
        gpiod_chip_close(chip);

    printf("Exiting.\n");
    return rc;
}

