        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- request relay lines as outputs, active-low --------------- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "watering-system", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    /* ---- main loop ------------------------------------------------- */
    while (g_running) {
        printf("Starting watering cycle...\n");
        log_watering_start();

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %u LOW: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        sleep_seconds(WATERING_SECS);

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %u HIGH: %s\n",
                        relay_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        printf("Watering cycle complete.\n");

        /* Sleep for the remainder of the 24-hour cycle, but wake every
         * second so signals are checked promptly. */
        unsigned int remaining = CYCLE_INTERVAL;
        while (remaining > 0 && g_running) {
            sleep_seconds(1);
            remaining--;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Ensure all relays are de-energized (HIGH = inactive) before exit */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            (void)gpiod_line_set_value(lines[i], 1);
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }

    if (chip)
        gpiod_chip_close(chip);

    printf("Exiting.\n");
    return rc;
}

