#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_WHO_AM_I   0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_GYRO_XOUT_H 0x43

/* Expected WHO_AM_I value for MPU-6050 */
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Angular velocity threshold (degrees/second) */
#define ANGULAR_VELOCITY_THRESHOLD 250.0f

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Structure to hold gyroscope data and timestamp */
typedef struct {
    float x;
    float y;
    float z;
    struct timespec timestamp;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* I2C handle */
static int i2c_handle = -1;

/* Flag to indicate program termination */
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_mpu6050(int handle);
static int read_gyro_data(int handle, float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int signal);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Initialise MPU-6050 */
static int init_mpu6050(int handle) {
    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilisation */

    /* Set sample rate divider to 1 kHz / (1 + 7) = 125 Hz */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Error writing to SMPLRT_DIV\n");
        return -1;
    }

    /* Set gyroscope full-scale range to ±250 deg/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data (6 bytes from GYRO_XOUT_H) */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        return -1;
    }

    /* Convert big-endian signed 16-bit values to degrees/second */
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* Add data to circular buffer */
static void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* Check if any axis exceeds the threshold */
static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(y) > ANGULAR_VELOCITY_THRESHOLD ||
        fabsf(z) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus 1 at address 0x68 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float x, y, z;
    int consecutive_errors = 0;

    /* Main loop */
    while (program_running) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            consecutive_errors = 0;
            add_to_buffer(x, y, z);
            check_threshold(x, y, z);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading gyroscope data (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive errors, exiting\n");
                break;
            }
            /* Attempt to re-initialise the sensor */
            fprintf(stderr, "Attempting to re-initialise MPU-6050...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                break;
            }
            if (init_mpu6050(i2c_handle) < 0) {
                fprintf(stderr, "Re-initialisation failed\n");
                break;
            }
        }

        gpioDelay(50000); /* 50 ms = 20 Hz */
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

