#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 3900000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define GYRO_REG_XOUT_H 0x43
#define GYRO_REG_YOUT_H 0x45
#define GYRO_REG_ZOUT_H 0x47

#define GYRO_SENSITIVITY 131.0f
#define GYRO_THRESHOLD 200.0f
#define BUFFER_SIZE 64
#define LED_GPIO_LINE 17
#define LED_CHIP_NAME "gpiochip4"

#define GPIO_CHIP_NAME "gpiochip0"
#define CS_GPIO_LINE 8

typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int gpio_init(void) {
    led_chip = gpiod_chip_open_by_name(LED_CHIP_NAME);
    if (!led_chip) {
        perror("Failed to open LED GPIO chip");
        return -1;
    }

    led_line = gpiod_chip_get_line(led_chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(led_chip);
        led_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050_led", 0) < 0) {
        perror("Failed to request LED GPIO line as output");
        gpiod_chip_close(led_chip);
        led_chip = NULL;
        led_line = NULL;
        return -1;
    }

    cs_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!cs_chip) {
        perror("Failed to open CS GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(cs_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050_cs", 1) < 0) {
        perror("Failed to request CS GPIO line as output");
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int read_gyro_axis(uint8_t reg, float *out) {
    uint8_t tx[2] = { reg | 0x80, 0x00 };
    uint8_t rx[2] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    int16_t raw = (int16_t)((rx[0] << 8) | rx[1]);
    *out = (float)raw / GYRO_SENSITIVITY;
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, gyro_data_t data) {
    buf->buffer[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
}

static void buffer_print(const circular_buffer_t *buf) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buf->count; i++) {
        int index = (buf->tail + i) % BUFFER_SIZE;
        struct timespec ts = buf->buffer[index].timestamp;
        printf("%ld.%09ld,%f,%f,%f\n",
               ts.tv_sec, ts.tv_nsec,
               buf->buffer[index].x,
               buf->buffer[index].y,
               buf->buffer[index].z);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (cs_chip) {
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
        led_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (gpio_init() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    circular_buffer_t gyro_buffer;
    buffer_init(&gyro_buffer);

    struct timespec led_on_time = {0, 500000000L};
    struct timespec led_off_time = {0, 500000000L};
    struct timespec now;

    while (running) {
        float x, y, z;

        if (read_gyro_axis(GYRO_REG_XOUT_H, &x) < 0 ||
            read_gyro_axis(GYRO_REG_YOUT_H, &y) < 0 ||
            read_gyro_axis(GYRO_REG_ZOUT_H, &z) < 0) {
            fprintf(stderr, "Error reading gyroscope data\n");
            nanosleep(&led_off_time, NULL);
            continue;
        }

        if (x == 0.0f || y == 0.0f || z == 0.0f) {
            fprintf(stderr, "Invalid gyroscope data (zero or invalid)\n");
            nanosleep(&led_off_time, NULL);
            continue;
        }

        if (fabsf(x) > GYRO_THRESHOLD ||
            fabsf(y) > GYRO_THRESHOLD ||
            fabsf(z) > GYRO_THRESHOLD) {
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("Failed to turn LED on");
            }
            nanosleep(&led_on_time, NULL);
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("Failed to turn LED off");
            }
            nanosleep(&led_off_time, NULL);
        } else {
            nanosleep(&led_off_time, NULL);
        }

        clock_gettime(CLOCK_REALTIME, &now);
        gyro_data_t data = { .timestamp = now, .x = x, .y = y, .z = z };
        buffer_add(&gyro_buffer, data);
    }

    printf("\nExiting gracefully...\n");
    buffer_print(&gyro_buffer);
    cleanup();
    return 0;
}

