#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

/* GPIO pin for LED */
#define LED_PIN 21

/* Tilt thresholds (degrees) */
#define ROLL_THRESHOLD  45.0f
#define PITCH_THRESHOLD 45.0f

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Global state for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Initialise MPU-6050: wake up, set ±2g range, verify configuration    */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (wake)\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set accelerometer full-scale range to ±2g (AFS_SEL = 0) */
    if (i2cWriteByteData(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Verify configuration by reading back ACCEL_CONFIG */
    int cfg = i2cReadByteData(handle, ACCEL_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "Error: failed to read back ACCEL_CONFIG\n");
        return -1;
    }
    if (cfg != 0x00) {
        fprintf(stderr, "Warning: ACCEL_CONFIG read 0x%02X, expected 0x00\n", cfg);
        /* Non-fatal — continue anyway */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of accelerometer data (X, Y, Z) and convert to g       */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_accelerometer(int handle, float *x, float *y, float *z)
{
    char buf[6];

    /* Read 6 bytes starting at ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data block\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* Convert to g (±2g range: 16384 LSB/g) */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute roll (degrees) and pitch (degrees) from accelerometer data   */
/* ------------------------------------------------------------------ */
static void compute_tilt(float x, float y, float z, float *roll, float *pitch)
{
    *roll  = atan2f(y, z) * 180.0f / (float)M_PI;
    *pitch = atan2f(-x, sqrtf(y * y + z * z)) * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Log one reading to tilt_log.txt in CSV format                       */
/* ------------------------------------------------------------------ */
static void log_data(float roll, float pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open tilt_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);
    } else {
        fprintf(fp, "timestamp_error,%.2f,%.2f\n", roll, pitch);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup — turn off LED, close I2C, terminate pigpio                 */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise MPU-6050 */
    if (init_mpu6050(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    printf("MPU-6050 tilt monitor started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        float x, y, z, roll, pitch;

        if (read_accelerometer(i2c_handle, &x, &y, &z) == 0) {
            compute_tilt(x, y, z, &roll, &pitch);

            /* Tilt threshold check */
            if (fabsf(roll) > ROLL_THRESHOLD || fabsf(pitch) > PITCH_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
            } else {
                gpioWrite(LED_PIN, 0);
            }

            log_data(roll, pitch);
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            /* Sensor read failed — log error and continue */
            fprintf(stderr, "Warning: sensor read failed, continuing\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

