#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define SI1145_ADDR     0x5A
#define ALS_DATA_REG    0x20
#define PS_DATA_REG     0x22
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE        "biometric_log.txt"
#define I2C_RETRIES     3
#define I2C_RETRY_DELAY_MS 10
#define SAMPLE_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

