#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADXRS290 register addresses (8-bit) */
#define ADXRS290_REG_X_RATE 0x02
#define ADXRS290_REG_Y_RATE 0x04
#define ADXRS290_REG_TEMP   0x06
#define ADXRS290_REG_DIAG   0x08

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* Mode 0, active-low CE */

/* Gyroscope sensitivity: 200 LSB/deg/s */
#define GYRO_SENSITIVITY 200.0f

/* Sampling interval: 10 ms (100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Maximum consecutive read failures before exit */
#define MAX_READ_FAILURES 3

/* Global state for signal handler */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single register from the ADXRS290.                           */
/* Returns 0 on success (value stored in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2];
    char rx[2];

    /* ADXRS290 read: address byte = reg | 0x80, then dummy byte */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* 16-bit two's-complement: high byte first */
    *out = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI and verify communication with the gyroscope.        */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }

    /* Verify communication by reading the temperature register */
    int16_t temp_raw;
    if (read_register(ADXRS290_REG_TEMP, &temp_raw) != 0) {
        fprintf(stderr, "Gyroscope not responding on SPI channel %d\n",
                SPI_CHANNEL);
        spiClose(spi_handle);
        spi_handle = -1;
        return -1;
    }

    printf("SPI initialised (channel %d, %d Hz), temperature = %d LSB\n",
           SPI_CHANNEL, SPI_SPEED, temp_raw);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read both X and Y angular-rate registers.                           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int16_t *x_rate, int16_t *y_rate)
{
    if (read_register(ADXRS290_REG_X_RATE, x_rate) != 0)
        return -1;
    if (read_register(ADXRS290_REG_Y_RATE, y_rate) != 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the CSV file.                                     */
/* ------------------------------------------------------------------ */
static void log_data(double timestamp, int16_t x_rate, int16_t y_rate)
{
    if (log_file == NULL)
        return;

    fprintf(log_file, "%.6f,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup — close SPI, file, terminate pigpio                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("gyro_data.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "timestamp,X_rate,Y_rate\n");
    fflush(log_file);

    /* Initialise SPI */
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int16_t x_rate, y_rate;
    int consecutive_failures = 0;

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(&x_rate, &y_rate) == 0) {
            consecutive_failures = 0;

            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                double timestamp = (double)ts.tv_sec +
                                   (double)ts.tv_nsec / 1.0e9;
                log_data(timestamp, x_rate, y_rate);
            } else {
                perror("clock_gettime");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Read failure #%d\n", consecutive_failures);

            if (consecutive_failures >= MAX_READ_FAILURES) {
                fprintf(stderr, "Max consecutive failures reached. Exiting.\n");
                break;
            }

            /* Attempt to reinitialise SPI */
            fprintf(stderr, "Reinitialising SPI...\n");
            spiClose(spi_handle);
            spi_handle = -1;
            gpioDelay(100000); /* 100 ms backoff */
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinitialisation failed. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

