#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_1_GPIO 23
#define SENSOR_2_GPIO 24
#define ALERT_GPIO 17
#define SEISMIC_DURATION_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file);
    }
    fprintf(stderr, "%s - Seismic event detected!\n", timestamp);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_GPIO, 1) < 0) {
        fprintf(stderr, "Error: failed to set alert GPIO HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "Error: failed to set alert GPIO LOW\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    static uint32_t last_tick[2] = {0, 0};
    static int last_level[2] = {0, 0};
    static int active[2] = {0, 0};

    if (level == last_level[gpio - SENSOR_1_GPIO]) {
        uint32_t elapsed = tick - last_tick[gpio - SENSOR_1_GPIO];
        if (active[gpio - SENSOR_1_GPIO] && elapsed >= SEISMIC_DURATION_MS * 1000) {
            log_event();
            trigger_alert();
            active[gpio - SENSOR_1_GPIO] = 0;
        }
    }
