#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD 20.0
#define SENSITIVITY 200.0

#define REG_RATE_XL 0x02
#define REG_RATE_XH 0x03

typedef struct {
    struct timespec timestamp;
    double angular_velocity;
} gyro_data_t;

typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

static int spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int read_gyro_register(uint8_t reg, uint8_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (char)(reg | 0x80);
    tx_buf[1] = 0x00;

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI transfer error on reg 0x%02X: %d\n", reg, ret);
        return -1;
    }

    *data = (uint8_t)rx_buf[1];
    return 0;
}

static double read_angular_velocity(void) {
    uint8_t xl, xh;

    if (read_gyro_register(REG_RATE_XL, &xl) != 0) {
        return 0.0;
    }
    if (read_gyro_register(REG_RATE_XH, &xh) != 0) {
        return 0.0;
    }

    int16_t raw = (int16_t)((xh << 8) | xl);
    return (double)raw / SENSITIVITY;
}

static void add_to_buffer(circular_buffer_t *cb, double av) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    cb->buffer[cb->head].timestamp = ts;
    cb->buffer[cb->head].angular_velocity = av;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    } else {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
}

static void check_threshold(double av) {
    if (av > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    gyro_buffer.head = 0;
    gyro_buffer.tail = 0;
    gyro_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        double av = read_angular_velocity();
        add_to_buffer(&gyro_buffer, av);
        check_threshold(av);
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

