#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQ 100
#define PWM_DUTY_ON 255
#define PWM_DUTY_OFF 0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    int pins[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], PWM_DUTY_OFF) < 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void turn_off_all_lamps(void) {
    int pins[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], PWM_DUTY_OFF);
    }
}

static void cleanup(void) {
    turn_off_all_lamps();
    gpioTerminate();
}

static int validate_duration(int duration) {
    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: duration must be between 1 and 3600 seconds.\n");
        return -1;
    }
    return 0;
}

static void fade_lamp(int gpio_pin, int duration_seconds) {
    int num_steps = duration_seconds * PWM_FREQ;
    if (num_steps <= 0) {
        fprintf(stderr, "Error: invalid step count for GPIO %d.\n", gpio_pin);
        return;
    }

    int step_delay_us = 1000000 / PWM_FREQ;
    int current_duty = PWM_DUTY_ON;

    for (int i = 0; i < num_steps && g_running; ++i) {
        if (gpioPWM(gpio_pin, current_duty) < 0) {
            fprintf(stderr, "Error: PWM write failed on GPIO %d.\n", gpio_pin);
            return;
        }
        current_duty -= 1;
        if (current_duty < PWM_DUTY_OFF) {
            current_duty = PWM_DUTY_OFF;
        }
        gpioDelay(step_delay_us);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (validate_duration(duration) != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fading lamps over %d seconds.\n", duration);
    printf("Lamp 1 (GPIO%d), Lamp 2 (GPIO%d), Lamp 3 (GPIO%d)\n", LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO);
    printf("Press Ctrl+C to exit early.\n\n");

    int pins[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]) && g_running; ++i) {
        printf("Fading lamp %zu/%zu (GPIO %d)...\n", i + 1, sizeof(pins) / sizeof(pins[0]), pins[i]);
        fade_lamp(pins[i], duration);
        if (!g_running) {
            break;
        }
        printf("Lamp %zu/%zu complete.\n", i + 1, sizeof(pins) / sizeof(pins[0]));
    }

    if (!g_running) {
        printf("\nInterrupted by signal. Turning off lamps and cleaning up.\n");
    } else {
        printf("\nAll lamps faded. Turning off lamps and cleaning up.\n");
    }

    cleanup();
    return EXIT_SUCCESS;
}

