#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RED_PIN    17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define ALL_OFF_PIN 24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int set_all_off(struct gpiod_line *r, struct gpiod_line *y,
                       struct gpiod_line *g, struct gpiod_line *a) {
    if (gpiod_line_set_value(a, 0) < 0) return -1;
    if (gpiod_line_set_value(r, 1) < 0) return -1;
    if (gpiod_line_set_value(y, 1) < 0) return -1;
    if (gpiod_line_set_value(g, 1) < 0) return -1;
    return 0;
}

static int set_red(struct gpiod_line *r, struct gpiod_line *y,
                   struct gpiod_line *g, struct gpiod_line *a) {
    if (gpiod_line_set_value(a, 0) < 0) return -1;
    if (gpiod_line_set_value(r, 0) < 0) return -1;
    if (gpiod_line_set_value(y, 1) < 0) return -1;
    if (gpiod_line_set_value(g, 1) < 0) return -1;
    return 0;
}

static int set_yellow(struct gpiod_line *r, struct gpiod_line *y,
                      struct gpiod_line *g, struct gpiod_line *a) {
    if (gpiod_line_set_value(a, 0) < 0) return -1;
    if (gpiod_line_set_value(r, 1) < 0) return -1;
    if (gpiod_line_set_value(y, 0) < 0) return -1;
    if (gpiod_line_set_value(g, 1) < 0) return -1;
    return 0;
}

static int set_green(struct gpiod_line *r, struct gpiod_line *y,
                     struct gpiod_line *g, struct gpiod_line *a) {
    if (gpiod_line_set_value(a, 0) < 0) return -1;
    if (gpiod_line_set_value(r, 1) < 0) return -1;
    if (gpiod_line_set_value(y, 1) < 0) return -1;
    if (gpiod_line_set_value(g, 0) < 0) return -1;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red = NULL, *yellow = NULL, *green = NULL, *all_off = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    red = gpiod_chip_get_line(chip, RED_PIN);
    yellow = gpiod_chip_get_line(chip, YELLOW_PIN);
    green = gpiod_chip_get_line(chip, GREEN_PIN);
    all_off = gpiod_chip_get_line(chip, ALL_OFF_PIN);
    if (!red || !yellow || !green || !all_off) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(red, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(yellow, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(green, "traffic-light", 1) < 0 ||
        gpiod_line_request_output(all_off, "traffic-light", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        printf("Red\n");
        fflush(stdout);
        if (set_red(red, yellow, green, all_off) < 0) {
            perror("set_red");
            goto cleanup;
        }
        sleep(10);
        if (!running) break;

        printf("Red + Yellow\n");
        fflush(stdout);
        if (set_yellow(red, yellow, green, all_off) < 0) {
            perror("set_yellow");
            goto cleanup;
        }
        sleep(2);
        if (!running) break;

        printf("Green\n");
        fflush(stdout);
        if (set_green(red, yellow, green, all_off) < 0) {
            perror("set_green");
            goto cleanup;
        }
        sleep(10);
        if (!running) break;

        printf("Yellow\n");
        fflush(stdout);
        if (set_yellow(red, yellow, green, all_off) < 0) {
            perror("set_yellow");
            goto cleanup;
        }
        sleep(3);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (red || yellow || green || all_off) {
        set_all_off(red, yellow, green, all_off);
        gpiod_line_release(red);
        gpiod_line_release(yellow);
        gpiod_line_release(green);
        gpiod_line_release(all_off);
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

