#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define LOG_FILE "touch_relay.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(msg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (mpr121_write(0x80, 0x63) < 0) return -1;  // Reset
    gpioDelay(10000);  // 10 ms
    if (mpr121_write(0x5E, 0x00) < 0) return -1;  // Stop mode
    if (mpr121_write(0x5D, 0x01) < 0) return -1;  // Enable electrode 0
    if (mpr121_write(0x41, 0x0A) < 0) return -1;  // Touch threshold
    if (mpr121_write(0x42, 0x08) < 0) return -1;  // Release threshold
    if (mpr121_write(0x5B, 0x21) < 0) return -1;  // Debounce
    if (mpr121_write(0x5C, 0x0D) < 0) return -1;  // Charge time
    if (mpr121_write(0x5E, 0x0D) < 0) return -1;  // Run mode
    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lsb = i2cReadByteData(i2c_handle, 0x00);
    if (lsb < 0) {
        log_message("I2C read LSB failed");
        return -1;
    }
    int msb = i2cReadByteData(i2c_handle, 0x01);
    if (msb < 0) {
        log_message("I2C read MSB failed");
        return -1;
    }
    *status = (uint16_t)((msb << 8) | lsb);
    return 0;
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Failed to set relay GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "I2C open failed: bus=%d, addr=0x%02X, rc=%d", I2C_BUS, MPR121_ADDR, i2c_handle);
        log_message(msg);
        cleanup();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Program started");

    int relay_state = 0;
    uint16_t last_touch = 0;
    int consecutive_errors = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) == 0) {
            consecutive_errors = 0;
            if (touch_status & 0x0001) {
                gpioDelay(100000);  // 100 ms debounce
                uint16_t current = 0;
                if (read_touch_status(&current) == 0) {
                    if (current & 0x0001) {
                        relay_state = !relay_state;
                        gpioWrite(RELAY_GPIO, relay_state);
                        char msg[128];
                        snprintf(msg, sizeof(msg), "Relay toggled to %s", relay_state ? "ON" : "OFF");
                        log_message(msg);
                    }
                }
            }
        } else {
            consecutive_errors++;
            if (consecutive_errors > 10) {
                log_message("Too many consecutive I2C errors, aborting");
                break;
            }
        }
        gpioDelay(10000);  // 10 ms polling interval
    }

    gpioWrite(RELAY_GPIO, 0);
    log_message("Program terminated");
    cleanup();
    return EXIT_SUCCESS;
}

