#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_CYCLE_MS 5000
#define HALF_DISPENSE_MS (DISPENSE_DURATION_MS / 2)
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Solenoids: %d, %d, Duration: %d ms\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pin1, pin2, duration_ms);
    } else {
        fprintf(fp, "Timestamp error, Solenoids: %d, %d, Duration: %d ms\n", pin1, pin2, duration_ms);
    }
    fclose(fp);
    return 0;
}

static int dispense(int pin1, int pin2, int duration_ms) {
    if (gpioWrite(pin1, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin1);
        return -1;
    }
    if (gpioWrite(pin2, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin2);
        gpioWrite(pin1, 0);
        return -1;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioWrite(pin1, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin1);
        gpioWrite(pin2, 0);
        return -1;
    }
    if (gpioWrite(pin2, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin2);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, HALF_DISPENSE_MS) != 0) {
            fprintf(stderr, "Dispense cycle failed\n");
        } else {
            if (log_dispense(SOLENOID_1_PIN, SOLENOID_2_PIN, HALF_DISPENSE_MS) != 0) {
                fprintf(stderr, "Logging failed\n");
            }
        }

        if (running) {
            gpioDelay(DISPENSE_CYCLE_MS * 1000);
        }
    }

    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
    printf("Pneumatic dispensing system stopped.\n");
    return EXIT_SUCCESS;
}

