#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

// Motor A pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N enable pins
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// PID constants
#define KP 1.0
#define KI 0.01
#define KD 0.1

// PWM range
#define PWM_RANGE 255

// Obstacle avoidance threshold (cm)
#define OBSTACLE_THRESHOLD 20.0

// Log file path
#define LOG_FILE "balance_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Motor structure
typedef struct {
    int forward_pin;
    int backward_pin;
    int enable_pin;
    int current_speed;
} Motor;

// Motor instances
Motor motor_a = {MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_A_ENABLE, 0};
Motor motor_b = {MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_B_ENABLE, 0};

// PID state
typedef struct {
    float integral;
    float previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
void motor_init(Motor *motor);
void motor_set_speed(Motor *motor, int speed);
void motor_stop(Motor *motor);
int motor_char_to_index(char motor_char);
int calculate_pid(float tilt_error, float distance);
void obstacle_avoidance(void);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Motor initialization function
void motor_init(Motor *motor) {
    gpioSetMode(motor->forward_pin, PI_OUTPUT);
    gpioSetMode(motor->backward_pin, PI_OUTPUT);
    gpioSetMode(motor->enable_pin, PI_OUTPUT);
    gpioWrite(motor->enable_pin, 1); // Enable PWM
    motor_stop(motor);
}

// Motor control function
void motor_set_speed(Motor *motor, int speed) {
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;
    motor->current_speed = speed;
    if (speed > 0) {
        gpioWrite(motor->backward_pin, 0);
        gpioPWM(motor->forward_pin, abs(speed));
    } else if (speed < 0) {
        gpioWrite(motor->forward_pin, 0);
        gpioPWM(motor->backward_pin, abs(speed));
    } else {
        gpioWrite(motor->forward_pin, 0);
        gpioWrite(motor->backward_pin, 0);
    }
}

// Motor stop function
void motor_stop(Motor *motor) {
    gpioWrite(motor->forward_pin, 0);
    gpioWrite(motor->backward_pin, 0);
    motor->current_speed = 0;
}

// Convert motor character to index (A or B)
int motor_char_to_index(char motor_char) {
    if (motor_char == 'A') return 0;
    if (motor_char == 'B') return 1;
    return -1; // Error
}

// PID controller function
int calculate_pid(float tilt_error, float distance) {
    float error = tilt_error;
    float derivative = 0.0;
    float output;

    // Proportional term
    output = KP * error;

    // Integral term (with anti-windup clamping)
    pid_state.integral += error;
    if (pid_state.integral > PWM_RANGE) pid_state.integral = PWM_RANGE;
    if (pid_state.integral < -PWM_RANGE) pid_state.integral = -PWM_RANGE;
    output += KI * pid_state.integral;

    // Derivative term
    derivative = (error - pid_state.previous_error) / 0.05; // 50 ms time step
    output += KD * derivative;

    pid_state.previous_error = error;

    return (int)output;
}

// Obstacle avoidance function
void obstacle_avoidance(void) {
    motor_set_speed(&motor_a, -PWM_RANGE / 2);
    motor_set_speed(&motor_b, -PWM_RANGE / 2);
    printf("Obstacle detected! Reversing...\n");
}

// Data logging function
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and cleaning up...\n", signal);
    running = 0;
    motor_stop(&motor_a);
    motor_stop(&motor_b);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize motors
    motor_init(&motor_a);
    motor_init(&motor_b);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Simulate tilt error (random between -10 and 10 degrees)
        float tilt_error = ((float)rand() / RAND_MAX) * 20.0 - 10.0;

        // Simulate distance (random between 2 and 400 cm)
        float distance = ((float)rand() / RAND_MAX) * 400.0 + 2.0;

        // Calculate PID output
        int pid_output = calculate_pid(tilt_error, distance);

        // Set motor speeds
        motor_set_speed(&motor_a, pid_output);
        motor_set_speed(&motor_b, pid_output);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            obstacle_avoidance();
        }

        // Log data
        log_data(tilt_error, distance, motor_a.current_speed, motor_b.current_speed);

        // Delay
        gpioDelay(50000); // 50 ms in microseconds
    }

    // Cleanup (should not reach here if signal handler works)
    motor_stop(&motor_a);
    motor_stop(&motor_b);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

