/*
 * Mood Light for Raspberry Pi 3 Model B+
 * RGB LED on GPIO17 (R), GPIO18 (G), GPIO27 (B) via pigpio PWM
 * ALSA capture on default device (8 kHz, 16-bit, 1 ch, 1024-frame period)
 * Compile: gcc -o mood_light mood_light.c -lpigpio -lasound -lm
 * Run:     sudo ./mood_light [sensitivity_scale]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_RANGE  255
#define PWM_FREQ   1000   /* Hz */

#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define FRAMES_PER_BUFFER 1

#define DEFAULT_SENSITIVITY 1.0
#define MIN_SENSITIVITY 0.01
#define MAX_SENSITIVITY 10.0

#define SIM_SAMPLE_RATE 44100
#define SIM_PERIOD_US  20000  /* 20 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

#ifdef ALSA_AVAILABLE

static int alsa_init(snd_pcm_t **handle, snd_pcm_hw_params_t **params)
{
    int err;

    if ((err = snd_pcm_open(handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "ALSA: cannot open default device (%s)\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_malloc(params)) < 0) {
        fprintf(stderr, "ALSA: snd_pcm_hw_params_malloc failed (%s)\n", snd_strerror(err));
        snd_pcm_close(*handle);
        *handle = NULL;
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(*handle, *params)) < 0) {
        fprintf(stderr, "ALSA: snd_pcm_hw_params_any failed (%s)\n", snd_strerror(err));
        snd_pcm_hw_params_free(*params);
        snd_pcm_close(*handle);
        *handle = NULL;
        *params = NULL;
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*handle, *params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "ALSA: set_access failed (%s)\n", snd_strerror(err));
        goto fail;
    }

    if ((err = snd_pcm_hw_params_set_format(*handle, *params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "ALSA: set_format failed (%s)\n", snd_strerror(err));
        goto fail;
    }

    if ((err = snd_pcm_hw_params_set_channels(*handle, *params, 1)) < 0) {
        fprintf(stderr, "ALSA: set_channels failed (%s)\n", snd_strerror(err));
        goto fail;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*handle, *params, &rate, 0)) < 0) {
        fprintf(stderr, "ALSA: set_rate failed (%s)\n", snd_strerror(err));
        goto fail;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "ALSA: requested %d Hz, got %u Hz\n", SAMPLE_RATE, rate);
    }

    unsigned int period_size = PERIOD_SIZE;
    if ((err = snd_pcm_hw_params_set_period_size_near(*handle, *params, &period_size, 0)) < 0) {
        fprintf(stderr, "ALSA: set_period_size failed (%s)\n", snd_strerror(err));
        goto fail;
    }
    if (period_size != PERIOD_SIZE) {
        fprintf(stderr, "ALSA: requested %d frames, got %u\n", PERIOD_SIZE, period_size);
    }

    if ((err = snd_pcm_hw_params(*handle, *params)) < 0) {
        fprintf(stderr, "ALSA: hw_params failed (%s)\n", snd_strerror(err));
        goto fail;
    }

    if ((err = snd_pcm_prepare(*handle)) < 0) {
        fprintf(stderr, "ALSA: prepare failed (%s)\n", snd_strerror(err));
        goto fail;
    }

    return 0;

fail:
    snd_pcm_hw_params_free(*params);
    snd_pcm_close(*handle);
    *handle = NULL;
    *params = NULL;
    return -1;
}

static int alsa_read_audio(snd_pcm_t *handle, int16_t *buffer, int frames)
{
    int err;
    snd_pcm_sframes_t frames_read;

    frames_read = snd_pcm_readi(handle, buffer, frames);
    if (frames_read == -EPIPE) {
        fprintf(stderr, "ALSA: overrun, preparing device\n");
        if ((err = snd_pcm_prepare(handle)) < 0) {
            fprintf(stderr, "ALSA: prepare failed after overrun (%s)\n", snd_strerror(err));
            return -1;
        }
        return 0;
    }
    if (frames_read == -ESTRPIPE) {
        fprintf(stderr, "ALSA: suspended, resuming\n");
        if ((err = snd_pcm_resume(handle)) < 0) {
            fprintf(stderr, "ALSA: resume failed (%s)\n", snd_strerror(err));
            return -1;
        }
        return 0;
    }
    if (frames_read < 0) {
        fprintf(stderr, "ALSA: read error (%s)\n", snd_strerror((int)frames_read));
        return -1;
    }
    if (frames_read != frames) {
        fprintf(stderr, "ALSA: short read: %ld frames\n", frames_read);
    }
    return (int)frames_read;
}

#else

static int alsa_init(snd_pcm_t **handle, snd_pcm_hw_params_t **params)
{
    (void)handle; (void)params;
    fprintf(stderr, "ALSA support not compiled in; simulating audio\n");
    return 0;
}

static int alsa_read_audio(snd_pcm_t *handle, int16_t *buffer, int frames)
{
    (void)handle;
    static double phase = 0.0;
    double freq = 440.0;
    for (int i = 0; i < frames; i++) {
        buffer[i] = (int16_t)(32767.0 * sin(phase));
        phase += 2.0 * M_PI * freq / SIM_SAMPLE_RATE;
        if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
    }
    return frames;
}

#endif

static double calculate_amplitude(const int16_t *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / frames);
}

static void map_amplitude_to_color(double amplitude, double sensitivity,
                                   int *r, int *g, int *b)
{
    double norm = amplitude * sensitivity;
    if (norm > 1.0) norm = 1.0;
    if (norm < 0.0) norm = 0.0;

    double h = norm * 4.0;
    if (h < 1.0) {
        *r = (int)(255.0 * (1.0 - h));
        *g = (int)(255.0 * h);
        *b = 0;
    } else if (h < 2.0) {
        h -= 1.0;
        *r = 0;
        *g = (int)(255.0 * (1.0 - h));
        *b = (int)(255.0 * h);
    } else if (h < 3.0) {
        h -= 2.0;
        *r = (int)(255.0 * h);
        *g = 0;
        *b = (int)(255.0 * (1.0 - h));
    } else {
        h -= 3.0;
        *r = (int)(255.0 * (1.0 - h));
        *g = 0;
        *b = 0;
    }
}

static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN, r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN, b);
}

static void cleanup(snd_pcm_t *handle, snd_pcm_hw_params_t *params)
{
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }
    if (params) {
        snd_pcm_hw_params_free(params);
    }
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    double sensitivity = DEFAULT_SENSITIVITY;
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= MIN_SENSITIVITY || sensitivity > MAX_SENSITIVITY) {
            fprintf(stderr, "Invalid sensitivity: %.2f (range %.1f-%.1f)\n",
                    sensitivity, MIN_SENSITIVITY, MAX_SENSITIVITY);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    snd_pcm_t *handle = NULL;
    snd_pcm_hw_params_t *params = NULL;

    if (alsa_init(&handle, &params) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t *audio_buffer = (int16_t *)malloc(PERIOD_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup(handle, params);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Mood light running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int frames_read = alsa_read_audio(handle, audio_buffer, PERIOD_SIZE);
        if (frames_read < 0) {
            fprintf(stderr, "ALSA read error, continuing...\n");
            gpioDelay(100000);
            continue;
        }

        double amplitude = calculate_amplitude(audio_buffer, frames_read);
        int r, g, b;
        map_amplitude_to_color(amplitude, sensitivity, &r, &g, &b);
        set_led_color(r, g, b);

        gpioDelay(10000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup(handle, params);
    free(audio_buffer);
    return EXIT_SUCCESS;
}

