static double calculate_amplitude(const int16_t *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / frames);
}

static void map_amplitude_to_color(double amplitude, double sensitivity,
                                   int *r, int *g, int *b)
{
    double norm = amplitude * sensitivity;
    if (norm > 1.0) norm = 1.0;
    if (norm < 0.0) norm = 0.0;

    double h = norm * 4.0;
    if (h < 1.0) {
        *r = (int)(255.0 * (1.0 - h));
        *g = (int)(255.0 * h);
        *b = 0;
    } else if (h < 2.0) {
        h -= 1.0;
        *r = 0;
        *g = (int)(255.0 * (1.0 - h));
        *b = (int)(255.0 * h);
    } else if (h < 3.0) {
        h -= 2.0;
        *r = (int)(255.0 * h);
        *g = 0;
        *b = (int)(255.0 * (1.0 - h));
    } else {
        h -= 3.0;
        *r = (int)(255.0 * (1.0 - h));
        *g = 0;
        *b = 0;
    }
}

static void set_led_color(int r, int g, int b)
{
    gpioPWM(RED_PIN, r);
    gpioPWM(GREEN_PIN, g);
    gpioPWM(BLUE_PIN, b);
}

static void cleanup(snd_pcm_t *handle, snd_pcm_hw_params_t *params)
{
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }
    if (params) {
        snd_pcm_hw_params_free(params);
    }
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    double sensitivity = DEFAULT_SENSITIVITY;
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= MIN_SENSITIVITY || sensitivity > MAX_SENSITIVITY) {
            fprintf(stderr, "Invalid sensitivity: %.2f (range %.1f-%.1f)\n",
                    sensitivity, MIN_SENSITIVITY, MAX_SENSITIVITY);
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != PWM_FREQ ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    snd_pcm_t *handle = NULL;
    snd_pcm_hw_params_t *params = NULL;

    if (alsa_init(&handle, &params) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int16_t *audio_buffer = (int16_t *)malloc(PERIOD_SIZE * sizeof(int16_t));
    if (!audio_buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup(handle, params);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Mood light running. Press Ctrl+C to exit.\n");

    while (g_running) {
        int frames_read = alsa_read_audio(handle, audio_buffer, PERIOD_SIZE);
        if (frames_read < 0) {
            fprintf(stderr, "ALSA read error, continuing...\n");
            gpioDelay(100000);
            continue;
        }

        double amplitude = calculate_amplitude(audio_buffer, frames_read);
        int r, g, b;
        map_amplitude_to_color(amplitude, sensitivity, &r, &g, &b);
        set_led_color(r, g, b);

        gpioDelay(10000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup(handle, params);
    free(audio_buffer);
    return EXIT_SUCCESS;
}

