#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* TCS34725 I2C address (ADDR pin tied to GND) */
#define TCS34725_ADDRESS 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CDATAL  0x14
#define TCS34725_CDATAH  0x15
#define TCS34725_RDATAL  0x16
#define TCS34725_RDATAH  0x17
#define TCS34725_GDATAL  0x18
#define TCS34725_GDATAH  0x19
#define TCS34725_BDATAL  0x1A
#define TCS34725_BDATAH  0x1B

/* Global state for signal handler */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* Calibration coefficients (example values, replace with actual calibration) */
static float red_scale   = 1.0f;
static float green_scale = 1.0f;
static float blue_scale  = 1.0f;
static float clear_scale = 1.0f;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to a TCS34725 register; return 0 on success, -1 error */
/* ------------------------------------------------------------------ */
static int tcs34725_write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a byte from a TCS34725 register; return 0 on success, -1 error */
/* ------------------------------------------------------------------ */
static int tcs34725_read_reg(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian word from two consecutive registers     */
/* ------------------------------------------------------------------ */
static int tcs34725_read_word(uint8_t reg_low, uint16_t *out)
{
    uint8_t lo, hi;
    if (tcs34725_read_reg(reg_low, &lo) < 0) return -1;
    if (tcs34725_read_reg(reg_low + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TCS34725: power on, enable RGBC, set integration time*/
/* ------------------------------------------------------------------ */
static int tcs34725_init(void)
{
    /* Power on */
    if (tcs34725_write_reg(TCS34725_ENABLE, 0x01) < 0) return -1;
    gpioDelay(3000); /* 3 ms power-up delay */

    /* Enable RGBC (bit 1) and AEN (bit 0) */
    if (tcs34725_write_reg(TCS34725_ENABLE, 0x03) < 0) return -1;

    /* Integration time 154 ms (ATIME = 0xD5) */
    if (tcs34725_write_reg(TCS34725_ATIME, 0xD5) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read calibrated RGBC values; on error, set all values to 0         */
/* ------------------------------------------------------------------ */
static void tcs34725_read_rgbc(uint16_t *clear, uint16_t *red,
                               uint16_t *green, uint16_t *blue)
{
    if (tcs34725_read_word(TCS34725_CDATAL, clear) < 0 ||
        tcs34725_read_word(TCS34725_RDATAL, red)   < 0 ||
        tcs34725_read_word(TCS34725_GDATAL, green) < 0 ||
        tcs34725_read_word(TCS34725_BDATAL, blue)  < 0) {
        *clear = *red = *green = *blue = 0;
        return;
    }

    /* Apply calibration (example scaling) */
    *red   = (uint16_t)((float)(*red)   * red_scale);
    *green = (uint16_t)((float)(*green) * green_scale);
    *blue  = (uint16_t)((float)(*blue)  * blue_scale);
    *clear = (uint16_t)((float)(*clear) * clear_scale);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                  */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TCS34725 address */
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file for appending */
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open color_data.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
    }

    /* Main sampling loop */
    while (running) {
        uint16_t clear, red, green, blue;
        tcs34725_read_rgbc(&clear, &red, &green, &blue);

        time_t now = time(NULL);
        fprintf(fp, "%ld,%u,%u,%u,%u\n",
                (long)now, clear, red, green, blue);
        fflush(fp);

        gpioDelay(500000); /* 500 ms */
    }

    /* Graceful shutdown */
    cleanup();
    return EXIT_SUCCESS;
}

