#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_LAMPS 4
#define SUNRISE_HOURS 1
#define DAYTIME_HOURS 6
#define SUNSET_HOURS 1
#define NIGHTTIME_HOURS 14.4
#define STEP_DELAY_SEC 1
#define PWM_STEPS 100

static const int lamp_pins[NUM_LAMPS] = {17, 27, 22, 23};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_sec(unsigned int seconds) {
    while (seconds > 0 && running) {
        unsigned int remaining = seconds;
        if (remaining > STEP_DELAY_SEC) remaining = STEP_DELAY_SEC;
        sleep(remaining);
        seconds -= remaining;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_LAMPS];
    int i;

    for (i = 0; i < NUM_LAMPS; i++) lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_LAMPS; i++) {
        lines[i] = gpiod_chip_get_line(chip, lamp_pins[i]);
        if (!lines[i]) {
