#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION_SEC 5
#define DEBOUNCE_DELAY_US 200000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static int detect_motion(void) {
    return (gpioRead(MOTION_SENSOR_GPIO) == 0);
}

static void record_video(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed.\n");
        return;
    }

    strftime(filename, sizeof(filename), "/home/pi/videos/%Y%m%d_%H%M%S.h264", timeinfo);

    snprintf(command, sizeof(command), "raspivid -o %s -t %d -w 1280 -h 720 -fps 30 -n",
             filename, VIDEO_DURATION_SEC);

    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: system() failed to execute raspivid.\n");
    } else if (result != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d.\n", result);
    } else {
        printf("Video recorded: %s\n", filename);
    }
}

static void log_motion_event(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed for logging.\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Motion detected on GPIO %d\n", timestamp, MOTION_SENSOR_GPIO);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Error: sigaction failed");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen("/home/pi/logs/motion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open motion_log.txt");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (detect_motion()) {
            gpioDelay(DEBOUNCE_DELAY_US);
            if (detect_motion()) {
                record_video();
                log_motion_event();
                gpioDelay(DEBOUNCE_DELAY_US);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    return 0;
}

