#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(int zone) {
    return rand() % 101;
}

static void control_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", pin);
    }
}

static void log_data(int zone, int moisture_level, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Zone %d: Moisture Level = %d, Relay State = %s\n",
                timestamp, zone, moisture_level, relay_state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

static void cleanup(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioWrite(pins[i], 1);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture1 = read_moisture_sensor(1);
        int moisture2 = read_moisture_sensor(2);
        int moisture3 = read_moisture_sensor(3);
        int moisture4 = read_moisture_sensor(4);

        if (moisture1 < MOISTURE_THRESHOLD) {
            control_relay(RELAY1_PIN, 0);
        } else {
            control_relay(RELAY1_PIN, 1);
        }
        if (moisture2 < MOISTURE_THRESHOLD) {
            control_relay(RELAY2_PIN, 0);
        } else {
            control_relay(RELAY2_PIN, 1);
        }
        if (moisture3 < MOISTURE_THRESHOLD) {
            control_relay(RELAY3_PIN, 0);
        } else {
            control_relay(RELAY3_PIN, 1);
        }
        if (moisture4 < MOISTURE_THRESHOLD) {
            control_relay(RELAY4_PIN, 0);
        } else {
            control_relay(RELAY4_PIN, 1);
        }

        log_data(1, moisture1, moisture1 < MOISTURE_THRESHOLD ? 1 : 0);
        log_data(2, moisture2, moisture2 < MOISTURE_THRESHOLD ? 1 : 0);
        log_data(3, moisture3, moisture3 < MOISTURE_THRESHOLD ? 1 : 0);
        log_data(4, moisture4, moisture4 < MOISTURE_THRESHOLD ? 1 : 0);

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

