#include <errno.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 100000
#define MAX_PULSE_US 23200

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void trigger_sensor(void) {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIG_PIN, 0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        start_tick = tick;
        echo_received = 0;
        pthread_mutex_unlock(&pulse_mutex);
    } else if (level == 0) {
        pthread_mutex_lock(&pulse_mutex);
        end_tick = tick;
        echo_received = 1;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_distance(double distance) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%ld,%lf\n", (long)ts.tv_nsec, distance);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        trigger_sensor();

        uint32_t elapsed = 0;
        while (running && !echo_received) {
            gpioDelay(1000);
            elapsed += 1000;
            if (elapsed > TIMEOUT_US) {
                break;
            }
        }

        if (!running) {
            break;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        pthread_mutex_lock(&pulse_mutex);
        uint32_t pulse_width = end_tick - start_tick;
        pthread_mutex_unlock(&pulse_mutex);

        if (pulse_width > MAX_PULSE_US) {
            fprintf(stderr, "Pulse width out of range: %u us\n", pulse_width);
            continue;
        }

        double distance = (double)pulse_width / 58.0;
        if (distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            continue;
        }

        log_distance(distance);
        printf("Distance: %.2f cm\n", distance);
    }

    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIG_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
    printf("Distance measurement stopped.\n");
    return EXIT_SUCCESS;
}

