#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_PIN 17
#define I2C_BUS 1
#define SAMPLE_RATE_HZ 100
#define SENSITIVITY 16384.0f
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lis3dh(void) {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, LIS3DH_ADDR, i2c_handle);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (result == 6) {
            int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

            *x = (float)raw_x / SENSITIVITY;
            *y = (float)raw_y / SENSITIVITY;
            *z = (float)raw_z / SENSITIVITY;
            return 0;
        }
        fprintf(stderr, "I2C read error (attempt %d): %d\n", 4 - retries, result);
        retries--;
        gpioDelay(10000);
    }

    fprintf(stderr, "Failed to read acceleration data after retries.\n");
    return -1;
}

static void detect_fall(float x, float y, float z, float freefall_threshold) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude < freefall_threshold) {
        printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(1000000);
        gpioWrite(BUZZER_PIN, 0);
    }
}

static void detect_impact(float x, float y, float z, float impact_threshold) {
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > impact_threshold) {
        printf("Impact detected! Magnitude: %.2f g\n", magnitude);
        gpioWrite(BUZZER_PIN, 1);
        gpioDelay(1000000);
        gpioWrite(BUZZER_PIN, 0);
    }
}

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (argc > 2) {
            impact_threshold = atof(argv[2]);
        }
    }

    printf("Using freefall threshold: %.2f g, impact threshold: %.2f g\n", freefall_threshold, impact_threshold);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);

    if (init_lis3dh() != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    float x, y, z;
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            detect_fall(x, y, z, freefall_threshold);
            detect_impact(x, y, z, impact_threshold);
        }
        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

