#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define STEPS_PER_REV 2048
#define STEP_DELAY_US 1000
#define STEPS_PER_MM 10.0
#define SIDE_LENGTH_MM 50.0
#define STEPS_PER_SIDE (int)(SIDE_LENGTH_MM * STEPS_PER_MM)

#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

static volatile sig_atomic_t running = 1;

static const int motor1_pins[4] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4};
static const int motor2_pins[4] = {MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};

static const int step_sequence[4][4] = {
    {1, 0, 0, 0},
    {1, 1, 0, 0},
    {0, 1, 0, 0},
    {0, 1, 1, 0}
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_pins(int motor, int step) {
    for (int i = 0; i < 4; i++) {
        if (gpioWrite(motor1_pins[i], step_sequence[step][i]) != 0) {
            fprintf(stderr, "Error: gpioWrite failed on pin %d\n", motor1_pins[i]);
            return -1;
        }
    }
    return 0;
}

static int move_motor(int motor, int steps, int direction) {
    int current_step = 0;
    for (int i = 0; i < steps && running; i++) {
        if (set_motor_pins(motor, current_step) != 0) return -1;
        gpioDelay(STEP_DELAY_US);
        current_step = (current_step + direction + 4) % 4;
    }
    return 0;
}

static int draw_line(int motor, int steps) {
    return move_motor(motor, steps, 1);
}

static int draw_square(void) {
    if (draw_line(0, STEPS_PER_SIDE) != 0) return -1;
    if (draw_line(1, STEPS_PER_SIDE) != 0) return -1;
    if (draw_line(0, -STEPS_PER_SIDE) != 0) return -1;
    if (draw_line(1, -STEPS_PER_SIDE) != 0) return -1;
    return 0;
}

static void stop_motor(int motor) {
    for (int i = 0; i < 4; i++) {
        gpioWrite(motor == 0 ? motor1_pins[i] : motor2_pins[i], 0);
    }
}

static void cleanup(void) {
    stop_motor(0);
    stop_motor(1);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(motor1_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", motor1_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetMode(motor2_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", motor2_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CNC Plotter: Drawing square (%d mm per side)...\n", SIDE_LENGTH_MM);
    printf("Press Ctrl+C to stop.\n");

    if (draw_square() != 0) {
        fprintf(stderr, "Error: Failed to draw square\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Square drawn successfully.\n");
    cleanup();
    return EXIT_SUCCESS;
}

