#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN    4
#define CENTER_SENSOR_PIN  17
#define RIGHT_SENSOR_PIN   27
#define ALERT_PIN          22

#define BUFFER_SIZE        5
#define ALERT_DURATION_MS  2000
#define POLL_INTERVAL_MS   10
#define ALERT_THRESHOLD    5

typedef struct {
    int left;
    int center;
    int right;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, SensorData d) {
    cb->data[cb->head] = d;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void log_data(const SensorData *d) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    printf("[%04d-%02d-%02d %02d:%02d:%02d] L:%d C:%d R:%d\n",
           tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
           tm.tm_hour, tm.tm_min, tm.tm_sec,
           d->left, d->center, d->right);
}

static void trigger_alert(struct gpiod_line *alert) {
    if (gpiod_line_set_value(alert, 1) < 0) {
        perror("Failed to set alert HIGH");
        return;
    }
    usleep(ALERT_DURATION_MS * 1000);
    if (gpiod_line_set_value(alert, 0) < 0) {
        perror("Failed to set alert LOW");
    }
}

static void line_follow(SensorData d) {
    if (d.center == 0) {
        printf("Moving forward\n");
    } else if (d.left == 0) {
        printf("Turning left\n");
    } else if (d.right == 0) {
        printf("Turning right\n");
    } else {
        printf("Stopping\n");
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left = NULL, *center = NULL, *right = NULL, *alert = NULL;
    CircularBuffer buf;
    int no_line_count = 0;
    int ret = EXIT_FAILURE;

    cb_init(&buf);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    left = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left || !center || !right || !alert) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(left, "line_follower") < 0) {
        perror("request left input");
        goto cleanup;
    }
    if (gpiod_line_request_input(center, "line_follower") < 0) {
        perror("request center input");
        goto cleanup;
    }
    if (gpiod_line_request_input(right, "line_follower") < 0) {
        perror("request right input");
        goto cleanup;
    }
    if (gpiod_line_request_output(alert, "line_follower", 0) < 0) {
        perror("request alert output");
        goto cleanup;
    }

    printf("Line following started. Press Ctrl+C to exit.\n");

    while (running) {
        int l = gpiod_line_get_value(left);
        int c = gpiod_line_get_value(center);
        int r = gpiod_line_get_value(right);

        if (l < 0 || c < 0 || r < 0) {
            fprintf(stderr, "Sensor read error: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        SensorData d = {l, c, r};
        cb_add(&buf, d);
        log_data(&d);

        if (c == 1) {
            no_line_count++;
            if (no_line_count >= ALERT_THRESHOLD) {
                printf("No line detected for %d consecutive readings. Triggering alert.\n", no_line_count);
                trigger_alert(alert);
                no_line_count = 0;
            }
        } else {
            no_line_count = 0;
        }

        line_follow(d);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alert) gpiod_line_release(alert);
    if (left) gpiod_line_release(left);
    if (center) gpiod_line_release(center);
    if (right) gpiod_line_release(right);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

