static int g_i2c_handle = -1;

static void log_event(const char *msg) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (!fp) { perror("fopen"); return; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s %s\n", ts, msg);
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read error reg 0x%02X: %d", reg, v);
        log_event(buf);
    }
    return v;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int r = i2cWriteByteData(handle, reg, val);
    if (r < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write error reg 0x%02X val 0x%02X: %d", reg, val, r);
        log_event(buf);
    }
    return r;
}

static int read_field_raw(int handle, int16_t *out) {
    if (i2c_write_byte(handle, REG_OP_CTRL, 0x01) < 0) return -1;
    for (int i = 0; i < MAX_POLLS; i++) {
        int status = i2c_read_byte(handle, REG_OP_CTRL);
        if (status < 0) return -1;
        if (status == 0x00) break;
        gpioDelay(POLL_US);
    }
    if (i >= MAX_POLLS) {
        log_event("Field conversion timeout");
        return -1;
    }
    int lsb = i2c_read_byte(handle, REG_FIELD_LSB);
    int msb = i2c_read_byte(handle, REG_FIELD_MSB);
    if (lsb < 0 || msb < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        char buf[64];
        snprintf(buf, sizeof(buf), "GPIO write error GPIO %d: %d", RELAY_GPIO, state);
        log_event(buf);
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    control_relay(0);
    gpioTerminate();
    log_event("Program terminated");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        log_event("I2C open failed");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return 1;
    }
    control_relay(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    log_event("Program started");

    while (g_running) {
        int16_t raw;
        if (read_field_raw(g_i2c_handle, &raw) < 0) {
            control_relay(0);
            relay_state = 0;
            gpioDelay(SAMPLE_US);
            continue;
        }

        int field_mT_x100 = (raw * 25) / 1000;
        int exceed = (field_mT_x100 > THRESHOLD_MT) ? 1 : 0;

        if (exceed && !relay_state) {
            control_relay(1);
            relay_state = 1;
            log_event("Field threshold exceeded, relay activated");
        } else if (!exceed && relay_state) {
            control_relay(0);
            relay_state = 0;
            log_event("Field below threshold, relay deactivated");
        }

        char buf[128];
        snprintf(buf, sizeof(buf), "Field: %d mT (raw: %d)", field_mT_x100 / 100, raw);
        log_event(buf);

        gpioDelay(SAMPLE_US);
    }

    cleanup();
    return 0;
}

