#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"
#define BUFFER_SIZE 1024

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (client_fd >= 0) { shutdown(client_fd, SHUT_RDWR); close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { shutdown(server_fd, SHUT_RDWR); close(server_fd); server_fd = -1; }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    return 0;
}

static int init_socket(void) {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); return -1; }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt"); close(server_fd); server_fd = -1; return -1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind"); close(server_fd); server_fd = -1; return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen"); close(server_fd); server_fd = -1; return -1;
    }
    return 0;
}

static int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("recv");
        log_event("Error receiving data from client");
        return -1;
    }
    if (bytes_received == 0) {
        log_event("Client disconnected");
        return 0;
    }
    buffer[bytes_received] = '\0';

    char *newline = strpbrk(buffer, "\r\n");
    if (newline) *newline = '\0';

    char *command = strtok(buffer, " \t\r\n");
    if (!command) {
        log_event("Invalid command format");
        return -1;
    }

    if (strcasecmp(command, "on") == 0) {
        gpioWrite(GPIO_PIN, 1);
        log_event("Relay turned ON");
        const char *response = "Relay turned ON\n";
        send(client_socket, response, strlen(response), 0);
    } else if (strcasecmp(command, "off") == 0) {
        gpioWrite(GPIO_PIN, 0);
        log_event("Relay turned OFF");
        const char *response = "Relay turned OFF\n";
        send(client_socket, response, strlen(response), 0);
    } else {
        log_event("Invalid command");
        const char *response = "Invalid command\n";
        send(client_socket, response, strlen(response), 0);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) { perror("fopen"); return 1; }

    if (init_gpio() != 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    if (init_socket() != 0) {
        log_event("Socket initialization failed");
        cleanup();
        return 1;
    }

    log_event("Server started");
    printf("Server listening on port %d\n", PORT);

    while (running) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            log_event("Error accepting connection");
            continue;
        }

        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_address.sin_addr, client_ip, sizeof(client_ip));
        char log_msg[128];
        snprintf(log_msg, sizeof(log_msg), "Connection from %s:%d", client_ip, ntohs(client_address.sin_port));
        log_event(log_msg);

        if (handle_client(client_fd) != 0) {
            log_event("Error handling client");
        }

        close(client_fd);
        client_fd = -1;
    }

    log_event("Server shutting down");
    cleanup();
    return 0;
}

