/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F liquid flow sensor monitor.
 *
 * Wiring:
 *   Sensor 1 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD 3V3, GND
 *   Sensor 2 SDA -> GPIO2 (pin 3), SCL -> GPIO3 (pin 5), VDD 3V3, GND
 *   Relay control -> GPIO18 (pin 12), 3V3, GND (active-high assumed)
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define SENSOR1_ADDR         0x08
#define SENSOR2_ADDR         0x09
#define RELAY_GPIO           18
#define FLOW_THRESHOLD_MLM   5.0f
#define POLL_INTERVAL_US     100000          /* 100 ms */
#define LOG_FILE             "flow_log.txt"
#define SCALE_FACTOR         1.0f / 1500.0f   /* SLF3S-1300F: 1/1500 ml/min */

/* SLF3S start-measurement command (0x3608) */
static const uint8_t CMD_START_MEAS[2] = { 0x36, 0x08 };

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_h1 = -1;
static int  g_i2c_h2 = -1;
static bool g_pigpio_inited = false;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static uint8_t crc8(const uint8_t *data, int len);
static int  init_sensor(int handle);
static int  read_flow_rate(int handle, float *out_mlm);
static void control_relay(bool below_threshold);
static void log_flow_data(float f1, float f2);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* CRC-8, polynomial 0x31, init 0xFF (Sensirion convention) */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ----------------------------- Sensor init ------------------------------- */
static int init_sensor(int handle)
{
    if (i2cWriteDevice(handle, (char *)CMD_START_MEAS, 2) != 0) {
        fprintf(stderr, "[0x%02X] Failed to send start-measurement command\n",
                i2cReadI2CBlockData(handle, 0, NULL, 0));
        return -1;
    }
    return 0;
}

/* ----------------------------- Read flow --------------------------------- */
static int read_flow_rate(int handle, float *out_mlm)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "[0x%02X] I2C read returned %d bytes (expected 3)\n",
                i2cReadI2CBlockData(handle, 0, NULL, 0), n);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[0x%02X] CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                i2cReadI2CBlockData(handle, 0, NULL, 0),
                crc8(buf, 2), buf[2]);
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_mlm = (float)raw * SCALE_FACTOR;
    return 0;
}

/* ----------------------------- Relay control ----------------------------- */
static void control_relay(bool below_threshold)
{
    if (gpioWrite(RELAY_GPIO, below_threshold ? 1 : 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", RELAY_GPIO);
}

/* ----------------------------- Logging ----------------------------------- */
static void log_flow_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        fclose(fp);
        return;
    }

    struct tm tm_local;
    localtime_r(&ts.tv_sec, &tm_local);

    char tbuf[40];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_local);
    fprintf(fp, "%s.%03ld, S1: %.2f ml/min, S2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, f1, f2);
    fflush(fp);
    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_pigpio_inited) {
        gpioWrite(RELAY_GPIO, 0);
        if (g_i2c_h1 >= 0) i2cClose(g_i2c_h1);
        if (g_i2c_h2 >= 0) i2cClose(g_i2c_h2);
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
