#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN  22
#define MOTOR_IN1_PIN  23
#define MOTOR_IN2_PIN  24

#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_POLLS_REQUIRED 3       /* 3 * 200 ms = 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed", pin, level);
        return -1;
    }
    return 0;
}

static int stop_motor(void)
{
    int rc = 0;
    if (safe_write(MOTOR_ENA_PIN, 0) < 0) rc = -1;
    if (safe_write(MOTOR_IN1_PIN, 0) < 0) rc = -1;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) rc = -1;
    return rc;
}

static int close_window(void)
{
    syslog(LOG_INFO, "Closing window...");

    if (safe_write(MOTOR_ENA_PIN, 1) < 0) return -1;
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) return -1;
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) return -1;

    syslog(LOG_INFO, "Motor running for 5 seconds...");
    gpioDelay(MOTOR_RUN_US);

    if (stop_motor() < 0) {
        syslog(LOG_ERR, "Failed to stop motor after close");
        return -1;
    }

    syslog(LOG_INFO, "Window closed.");
    return 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain-activated window controller started");

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pull-up");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (stop_motor() < 0) {
        syslog(LOG_ERR, "Initial motor stop failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed");
        stop_motor();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int dry_count = 0;
    int last_rain = 0;

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(%d) failed", RAIN_SENSOR_PIN);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (rain == 0 && last_rain == 1) {
            syslog(LOG_INFO, "Rain detected (sensor LOW)");
            if (close_window() < 0) {
                syslog(LOG_ERR, "Close sequence failed");
            }
            dry_count = 0;
        } else if (rain == 1) {
            dry_count++;
            if (dry_count >= DRY_POLLS_REQUIRED) {
                syslog(LOG_INFO, "Rain stopped after %d polls", dry_count);
                dry_count = 0;
            }
        }

        last_rain = rain;
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

