#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17
#define FLOODLIGHT_DURATION_SEC 60
#define POLL_DELAY_US 100000
#define LOG_FILE "security_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event, double duration)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s, Duration: %.2f seconds\n",
                timestamp, event, duration) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_floodlight(void)
{
    if (gpioWrite(FLOODLIGHT_PIN, 1) != 0) {
        fprintf(stderr, "Failed to set floodlight pin HIGH\n");
        return -1;
    }
    printf("Floodlight activated\n");
    return 0;
}

static int deactivate_floodlight(void)
{
    if (gpioWrite(FLOODLIGHT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to set floodlight pin LOW\n");
        return -1;
    }
    printf("Floodlight deactivated\n");
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PIR_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set floodlight pin %d as output\n",
                FLOODLIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    if (deactivate_floodlight() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pir_value = gpioRead(PIR_SENSOR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR sensor on pin %d\n",
                    PIR_SENSOR_PIN);
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");

            if (activate_floodlight() != 0) {
                break;
            }

            time_t start = time(NULL);
            if (start == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                break;
            }

            while (g_running) {
                int val = gpioRead(PIR_SENSOR_PIN);
                if (val < 0) {
                    fprintf(stderr, "Failed to read PIR during floodlight\n");
                    break;
                }
                if (val == 0) {
                    break;
                }
                gpioDelay(POLL_DELAY_US);
            }

            time_t end = time(NULL);
            if (end == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
                break;
            }

            double duration = difftime(end, start);

            if (deactivate_floodlight() != 0) {
                break;
            }

            if (log_event("Motion detected, floodlight activated", duration) != 0) {
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (deactivate_floodlight() != 0) {
        fprintf(stderr, "Warning: floodlight may still be ON at exit\n");
    }

    gpioTerminate();
    printf("Smart Security Light System stopped.\n");
    return 0;
}

