#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_MHD_R         0x2B
#define MPR121_NHD_R         0x2C
#define MPR121_NCL_R         0x2D
#define MPR121_FDL_R         0x2E
#define MPR121_E0TTH         0x41
#define MPR121_DEBOUNCE      0x5B
#define MPR121_CONFIG1       0x5C
#define MPR121_CONFIG2       0x5D
#define MPR121_AUTO_CONFIG0  0x7B
#define MPR121_AUTO_CONFIG1  0x7C
#define MPR121_AUTO_CONFIG2  0x7D
#define MPR121_ECR           0x5E

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(g_i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    /* Soft reset: write 0x63 to register 0x80 */
    if (mpr121_write(0x80, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Baseline filtering — rising (MHD/NHD/NCL/FDL) */
    if (mpr121_write(MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_R, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI=00 (6 samples), SFI=10 (4 samples), CDT=10 (16 µA) */
    if (mpr121_write(0x2C, 0x24) < 0) return -1;

    /* Auto-config registers */
    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG2, 0x04) < 0) return -1;

    /* Touch/release thresholds for electrodes 0-11 (E0TTH=0x0F) */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
    }

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (mpr121_write(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int lo = i2cReadByteData(g_i2c_handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) {
        fprintf(stderr, "Error reading touch status low byte\n");
        return -1;
    }
    int hi = i2cReadByteData(g_i2c_handle, MPR121_TOUCHSTATUS_H);
    if (hi < 0) {
        fprintf(stderr, "Error reading touch status high byte\n");
        return -1;
    }
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    uint32_t last_toggle_tick = 0;
    int relay_state = 0;

    while (g_running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_toggle_tick;

        if (touch_status & 0x0001) {
            if (relay_state == 0 && elapsed >= DEBOUNCE_MS * 1000) {
                relay_state = 1;
                gpioWrite(RELAY_GPIO, 1);
                last_toggle_tick = now;
                printf("Electrode 0 touched — relay ON\n");
            }
        } else {
            if (relay_state == 1) {
                relay_state = 0;
                gpioWrite(RELAY_GPIO, 0);
                printf("Electrode 0 released — relay OFF\n");
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

