#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <pthread.h>
#include <stdarg.h>

#define PORT 5000
#define SERVO_PIN 17
#define PIR_PIN 4
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define LOG_FILE "security.log"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);
    syslog(priority, "%s", buffer);
    if (log_file) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char time_buf[32];
        strftime(time_buf, sizeof(time_buf), "%Y-%m-%dT%H:%M:%S", tm_info);
        fprintf(log_file, "%s %s\n", time_buf, buffer);
        fflush(log_file);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
    if (server_fd >= 0) {
        shutdown(server_fd, SHUT_RDWR);
        close(server_fd);
        server_fd = -1;
    }
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message(LOG_ERR, "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir_sensor") < 0) {
        log_message(LOG_ERR, "Failed to request PIR line as input: %s", strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo_motor", 0) < 0) {
        log_message(LOG_ERR, "Failed to request servo line as output: %s", strerror(errno));
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int angle_to_pulse_width(int angle) {
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;
    return SERVO_MIN_PULSE_WIDTH +
           (int)((long)angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / SERVO_MAX_ANGLE);
}

static void *servo_control_thread(void *arg) {
    (void)arg;
    while (running) {
        int angle = angle_to_pulse_width(0);
        int pulse_width = angle;
        int period_us = 20000;
        int half_period_us = period_us / 2;
        int high_us = pulse_width;
        int low_us = period_us - pulse_width;
        if (high_us < 100) high_us = 100;
        if (low_us < 100) low_us = 100;
        gpiod_line_set_value(servo_line, 1);
        usleep(high_us);
        gpiod_line_set_value(servo_line, 0);
        usleep(low_us);
    }
    return NULL;
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;
    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';
        log_message(LOG_INFO, "Received command: %s", buffer);
        if (strncmp(buffer, "SERVO", 5) == 0) {
            int angle = atoi(buffer + 5);
            if (angle >= SERVO_MIN_ANGLE && angle <= SERVO_MAX_ANGLE) {
                int pulse_width = angle_to_pulse_width(angle);
                char response[64];
                snprintf(response, sizeof(response), "SERVO:OK %d us", pulse_width);
                send(client_socket, response, strlen(response), 0);
                log_message(LOG_INFO, "Setting servo to %d degrees (%d us)", angle, pulse_width);
            } else {
                send(client_socket, "SERVO:ERROR Invalid angle\n", 27, 0);
                log_message(LOG_ERR, "Invalid angle: %d", angle);
            }
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = gpiod_line_get_value(pir_line);
            if (pir_value < 0) {
                send(client_socket, "PIR:ERROR\n", 10, 0);
                log_message(LOG_ERR, "Failed to read PIR sensor: %s", strerror(errno));
            } else {
                char response[16];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                send(client_socket, response, strlen(response), 0);
                log_message(LOG_INFO, "PIR sensor value: %d", pir_value);
            }
        } else {
            send(client_socket, "ERROR: Invalid command\n", 24, 0);
            log_message(LOG_ERR, "Invalid command: %s", buffer);
        }
    }
    if (bytes_received < 0) {
        log_message(LOG_ERR, "recv failed: %s", strerror(errno));
    }
    close(client_socket);
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message(LOG_ERR, "Failed to open log file: %s", strerror(errno));
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }
    if (init_gpio() < 0) {
        log_message(LOG_ERR, "GPIO initialization failed");
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message(LOG_ERR, "socket failed: %s", strerror(errno));
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message(LOG_WARNING, "setsockopt failed: %s", strerror(errno));
    }
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        log_message(LOG_ERR, "bind failed: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "listen failed: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }
    log_message(LOG_INFO, "Listening on port %d", PORT);
    pthread_t servo_thread;
    if (pthread_create(&servo_thread, NULL, servo_control_thread, NULL) != 0) {
        log_message(LOG_ERR, "Failed to create servo thread: %s", strerror(errno));
        close(server_fd);
        cleanup_gpio();
        if (log_file) fclose(log_file);
        closelog();
        return 1;
    }
    while (running) {
        int client_socket = accept(server_fd, NULL, NULL);
        if (client_socket < 0) {
            if (errno == EINTR && !running) break;
            log_message(LOG_ERR, "accept failed: %s", strerror(errno));
            continue;
        }
        log_message(LOG_INFO, "Client connected");
        handle_client(client_socket);
    }
    pthread_join(servo_thread, NULL);
    log_message(LOG_INFO, "Shutting down");
    close(server_fd);
    cleanup_gpio();
    if (log_file) fclose(log_file);
    closelog();
    return 0;
}

