#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE     1.0
#define DEFAULT_DURATION  200
#define NUM_READINGS      5
#define TARE_READINGS     10
#define DOUT_TIMEOUT_US   1000000
#define POLL_DELAY_US     500000
#define MAX_RETRIES       3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int32_t read_hx711(struct gpiod_line *dout, struct gpiod_line *sck) {
    int32_t value = 0;
    int i;

    /* Wait for DOUT to go LOW (data ready) */
    for (i = 0; i < DOUT_TIMEOUT_US; i += 10) {
        if (gpiod_line_get_value(dout) == 0) break;
        usleep(10);
    }
    if (i >= DOUT_TIMEOUT_US) {
        syslog(LOG_ERR, "HX711 timeout waiting for DOUT low");
        return -1;
    }

    /* Read 24 bits MSB-first */
    for (i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "SCK high write failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
        value = (value << 1) | (gpiod_line_get_value(dout) & 1);
        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "SCK low write failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    /* 25th clock pulse: Channel A, Gain 128 */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "SCK 25th high failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "SCK 25th low failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (value & 0x800000) value |= 0xFF000000;
    return value;
}

static double calculate_weight(int32_t raw, double scale, int32_t tare_offset) {
    return ((double)(raw - tare_offset)) / scale;
}

static void activate_solenoid(struct gpiod_line *solenoid, int duration_ms) {
    if (gpiod_line_set_value(solenoid, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(solenoid, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
    }
}

static int tare_hx711(struct gpiod_line *dout, struct gpiod_line *sck, int32_t *offset) {
    int32_t sum = 0;
    int i;

    syslog(LOG_INFO, "Starting tare (%d readings)...", TARE_READINGS);
    for (i = 0; i < TARE_READINGS; i++) {
        int32_t raw = read_hx711(dout, sck);
        if (raw == -1) {
            syslog(LOG_ERR, "Tare read %d failed", i + 1);
            return -1;
        }
        sum += raw;
        usleep(10000);
    }
    *offset = sum / TARE_READINGS;
    syslog(LOG_INFO, "Tare complete: offset = %d", *offset);
    return 0;
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    double scale = DEFAULT_SCALE;
    int duration = DEFAULT_DURATION;
    int opt;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't': threshold = atof(optarg); break;
            case 's': scale = atof(optarg); break;
            case 'd': duration = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration_ms]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("hx711_solenoid", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    struct gpiod_line *sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    struct gpiod_line *solenoid = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!dout || !sck || !solenoid) {
        syslog(LOG_ERR, "Failed to get GPIO lines: %s", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Request DOUT input failed: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Request SCK output failed: %s", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Request solenoid output failed: %s", strerror(errno));
        goto cleanup;
    }

    int32_t tare_offset = 0;
    if (tare_hx711(dout, sck, &tare_offset) < 0) {
        syslog(LOG_ERR, "Tare failed, exiting");
        goto cleanup;
    }

    syslog(LOG_INFO, "Starting weight monitoring (threshold=%.2f, scale=%.2f, duration=%dms)",
           threshold, scale, duration);

    while (running) {
        int32_t sum = 0;
        int valid = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            int32_t raw = read_hx711(dout, sck);
            if (raw == -1) {
                syslog(LOG_ERR, "HX711 read failed (attempt %d/%d)", attempt + 1, MAX_RETRIES);
                usleep(100000);
                continue;
            }
            sum += raw;
            valid++;
            break;
        }

        if (valid == 0) {
            syslog(LOG_ERR, "HX711 unavailable after %d retries, exiting", MAX_RETRIES);
            break;
        }

        double weight = calculate_weight(sum, scale, tare_offset);
        syslog(LOG_INFO, "Weight: %.2f g", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded (%.2f > %.2f), activating solenoid", weight, threshold);
            activate_solenoid(solenoid, duration);
        }

        usleep(POLL_DELAY_US);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down");
    if (solenoid) gpiod_line_set_value(solenoid, 0);
    if (sck) gpiod_line_release(sck);
    if (dout) gpiod_line_release(dout);
    if (chip) gpiod_chip_close(chip);
    closelog();
    return EXIT_SUCCESS;
}

