/*
 * relay_controller.c — Raspberry Pi 4 Model B, Raspberry Pi OS
 *
 * Subscribes to home/lights/control (QoS 0) and drives GPIO17 (BCM 17,
 * physical pin 11) via a relay module.  ON  -> relay ON  -> GPIO HIGH
 * OFF -> relay OFF -> GPIO LOW.  Empty payload or anything but "ON" or
 * "OFF" is logged as an error and leaves the relay unchanged.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c \
 *                  -lmosquitto -lpigpio -lrt
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST      "localhost"
#define MQTT_PORT      1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC     "home/lights/control"
#define GPIO_PIN       17          /* BCM 17, physical pin 11 */
#define KEEPALIVE_SEC  60
#define RECONNECT_DELAY_SEC 5

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        return -1;
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode(%d, PI_OUTPUT) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {   /* relay OFF at startup */
        syslog(LOG_ERR, "gpioWrite(%d, 0) failed", GPIO_PIN);
        gpioTerminate();
        return -1;
    }
    syslog(LOG_INFO, "GPIO%d initialised as output, relay OFF", GPIO_PIN);
    return 0;
}

static void gpio_set_relay(int state)
{
    if (gpioWrite(GPIO_PIN, state) != 0)
        syslog(LOG_ERR, "gpioWrite(%d, %d) failed", GPIO_PIN, state);
    else
        syslog(LOG_INFO, "Relay set to %s (GPIO%d = %d)",
               state ? "ON" : "OFF", GPIO_PIN, state);
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *m, void *ud, int rc)
{
    (void)ud;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker %s:%d", MQTT_HOST, MQTT_PORT);
        int r = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (r == MOSQ_ERR_SUCCESS)
            syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
        else
            syslog(LOG_ERR, "mosquitto_subscribe() failed: %s",
                   mosquitto_strerror(r));
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(rc));
    }
}

static void on_disconnect(struct mosquitto *m, void *ud, int rc)
{
    (void)m; (void)ud;
    if (rc == MOSQ_ERR_SUCCESS)
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    else
        syslog(LOG_WARNING, "Unexpected MQTT disconnect: %s",
               mosquitto_strerror(rc));
}

static void on_message(struct mosquitto *m, void *ud,
                        const struct mosquitto_message *msg)
{
    (void)m; (void)ud;

    if (!msg || !msg->payload || msg->payloadlen <= 0) {
        syslog(LOG_ERR, "Received empty message on %s", msg ? msg->topic : "");
        return;
    }

    /* Ensure NUL-terminated payload for safe string comparison */
    char payload[256];
    size_t len = (size_t)msg->payloadlen;
    if (len >= sizeof(payload))
        len = sizeof(payload) - 1;
    memcpy(payload, msg->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        gpio_set_relay(1);
        syslog(LOG_INFO, "Received ON on %s", msg->topic);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set_relay(0);
        syslog(LOG_INFO, "Received OFF on %s", msg->topic);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on %s", payload, msg->topic);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();

    gpio_set_relay(0);   /* relay OFF */
    gpioTerminate();

    closelog();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "mosquitto_new() failed");
        cleanup();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect() failed: %s",
               mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_loop_start() failed: %s",
               mosquitto_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started (GPIO%d, %s:%d/%s)",
           GPIO_PIN, MQTT_HOST, MQTT_PORT, MQTT_TOPIC);

    while (running)
        sleep(1);

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

