#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define NUM_SERVOS 5
#define PWM_FREQ 50
#define PWM_RANGE 20000
#define PULSE_MIN 500
#define PULSE_MAX 2500

static const int servo_pins[NUM_SERVOS] = {7, 8, 9, 10, 11};
static const int pulse_widths[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500};

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        if (gpioSetMode(servo_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(servo_pins[i], PWM_FREQ) != PWM_FREQ) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(servo_pins[i], PWM_RANGE) != PWM_RANGE) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        int pulse = pulse_widths[i];
        if (pulse < PULSE_MIN || pulse > PULSE_MAX) {
            fprintf(stderr, "Warning: pulse width %d out of range [%d, %d] for servo %d\n",
                    pulse, PULSE_MIN, PULSE_MAX, i);
            pulse = (pulse < PULSE_MIN) ? PULSE_MIN : PULSE_MAX;
        }
        if (gpioPWM(servo_pins[i], pulse) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Servo %d (GPIO %d) -> pulse %d us\n", i, servo_pins[i], pulse);
    }

    printf("Servos moving to positions... hold for 3 seconds.\n");
    sleep(3);

    for (int i = 0; i < NUM_SERVOS; i++) {
        if (gpioPWM(servo_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to stop PWM on GPIO %d\n", servo_pins[i]);
        }
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

