#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>

/* Motor A */
#define MOTOR_A_PWM  17
#define MOTOR_A_DIR  18

/* Motor B */
#define MOTOR_B_PWM  22
#define MOTOR_B_DIR  23

/* Encoder A */
#define ENCODER_A_A  4
#define ENCODER_A_B  5

/* Encoder B */
#define ENCODER_B_A  6
#define ENCODER_B_B  12

#define TARGET_SPEED_RPM  50.0
#define KP  0.5
#define KI  0.05
#define PWM_FREQ_HZ  10000
#define PWM_RANGE    255
#define CONTROL_PERIOD_US 100000  /* 100 ms */
#define ENCODER_TICKS_PER_REV 64
#define STALL_TIMEOUT_S 2

static atomic_int encoder_a_count = 0;
static atomic_int encoder_b_count = 0;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    if (gpioRead(ENCODER_A_A) == gpioRead(ENCODER_A_B)) {
        atomic_fetch_add(&encoder_a_count, 1);
    } else {
        atomic_fetch_sub(&encoder_a_count, 1);
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    if (gpioRead(ENCODER_B_A) == gpioRead(ENCODER_B_B)) {
        atomic_fetch_add(&encoder_b_count, 1);
    } else {
        atomic_fetch_sub(&encoder_b_count, 1);
    }
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_DIR, PI_OUTPUT) < 0 ||
        gpioSetMode(ENCODER_A_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_A_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER_B_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(ENCODER_A_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_A_B, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER_B_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-ups\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQ_HZ) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) < 0 ||
        gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) < 0) {
        fprintf(stderr, "Failed to register ISRs\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_motor_direction(int motor_pwm, int motor_dir, int direction) {
    if (direction > 0) {
        gpioWrite(motor_dir, 1);
    } else if (direction < 0) {
