#define BH1750_CONV_TIME_MS 180
#define BH1750_CMD_OT_HIGH_RES_2 0x21

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int lux, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Lux = %d, Relay = %s\n",
            timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static int read_bh1750(int handle, int *lux_out) {
    char buf[2];
    int result;

    result = i2cWriteByte(handle, BH1750_CMD_OT_HIGH_RES_2);
    if (result < 0) {
        fprintf(stderr, "Error writing to BH1750: %d\n", result);
        return -1;
    }

    gpioDelay(BH1750_CONV_TIME_MS * 1000);

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from BH1750: %d\n", result);
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | (unsigned int)buf[1];
    *lux_out = (int)(raw / 1.2);
    return 0;
}

