    int lux, relay_state = 0;
    int lux_low = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Smart Chicken Coop Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_bh1750(i2c_handle, &lux) == 0) {
            log_data(lux, relay_state);

            if (lux < LUX_THRESHOLD_LOW && lux_low) {
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
                lux_low = 0;
