                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
                lux_low = 1;
            }
        } else {
            fprintf(stderr, "Error reading BH1750 sensor. Turning off relay for safety.\n");
            control_relay(RELAY_GPIO, 0);
            relay_state = 0;
            lux_low = 1;
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    control_relay(RELAY_GPIO, 0);
    cleanup();
    return 0;
}

