#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_VALVE_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_US 1000000
#define SAMPLE_INTERVAL_US 1000000

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile int solenoid_state = 1; /* 1 = open (HIGH), 0 = closed (LOW) */

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

static void control_solenoid(double lpm) {
    int new_state = solenoid_state;
    if (lpm > LPM_THRESHOLD_HIGH && solenoid_state == 1) {
        new_state = 0;
    } else if (lpm < LPM_THRESHOLD_LOW && solenoid_state == 0) {
        new_state = 1;
    }
    if (new_state != solenoid_state) {
        if (gpioWrite(SOLENOID_VALVE_GPIO, new_state) == 0) {
            solenoid_state = new_state;
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Solenoid %s (LPM: %.2f L/min)",
                     new_state ? "OPEN" : "CLOSED", lpm);
            log_event(msg);
        } else {
            log_event("ERROR: Failed to write solenoid GPIO");
        }
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        log_event("ERROR: Failed to set flow sensor GPIO mode");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_VALVE_GPIO, PI_OUTPUT) != 0) {
        log_event("ERROR: Failed to set solenoid GPIO mode");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_VALVE_GPIO, 1) != 0) {
        log_event("ERROR: Failed to initialize solenoid to open state");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    solenoid_state = 1;

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US,
                         flow_sensor_isr, NULL) != 0) {
        log_event("ERROR: Failed to set ISR function for flow sensor");
        gpioWrite(SOLENOID_VALVE_GPIO, 0);
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    while (running) {
        gpioDelay(SAMPLE_INTERVAL_US);
        if (!running) break;

        int local_pulses;
        pthread_mutex_lock(&pulse_mutex);
        local_pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (local_pulses / PULSES_PER_LITER) * 60.0;

        char msg[128];
        snprintf(msg, sizeof(msg), "LPM: %.2f L/min", lpm);
        log_event(msg);

        control_solenoid(lpm);
    }

    log_event("Shutting down");
    gpioWrite(SOLENOID_VALVE_GPIO, 1);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_US, NULL, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

