#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define MAX_WEIGHT_GRAMS 1000.0
#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_TIMEOUT_US 1000

static volatile sig_atomic_t running = 1;
static int server_socket = -1;
static int server_port = 12345;
static char server_ip[64] = "127.0.0.1";
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: config file '%s' not found, using defaults.\n", filename);
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        line[strcspn(line, "\n")] = 0;
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");
        if (!key || !value) continue;
        if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = 0;
        } else if (strcmp(key, "server_port") == 0) {
            server_port = atoi(value);
            if (server_port <= 0 || server_port > 65535) server_port = 12345;
        } else if (strcmp(key, "calibration_factor") == 0) {
            calibration_factor = atof(value);
            if (calibration_factor == 0.0) calibration_factor = 1.0;
        }
    }
    fclose(fp);
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(HX711_SCK_PIN, 0);
    return 0;
}

static int init_socket(void) {
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("socket");
        return -1;
    }
    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        close(server_socket);
        server_socket = -1;
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(server_ip);
    addr.sin_port = htons(server_port);
    if (bind(server_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_socket);
        server_socket = -1;
        return -1;
    }
    if (listen(server_socket, 3) < 0) {
        perror("listen");
        close(server_socket);
        server_socket = -1;
        return -1;
    }
    printf("Listening on %s:%d\n", server_ip, server_port);
    return 0;
}

static long read_hx711(void) {
    long count = 0;
    int i;
    for (i = 0; i < HX711_TIMEOUT_ATTEMPTS; i++) {
        if (gpioRead(HX711_DATA_PIN) == 0) break;
        gpioDelay(HX711_TIMEOUT_US / HX711_TIMEOUT_ATTEMPTS);
    }
    if (i >= HX711_TIMEOUT_ATTEMPTS) {
        fprintf(stderr, "HX711 timeout: DATA pin stuck HIGH\n");
        return -1;
    }
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(HX711_DATA_PIN)) count++;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (count & 0x800000) count |= 0xFF000000;
    return count;
}

static double convert_to_grams(long raw) {
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(int pulse_us) {
    if (pulse_us < SERVO_MIN_PULSE_US || pulse_us > SERVO_MAX_PULSE_US) {
        fprintf(stderr, "Servo pulse %d us out of range\n", pulse_us);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

static int dispense_ingredient(double target_grams) {
    int pulse_us = SERVO_MIN_PULSE_US + (int)(target_grams / MAX_WEIGHT_GRAMS * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US));
    if (pulse_us < SERVO_MIN_PULSE_US) pulse_us = SERVO_MIN_PULSE_US;
    if (pulse_us > SERVO_MAX_PULSE_US) pulse_us = SERVO_MAX_PULSE_US;
    if (set_servo_pulse(pulse_us) < 0) return -1;
    gpioDelay(1000000);
