#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int toggle_relay(void) {
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "Error: gpioRead failed on relay pin %d\n", RELAY_PIN);
        return -1;
    }
    int new_state = !current;
    if (gpioWrite(RELAY_PIN, new_state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on relay pin %d\n", RELAY_PIN);
        return -1;
    }
    return new_state;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEFAULT_DEBOUNCE_MS;

    if (argc > 1) {
        debounce_ms = atoi(argv[1]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Warning: invalid debounce '%s', using default %d ms\n",
                    argv[1], DEFAULT_DEBOUNCE_MS);
            debounce_ms = DEFAULT_DEBOUNCE_MS;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch sensor pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed to initialise relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-controlled desk lamp started. Touch GPIO %d to toggle relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Debounce: %d ms. Press Ctrl+C to exit.\n", debounce_ms);
    fflush(stdout);

    int relay_state = 0;
    int last_stable = 0;
    uint32_t last_change_tick = 0;

    while (running) {
        int raw = gpioRead(TOUCH_SENSOR_PIN);
        if (raw < 0) {
            fprintf(stderr, "Error: gpioRead failed on touch sensor pin %d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (raw != last_stable) {
            last_change_tick = gpioTick();
            last_stable = raw;
        }

        uint32_t elapsed = gpioTick() - last_change_tick;
        if (elapsed >= (uint32_t)(debounce_ms * 1000)) {
            if (last_stable == 1) {
                relay_state = toggle_relay();
                if (relay_state >= 0) {
                    log_relay_state(relay_state);
                }
            }
        }

        gpioDelay(1000);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nCleanup complete. Exiting.\n");
    return EXIT_SUCCESS;
}

