#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define INITIAL_ANGLE  90
#define STEP_DEGREES   10
#define PWM_FREQ_HZ    50
#define PWM_RANGE      1000000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int angle_to_pulse_us(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (int)((long)(angle - MIN_ANGLE) *
                                (MAX_PULSE_US - MIN_PULSE_US) /
                                (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int angle) {
    int pw = angle_to_pulse_us(angle);
    if (pw < MIN_PULSE_US || pw > MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse width %d us out of range [%d, %d]\n",
                pw, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pw) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static int restore_termios(int fd, const struct termios *old) {
    if (tcsetattr(fd, TCSANOW, old) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

int main(void) {
    struct termios old, raw;
    int angle = INITIAL_ANGLE;
    int rc = EXIT_SUCCESS;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (tcgetattr(STDIN_FILENO, &old) != 0) {
        perror("tcgetattr");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    raw = old;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN] = 1;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        restore_termios(STDIN_FILENO, &old);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(angle) != 0) {
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("Servo control ready. Angle: %d°  (Ctrl-C to quit)\n", angle);
    fflush(stdout);

    while (g_running) {
        int ch = getchar();
        if (ch == EOF) {
            if (errno == EINTR) continue;
            break;
        }

        switch (ch) {
            case '+':
                angle += STEP_DEGREES;
                if (angle > MAX_ANGLE) angle = MAX_ANGLE;
                break;
            case '-':
                angle -= STEP_DEGREES;
                if (angle < MIN_ANGLE) angle = MIN_ANGLE;
                break;
            case 'q':
            case 'Q':
                g_running = 0;
                break;
            default:
                continue;
        }

        if (set_servo_angle(angle) != 0) {
            rc = EXIT_FAILURE;
            break;
        }
        printf("Angle: %d°\n", angle);
        fflush(stdout);
    }

cleanup:
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    restore_termios(STDIN_FILENO, &old);
    printf("\nExiting.\n");
    return rc;
}

