#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000   /* 50 ms */
#define FAILSAFE_TIMEOUT_S 10

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins --- */
    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT)    != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in OFF state */
    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    printf("Touch-controlled relay started. Touch GPIO%d to toggle GPIO%d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int relay_state = 0;
    int failsafe_active = 0;
    uint32_t failsafe_start_tick = 0;

    while (g_running) {
        int touch_value = safe_read(TOUCH_SENSOR_PIN);
        if (touch_value < 0) {
            break;
        }

        if (touch_value == 1) {
            /* Touch detected — toggle relay */
            relay_state = !relay_state;
            if (safe_write(RELAY_PIN, relay_state) != 0) {
                break;
            }
            printf("Touch detected — relay %s\n", relay_state ? "ON" : "OFF");

            if (!failsafe_active) {
                failsafe_active = 1;
                failsafe_start_tick = gpioTick();
            }
        } else {
            /* Touch released */
            failsafe_active = 0;
        }

        /* Failsafe: force relay OFF if sensor is held HIGH too long */
        if (failsafe_active) {
            uint32_t elapsed = gpioTick() - failsafe_start_tick;
            if (elapsed >= (uint32_t)(FAILSAFE_TIMEOUT_S * 1000000)) {
                printf("Failsafe triggered: sensor held HIGH > %d s — relay OFF\n",
                       FAILSAFE_TIMEOUT_S);
                if (safe_write(RELAY_PIN, 0) != 0) {
                    break;
                }
                relay_state = 0;
                failsafe_active = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    safe_write(RELAY_PIN, 0);   /* best-effort relay OFF */
    gpioTerminate();
    return EXIT_SUCCESS;
}

