#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_RANGE          255
#define PWM_FREQUENCY      1000
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */
#define YF_S201_PULSES_LITER 450.0
#define DEFAULT_TARGET_FLOW 5.0
#define MIN_TARGET_FLOW     0.0
#define MAX_TARGET_FLOW     100.0
#define KP                  1.0
#define LOG_FILE            "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;
    if (level == 1) {
        g_pulse_count++;
    }
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set PWM pin %d as output.\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set enable pin %d as output.\n", VALVE_ENABLE_PIN);
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set flow sensor pin %d as input.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on pin %d.\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on pin %d.\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM to 0 on pin %d.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set enable pin %d high.\n", VALVE_ENABLE_PIN);
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
