#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_PIN_1      17
#define LOCK_PIN_2      27
#define BUTTON_PIN      22
#define SPI_CHANNEL     0
#define SPI_SPEED       100000
#define SPI_BYTES       10
#define DEBOUNCE_US     50000
#define UNLOCK_DELAY_US 5000000
#define POLL_DELAY_US   100000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

static const unsigned char valid_tag[10] = {
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A
};

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *event) {
    if (!g_log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(g_log_file, "%s %s\n", ts, event);
    fflush(g_log_file);
}

static void lock_engage(int pin) {
    if (gpioWrite(pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(engage) failed on pin %d\n", pin);
    }
}

static void lock_disengage(int pin) {
    if (gpioWrite(pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(disengage) failed on pin %d\n", pin);
    }
}

static int read_rfid(unsigned char *buf, int len) {
    if (g_spi_handle < 0) return -1;
    int n = spiXfer(g_spi_handle, (char *)buf, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "SPI transfer failed (got %d, expected %d)\n", n, len);
        return -1;
    }
    return 0;
}

static int authenticate(void) {
    unsigned char rx[SPI_BYTES];
    memset(rx, 0, sizeof(rx));

    if (read_rfid(rx, SPI_BYTES) != 0) {
        log_event("RFID read failure");
        return 0;
    }

    if (memcmp(rx, valid_tag, 10) == 0) {
        log_event("Access granted");
        return 1;
    }

    if (memcmp(rx, valid_tag, 10) != 0) {
        log_event("Invalid tag");
    }
    return 0;
}

static void cleanup(void) {
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    lock_engage(LOCK_PIN_1);
    lock_engage(LOCK_PIN_2);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_log_file = fopen("/var/log/door_access.log", "a");
    if (!g_log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LOCK_PIN_1, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_PIN_2, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    lock_engage(LOCK_PIN_1);
    lock_engage(LOCK_PIN_2);

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (g_running) {
        if (gpioRead(BUTTON_PIN) == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(BUTTON_PIN) == 0) {
                if (authenticate()) {
                    lock_disengage(LOCK_PIN_1);
                    lock_disengage(LOCK_PIN_2);
                    gpioDelay(UNLOCK_DELAY_US);
                    lock_engage(LOCK_PIN_1);
                    lock_engage(LOCK_PIN_2);
                }
                gpioDelay(DEBOUNCE_US);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

