#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define SAMPLE_TIME_MS 100
#define ENCODER_PPR 600
#define TARGET_RPM 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6];
static struct gpiod_line *encoder_lines[4];
static int encoder_counts[2] = {0, 0};
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(double m1_speed, double m2_speed,
                     double pid_p, double pid_i, double pid_d, double pid_out) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%.4f,%.4f,%.4f,%.4f\n",
            ts, m1_speed, m2_speed, pid_p, pid_i, pid_d, pid_out);
    fflush(log_file);
}

static void set_motor_speed(int motor, double speed) {
    int pins[4];
    int en_pin, in1_pin, in2_pin;
    if (motor == 1) {
        en_pin = MOTOR1_ENA; in1_pin = MOTOR1_IN1; in2_pin = MOTOR1_IN2;
    } else if (motor == 2) {
        en_pin = MOTOR2_ENB; in1_pin = MOTOR2_IN3; in2_pin = MOTOR2_IN4;
    } else return;

    int duty_us = (int)(speed * PWM_PERIOD_US);
    if (duty_us < 0) duty_us = 0;
    if (duty_us > PWM_PERIOD_US) duty_us = PWM_PERIOD_US;

    pins[0] = en_pin; pins[1] = in1_pin; pins[2] = in2_pin; pins[3] = -1;
    for (int i = 0; pins[i] >= 0; i++) {
        if (gpiod_line_set_value(motor_lines[pins[i]], 0) < 0)
            fprintf(stderr, "Warning: set_value failed on line %d\n", pins[i]);
    }

    if (duty_us > 0) {
        if (gpiod_line_set_value(motor_lines[in1_pin], 1) < 0) return;
        if (gpiod_line_set_value(motor_lines[in2_pin], 0) < 0) return;
    }

    struct timespec on = {0, duty_us * 1000};
    struct timespec off = {0, (PWM_PERIOD_US - duty_us) * 1000};
    nanosleep(&on, NULL);
    if (gpiod_line_set_value(motor_lines[in1_pin], 0) < 0) return;
    if (gpiod_line_set_value(motor_lines[in2_pin], 0) < 0) return;
    nanosleep(&off, NULL);
}

static void *encoder_thread(void *arg) {
    int encoder_id = *(int *)arg;
    int a_pin = (encoder_id == 1) ? ENCODER1_A : ENCODER2_A;
    int b_pin = (encoder_id == 1) ? ENCODER1_B : ENCODER2_B;

    struct gpiod_line *a_line = encoder_lines[encoder_id * 2 - 2];
    struct gpiod_line *b_line = encoder_lines[encoder_id * 2 - 1];

    int last_a = gpiod_line_get_value(a_line);
    if (last_a < 0) { fprintf(stderr, "Encoder init read failed\n"); return NULL; }
    int last_b = gpiod_line_get_value(b_line);
    if (last_b < 0) { fprintf(stderr, "Encoder init read failed\n"); return NULL; }

    while (running) {
        int cur_a = gpiod_line_get_value(a_line);
        if (cur_a < 0) { fprintf(stderr, "Encoder read A failed\n"); break; }
        int cur_b = gpiod_line_get_value(b_line);
        if (cur_b < 0) { fprintf(stderr, "Encoder read B failed\n"); break; }

        if (cur_a != last_a) {
            int dir = (cur_a == cur_b) ? 1 : -1;
            pthread_mutex_lock(&encoder_mutex);
            encoder_counts[encoder_id - 1] += dir;
            pthread_mutex_unlock(&encoder_mutex);
            last_a = cur_a;
        }
        usleep(100);
    }
    return NULL;
}

static double calculate_pid(int encoder_id, double target_rpm) {
    double current_rpm = 0.0;
    pthread_mutex_lock(&encoder_mutex);
    int count = encoder_counts[encoder_id - 1];
    encoder_counts[encoder_id - 1] = 0;
    pthread_mutex_unlock(&encoder_mutex);

    current_rpm = (double)count * (600000.0 / (SAMPLE_TIME_MS * 1000.0));

    static double integral[2] = {0.0, 0.0};
    static double prev_error[2] = {0.0, 0.0};

    double error = target_rpm - current_rpm;
    integral[encoder_id - 1] += error * (SAMPLE_TIME_MS / 1000.0);
    double derivative = (error - prev_error[encoder_id - 1]) / (SAMPLE_TIME_MS / 1000.0);
    prev_error[encoder_id - 1] = error;

    double output = KP * error + KI * integral[encoder_id - 1] + KD * derivative;
    if (output > 100.0) output = 100.0;
    if (output < -100.0) output = -100.0;
    return output;
}

int main(void) {
    motor_lines[MOTOR1_ENA] = motor_lines[MOTOR1_IN1] = motor_lines[MOTOR1_IN2] = NULL;
    motor_lines[MOTOR2_ENB] = motor_lines[MOTOR2_IN3] = motor_lines[MOTOR2_IN4] = NULL;
    encoder_lines[0] = encoder_lines[1] = encoder_lines[2] = encoder_lines[3] = NULL;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[motor_pins[i]] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[motor_pins[i]]) {
            fprintf(stderr, "Failed to get motor line %d\n", motor_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(motor_lines[motor_pins[i]], "motor_control", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output\n", motor_pins[i]);
            goto cleanup;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d\n", encoder_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder_events") < 0) {
            fprintf(stderr, "Failed to request encoder events on line %d\n", encoder_pins[i]);
            goto cleanup;
        }
    }

    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID_P,PID_I,PID_D,PID_Output\n");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t enc_thread1, enc_thread2;
    int enc_id1 = 1, enc_id2 = 2;
    if (pthread_create(&enc_thread1, NULL, encoder_thread, &enc_id1) != 0) {
        perror("pthread_create enc1");
        goto cleanup;
    }
    if (pthread_create(&enc_thread2, NULL, encoder_thread, &enc_id2) != 0) {
        perror("pthread_create enc2");
        running = 0;
        pthread_join(enc_thread1, NULL);
        goto cleanup;
    }

    while (running) {
        double pid1 = calculate_pid(1, TARGET_RPM);
        double pid2 = calculate_pid(2, TARGET_RPM);

        set_motor_speed(1, pid1);
        set_motor_speed(2, pid2);

        double m1_speed = 0.0, m2_speed = 0.0;
        pthread_mutex_lock(&encoder_mutex);
        m1_speed = (double)encoder_counts[0] * (600000.0 / (SAMPLE_TIME_MS * 1000.0));
        m2_speed = (double)encoder_counts[1] * (600000.0 / (SAMPLE_TIME_MS * 1000.0));
        encoder_counts[0] = 0;
        encoder_counts[1] = 0;
        pthread_mutex_unlock(&encoder_mutex);

        log_data(m1_speed, m2_speed, pid1, 0.0, 0.0, pid1);
        usleep(SAMPLE_TIME_MS * 1000);
    }

    pthread_join(enc_thread1, NULL);
    pthread_join(enc_thread2, NULL);

cleanup:
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) gpiod_line_release(motor_lines[i]);
    }
    for (int i = 0; i < 4; i++) {
        if (encoder_lines[i]) gpiod_line_release(encoder_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    return 0;
}

