#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define POLL_DELAY_US 50000

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_NHDT 0x33
#define MPR121_NCLT 0x34
#define MPR121_FDLT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, value, rc);
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* AFE configuration: FFI=00, CDC=16uA, ESI=1ms, SFI=00, ESI=1ms */
    if (mpr121_write(0x2B, 0x01) < 0) return -1;
    if (mpr121_write(0x2C, 0x20) < 0) return -1;
    if (mpr121_write(0x2D, 0x04) < 0) return -1;
    if (mpr121_write(0x2E, 0x00) < 0) return -1;
    if (mpr121_write(0x2F, 0x01) < 0) return -1;
    if (mpr121_write(0x30, 0x20) < 0) return -1;
    if (mpr121_write(0x31, 0x04) < 0) return -1;
    if (mpr121_write(0x32, 0x00) < 0) return -1;
    if (mpr121_write(0x33, 0x01) < 0) return -1;
    if (mpr121_write(0x34, 0x20) < 0) return -1;
    if (mpr121_write(0x35, 0x04) < 0) return -1;

    /* Touch and release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1;
        if (mpr121_write(MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1;
    }

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ELECONFIG, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    int low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (low < 0) {
        fprintf(stderr, "I2C read failed: TOUCHSTATUS_L, rc=%d\n", low);
        return -1;
    }
    int high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "I2C read failed: TOUCHSTATUS_H, rc=%d\n", high);
        return -1;
    }
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_relay_state(int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (!fp) {
        perror("Error opening relay_log.txt");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay %s\n", timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

