#include <unistd.h>
#include <gpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION_MS 500
#define VALVE2_DURATION_MS 1000
#define PAUSE_BETWEEN_VALVES_S 5
#define PAUSE_BETWEEN_VALVES_S2 10
#define LOG_FILE "valve_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *valve1_line = NULL;
static struct gpiod_line *valve2_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static void cleanup(void) {
    if (valve1_line) {
        gpiod_line_set_value(valve1_line, 0);
        gpiod_line_release(valve1_line);
        valve1_line = NULL;
    }
    if (valve2_line) {
        gpiod_line_set_value(valve2_line, 0);
        gpiod_line_release(valve2_line);
        valve2_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        cleanup();
        return EXIT_FAILURE;
    }

    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        perror("gpiod_chip_get_line valve1");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(valve1_line, "valve_schedule", 0) < 0) {
        perror("gpiod_line_request_output valve1");
        cleanup();
        return EXIT_FAILURE;
    }

    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        perror("gpiod_chip_get_line valve2");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(valve2_line, "valve_schedule", 0) < 0) {
        perror("gpiod_line_request_output valve2");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("System started");

    while (running) {
        log_event("Activating Valve 1");
        if (gpiod_line_set_value(valve1_line, 1) < 0) {
            perror("gpiod_line_set_value valve1 ON");
            break;
        }
        usleep(VALVE1_DURATION_MS * 1000);
        if (gpiod_line_set_value(valve1_line, 0) < 0) {
            perror("gpiod_line_set_value valve1 OFF");
            break;
        }
        log_event("Valve 1 deactivated");

        if (!running) break;
        sleep(PAUSE_BETWEEN_VALVES_S);

        log_event("Activating Valve 2");
        if (gpiod_line_set_value(valve2_line, 1) < 0) {
            perror("gpiod_line_set_value valve2 ON");
            break;
        }
        usleep(VALVE2_DURATION_MS * 1000);
        if (gpiod_line_set_value(valve2_line, 0) < 0) {
            perror("gpiod_line_set_value valve2 OFF");
            break;
        }
        log_event("Valve 2 deactivated");

        if (!running) break;
        sleep(PAUSE_BETWEEN_VALVES_S2);
    }

    log_event("System shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

