        return -1;
    }
    int high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", MPR121_TOUCHSTATUS_H, high);
        return -1;
    }
