    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            int current = gpioRead(RELAY_PIN);
            gpioWrite(RELAY_PIN, !current);
            printf("Touch detected! Relay toggled to %s\n", current ? "OFF" : "ON");
