        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", MPR121_TOUCHSTATUS_L, low);
        return -1;
    }
    int high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (high < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", MPR121_TOUCHSTATUS_H, high);
        return -1;
    }
    *status = (uint16_t)((high << 8) | low);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            int current = gpioRead(RELAY_PIN);
            gpioWrite(RELAY_PIN, !current);
            printf("Touch detected! Relay toggled to %s\n", current ? "OFF" : "ON");
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_PIN, 0);
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

