#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

static int generate_haptic_pattern(int *duty1, int *duty2, int *duration_ms, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        duty1[i] = rand() % (MAX_DUTY + 1);
        duty2[i] = rand() % (MAX_DUTY + 1);
        duration_ms[i] = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }
    return 0;
}

static void play_haptic_pattern(const int *duty1, const int *duty2, const int *duration_ms, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        if (shutdown_flag) break;

        if (gpioPWM(MOTOR1_PIN, duty1[i]) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on motor 1 (step %d).\n", i);
        }
        if (gpioPWM(MOTOR2_PIN, duty2[i]) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on motor 2 (step %d).\n", i);
        }

        gpioDelay(duration_ms[i] * 1000);
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int num_steps;
    int *duty1 = NULL, *duty2 = NULL, *duration_ms = NULL;

    while (!shutdown_flag) {
        num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;

        duty1 = (int *)malloc(num_steps * sizeof(int));
        duty2 = (int *)malloc(num_steps * sizeof(int));
        duration_ms = (int *)malloc(num_steps * sizeof(int));

        if (duty1 == NULL || duty2 == NULL || duration_ms == NULL) {
            fprintf(stderr, "Error: memory allocation failed.\n");
            free(duty1);
            free(duty2);
            free(duration_ms);
            break;
        }

        generate_haptic_pattern(duty1, duty2, duration_ms, num_steps);
        play_haptic_pattern(duty1, duty2, duration_ms, num_steps);

        free(duty1);
        duty1 = NULL;
        free(duty2);
        duty2 = NULL;
        free(duration_ms);
        duration_ms = NULL;
    }

    cleanup();
    return 0;
}

