#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

#define WEIGHT_THRESHOLD 10.0
#define NUM_CALIBRATION_READINGS 100
#define READ_TIMEOUT_US 500000
#define LOOP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin, long *raw_value) {
    if (gpioSetMode(data_pin, PI_INPUT) < 0) return -1;
    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) return -1;

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    int timeout = 0;
    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > READ_TIMEOUT_US) return -2;
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) value++;
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    *raw_value = value ^ 0x800000;
    return 0;
}

static double calibrate_hx711(int data_pin, int clock_pin) {
    long sum = 0;
    int valid = 0;
    for (int i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        long raw;
        if (read_hx711(data_pin, clock_pin, &raw) == 0) {
            sum += raw;
            valid++;
        }
        gpioDelay(1000);
    }
    if (valid == 0) return 0.0;
    return (double)sum / valid;
}

static double convert_to_weight(long raw_value, double scale, double off) {
    return (raw_value - off) / scale;
}

static void control_solenoid(int pin, int state) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) return;
    gpioWrite(pin, state);
}

static void log_weight(double weight, int lock_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Weight: %.2f kg, Lock: %s\n", ts, weight, lock_state ? "Engaged" : "Released");
    fclose(fp);
}

static void save_calibration(double scale, double off) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (!fp) return;
    fprintf(fp, "%.6f %.6f\n", scale, off);
    fclose(fp);
}

static void load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (!fp) return;
    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fclose(fp);
        return;
    }
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    load_calibration();

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    double zero_offset = calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
    offset = zero_offset;
    save_calibration(scale_factor, offset);

    printf("Calibration complete. Offset: %.2f\n", offset);

    while (running) {
        long raw;
        int rc = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &raw);
        if (rc == 0) {
            double weight = convert_to_weight(raw, scale_factor, offset);
            int lock = (weight > WEIGHT_THRESHOLD) ? 1 : 0;
            control_solenoid(SOLENOID_PIN, lock);
            log_weight(weight, lock);
            printf("Weight: %.2f kg, Lock: %s\n", weight, lock ? "Engaged" : "Released");
        } else if (rc == -2) {
            fprintf(stderr, "HX711 read timeout\n");
        } else {
            fprintf(stderr, "HX711 read error\n");
        }
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

