#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_LOCK 17
#define WEIGHT_THRESHOLD 100.0
#define SOLENOID_LOCK_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int dt, int sck, long *raw_value) {
    if (gpioSetMode(dt, PI_INPUT) < 0) return -1;
    if (gpioSetMode(sck, PI_OUTPUT) < 0) return -1
    if (gpioWrite(sck, 0) < 0) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(dt) == 1) {
        if (gpioTick() - start > HX711_TIMEOUT_US) return -2;
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(sck, 1) < 0) return -1;
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(dt) == 1) value |= 1;
        if (gpioWrite(sck, 0) < 0) return -1;
        gpioDelay(1);
    }

    if (gpioWrite(sck, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(sck, 0) < 0) return -1;
    gpioDelay(1);

    if (value & 0x800000) value |= 0xFF000000;

    *raw_value = value;
    return 0;
}

static double convert_to_grams(long raw_value) {
    return (double)raw_value / 1000.0;
}

static void activate_solenoid(int gpio_pin, int duration_seconds) {
    if (gpioWrite(gpio_pin, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d high\n", gpio_pin);
        return;
    }
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(gpio_pin, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d low\n", gpio_pin);
    }
}

static void log_event(const char *event_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    if (tm == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, event_message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_LOCK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SOLENOID_LOCK);
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_LOCK, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Stock monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        long raw_value = 0;
        int ret = read_hx711(HX711_DT, HX711_SCK, &raw_value);

        if (ret == -2) {
            fprintf(stderr, "Error: HX711 timeout - sensor not responding or data line stuck high\n");
            log_event("Error: HX711 timeout");
        } else if (ret < 0) {
            fprintf(stderr, "Error: GPIO write failed during HX711 read\n");
            log_event("Error: GPIO write failed");
        } else {
            double weight = convert_to_grams(raw_value);
            printf("Weight: %.2f g\n", weight);

            if (weight < WEIGHT_THRESHOLD) {
                printf("Stock level below threshold. Activating solenoid lock.\n");
                activate_solenoid(SOLENOID_LOCK, SOLENOID_LOCK_DURATION);
                log_event("Solenoid lock activated");
            }
        }

        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_LOCK, 0);
    gpioTerminate();
    printf("Stock monitoring system stopped.\n");
    return 0;
}

