#define HX711_TIMEOUT_US 100000

static volatile sig_atomic_t running = 1;
static double calibration_factor = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711_raw(int data_pin, int clock_pin, long *out_value) {
    if (out_value == NULL) return -1;

    int timeout = 0;
    while (gpioRead(data_pin) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > HX711_TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout: data line stuck high\n");
            return -1;
        }
    }

    long value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = (value << 1) | (gpioRead(data_pin) & 1);
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = value;
    return 0;
}

static double read_weight(int data_pin, int clock_pin) {
    long raw_value;
    if (read_hx711_raw(data_pin, clock_pin, &raw_value) != 0) {
        return -1.0;
    }
    return (double)raw_value / calibration_factor;
}

static int calibrate_load_cell(int data_pin, int clock_pin) {
    printf("Place a known weight on the load cell and press Enter...\n");
    int c;
    while ((c = getchar()) != '\n' && c != EOF) {
        /* discard input */
    }
    if (c == EOF) {
        fprintf(stderr, "Error reading input during calibration.\n");
        return -1;
    }

    long raw_value;
    if (read_hx711_raw(data_pin, clock_pin, &raw_value) != 0) {
        fprintf(stderr, "Error reading raw value during calibration.\n");
        return -1;
    }

    printf("Enter the known weight in kilograms: ");
    double known_weight;
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight.\n");
        int c;
        while ((c = getchar()) != '\n' && c != EOF) {
            /* discard */
        }
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %.2f\n", calibration_factor);

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return -1;
    }
    if (fprintf(fp, "%.2f", calibration_factor) < 0) {
        fprintf(stderr, "Error writing to calibration file.\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing calibration file.\n");
        return -1;
    }

    printf("Calibration saved to %s\n", CALIBRATION_FILE);
    return 0;
}

static int load_calibration_factor(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file %s. Using default factor 1.0.\n", CALIBRATION_FILE);
        return -1;
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Warning: Could not read calibration factor from file. Using default factor 1.0.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: Error closing calibration file.\n");
        return -1;
    }

    printf("Calibration factor loaded from %s: %.2f\n", CALIBRATION_FILE, calibration_factor);
    return 0;
}

static int log_security_event(double weight) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting current time.\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error converting time to local time.\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp.\n");
        return -1;
    }

    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening security log file %s.\n", SECURITY_LOG_FILE);
        return -1;
    }

    if (fprintf(fp, "%s Weight: %.2f kg\n", timestamp, weight) < 0) {
        fprintf(stderr, "Error writing to security log file.\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing security log file.\n");
        return -1;
    }

    printf("Security event logged: %s Weight: %.2f kg\n", timestamp, weight);
    return 0;
}

static void activate_solenoid_lock(int gpio_pin, int duration_seconds) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error setting solenoid lock GPIO high.\n");
        return;
    }
    printf("Solenoid lock activated.\n");
    sleep(duration_seconds);
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error setting solenoid lock GPIO low.\n");
        return;
    }
    printf("Solenoid lock deactivated.\n");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting HX711 data pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting HX711 clock pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_LOCK_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting solenoid lock pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(HX711_CLOCK_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing HX711 clock pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_LOCK_PIN, 0) != 0) {
        fprintf(stderr, "Error initializing solenoid lock pin low.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (load_calibration_factor() != 0) {
        if (calibrate_load_cell(HX711_DATA_PIN, HX711_CLOCK_PIN) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Weight-based access control system started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = read_weight(HX711_DATA_PIN, HX711_CLOCK_PIN);

        if (weight < 0.0) {
            fprintf(stderr, "Error reading weight. Retrying...\n");
            gpioDelay(100000);
            continue;
        }

        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Activating solenoid lock.\n");
            log_security_event(weight);
            activate_solenoid_lock(SOLENOID_LOCK_PIN, SOLENOID_LOCK_DURATION);
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    gpioWrite(SOLENOID_LOCK_PIN, 0);
    gpioTerminate();
    printf("pigpio terminated.\n");

    return EXIT_SUCCESS;
}

