#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define CHIP_NAME "gpiochip0"
#define LOG_FILE "motion_log.txt"
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *buzzer_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (pir_line) gpiod_line_release(pir_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        perror("gpiod_chip_get_line (PIR)");
        return -1;
    }

    if (gpiod_line_request_input(pir_line, "pir-sensor") < 0) {
        perror("gpiod_line_request_input (PIR)");
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line (buzzer)");
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("gpiod_line_request_output (buzzer)");
        return -1;
    }

    return 0;
}

static int read_pir_sensor(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        perror("gpiod_line_get_value (PIR)");
        return -1;
    }
    return val;
}

static int activate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("gpiod_line_set_value (buzzer ON)");
        return -1;
    }
    return 0;
}

static int deactivate_buzzer(void) {
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("gpiod_line_set_value (buzzer OFF)");
        return -1;
    }
    return 0;
}

static int log_motion(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) {
        perror("localtime");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        perror("fprintf");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            cleanup();
            return 1;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            if (activate_buzzer() < 0) {
                cleanup();
                return 1;
            }
            if (log_motion() < 0) {
                cleanup();
                return 1;
            }
            usleep(2000000);
            if (deactivate_buzzer() < 0) {
                cleanup();
                return 1;
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

