#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE "watering.conf"
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_duration_from_file(const char *filename, int *duration_out)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening configuration file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading configuration file '%s': %s\n",
                filename, ferror(fp) ? strerror(errno) : "unexpected EOF");
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *newline = strchr(line, '\n');
    if (newline) *newline = '\0';

    char *equal = strchr(line, '=');
    if (!equal) {
        fprintf(stderr, "Error: configuration file '%s' does not contain '=', "
                        "expected 'duration=<seconds>'\n", filename);
        return -1;
    }

    *equal = '\0';
    char *key = line;
    char *value = equal + 1;

    while (*key == ' ' || *key == '\t') key++;
    while (*value == ' ' || *value == '\t') value++;

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: configuration file '%s' does not contain "
                        "'duration=<seconds>', found '%s'\n", filename, key);
        return -1;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(value, &endptr, 10);
    if (errno == ERANGE || val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration value '%s' is out of range "
                        "(%d-%d seconds)\n", value, MIN_DURATION, MAX_DURATION);
        return -1;
    }
    if (endptr == value) {
        fprintf(stderr, "Error: duration value '%s' is not a valid integer\n", value);
        return -1;
    }

    *duration_out = (int)val;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    int duration = 0;
    if (read_duration_from_file(CONFIG_FILE, &duration) != 0) {
        goto cleanup;
    }

    printf("Watering system started. Duration: %d seconds\n", duration);
    fflush(stdout);

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error activating valve (GPIO high): %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve activated\n");
    fflush(stdout);

    for (int elapsed = 0; elapsed < duration && g_running; elapsed++) {
        sleep(1);
    }

    if (!g_running) {
        printf("\nInterrupted by signal. Shutting down...\n");
        fflush(stdout);
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error deactivating valve (GPIO low): %s\n", strerror(errno));
        goto cleanup;
    }
    printf("Valve deactivated\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

