#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LEFT_SENSOR   4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR  27

#define LEFT_MOTOR    22
#define RIGHT_MOTOR   23

#define PWM_FREQ      1000
#define BASE_SPEED    150
#define SPEED_LIMIT   255

#define LOG_FILE      "trace_log.txt"
#define SAMPLE_US     10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensors(int *left, int *middle, int *right) {
    int l = gpioRead(LEFT_SENSOR);
    int m = gpioRead(MIDDLE_SENSOR);
    int r = gpioRead(RIGHT_SENSOR);
    if (l < 0 || m < 0 || r < 0) {
        fprintf(stderr, "Error reading sensor GPIOs: %s\n", strerror(errno));
        return -1;
    }
    *left = l;
    *middle = m;
    *right = r;
    return 0;
}

static void set_motor_speed(int left_speed, int right_speed) {
    if (left_speed < 0) left_speed = 0;
    if (left_speed > SPEED_LIMIT) left_speed = SPEED_LIMIT;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > SPEED_LIMIT) right_speed = SPEED_LIMIT;

    if (gpioPWM(LEFT_MOTOR, left_speed) < 0) {
        fprintf(stderr, "Error setting PWM on left motor: %s\n", strerror(errno));
    }
    if (gpioPWM(RIGHT_MOTOR, right_speed) < 0) {
        fprintf(stderr, "Error setting PWM on right motor: %s\n", strerror(errno));
    }
}

static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%d,%d,%d,%d,%d\n",
                timestamp, left, middle, right, left_speed, right_speed) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    set_motor_speed(0, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int left, middle, right;
    int left_speed, right_speed;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting sensor GPIO modes: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_MOTOR, PI_OUTPUT) < 0 ||
        gpioSetMode(RIGHT_MOTOR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting motor GPIO modes: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(LEFT_MOTOR, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RIGHT_MOTOR, PWM_FREQ) < 0) {
        fprintf(stderr, "Error setting PWM frequency: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line following started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_sensors(&left, &middle, &right) < 0) {
            gpioDelay(SAMPLE_US);
            continue;
        }

        if (left == 0 && middle == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left == 0) {
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else if (right == 0) {
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else {
            left_speed = 0;
            right_speed = 0;
        }

        set_motor_speed(left_speed, right_speed);
        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

