#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define LOG_FILE "grow_log.txt"
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int read_lux(float *lux_out) {
    if (i2cWriteByte(i2c_handle, BH1750_CONT_HIGH_RES) < 0) {
        log_event("Error: failed to write BH1750 command");
        return -1;
    }
    gpioDelay(180000);
    int raw = i2cReadWordData(i2c_handle, 0x00);
    if (raw < 0) {
        log_event("Error: failed to read BH1750 data");
        return -1;
    }
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        log_event("Error: failed to write relay GPIO");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay set to %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "GPIO mode set failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    log_event("Program started");

    while (running) {
        float lux = 0.0f;
        if (read_lux(&lux) == 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
            }
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down");
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

