#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int current_pulse_width = UNLOCKED_PULSE_WIDTH;
    gpioServo(SERVO_PIN, current_pulse_width);
    printf("Door lock initialized. Current state: Unlocked.\n");

    while (program_running) {
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            gpioDelay(100000);
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                current_pulse_width = LOCKED_PULSE_WIDTH;
                gpioServo(SERVO_PIN, current_pulse_width);
                printf("Door locked.\n");
            }
        } else if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            gpioDelay(100000);
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                current_pulse_width = UNLOCKED_PULSE_WIDTH;
                gpioServo(SERVO_PIN, current_pulse_width);
                printf("Door unlocked.\n");
            }
        }
        gpioDelay(10000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

