#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PULSE_DURATION_MS 200
#define PULSE_INTERVAL_MS 300
#define CONSUMER "haptic-feedback"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("gpiod_line_set_value failed");
        return -1;
    }
    return 0;
}

static int pulse_motor(struct gpiod_line *line, int duration_ms) {
    if (safe_set_value(line, 1) < 0) return -1;
    usleep(duration_ms * 1000);
    if (safe_set_value(line, 0) < 0) return -1;
    usleep(PULSE_INTERVAL_MS * 1000);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("gpiod_chip_get_line (motor1) failed");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("gpiod_chip_get_line (motor2) failed");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (motor1) failed");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (motor2) failed");
        goto cleanup;
    }

    while (running) {
        if (pulse_motor(motor1_line, PULSE_DURATION_MS) < 0) {
            fprintf(stderr, "Error during motor1 pulse\n");
            goto cleanup;
        }
        if (!running) break;
        if (pulse_motor(motor2_line, PULSE_DURATION_MS) < 0) {
            fprintf(stderr, "Error during motor2 pulse\n");
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (motor1_line) gpiod_line_release(motor1_line);
    if (motor2_line) gpiod_line_release(motor2_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

