#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_SUBSCRIBE_ENDPOINT "tcp://localhost:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_MS 10
#define ALARM_DURATION_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return EXIT_FAILURE;
