#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100

#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250

static volatile sig_atomic_t running = 1;
static volatile uint32_t pulses[MAX_PULSES];
static volatile int pulse_count = 0;
static MQTTClient mqtt_client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulses[pulse_count++] = tick;
        } else {
            syslog(LOG_WARNING, "IR pulse buffer overflow, resetting");
            pulse_count = 0;
        }
    }
}

static int decode_nec(uint32_t *p, int count, uint32_t *addr, uint32_t *cmd) {
    if (count < 34) return -1;
    if (p[0] > NEC_HDR_MARK * 0.7 && p[0] < NEC_HDR_MARK * 1.3 &&
        p[1] > NEC_HDR_SPACE * 0.7 && p[1] < NEC_HDR_SPACE * 1.3) {
        uint32_t data = 0;
        for (int i = 0; i < 32; i++) {
            int idx = 2 + i * 2;
            if (idx + 1 >= count) return -1;
            if (p[idx] > NEC_BIT_MARK * 0.7 && p[idx] < NEC_BIT_MARK * 1.3) {
                if (p[idx + 1] > NEC_ONE_SPACE * 0.7 && p[idx + 1] < NEC_ONE_SPACE * 1.3) {
                    data |= (1u << i);
                } else if (p[idx + 1] > NEC_ZERO_SPACE * 0.7 && p[idx + 1] < NEC_ZERO_SPACE * 1.3) {
                    /* bit 0 */
                } else {
                    return -1;
                }
            } else {
                return -1;
            }
        }
        uint8_t addr_lo = data & 0xFF;
        uint8_t addr_hi = (data >> 8) & 0xFF;
        uint8_t cmd_lo = (data >> 16) & 0xFF;
        uint8_t cmd_hi = (data >> 24) & 0xFF;
        *addr = (uint32_t)addr_hi << 8 | addr_lo;
        *cmd = (uint32_t)cmd_hi << 8 | cmd_lo;
        return 0;
    }
    return -1;
}

static void publish_mqtt(uint32_t addr, uint32_t cmd) {
    char payload[128];
    snprintf(payload, sizeof(payload), "{\"address\": %u, \"command\": %u}", addr, cmd);
    MQTTClient_message msg = MQTTClient_message_initializer;
    msg.payload = payload;
    msg.payloadlen = (int)strlen(payload);
    MQTTClient_deliveryToken token;
    if (MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &msg, &token) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed");
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(IR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "Failed to set alert on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    int rc = MQTTClient_create(&mqtt_client, "tcp://localhost:1883", "ir_decoder", MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_create failed: %s", MQTTClient_strerror(rc));
        gpioTerminate();
        closelog();
        return 1;
    }

    rc = MQTTClient_connect(mqtt_client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTTClient_connect failed: %s", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d", IR_GPIO);

    while (running) {
        gpioDelay(100000);
        if (pulse_count >= 34) {
            uint32_t addr, cmd;
            if (decode_nec((uint32_t *)pulses, pulse_count, &addr, &cmd) == 0) {
                publish_mqtt(addr, cmd);
                syslog(LOG_INFO, "Decoded: addr=0x%04X cmd=0x%04X", addr, cmd);
            }
            pulse_count = 0;
        }
    }

    syslog(LOG_INFO, "Shutting down");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    closelog();
    return 0;
}

