static const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};
static const char *sensor_ids[NUM_SENSORS] = {"1", "2", "3", "4"};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_open(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux_out) {
    unsigned char cmd = BH1750_CMD_OT_HRES;
    ssize_t w = write(fd, &cmd, 1);
    if (w != 1) {
        fprintf(stderr, "write cmd: %s\n", w < 0 ? strerror(errno) : "short write");
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    unsigned char data[2];
    ssize_t r = read(fd, data, 2);
    if (r != 2) {
        fprintf(stderr, "read: %s\n", r < 0 ? strerror(errno) : "short read");
        return -1;
    }
    int raw = (data[0] << 8) | data[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int udp_open(void) {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sock);
        return -1;
    }
    return sock;
}

static void send_multicast(int sock, const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "inet_pton: invalid multicast address\n");
        return;
    }
    if (sendto(sock, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int udp_sock = udp_open();
    if (udp_sock < 0) {
        return 1;
    }

    while (running) {
        char data[256];
        int data_len = 0;
        int ok = 1;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int fd = i2c_open(sensor_addresses[i]);
            if (fd < 0) {
                data_len += snprintf(data + data_len, sizeof(data) - data_len, "%s,NaN;", sensor_ids[i]);
