            } else {
                data_len += snprintf(data + data_len, sizeof(data) - data_len, "%s,%.1f;", sensor_ids[i], lux);
            }
            close(fd);
        }

        if (ok) {
            data[data_len - 1] = '\0';
            send_multicast(udp_sock, data);
            printf("Sent: %s\n", data);
        } else {
            fprintf(stderr, "Partial data: %s\n", data);
        }

        for (int s = 0; s < SAMPLE_INTERVAL_S && running; s++) {
            sleep(1);
        }
    }

    close(udp_sock);
    return 0;
}

