#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_empty(int fd)
{
    /* Zero-length write: generate a repeated-start condition */
    if (write(fd, NULL, 0) < 0) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        return -1;
    }
    if ((size_t)n != len) {
        return -1;
    }
    return 0;
}

static int read_airflow(int fd, float *flow_out)
{
    uint8_t buf[2];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_empty(fd) < 0) {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor absent (ENXIO) at attempt %d\n", attempt + 1);
            } else if (errno == EIO) {
                fprintf(stderr, "I2C bus error (EIO) at attempt %d\n", attempt + 1);
            } else {
                fprintf(stderr, "I2C write error at attempt %d: %s\n",
                        attempt + 1, strerror(errno));
            }
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0) {
            if (errno == ENXIO) {
                fprintf(stderr, "Sensor absent (ENXIO) at attempt %d\n", attempt + 1);
            } else if (errno == EIO) {
                fprintf(stderr, "I2C bus error (EIO) at attempt %d\n", attempt + 1);
            } else {
                fprintf(stderr, "I2C read error at attempt %d: %s\n",
                        attempt + 1, strerror(errno));
            }
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        raw &= 0x3FFF;
        *flow_out = ((float)raw - 3277.0f) * 0.1f;
        return 0;
    }

    return -1;
}

static void log_airflow(FILE *fp, float flow)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s, %.2f SLPM\n", ts, flow) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300V_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float flow;

        if (read_airflow(g_i2c_fd, &flow) == 0) {
            log_airflow(g_log_fp, flow);
            printf("Flow: %.2f SLPM\n", flow);
        } else {
            fprintf(stderr, "Failed to read airflow after %d retries.\n", MAX_RETRIES);
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        if (fclose(g_log_fp) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
        g_log_fp = NULL;
    }

    if (g_i2c_fd >= 0) {
        if (close(g_i2c_fd) < 0) {
            fprintf(stderr, "close(i2c) failed: %s\n", strerror(errno));
        }
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

