#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define AS7341_ADDR 0x39
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "spectral_log.csv"

#define AS7341_ENABLE 0x80
#define AS7341_ATIME 0x81
#define AS7341_WTIME 0x83
#define AS7341_ID 0x24
#define AS7341_CFG6 0xAF
#define AS7341_SP_DATA 0x60

#define AS7341_ID_VAL 0x19
#define AS7341_ENABLE_PON 0x01
#define AS7341_ENABLE_SP_EN 0x02

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, int len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(i2c_fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int as7341_init(void) {
    uint8_t id = 0;
    if (i2c_read_reg(AS7341_ID, &id) < 0) return -1;
    if (id != AS7341_ID_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", id, AS7341_ID_VAL);
        return -1;
    }
    if (i2c_write_reg(AS7341_ENABLE, AS7341_ENABLE_PON) < 0) return -1;
    usleep(10000);
    if (i2c_write_reg(AS7341_CFG6, 0x00) < 0) return -1;
    if (i2c_write_reg(AS7341_ATIME, 0x00) < 0) return -1;
    if (i2c_write_reg(AS7341_WTIME, 0xFF) < 0) return -1;
