#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILE "seismic_error.log"
#define I2C_BUS "/dev/i2c-1"
#define ACCEL_REG 0x28
#define ACCEL_BYTES 6
#define SCALE_FACTOR 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *csv_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time]: %s\n", msg);
    }
    fclose(fp);
}

static int i2c_write_byte(uint8_t reg) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    if (read(i2c_fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

static int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = ACCEL_REG;
    uint8_t data[ACCEL_BYTES];
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2c_write_byte(reg) < 0) {
            log_error("I2C write register address failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (i2c_read_bytes(data, ACCEL_BYTES) < 0) {
            log_error("I2C read acceleration data failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        *x = (int16_t)((data[1] << 8) | data[0]);
        *y = (int16_t)((data[3] << 8) | data[2]);
        *z = (int16_t)((data[5] << 8) | data[4]);
        return 0;
    }
    log_error("Failed to read acceleration after retries");
    return -1;
}

static void log_data(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        log_error("localtime_r failed");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    if (fprintf(csv_fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z) < 0) {
        log_error("fprintf to CSV failed");
    }
    fflush(csv_fp);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    const char *filename = DEFAULT_FILENAME;
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) interval = DEFAULT_INTERVAL;
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("ioctl I2C_SLAVE");
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return EXIT_FAILURE;
    }

    csv_fp = fopen(filename, "a");
    if (!csv_fp) {
        perror("fopen CSV");
        log_error("Failed to open CSV file");
        close(i2c_fd);
        i2c_fd = -1;
        return EXIT_FAILURE;
    }

    fprintf(csv_fp, "# timestamp,x_g,y_g,z_g\n");
    fflush(csv_fp);

    printf("Starting seismic monitoring on %s (addr 0x%02X), interval %d s, logging to %s\n",
           I2C_BUS, i2c_address, interval, filename);

    while (running) {
        int16_t raw_x, raw_y, raw_z;
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            float x = (float)raw_x * SCALE_FACTOR;
            float y = (float)raw_y * SCALE_FACTOR;
            float z = (float)raw_z * SCALE_FACTOR;
            log_data(x, y, z);
        }
        sleep(interval);
    }

    printf("\nShutting down...\n");
    if (csv_fp) {
        fflush(csv_fp);
        fclose(csv_fp);
        csv_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

