#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define BUFFER_SIZE 4096
#define MAGIC_WORD_LEN 8
#define TLV_HEADER_LEN 8
#define OBJ_DETECTED_TLV 1
#define MAX_OBJECTS 100

static const uint8_t MAGIC_WORD[MAGIC_WORD_LEN] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};

typedef struct {
    float range;
    float velocity;
} RadarObject;

typedef struct {
    time_t timestamp;
    int object_index;
    float range;
    float velocity;
} RadarData;

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Error opening CSV file");
        return -1;
    }
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    fflush(csv_file);
    return 0;
}

static int find_magic_word(const uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_LEN; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_WORD_LEN) == 0) {
            return i;
        }
    }
    return -1;
}

static int read_exact(int handle, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = serRead(handle, (char *)(buf + total), len - total);
        if (n < 0) {
            fprintf(stderr, "UART read error: %d\n", n);
            return -1;
        }
        if (n == 0) {
            usleep(1000);
            continue;
        }
        total += n;
    }
    return total;
}

static int process_frame(const uint8_t *frame, int frame_len) {
    if (frame_len < MAGIC_WORD_LEN + TLV_HEADER_LEN) {
        fprintf(stderr, "Frame too short for TLV header\n");
        return -1;
    }
    int offset = MAGIC_WORD_LEN;
    int obj_count = 0;
    while (offset + TLV_HEADER_LEN <= frame_len) {
        uint32_t tlv_type = frame[offset] | (frame[offset + 1] << 8) |
                            (frame[offset + 2] << 16) | (frame[offset + 3] << 24);
        uint32_t tlv_len = frame[offset + 4] | (frame[offset + 5] << 8) |
                           (frame[offset + 6] << 16) | (frame[offset + 7] << 24);
        offset += TLV_HEADER_LEN;
        if (offset + tlv_len > frame_len) {
            fprintf(stderr, "TLV length exceeds frame\n");
            return -1;
        }
        if (tlv_type == OBJ_DETECTED_TLV) {
            if (tlv_len < 4) {
                fprintf(stderr, "Object TLV too short\n");
                return -1;
            }
            uint16_t num_obj = frame[offset] | (frame[offset + 1] << 8);
            int obj_offset = 4;
            for (int i = 0; i < num_obj && obj_offset + 8 <= tlv_len; i++) {
                uint32_t range_raw = frame[offset + obj_offset] |
                                     (frame[offset + obj_offset + 1] << 8) |
                                     (frame[offset + obj_offset + 2] << 16) |
                                     (frame[offset + obj_offset + 3] << 24);
                uint32_t vel_raw = frame[offset + obj_offset + 4] |
                                   (frame[offset + obj_offset + 5] << 8) |
                                   (frame[offset + obj_offset + 6] << 16) |
                                   (frame[offset + obj_offset + 7] << 24);
                RadarObject obj;
                obj.range = (float)range_raw / 1000.0f;
                obj.velocity = (float)vel_raw / 1000.0f;
                RadarData data;
                data.timestamp = time(NULL);
                data.object_index = i;
                data.range = obj.range;
                data.velocity = obj.velocity;
                fprintf(csv_file, "%ld,%d,%.3f,%.3f\n",
                        (long)data.timestamp, data.object_index,
                        data.range, data.velocity);
                fflush(csv_file);
                obj_count++;
                obj_offset += 8;
            }
        }
        offset += tlv_len;
    }
    return obj_count;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint8_t *frame_buf = malloc(BUFFER_SIZE);
    if (!frame_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(csv_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t *read_buf = malloc(BUFFER_SIZE);
    if (!read_buf) {
        fprintf(stderr, "Memory allocation failed\n");
        free(frame_buf);
        fclose(csv_file);
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    int frame_len = 0;
    int read_len = 0;

    while (!terminate) {
        int space = BUFFER_SIZE - frame_len;
        if (space <= 0) {
            fprintf(stderr, "Buffer overflow, resetting\n");
            frame_len = 0;
            space = BUFFER_SIZE;
        }
        int n = serRead(uart_handle, (char *)(read_buf + read_len), space);
        if (n < 0) {
            fprintf(stderr, "UART read error: %d\n", n);
            break;
        }
        if (n == 0) {
            usleep(10000);
            continue;
        }
        read_len += n;

        int magic_pos = find_magic_word(read_buf, read_len);
        if (magic_pos < 0) {
            if (read_len > MAGIC_WORD_LEN) {
                memmove(read_buf, read_buf + read_len - MAGIC_WORD_LEN + 1, MAGIC_WORD_LEN - 1);
                read_len = MAGIC_WORD_LEN - 1;
            }
            continue;
        }

        if (magic_pos > 0) {
            memmove(read_buf, read_buf + magic_pos, read_len - magic_pos);
            read_len -= magic_pos;
        }

        if (read_len < MAGIC_WORD_LEN + TLV_HEADER_LEN) {
            continue;
        }

        int total_len = 0;
        memcpy(&total_len, read_buf + MAGIC_WORD_LEN, 4);
        total_len = total_len & 0xFFFF;
        if (total_len < MAGIC_WORD_LEN + TLV_HEADER_LEN || total_len > BUFFER_SIZE) {
            fprintf(stderr, "Invalid frame length %d\n", total_len);
            read_len = 0;
            continue;
        }

        if (read_len < total_len) {
            continue;
        }

        memcpy(frame_buf, read_buf, total_len);
        frame_len = total_len;
        read_len = 0;

        int obj_count = process_frame(frame_buf, frame_len);
        if (obj_count < 0) {
            fprintf(stderr, "Frame processing error\n");
        }
    }

    free(read_buf);
    free(frame_buf);
    fclose(csv_file);
    serClose(uart_handle);
    gpioTerminate();
    return 0;
}

