#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 256
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int parse_radar_line(const char *line, time_t *timestamp, float *range) {
    char *endptr = NULL;
    errno = 0;
    long val = strtol(line, &endptr, 10);
    if (errno != 0 || endptr == line) {
        fprintf(stderr, "Invalid timestamp: %s\n", line);
        return -1;
    }
    *timestamp = (time_t)val;

    if (*endptr != ',') {
        fprintf(stderr, "Missing comma after timestamp: %s\n", line);
        return -1;
    }
    endptr++;

    char *endptr2 = NULL;
    errno = 0;
    double range_d = strtod(endptr, &endptr2);
    if (errno != 0 || endptr2 == endptr) {
        fprintf(stderr, "Invalid range value: %s\n", endptr);
        return -1;
    }
    *range = (float)range_d;
    return 0;
}

static void log_detection(time_t timestamp, float range) {
    struct tm tm_info;
    char time_str[32];
    if (localtime_r(&timestamp, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("Timestamp: %s, Range: %.2f meters\n", time_str, range);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", UART_PORT, strerror(errno));
        return 1;
    }

    if (configure_uart(fd) != 0) {
        close(fd);
        return 1;
    }

    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    char read_buf[256];

    printf("Radar data acquisition started on %s at 115200 8N1.\n", UART_PORT);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int sel = select(fd + 1, &readfds, NULL, NULL, &timeout);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            continue; /* timeout, no data */
        }

        ssize_t n = read(fd, read_buf, sizeof(read_buf) - 1);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            fprintf(stderr, "UART closed unexpectedly.\n");
            break;
        }

        read_buf[n] = '\0';

        for (ssize_t i = 0; i < n; i++) {
            char c = read_buf[i];
            if (c == '\n') {
                line_buf[line_len] = '\0';
                if (line_len > 0) {
                    time_t ts;
                    float range;
                    if (parse_radar_line(line_buf, &ts, &range) == 0) {
                        log_detection(ts, range);
                    }
                }
                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SIZE - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line buffer overflow, discarding.\n");
                    line_len = 0;
                }
            }
        }
    }

    if (close(fd) != 0) {
        fprintf(stderr, "close() failed: %s\n", strerror(errno));
    }
    printf("\nRadar data acquisition stopped.\n");
    return 0;
}

